-- Step 76: pages feed off each other, so they can't disagree.
-- Run after step 75.
--
-- 1. Varieties inherit from their parent species. A new variety fills any blank field from its
--    parent, and when a parent's numbers change, every variety that matched the old value follows.
--    A variety only keeps its own value where it's truly different (a smaller fancy goldfish, say).
-- 2. The Society point list links to species pages (club_award_species.species_slug), and its
--    scientific names follow the species page from now on. Fixes a few names to current science,
--    and puts the Black-barred Limia back (step 74 renamed it to the wrong fish).
-- 3. Numbers written into text become live placeholders like {{temp}} or {{fact.nitrate_ok}},
--    which the site fills from the species data and its shared facts. The pages read exactly the
--    same today; they just can't drift. (256 texts)
--
-- All or nothing. Safe to run more than once.

begin;

-- 1. Varieties inherit
create or replace function public.species_inherit_from_parent() returns trigger
language plpgsql as $f$
declare p public.species%rowtype;
begin
  if new.parent_slug is null or new.entry_type not in ('variety', 'form') then return new; end if;
  select * into p from public.species where slug = new.parent_slug;
  if not found then return new; end if;
  new.temp_min_f := coalesce(new.temp_min_f, p.temp_min_f);
  new.temp_max_f := coalesce(new.temp_max_f, p.temp_max_f);
  new.ph_min := coalesce(new.ph_min, p.ph_min);
  new.ph_max := coalesce(new.ph_max, p.ph_max);
  new.gh_min := coalesce(new.gh_min, p.gh_min);
  new.gh_max := coalesce(new.gh_max, p.gh_max);
  new.water_type := coalesce(new.water_type, p.water_type);
  new.diet := coalesce(new.diet, p.diet);
  new.social := coalesce(new.social, p.social);
  new.min_group_size := coalesce(new.min_group_size, p.min_group_size);
  new.temperament := coalesce(new.temperament, p.temperament);
  new.swim_level := coalesce(new.swim_level, p.swim_level);
  new.breeding_type := coalesce(new.breeding_type, p.breeding_type);
  new.fin_nipper := coalesce(new.fin_nipper, p.fin_nipper);
  new.plant_safe := coalesce(new.plant_safe, p.plant_safe);
  new.care_level := coalesce(new.care_level, p.care_level);
  new.lifespan := coalesce(new.lifespan, p.lifespan);
  new.origin := coalesce(new.origin, p.origin);
  new.scientific_name := coalesce(new.scientific_name, p.scientific_name);
  new.family := coalesce(new.family, p.family);
  new.genus := coalesce(new.genus, p.genus);
  new.former_names := coalesce(new.former_names, p.former_names);
  new.described := coalesce(new.described, p.described);
  new.max_size_in := coalesce(new.max_size_in, p.max_size_in);
  new.min_tank_gal := coalesce(new.min_tank_gal, p.min_tank_gal);
  return new;
end $f$;

drop trigger if exists species_inherit on public.species;
create trigger species_inherit before insert or update of parent_slug, entry_type on public.species
  for each row execute function public.species_inherit_from_parent();

create or replace function public.species_pass_to_varieties() returns trigger
language plpgsql as $f$
begin
  update public.species c set
    temp_min_f = case when c.temp_min_f is not distinct from old.temp_min_f then new.temp_min_f else c.temp_min_f end,
    temp_max_f = case when c.temp_max_f is not distinct from old.temp_max_f then new.temp_max_f else c.temp_max_f end,
    ph_min = case when c.ph_min is not distinct from old.ph_min then new.ph_min else c.ph_min end,
    ph_max = case when c.ph_max is not distinct from old.ph_max then new.ph_max else c.ph_max end,
    gh_min = case when c.gh_min is not distinct from old.gh_min then new.gh_min else c.gh_min end,
    gh_max = case when c.gh_max is not distinct from old.gh_max then new.gh_max else c.gh_max end,
    water_type = case when c.water_type is not distinct from old.water_type then new.water_type else c.water_type end,
    diet = case when c.diet is not distinct from old.diet then new.diet else c.diet end,
    social = case when c.social is not distinct from old.social then new.social else c.social end,
    min_group_size = case when c.min_group_size is not distinct from old.min_group_size then new.min_group_size else c.min_group_size end,
    temperament = case when c.temperament is not distinct from old.temperament then new.temperament else c.temperament end,
    swim_level = case when c.swim_level is not distinct from old.swim_level then new.swim_level else c.swim_level end,
    breeding_type = case when c.breeding_type is not distinct from old.breeding_type then new.breeding_type else c.breeding_type end,
    fin_nipper = case when c.fin_nipper is not distinct from old.fin_nipper then new.fin_nipper else c.fin_nipper end,
    plant_safe = case when c.plant_safe is not distinct from old.plant_safe then new.plant_safe else c.plant_safe end,
    care_level = case when c.care_level is not distinct from old.care_level then new.care_level else c.care_level end,
    lifespan = case when c.lifespan is not distinct from old.lifespan then new.lifespan else c.lifespan end,
    origin = case when c.origin is not distinct from old.origin then new.origin else c.origin end,
    scientific_name = case when c.scientific_name is not distinct from old.scientific_name then new.scientific_name else c.scientific_name end,
    family = case when c.family is not distinct from old.family then new.family else c.family end,
    genus = case when c.genus is not distinct from old.genus then new.genus else c.genus end,
    former_names = case when c.former_names is not distinct from old.former_names then new.former_names else c.former_names end,
    described = case when c.described is not distinct from old.described then new.described else c.described end,
    max_size_in = case when c.max_size_in is not distinct from old.max_size_in then new.max_size_in else c.max_size_in end,
    min_tank_gal = case when c.min_tank_gal is not distinct from old.min_tank_gal then new.min_tank_gal else c.min_tank_gal end
  where c.parent_slug = new.slug and c.entry_type in ('variety', 'form') and c.slug <> new.slug;
  if new.scientific_name is distinct from old.scientific_name then
    update public.club_award_species a set scientific_name = new.scientific_name
    where a.species_slug = new.slug and a.scientific_name is distinct from new.scientific_name
      and coalesce(a.scientific_name, '') not like '%spp.%';
  end if;
  return null;
end $f$;

drop trigger if exists species_pass_down on public.species;
create trigger species_pass_down after update on public.species
  for each row when (pg_trigger_depth() < 5) execute function public.species_pass_to_varieties();

-- 2. Society list linked to species pages
alter table public.club_award_species add column if not exists species_slug text;
update public.club_award_species a set species_slug = g.species_slug
  from public.breeding_guides g
  where g.award_species_id = a.id and g.species_slug is not null and a.species_slug is null;
update public.club_award_species set common_name = 'Black-barred Limia', scientific_name = 'Limia nigrofasciata'
  where id = '008c1728-72a5-441c-8339-3e23c7af9abd';

update public.species set scientific_name = $v$Psalidodon anisitsi$v$, genus = $v$Psalidodon$v$, former_names = array[$v$Hyphessobrycon anisitsi$v$, $v$Hemigrammus caudovittatus$v$]::text[] where slug = $v$buenos-aires-tetra$v$;
update public.species set scientific_name = $v$Glossolepis incisa$v$, genus = $v$Glossolepis$v$, former_names = array[$v$Glossolepis incisus$v$]::text[] where slug = $v$red-rainbowfish$v$;
update public.species set scientific_name = $v$Hoplisoma habrosum$v$, genus = $v$Hoplisoma$v$, former_names = array[$v$Corydoras habrosus$v$, $v$Gastrodermus habrosus$v$]::text[] where slug = $v$salt-and-pepper-cory$v$;
update public.species set scientific_name = $v$Megalamphodus megalopterus$v$, genus = $v$Megalamphodus$v$, former_names = array[$v$Hyphessobrycon megalopterus$v$]::text[] where slug = $v$black-phantom-tetra$v$;
update public.species set scientific_name = $v$Pseudepiplatys annulatus$v$, genus = $v$Pseudepiplatys$v$, former_names = array[$v$Epiplatys annulatus$v$]::text[] where slug = $v$clown-killifish$v$;
update public.species set scientific_name = $v$Petitella bleheri$v$, genus = $v$Petitella$v$, former_names = array[$v$Hemigrammus bleheri$v$]::text[] where slug = $v$brilliant-rummynose-tetra$v$;
update public.species set scientific_name = $v$Petitella rhodostoma$v$, genus = $v$Petitella$v$, former_names = array[$v$Hemigrammus rhodostomus$v$]::text[] where slug = $v$rummy-nose-tetra$v$;

update public.club_award_species a set scientific_name = s.scientific_name
  from public.species s
  where a.species_slug = s.slug and a.scientific_name is distinct from s.scientific_name
    and coalesce(a.scientific_name, '') not like '%spp.%';

-- 3. Live numbers in text
update public.species set body = $v$Grows to about {{size}} inches, so it needs a large tank and a school of 6 or more. Boisterous at feeding time and eats soft plants, so choose hardy decor. Good for larger communities with other sturdy, similar-sized fish.$v$ where slug = $v$spanner-barb$v$;
update public.species set body = $v$Needs soft, acidic water, ideally tinted with leaf litter or peat, to thrive and show color. In the wild they live in peat swamps where the water can be as acidic as pH 4.5; in the aquarium aim for pH {{ph}}. Keep a school of 6 or more with dim lighting and plenty of plants. Much calmer than most barbs and a good fit with small peaceful fish.$v$ where slug = $v$snakeskin-barb$v$;
update public.species set body = $v$Needs very soft, acidic blackwater with leaf litter, dim light and small caves. In the wild they live in peat swamp water as low as pH 4.5; in the aquarium aim for about pH {{ph}}. Best kept as a pair or small group in a species tank since it is shy and easily outcompeted. Feed small live and frozen foods; many refuse flakes.$v$ where slug = $v$licorice-gourami$v$;
update public.species set body = $v$Grows to around {{size}} inches, so plan on {{tank}} gallons or more. Very peaceful and hardy, and even males are rarely aggressive. Good with medium community fish; avoid nippers that target its long ventral feelers.$v$ where slug = $v$snakeskin-gourami$v$;
update public.species set body = $v$Needs a tall tank of {{tank}} gallons or more with very warm, soft, acidic water and pristine quality. Keep in a group of 5 or more; wild fish are skittish and sensitive to shipping stress. Good with discus and peaceful South American fish.$v$ where slug = $v$altum-angelfish$v$;
update public.species set body = $v$Grows to about {{size}} inches and does best in a group, so plan on {{tank}} gallons or more. Needs warm, soft water and a diet heavy in vegetables and spirulina. It will eat most plants. A peaceful tankmate for discus and larger angelfish.$v$ where slug = $v$uaru$v$;
update public.species set body = $v$Keep one male with several females in {{tank}} gallons or more over fine sand for sifting. More territorial than most eartheaters, especially males. It will uproot plants. Keep water clean since it is sensitive to nitrate buildup.$v$ where slug = $v$red-hump-geophagus$v$;
update public.species set body = $v$Grows to about {{size}} inches, so give {{tank}} gallons or more. Calmer than many Central Americans but territorial when breeding. It digs pits to spawn and will uproot plants. Prefers hard, alkaline water and robust tankmates.$v$ where slug = $v$nicaraguan-cichlid$v$;
update public.species set body = $v$Grows to around {{size}} inches or more and is highly aggressive, so it is best kept alone or with very large, tough fish in {{tank}} gallons or more. It digs heavily and destroys plants. Use strong filtration and secure decor.$v$ where slug = $v$midas-cichlid$v$;
update public.species set body = $v$Among the most aggressive cichlids, it usually needs to be kept alone in {{tank}} gallons or more. It moves rocks, digs pits and destroys plants and equipment. Hard to tell apart from the Midas cichlid, and the two are often mixed in the trade.$v$ where slug = $v$red-devil-cichlid$v$;
update public.species set body = $v$Males can exceed {{size}} inches, so plan on {{tank}} gallons or more. Highly aggressive and piscivorous, it will eat any fish it can fit in its mouth. Tankmates must be very large and robust. Needs powerful filtration and heavy decor it cannot move.$v$ where slug = $v$jaguar-cichlid$v$;
update public.species set body = $v$Grows to about {{size}} inches but is relatively peaceful for its size, so {{tank}} gallons or more with similar-sized, calm tankmates works well. Prefers soft, slightly acidic water. It will eat small fish but usually leaves plants alone.$v$ where slug = $v$chocolate-cichlid$v$;
update public.species set body = $v$A hardy, easy-breeding small cichlid for {{tank}} gallons or more. Pairs defend a cave fiercely when spawning. Keep with robust fish of similar size. It digs, so rocks and sturdy or potted plants work best.$v$ where slug = $v$honduran-red-point$v$;
update public.species set body = $v$One of the calmer convict relatives, but still territorial when breeding. Give a pair {{tank}} gallons or more with caves and rockwork. Tolerates a wide range of water and breeds readily. Keep with robust, similar-sized tankmates.$v$ where slug = $v$sajica-cichlid$v$;
update public.species set body = $v$Keep one male with one or more females in {{tank}} gallons or more with caves, leaf litter and soft, acidic water. Males are territorial with each other. Good with small peaceful schooling fish like tetras and rasboras.$v$ where slug = $v$macmasters-dwarf-cichlid$v$;
update public.species set body = $v$Needs very soft, acidic blackwater with leaf litter and small caves. Keep a pair or one male with females in {{tank}} gallons or more with small, peaceful tankmates. Sensitive to nitrate and water changes that swing pH.$v$ where slug = $v$panda-dwarf-cichlid$v$;
update public.species set body = $v$Needs very soft, acidic water with dim light, plants and leaf litter. Keep one male with a few females in {{tank}} gallons or more. Timid and sensitive, so pair it only with small peaceful fish like pencilfish and small tetras.$v$ where slug = $v$checkerboard-cichlid$v$;
update public.species set body = $v$Keep a pair in {{tank}} gallons or more with plants and flat stones for spawning. Unlike many cichlids it rarely digs or harms plants. Peaceful with tetras and corydoras, though it guards eggs and fry firmly.$v$ where slug = $v$dwarf-flag-cichlid$v$;
update public.species set body = $v$Despite its {{size}} inch size, it is an active, aggressive predator that needs {{tank}} gallons or more with caves. Keep only with robust fish too large to eat. Needs soft, slightly acidic, very clean water and meaty live or frozen foods.$v$ where slug = $v$dwarf-pike-cichlid$v$;
update public.species set body = $v$A large, belligerent mbuna best kept one male to several females in a {{tank}} gallon or larger rockwork tank. Give hard, alkaline water and a balanced diet with vegetable matter, and only pair with other robust Malawi cichlids.$v$ where slug = $v$bumblebee-cichlid$v$;
update public.species set body = $v$Keep one male with several females in {{tank}} gallons or more, with open sand for sifting and some rock caves. Best with other peacocks and calm haps, since aggressive mbuna will stress it. Needs hard, alkaline water.$v$ where slug = $v$sunshine-peacock$v$;
update public.species set body = $v$Needs a {{tank}} gallon or larger tank with open swimming room and some rockwork, kept as one male with several females. Pairs well with peacocks and other peaceful haps. Keep water hard and alkaline, and color takes a year or more to develop.$v$ where slug = $v$red-empress$v$;
update public.species set body = $v$Grows to around {{size}} inches and needs a long tank of {{tank}} gallons or more with deep, fine sand it can dive into. Keep with other large, peaceful haps, not aggressive mbuna. It digs constantly, so plants will not last.$v$ where slug = $v$fossorochromis-rostratus$v$;
update public.species set body = $v$A predatory hap reaching about {{size}} inches that will eat any fish small enough to swallow. Needs {{tank}} gallons or more, hard alkaline water, and tankmates of similar size. Feed quality meaty foods and pellets, not live feeders.$v$ where slug = $v$livingstoni-cichlid$v$;
update public.species set body = $v$One of the calmer Malawi haps, ideally kept one male to several females in a {{tank}} gallon or larger tank with open swimming space. Great with peacocks, but avoid aggressive mbuna. Feed small plankton-type foods and quality pellets.$v$ where slug = $v$borleyi-cichlid$v$;
update public.species set body = $v$Males are territorial, so keep one male with several females in a {{tank}} gallon or larger rock-filled mbuna tank. Needs hard, alkaline water and a diet of quality pellets with some vegetable matter. Avoid mixing with similar-looking mbuna.$v$ where slug = $v$afra-cichlid$v$;
update public.species set body = $v$A territorial algae grazer best kept one male to several females in a {{tank}} gallon or larger rocky mbuna tank. Feed a vegetable-based diet like spirulina pellets to avoid bloat. Needs hard, alkaline water and plenty of caves.$v$ where slug = $v$red-top-trewavasae$v$;
update public.species set body = $v$Among the least aggressive mbuna, but still belongs in a {{tank}} gallon or larger rocky Malawi tank with other mbuna. Keep in a group with more females than males. Needs hard, alkaline water and a diet with some vegetable matter.$v$ where slug = $v$maingano-cichlid$v$;
update public.species set body = $v$An aggressive mbuna that should be kept one male to several females in a {{tank}} gallon or larger tank with lots of rockwork. Avoid other blue striped Melanochromis to limit fighting and hybrids. Needs hard, alkaline water.$v$ where slug = $v$blue-johanni$v$;
update public.species set body = $v$Keep a colony in a {{tank}} gallon long or larger tank with fine sand and plenty of empty escargot shells. They dig and bury shells, so rooted plants may be uprooted. Needs hard, alkaline water and will defend shells fiercely.$v$ where slug = $v$similis-shell-dweller$v$;
update public.species set body = $v$A hardy, peaceful catfish reaching about {{size}} inches, best kept in small groups in {{tank}} gallons or more. Will eat very small fish and shrimp. Males guard bubble nests and get territorial when spawning. Can gulp air at the surface.$v$ where slug = $v$hoplo-catfish$v$;
update public.species set body = $v$Grows to around {{size}} inches and will eat small fish, so keep with medium to large peaceful species. Needs a long tank with a tight lid, as it can gulp air and climb out. Feed meaty sinking foods.$v$ where slug = $v$delhezi-bichir$v$;
update public.species set body = $v$More delicate than common otos. Add a group of 6 or more only to a mature, planted {{tank}} gallon or larger tank with plenty of biofilm and algae. Supplement with algae wafers and blanched veggies, and acclimate slowly.$v$ where slug = $v$zebra-otocinclus$v$;
update public.species set body = $v$Grows to around {{size}} inches and will eat small fish at night, so keep with mid-sized tankmates in {{tank}} gallons or more. Provide caves and dim areas. Can be quarrelsome with its own kind, so one per tank is safest.$v$ where slug = $v$asian-bumblebee-catfish$v$;
update public.species set body = $v$A hardy nocturnal catfish that hides in caves by day and needs a {{tank}} gallon or larger tank. Peaceful, but it will eat fish small enough to swallow. Its spines tangle in nets, so move it with a container instead.$v$ where slug = $v$spotted-raphael-catfish$v$;
update public.species set body = $v$Must be kept in a group of 6 or more, or it becomes stressed and hides. Needs a {{tank}} gallon or larger tank with open swimming space and gentle flow. Peaceful, but may eat very small fry. Accepts flakes and small frozen foods.$v$ where slug = $v$african-glass-catfish$v$;
update public.species set body = $v$Sold at a few inches but reaches 3 to 4 feet and needs a custom tank of {{tank}} gallons or more. Swallows any tankmate that fits in its mouth and produces heavy waste. Public aquariums rarely accept rehomed adults, so avoid buying one.$v$ where slug = $v$redtail-catfish$v$;
update public.species set body = $v$Keep five or more in a large tank with caves and soft substrate, since single fish or pairs bully tankmates. They grow to about {{size}} inches and click when feeding. Avoid slow or long-finned fish and expect all snails to disappear.$v$ where slug = $v$blue-botia$v$;
update public.species set body = $v$Needs brackish water as adults, a large tank, and open air space above the water with a secure lid. Grows to around {{size}} inches and eats any fish that fits in its mouth. Feed floating insects and meaty foods.$v$ where slug = $v$banded-archerfish$v$;
update public.species set body = $v$Koi are pond fish, not aquarium fish. They grow to 2 feet or more, produce heavy waste, and need a large filtered pond of roughly {{tank}} gallons or more. Keep in groups and expect them to eat and uproot plants.$v$ where slug = $v$koi$v$;
update public.species set body = $v$Keep males alone in at least {{tank}} gallons, heated to {{temp}}F, with gentle filtration since the long fins make it a weak swimmer. Avoid fin nippers like tiger barbs. Fins are prone to rot if water quality slips.$v$ where slug = $v$veiltail-betta$v$;
update public.species set body = $v$Care is the same as any betta: one male per tank of {{tank}} gallons or more, warm stable water and low flow. The genetics behind the double tail can mean a shorter body and occasional swim bladder trouble, so avoid overfeeding.$v$ where slug = $v$double-tail-betta$v$;
update public.species set body = $v$Most koi bettas are short-finned plakats, so they are more active and hardier swimmers than long-finned types. Keep males alone in {{tank}} gallons or more with a heater. The marble gene means the pattern can change noticeably as the fish ages.$v$ where slug = $v$koi-betta$v$;
update public.species set body = $v$The huge pectoral fins tire the fish quickly, so use gentle filtration and add resting spots near the surface like leaf hammocks. Keep one male per tank of at least {{tank}} gallons, and avoid nippy tankmates that target the big fins.$v$ where slug = $v$dumbo-betta$v$;
update public.species set body = $v$A single female does well in {{tank}} gallons or a peaceful community. Sororities are an advanced setup: keep 5 or more females in at least 20 gallons, heavily planted with broken sight lines, and have a backup tank ready since fighting can break out.$v$ where slug = $v$female-betta$v$;
update public.species set body = $v$Care is the same as standard angelfish: a tall tank of {{tank}} gallons or more, warm stable water and calm tankmates. Adults will eat small fish like neon tetras. Keep a group of 5 or more to spread aggression.$v$ where slug = $v$platinum-angelfish$v$;
update public.species set body = $v$Keep like standard angelfish: {{tank}} gallons or more for a group, tall, warm and planted. Angels become territorial when pairing and will eat small fish like neons as adults. Avoid fin nippers such as tiger barbs and serpae tetras.$v$ where slug = $v$marble-angelfish$v$;
update public.species set body = $v$Usually grows smaller and is more delicate than normal Jack Dempseys, so keep water very clean and avoid overly aggressive tankmates. Give {{tank}} gallons or more with rockwork and caves. It will eat small fish and may dig up plants.$v$ where slug = $v$electric-blue-jack-dempsey$v$;
update public.species set body = $v$Grows to 12 inches or more and is a very messy eater, so plan on {{tank}} gallons or more with heavy filtration. It will eat any fish that fits in its mouth and rearranges decor. Albinos may be a bit more light sensitive.$v$ where slug = $v$albino-oscar$v$;
update public.species set body = $v$Needs {{tank}} gallons or more and strong filtration, as it grows past {{size}} inches and produces lots of waste. Tankmates must be too big to swallow. Intelligent and interactive, often recognizing its owner, but it will uproot plants and move decor.$v$ where slug = $v$tiger-oscar$v$;
update public.species set body = $v$Care is identical to the standard dojo: cool to room temperature water, soft sand to burrow in, and a group of three or more. They grow to around {{size}} inches, jump well, and escape through tiny gaps, so a tight lid is essential.$v$ where slug = $v$leopard-dojo-loach$v$;
update public.species set body = $v$Slow growing and fairly calm, but will eat fry, shrimp, and small fish. Needs a {{tank}} gallon or larger tank with narrow rock crevices and hard, alkaline water. Feed meaty foods and keep with Tanganyikans too large to swallow.$v$ where slug = $v$compressiceps-cichlid$v$;
update public.species set body = $v$Scarlet bettas are a wild betta from blackwater peat swamps, small and slender compared to the domestic betta. They're deep wine red, and many show a shining green spot on each side. They need very soft, acidic water. In the wild their water can be as low as pH 4; in the aquarium aim for about pH {{ph}}, which most keepers reach with RO water, peat and leaf litter. Keep a pair or a small group in a quiet, dim, heavily planted tank with a tight lid. Feed small live and frozen foods; many won't take dry food at first.$v$ where slug = $v$scarlet-betta$v$;
update public.species set body = $v$Keep one male with three or more females in {{tank}} gallons or more, with open sand for sifting and rockwork to break sight lines. Albinos see poorly, so they can be slow to find food; feed sinking pellets and keep them with other peacocks and haps rather than fast, aggressive mbuna. Most albino lines are hybrids, so don't breed them with pure species.$v$ where slug = $v$albino-peacock-cichlid$v$;
update public.species set body = $v$Keep a pair or one male with a few females in a {{tank}} gallon long or larger tank with fine sand and extra empty shells. Very territorial for its size, so avoid other bottom dwellers. Needs hard, alkaline water.$v$ where slug = $v$ocellatus-shell-dweller$v$;
update public.species set body = $v$Keep a bonded pair in a {{tank}} gallon or larger tank with stacked rocks and caves. Pairs become very territorial when breeding and may fight, so watch for a mismatched pair. Needs hard, alkaline Tanganyika water.$v$ where slug = $v$regani-julie$v$;
update public.species set body = $v$A good starter mbuna for a {{tank}} gallon or larger rocky tank, kept with more females than males. Feed a vegetable-heavy diet to avoid bloat and keep water hard and alkaline. An albino form is also common in stores.$v$ where slug = $v$socolofi-cichlid$v$;
update public.species set body = $v$One of the most aggressive mbuna, so keep one male with several females in a crowded, rock-heavy mbuna tank of {{tank}} gallons or more. Needs hard, alkaline water and a veggie-based diet, as rich foods can cause bloat.$v$ where slug = $v$kenyi-cichlid$v$;
update public.species set body = $v$A tough, beginner-friendly cichlid for {{tank}} gallons or more. Mostly peaceful with similar-sized fish but will eat small tetras and gets territorial when spawning. Provide flat rocks for egg laying and some cover.$v$ where slug = $v$blue-acara$v$;
update public.species set body = $v$Keep like a German blue ram: {{tank}} gallons or more, warm soft water around {{temp}}F, and stable, clean conditions. Pairs claim a small territory near the bottom. Good with peaceful tetras and corydoras that tolerate the heat.$v$ where slug = $v$gold-ram$v$;
update public.species set body = $v$Needs {{tank}} gallons or more and grows to around {{size}} inches. Usually peaceful with similar-sized fish but will eat soft plants and small tankmates. Keep water clean with strong filtration and regular changes.$v$ where slug = $v$gold-severum$v$;
update public.species set body = $v$Hardy and easy but very territorial, especially when breeding, which happens often. Give {{tank}} gallons or more with caves and only robust tankmates. It digs and may uproot plants. Be ready to rehome the frequent fry.$v$ where slug = $v$pink-convict$v$;
update public.species set body = $v$Keep a pair in a {{tank}} gallon long or larger planted tank with caves. Prefers softer, slightly acidic water than the common krib. Territorial when breeding, so add dither fish and avoid other bottom-dwelling cichlids.$v$ where slug = $v$striped-kribensis$v$;
update public.species set body = $v$Keep a group of 6 or more in a {{tank}} gallon or larger tank with soft sand. Peaceful and easy with other small community fish. Feed sinking pellets, wafers, and frozen foods, and keep nitrates low with regular water changes.$v$ where slug = $v$schwartzs-cory$v$;
update public.species set body = $v$Keep a group of 6 or more on soft sand in a {{tank}} gallon or larger tank. Peaceful with small community fish. Needs clean water and sinking foods reaching the bottom, and prefers soft to moderately hard water.$v$ where slug = $v$similis-cory$v$;
update public.species set body = $v$Keep a group of 6 or more in a {{tank}} gallon or larger tank with soft sand. Very peaceful, active, and hardy once settled. Feed sinking pellets and frozen foods. Often confused with the similar Osteogaster zygata (formerly Corydoras zygatus) in stores.$v$ where slug = $v$rusty-cory$v$;
update public.species set body = $v$Prefers slightly cooler water than many corys, so pick tankmates that like the low to mid 70s. Keep a group of 6 or more on soft sand in {{tank}} gallons or more. Peaceful and a great bottom cleaner alongside small tetras.$v$ where slug = $v$green-gold-cory$v$;
update public.species set body = $v$Keep a group of 8 or more in a mature, planted tank of {{tank}} gallons or larger with fine sand. Unlike most corys it hovers in midwater, so tankmates must be small and gentle. Sensitive to poor water quality.$v$ where slug = $v$hastatus-cory$v$;
update public.species set body = $v$Keep a group of 6 or more in a {{tank}} gallon or larger tank with soft sand to protect its barbels. Peaceful and good with small community fish. Offer sinking pellets and frozen foods and keep water clean and well oxygenated.$v$ where slug = $v$leopard-cory$v$;
update public.species set body = $v$The peppered cory comes from cooler subtropical rivers and actually prefers {{temp}}F; keeping it too warm shortens its life. It was moved from Corydoras to Hoplisoma in the 2024 revision, though the old name persists in stores.$v$ where slug = $v$peppered-cory$v$;
update public.species set body = $v$Give it {{tank}} gallons or more with plants and floating cover. Males can be territorial with each other, so keep one male or a male with females. Generally peaceful with similar-sized community fish and hardier than the dwarf gourami.$v$ where slug = $v$banded-gourami$v$;
update public.species set body = $v$Single-tailed goldfish like the common and comet are big, messy, long-lived fish that belong in large tanks or ponds, not bowls. They produce heavy waste and need strong filtration and cool water. Pond fish ride out much colder winters, but in an aquarium aim for {{temp}}°F.$v$ where slug = $v$common-goldfish$v$;
update public.species set body = $v$Demanding and sensitive to water quality, it needs very soft, acidic, tannin-rich water and stable conditions. Unusually for a gourami, it is a mouthbrooder. Best for experienced keepers in a dedicated blackwater setup. In the wild they live in peat swamp water as low as pH 4; in the aquarium aim for about pH {{ph}} with very soft water.$v$ where slug = $v$chocolate-gourami$v$;
update public.species set body = $v$Care matches the standard dwarf gourami: {{tank}} gallons or more, planted, calm tankmates and floating plants. Males can squabble, so keep one per tank. Quarantine new fish since dwarf gourami iridovirus is common in farmed stock.$v$ where slug = $v$flame-dwarf-gourami$v$;
update public.species set body = $v$Keep one male per tank, or a male with females, in {{tank}} gallons or more with plants and floating cover. Commercial stock is prone to dwarf gourami iridovirus, so buy from a trusted source and quarantine. Peaceful with other calm community fish.$v$ where slug = $v$powder-blue-dwarf-gourami$v$;
update public.species set body = $v$A hardy, shy fish for {{tank}} gallons or more with plants and floating cover. It can be kept singly or in small groups with more females than males. Choose calm tankmates, as boisterous fish will outcompete it for food.$v$ where slug = $v$sunset-honey-gourami$v$;
update public.species set body = $v$Juveniles tolerate brackish water, but adults need higher salinity up to full marine. Keep six or more in a large tank, since singles become skittish or aggressive. They eat small fish and grow to around {{size}} inches.$v$ where slug = $v$mono-argentea$v$;
update public.species set body = $v$Best kept one per tank unless the aquarium is large and heavily broken up with decor, since they chase their own kind and other bottom dwellers. Give them at least {{tank}} gallons with caves and driftwood to claim. Hardy and long-lived, but not a fish for a calm nano community.$v$ where slug = $v$rainbow-shark$v$;
update public.species set body = $v$Needs warm, clean, well-oxygenated water with good flow and caves in a {{tank}} gallon or larger tank. Not an algae eater, so feed meaty sinking foods like bloodworms and quality pellets. Males defend caves from each other.$v$ where slug = $v$queen-arabesque-pleco$v$;
update public.species set body = $v$Comes from soft, acidic blackwater, so it does best in warm, soft water with driftwood and caves in a {{tank}} gallon or larger tank. Feed algae wafers, vegetables, and some meaty foods. Males can be territorial over caves.$v$ where slug = $v$starlight-bristlenose-pleco$v$;
update public.species set body = $v$Grows to around {{size}} inches and needs {{tank}} gallons or more with warm, fast, well-oxygenated water and large caves. Feeds mainly on meaty foods and will eat snails. Territorial toward other bottom dwellers, so keep only one.$v$ where slug = $v$sunshine-pleco$v$;
update public.species set summary = $v$A tiny, stocky algae grazer that stays around {{size}} inches, perfect for small planted tanks.$v$, body = $v$Best kept in a small group in a mature {{tank}} gallon or larger tank with biofilm and soft algae to graze. Supplement with algae wafers and blanched veggies. Peaceful and safe with shrimp and plants.$v$ where slug = $v$pitbull-pleco$v$;
update public.species set body = $v$Care matches the standard bristlenose. Stays around {{size}} inches and does well in a {{tank}} gallon or larger tank with driftwood and caves. Feed algae wafers and vegetables. Males are territorial with each other over caves.$v$ where slug = $v$super-red-bristlenose-pleco$v$;
update public.species set body = $v$A demanding shrimp for experienced keepers: RO water remineralized to GH {{gh}} and an active soil keeping pH near 6.0 to 6.8. Keep cool, around 68 to 74 F, in a mature tank with no fish. Drip acclimate slowly and avoid parameter swings.$v$ where slug = $v$blue-bolt-shrimp$v$;
update public.species set body = $v$Cardinal shrimp come from Lake Matano, a warm and extremely stable lake with alkaline water that is low in general hardness. They need a mature tank kept around {{temp}}°F with a pH near 8, no copper, and almost no change from week to week. Most keepers use RO water remineralized specifically for Sulawesi shrimp. Keep them on their own or with snails, since most fish will eat them, and give them porous rock covered in biofilm to graze. Females carry their eggs, and the young hatch as tiny copies of the adults.$v$ where slug = $v$cardinal-shrimp$v$;
update public.species set body = $v$Cherry shrimp are forgiving algae- and biofilm-grazers that breed readily in a stable, copper-free tank. The many color forms (blue, yellow, orange, green and more) are all the same species, Neocaridina davidi. Keep pH between 6.5 and 8 with some hardness (GH {{gh}}) so they molt cleanly.$v$ where slug = $v$cherry-shrimp$v$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up for Spawning", "text": "Goldfish usually spawn in their main tank or pond, so the setup is about catching eggs. Hang several spawning mops or add fine leaved plants where the fish can push through. Keep filtration strong in the adults' tank, but prepare a separate hatching tank of 10 to 20 gallons with a sponge filter and water from the main tank.\n\nThe site's everyday care range for goldfish is {{temp}}°F with harder, alkaline water, and the spawning temperatures of 68 to 72°F sit inside it. A natural pattern works best: a few weeks of slightly cooler water in winter as a rest period, then a steady warm up into spring."}, {"heading": "Conditioning and Sexing", "text": "In breeding season, males develop small white bumps called breeding tubercles on the gill covers and the leading rays of the pectoral fins. They also chase females. Females are rounder from above and may show a slightly protruding vent. Outside the season, sexing is unreliable, so don't rely on body shape alone.\n\nCondition fish well in late winter with a varied diet: quality pellets, gel food, frozen bloodworms and brine shrimp, and blanched vegetables. Healthy fish of a year or older, with full bodies, spawn most reliably."}, {"heading": "Spawning: What You'll See", "text": "As the water warms to about 68 to 72°F and the days get longer, males start following and nudging the female, often pushing at her belly and vent. Spawning usually starts early in the morning and can be frantic.\n\nThe female scatters eggs through the mops and plants while the males fertilize them. The eggs are sticky and cling wherever they land. Chasing can be rough on the female, so watch for damage and make sure she has room to rest. Spawning can repeat every week or two through spring."}, {"heading": "Eggs and Fungus Prevention", "text": "A large female can release several hundred to over a thousand eggs. Lift the mops into the hatching tank as soon as spawning stops, or remove the adults if you're using a separate breeding setup. Goldfish eat their own eggs eagerly.\n\nAt 68 to 72°F the eggs hatch in about 3 to 6 days; cooler water takes longer. Infertile eggs turn white and fuzzy. Add gentle aeration and pick out fungused eggs with tweezers or a pipette so the fungus doesn't spread to good ones."}, {"heading": "Raising the Fry", "text": "Newly hatched fry cling to the glass and mops, then swim freely about 2 to 3 days later.\n\n- First days of swimming: liquid or powdered fry food, infusoria or green water\n- From about day 3 to 5: newly hatched baby brine shrimp, several feeds a day\n- Weeks 3 to 6: baby brine shrimp plus crushed flake or fry powder\n\nGoldfish fry produce a lot of waste. Change 20 to 30 percent of the water every 1 to 2 days once they're eating well, matching temperature carefully. Keep them around 68 to 72°F."}, {"heading": "Growing Out and Culling", "text": "Fry reach about 1 inch in 2 to 3 months with heavy feeding and frequent water changes. Most start out dark bronze and change to gold, red or white over the following months; some never change.\n\nA spawn can be far larger than you can house. Thin the batch early and move fish into bigger tanks or a pond as they grow. Fancy varieties often produce many fry without the parents' traits, so keep the best and plan humane culling or rehoming for the rest. Never release goldfish into ponds or waterways."}, {"heading": "Common Mistakes", "text": "- Leaving eggs with the adults overnight\n- Keeping too many fry in too little water, which stunts growth\n- Skipping the cool winter period, then wondering why fish won't spawn\n- Letting fungus spread through a mop of eggs\n- Releasing extra fish outdoors instead of rehoming them"}]$g$::jsonb, updated_at = now() where slug = $g$common-goldfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank suits a small group. The important part is the spawning sites: give each male a flat ceiling such as a slate tile set on stones, a clay pot on its side, or a piece of PVC pipe cut in half lengthwise and placed curved side up. Males clean the underside and the eggs are laid there.\n\nUse a sponge filter and plants for cover. Rosy reds handle a wide range of temperatures, and the site lists {{temp}}°F. Spawning goes best when water warms to about 70 to 77°F with 14 or more hours of light."}, {"heading": "Conditioning and Choosing a Group", "text": "Out of season, sexes can look alike. In breeding condition, males are easy to spot: they get a dark head, white bumps called tubercles on the snout and a spongy pad on the back behind the head, which they use to clean the eggs. Females stay plain and get rounder.\n\nCondition with frozen bloodworms, brine shrimp, daphnia and a good flake for 1 to 2 weeks. Keep one male for every 2 or 3 females, and provide more spawning sites than males to reduce fighting."}, {"heading": "Spawning: What You'll See", "text": "The male picks a site, cleans its underside and chases off rivals. He then leads a ripe female under it. The pair turns upside down or on their sides and she presses eggs onto the ceiling one patch at a time while he fertilizes them.\n\nAfterwards the male drives her away and stays to guard. He rubs the eggs with his back pad and fans them. A single male may collect eggs from several females, so the patch can keep growing over a few days."}, {"heading": "Eggs and Their Care", "text": "Each spawning commonly produces 50 to a few hundred eggs. At around 75 to 77°F they hatch in about 4 to 6 days, more slowly when cooler.\n\nYou can leave the eggs with the male, who keeps them clean, or lift the tile or pipe into a separate tank with gentle aeration and a few drops of methylene blue. Taking the eggs out protects the fry from the adults. Eggs that turn white and fuzzy were infertile; remove them so fungus doesn't spread."}, {"heading": "Raising the Fry", "text": "The fry are free swimming soon after hatching and are fairly small.\n\n- First week: infusoria, green water or liquid fry food several times a day\n- Week 2: baby brine shrimp and microworms\n- Weeks 3 to 6: baby brine shrimp and crushed flake\n\nChange 10 to 20 percent every 2 to 3 days with matched water. Keep the fry tank at about 72 to 77°F for good growth. Avoid strong filter intakes; a sponge filter is safest."}, {"heading": "Growing Out", "text": "Fry grow steadily and reach about 1 inch in 6 to 10 weeks with regular feeding. Move them to larger quarters as they grow, as crowding slows them down.\n\nRosy reds mature quickly in warm, well fed conditions and keep spawning through long days. A healthy group can produce a lot of young, so plan where they will go. Never release them into ponds or streams, even though fathead minnows are native to parts of North America."}, {"heading": "Common Mistakes", "text": "- No flat ceilings, so males have nowhere to spawn\n- One site for several males, which leads to constant fighting\n- Leaving free swimming fry with hungry adults\n- Short day length, which keeps fish out of breeding mode\n- Treating a darkened, bumpy male as sick; that is breeding dress"}]$g$::jsonb, updated_at = now() where slug = $g$rosy-red-minnow$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Give a pair its own tank. The site lists {{tank}} gallons as the minimum for this species, and that is a good size for a breeding pair with room to raise fry. Add a few caves such as flowerpots on their sides, rock piles or coconut shells, over sand or fine gravel they can dig.\n\nKeep the water at 76 to 80°F with a pH between 6.5 and 8. A sponge filter is ideal because it won't suck in fry. Expect the pair to rearrange the substrate, so skip delicate plants."}, {"heading": "Conditioning and Choosing a Pair", "text": "Females are smaller and show orange or gold scales on the lower belly and often on the dorsal fin. Males are larger, with a steeper forehead and longer, pointed dorsal and anal fins, and lack the orange.\n\nThe best pairs form naturally: raise a group of young fish together and let two choose each other. Feed quality cichlid pellets plus frozen bloodworms, brine shrimp and mysis for 1 to 2 weeks. A bonded pair swims together, digs together and chases other fish away."}, {"heading": "Spawning: What You'll See", "text": "The pair cleans a flat surface inside a cave and digs out pits nearby. Both fish show darker bars and become protective. The female passes over the cleaned spot laying rows of eggs, and the male follows to fertilize them.\n\nAfterwards the female usually stays close to the eggs, fanning them, while the male patrols the area. If you see the pair hiding and chasing everything that comes near the cave, look carefully inside: you'll often find a patch of amber eggs."}, {"heading": "Eggs and Wrigglers", "text": "A spawn is commonly 100 to 300 eggs. At 78 to 80°F they hatch in about 3 days. The parents eat infertile or fungused eggs, so leave the cleaning to them.\n\nNewly hatched young, often called wrigglers, can't swim yet. The parents move them to pits in the substrate and guard them. Don't move rocks or do major cleaning during this stage. First time pairs sometimes eat a spawn; most get it right after one or two attempts."}, {"heading": "Raising the Fry", "text": "The fry swim freely about 4 to 6 days after hatching and move around the tank in a tight cloud with the parents. They are big enough to eat food straight away.\n\n- Week 1: newly hatched baby brine shrimp 2 to 3 times a day, plus fry powder\n- Weeks 2 to 4: baby brine shrimp and crushed flake or small pellets\n- From week 4: crushed pellets and flake\n\nChange 20 percent of the water weekly, or more often as the fry grow, matching temperature carefully. Keep a lid on and the tank calm."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks. They can stay with the parents for several weeks, but once the pair starts preparing for another spawn they may chase the older fry. Move the young into their own tank at that point.\n\nConvicts can breed every few weeks, so a single pair can produce far more fish than local stores want. Plan homes for the young before they're grown, and give the pair breaks if you can't place the offspring."}, {"heading": "Common Mistakes", "text": "- Keeping a breeding pair in a community tank, where they attack tankmates\n- Removing the parents too early; they are the fry's best protection\n- Moving rocks and caves while eggs or wrigglers are present\n- Breeding nonstop without homes lined up for the fry\n- Mixing with other Central American cichlids, which can hybridize"}]$g$::jsonb, updated_at = now() where slug = $g$convict-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 15 to 20 gallon tank suits a breeding group, in line with the site's 15 gallon minimum. Add plenty of cover: java moss, hornwort or floating plants give newborns places to hide. A sponge filter keeps them safe.\n\nVariatus platies come from cooler waters than common platies, and the site lists {{temp}}°F with pH {{ph}} and GH {{gh}}. For breeding, around 72 to 77°F works well. Cooler water slows gestation and growth, so keep the fry tank at the upper end of the range."}, {"heading": "Choosing Breeders", "text": "Males have a pointed anal fin called a gonopodium and usually develop brighter colors, often yellow, orange or red fins. Females are larger with a fan shaped anal fin and plainer coloring.\n\nVariatus males are known for maturing late. Some show their gonopodium and color within a few months, while others take much longer, so a fish you thought was female may turn out male. Keep one male to two or three females. Females store sperm and can have several broods from one mating."}, {"heading": "Pregnancy and Birth", "text": "Gestation is about 4 weeks in warm water, longer when it's cooler. A pregnant female grows wider and boxy from the front. Some show a darker area near the vent as birth approaches.\n\nBroods are commonly 20 to 50 fry, fewer for young females. Births usually take a few hours, and fry swim straight into the plants. A female can drop roughly once a month in good conditions. Avoid netting or moving her while she is actively giving birth."}, {"heading": "Saving the Fry", "text": "Adults will eat some newborns. In a densely planted tank a good number survive, which is often enough for most keepers.\n\nTo raise more, move a heavily pregnant female into a separate planted tank to give birth, then return her. Short stays in a breeder box are fine, but long ones stress females and can cause early or failed births."}, {"heading": "Raising the Fry", "text": "Variatus fry are born ready to eat.\n\n- Week 1: baby brine shrimp, fry powder and finely crushed flake, 3 to 4 small feeds a day\n- Weeks 2 to 4: baby brine shrimp, crushed flake and vegetable flake\n- From week 4: regular flake and small frozen foods\n\nChange 20 to 30 percent of the water weekly with matched temperature. Keep the fry tank at 74 to 77°F for steady growth; growth slows noticeably in cooler water.\n\nFeed little and often rather than one big meal, and siphon uneaten food from the bottom daily. Clean water and frequent feeding in the first two months set the size and shape of the adult fish."}, {"heading": "Growing Out", "text": "Fry grow steadily, and females are usually recognizable within a few months. Because some males mature late, wait before deciding a group is all female, and keep a close eye on young fish if you're breeding a specific color.\n\nVariatus can cross with common platies and swordtails. To keep a pure line, or to sell fish as variatus, keep them apart from related species. Choose the best colored fish of each batch as your next breeders, and plan homes for extras before the tank fills up."}, {"heading": "Common Mistakes", "text": "- Assuming late developing males are females\n- Keeping fry too cool, which slows growth a lot\n- Bare tanks where adults pick off fry\n- Mixing with common platies or swordtails when breeding a pure line\n- Long stays in breeder boxes"}]$g$::jsonb, updated_at = now() where slug = $g$variatus-platy$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is ideal. Lower the water to about 6 to 8 inches and add floating plants for the male to anchor a nest. Use a small sponge filter with very gentle flow, because strong currents break up bubble nests.\n\nHoney gouramis do fine in the 72 to 82°F range, but for spawning raise the temperature to around 80 to 82°F. Keep the tank covered so the air above the water stays warm and humid.\n\nSoft to medium water is fine, and the library range of pH {{ph}} works well for spawning. A few floating plants like water sprite or salvinia give the male a place to build and help hold infusoria for the fry."}, {"heading": "Choosing and Conditioning a Pair", "text": "Breeding males are easy to spot: they turn a deep honey orange with a dark blue-black throat and chest. Females are paler with a brownish horizontal stripe and get rounder when full of eggs.\n\nCondition the pair for 1 to 2 weeks with live and frozen foods like brine shrimp, daphnia and bloodworms. Honey gouramis are peaceful, but still give the female hiding places."}, {"heading": "Spawning: What You Will See", "text": "The male builds a bubble nest, often smaller and looser than a betta nest. He displays to the female and leads her under the nest. They embrace, eggs are released and float up or are carried to the nest by the male.\n\nSpawning repeats over a few hours. Spawns are commonly reported from several dozen up to about 300 eggs.\n\nBefore spawning, the male often swims in front of the female with his fins spread, then turns back toward the nest. If the female is not ready, he may chase her. Give her plants to hide in and watch closely the first day."}, {"heading": "Eggs and the Nest", "text": "Remove the female after spawning. The male guards the nest and gathers stray eggs.\n\nEggs usually hatch in about 24 to 36 hours around 80°F. Fry hang near the nest for a few days. Once they start swimming freely, remove the male, since he may eat them.\n\nAvoid big water changes while the male guards the nest. Stress and sudden changes can make males eat eggs. Keep the room quiet and the tank lid on."}, {"heading": "Raising the Fry", "text": "Honey gourami fry are very small, which is why many first spawns fail.\n\n- Week 1: infusoria or paramecium cultures several times a day\n- Week 2: start microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: baby brine shrimp and fine crushed foods\n- Keep the lid on while the labyrinth organ develops over the first few weeks\n- Small water changes of 10 to 20 percent a few times a week\n\nStart an infusoria culture a week before you expect a spawn so it is ready when the fry need it."}, {"heading": "Growing Out", "text": "Feed small amounts several times a day. Fry reach about an inch by 2 to 3 months and adult size around 6 months.\n\nSort by size if some grow faster, because the larger fry can outcompete the small ones for food.\n\nGrow-out tanks should be at least 10 gallons for a typical spawn. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old."}, {"heading": "Common Mistakes", "text": "- Starting with food that is too big for the newly free swimming fry\n- Leaving the tank uncovered\n- Strong filter flow that destroys the nest\n- Leaving the male in too long\n- Big water changes that drop the temperature"}]$g$::jsonb, updated_at = now() where slug = $g$honey-gourami$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Pearl gouramis grow to around 4 to 4.5 inches, so a 20 to 30 gallon tank is a good breeding size. Lower the water to about 8 inches and add plenty of floating plants.\n\nThe library range is {{temp}}°F; for spawning aim for the warm end, around 80 to 82°F. Use a gentle sponge filter and keep a tight lid on the tank.\n\nPearl gouramis spawn in soft to medium water. The library range is pH {{ph}}, but the soft, slightly acidic side, around pH 6.5 to 7, tends to work best. Floating plants also help the male anchor his nest and hold infusoria for the fry."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males have a longer, more pointed dorsal fin and a longer anal fin with extended rays. When breeding, their throat and chest turn bright orange-red. Females have a rounder dorsal fin, paler colors and fill out with eggs.\n\nCondition the pair for about two weeks with live and frozen foods. A healthy, well fed female will look noticeably rounder.\n\nPick fish that are at least 3 inches long and look healthy, with full fins. Young or small females often produce weak, small spawns. A pair that has grown up together is often calmer during spawning."}, {"heading": "Spawning: What You Will See", "text": "The male builds a large bubble nest, often anchored to floating plants. He displays with spread fins and leads the female under the nest. They embrace and release eggs, which float up into the nest.\n\nSpawning can last a few hours and often produces several hundred eggs.\n\nThe male may chase the female before she is ready. Give her plenty of cover, and remove her if she is being harassed. Once she is ready, the spawning embrace looks much like a betta's."}, {"heading": "Eggs and the Nest", "text": "Remove the female after spawning. The male guards the nest closely.\n\nEggs usually hatch in about 24 to 48 hours around 80°F. Fry stay near the nest for a few days. Remove the male once the fry are swimming freely.\n\nDo not disturb the nest while the male guards it. Keep the light low and avoid water changes for these few days. Stress can cause the male to eat eggs."}, {"heading": "Raising the Fry", "text": "- Week 1: infusoria or paramecium several times a day\n- Week 2: add microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: mainly baby brine shrimp and finely crushed foods\n- Keep the lid on while the labyrinth organ develops\n- Small, frequent water changes of 10 to 20 percent at matched temperature\n\nStart an infusoria culture a week before you expect a spawn. A large spawn can eat a lot, and running out in the first week is the most common reason fry are lost."}, {"heading": "Growing Out", "text": "Large spawns mean lots of mouths. Spread the fry across extra tanks as they grow so they do not stunt from crowding.\n\nFry reach about an inch by 2 to 3 months. Adult size can take around 6 to 9 months.\n\nGrow-out tanks should be at least 20 gallons. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old. Sort out larger fish if smaller siblings are falling behind."}, {"heading": "Common Mistakes", "text": "- Too little infusoria for the size of the spawn\n- Crowding hundreds of fry in one small tank\n- Uncovered tanks and cold air over the water\n- Strong filter flow that breaks the nest\n- Leaving the male in after the fry are swimming"}]$g$::jsonb, updated_at = now() where slug = $g$pearl-gourami$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank works well. Cover the bottom with mesh, marbles or a thick layer of java moss so eggs can fall where the adults cannot reach them. Add a spawning mop or a clump of fine leaved plants.\n\nBlack ruby barbs come from soft, slightly acidic streams in Sri Lanka. The library range is {{temp}}°F and pH {{ph}}. For spawning, aim for the warm end, around 77 to 79°F, with soft water toward pH 6.5. Use a gentle sponge filter."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males in breeding condition turn a deep red across the head and front of the body, with the black bars getting darker. Females are paler and rounder.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods like brine shrimp, daphnia and bloodworms. Keeping males and females apart during conditioning often leads to a stronger spawn when you put them together."}, {"heading": "Spawning: What You Will See", "text": "Move a pair or a male with two females into the spawning tank in the evening. Spawning often begins at first light the next morning.\n\nThe male chases the female through the plants, and the pair release eggs and sperm in short bursts. The adhesive eggs stick to the plants or fall to the bottom. A spawn often produces a hundred or more eggs.\n\nIf nothing happens in a couple of days, try a partial water change with slightly softer water. Pairs that have not spawned within 3 to 4 days are often better returned to conditioning and tried again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults as soon as spawning is finished, because they will eat the eggs.\n\nEggs usually hatch in about 24 to 48 hours around 77°F. Keep the tank dimly lit. Remove any white, fuzzy eggs, which are infertile or fungused. A few alder cones or a small amount of methylene blue in a separate hatching container can help reduce fungus.\n\nFertile eggs stay clear and slowly darken as the fry develop."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry hang on the glass and plants living off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food several times a day\n- From about day 7 to 10: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Add a few snails or a sponge filter cleaning routine to deal with uneaten food, and use a light sponge-covered intake so fry are not pulled in."}, {"heading": "Growing Out", "text": "Fry grow steadily on frequent feedings. They reach about an inch by 2 to 3 months and show adult color at around 6 months.\n\nMove them into a larger grow-out tank as they grow and keep up regular water changes.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Black ruby barbs are schooling fish, so they do best raised in a group. Keep the stock pure and avoid crossing it with other barbs."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No mesh or moss to protect eggs\n- Bright light on the eggs, which encourages fungus\n- Feeding baby brine shrimp too early\n- Hard, alkaline water that reduces spawning success"}]$g$::jsonb, updated_at = now() where slug = $g$black-ruby-barb$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Giant danios grow to around 4 inches and are strong swimmers, so a 20 gallon long tank is a good breeding size. Cover the bottom with mesh or marbles and add lots of fine leaved plants or spawning mops.\n\nThe library range is {{temp}}°F and pH {{ph}}. Around 75 to 77°F with clean, well oxygenated water works well for spawning. A gentle sponge filter keeps the eggs safe.\n\nGiant danios are strong jumpers, especially during spawning chases. Keep a tight lid on the tank. Moderate oxygenation from a sponge filter keeps the water fresh without blowing eggs around.\n\nSome breeders spawn giant danios in a group of 6 or more in a larger tank planted heavily with fine leaved plants, then remove the adults after a day. This works, but a pair or trio in a smaller setup usually gives cleaner, easier to manage spawns."}, {"heading": "Choosing and Conditioning Fish", "text": "Females are deeper bodied and rounder, especially when full of eggs. Males are slimmer and often show brighter color.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Many breeders separate males and females during conditioning, then put them together in the spawning tank.\n\nPick mature fish, usually at least 2.5 to 3 inches long. Young or underweight fish often fail to spawn or produce small, weak clutches. Females should look visibly rounder after conditioning."}, {"heading": "Spawning: What You Will See", "text": "Move a female with one or two males into the spawning tank in the evening. Spawning often starts at first light.\n\nThe males chase the female through the plants, and the eggs are scattered. A mature female can often release a few hundred eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, try a water change with water a few degrees cooler, or return the fish to conditioning and try again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults once spawning ends.\n\nEggs usually hatch in about 24 to 48 hours around 77°F. Keep the lighting dim and remove any fungused eggs. Clean water and good oxygen help.\n\nMany eggs fall to the bottom during the chase, which is why the mesh or marbles matter. Look for small clear eggs between the marbles and on the plants. Unfertilized eggs turn white within a day."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning and cover the filter intake. Fry are small, so use a sponge filter only."}, {"heading": "Growing Out", "text": "Giant danio fry grow quickly and need room to swim. Move them into a larger tank as they grow.\n\nThey reach about an inch by 2 to 3 months, and adult size around 6 to 9 months.\n\nA 20 to 30 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group, since they are schooling fish."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- A tank that is too small for these active swimmers\n- No mesh or plants to protect eggs\n- Overfeeding the fry tank and fouling the water\n- Skipping infusoria and going straight to brine shrimp\n- Using small, immature fish that are not ready to spawn"}]$g$::jsonb, updated_at = now() where slug = $g$giant-danio$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is enough for a pair. Cover the bottom with mesh, marbles or java moss, and add a spawning mop or fine plants.\n\nThe library range is {{temp}}°F and pH {{ph}}. Around 74 to 77°F with clean, slightly soft water works well for spawning. Use a gentle sponge filter.\n\nA tight lid is a good idea, since spawning chases can be lively. Keep the lighting dim or use a few floating plants to soften it. Odessa barbs are fine at normal community water parameters, so you rarely need to change much.\n\nOdessa barbs come from Myanmar and are fairly hardy. Clean, well oxygenated water matters more than exact chemistry, and dim, natural lighting helps them settle quickly in a new tank."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males have a bright red stripe along the body and dark spots on the fins. Females are paler, silver to yellowish, and rounder when full of eggs.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Conditioning males and females separately often helps trigger a strong spawn.\n\nPick fish at least 1.5 inches long. The male's red stripe gets much brighter when he is ready to spawn, and females should look noticeably round in the belly after conditioning."}, {"heading": "Spawning: What You Will See", "text": "Introduce the pair or trio to the spawning tank in the evening. Spawning often starts at first light.\n\nThe male chases the female through the plants, and eggs are scattered. Spawns often produce a hundred or more eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, return the fish to conditioning and try again in a week. Adding a little fresh, slightly cooler water can help trigger spawning."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 48 hours around 75°F. Keep lighting dim and remove fungused eggs.\n\nEggs are small and slightly sticky. They are easy to miss, so look carefully at the moss and mesh. Unfertilized eggs turn white within a day and should be removed to stop fungus spreading. Fertile eggs stay clear and darken as the fry develop."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake, and feed small amounts often rather than a lot at once."}, {"heading": "Growing Out", "text": "Fry grow steadily with frequent feedings. They reach about an inch by 2 to 3 months and show adult color around 6 months.\n\nMove them into a larger tank as they grow and keep the water clean.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group, since they are schooling fish. Males start to show red as they mature."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in the tank after spawning\n- No mesh or moss to protect eggs\n- Feeding baby brine shrimp too early\n- Bright light on eggs, which encourages fungus\n- Overfeeding and fouling the fry tank\n- Using a tank with strong flow that pushes eggs into the filter"}]$g$::jsonb, updated_at = now() where slug = $g$odessa-barb$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 30 gallon tank, in line with our care data, works well for a pair or trio. Add caves that fit the male snugly, with one opening. Clay or ceramic caves are common. Add driftwood for grazing and good filtration, since plecos produce a lot of waste.\n\nThe library range is {{temp}}°F and pH {{ph}}. Bristlenose are adaptable and breed in a wide range of water, so you do not need to change much.\n\nMany breeders use several caves so the male can choose. A cave around 1.5 to 2 inches wide for an adult male, closed at one end, works well. Place caves in a quiet, slightly darker part of the tank."}, {"heading": "Choosing and Conditioning a Pair", "text": "Mature males have long, branched bristles across the snout. Females have few or no bristles, mostly along the edge of the head. Males are often a little larger with a broader head.\n\nCondition for 2 to 3 weeks with vegetables, algae wafers and some protein like bloodworms. A well fed female looks rounder from above.\n\nBristlenose usually mature by about 9 to 12 months. A pair with a well fed female will often spawn every few weeks once they start."}, {"heading": "Spawning: What You Will See", "text": "The male claims a cave and cleans it. When the female is ready, she joins him in the cave and lays a clump of sticky, orange eggs on the ceiling or walls.\n\nShe leaves, and the male stays to guard the eggs. Clutches commonly range from about 20 to 100 or more eggs depending on the female.\n\nYou may not see the spawning itself. Often the first sign is the female out and about again looking thinner, while the male stays tucked in the cave, fanning his tail at the entrance."}, {"heading": "Eggs and the Male's Care", "text": "The male fans the eggs with his fins and guards the cave entrance. Eggs usually hatch in about 4 to 7 days at around 77°F.\n\nAfter hatching, fry stay in the cave on their yolk sacs for several days. Avoid disturbing the cave, as a stressed male may abandon or eat eggs. A good, steady water flow helps.\n\nIf the male abandons the eggs or keeps pushing them out, some breeders hatch them in a container with gentle aeration. This is a backup plan, not the normal route."}, {"heading": "Raising the Fry", "text": "- Once they emerge, offer algae wafers and blanched zucchini or cucumber\n- Driftwood provides grazing surface and fiber\n- Feed small amounts several times a day\n- Remove leftover vegetables within a day\n- Regular water changes of 20 to 30 percent weekly\n\nFry need wood and plenty of greens. Adding a few pieces of driftwood to the grow-out tank helps with growth and digestion."}, {"heading": "Growing Out", "text": "Fry grow steadily on a vegetable based diet. They commonly reach about an inch by around 2 months and about 2 inches in roughly 3 to 5 months, depending on feeding and water changes.\n\nMove them to a grow-out tank if the breeding tank gets crowded, and keep driftwood in there too.\n\nBristlenose are prolific, so plan ahead. A good pair may spawn again every few weeks, and fry need room. Have a home for the young fish, whether through local clubs, auctions or fish stores."}, {"heading": "Common Mistakes", "text": "- Caves that are too large for the male to defend\n- Disturbing the cave while he guards eggs\n- Not enough driftwood or vegetables for the fry\n- Overcrowding and poor water quality\n- Underfeeding the female before spawning\n- Too few hiding places, which leaves the female stressed and less willing to spawn"}]$g$::jsonb, updated_at = now() where slug = $g$bristlenose-pleco$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or fine sand, a sponge filter and a few plants.\n\nThe library range is {{temp}}°F and pH {{ph}}. Keep the water clean and well oxygenated.\n\nBronze corydoras are hardy and breed in a wide range of water. A sponge filter is best so eggs and fry are not pulled in. Some fine leaved plants or a spawning mop give the female more surfaces to choose from, though most still pick the glass."}, {"heading": "Choosing and Conditioning a Group", "text": "Females are larger and rounder, especially when viewed from above. Males are slimmer.\n\nA ratio of 2 males to 1 female works well. Condition for 1 to 2 weeks on bloodworms, brine shrimp and sinking pellets.\n\nThe Venezuelan orange is a color form of Corydoras aeneus. Breed it with the same form, not with other color forms or species, if you want true to type fry.\n\nMature fish, usually around 1.5 to 2 inches, breed best. A well conditioned female looks noticeably broader across the body when viewed from above."}, {"heading": "Spawning: What You Will See", "text": "After a large, slightly cooler water change, the males chase the female. A male positions himself across her head in the famous T-position.\n\nThe female holds eggs in her pelvic fins and then sticks them to the glass, plants or decor. This repeats over a few hours. Spawns often total dozens to a few hundred eggs.\n\nIf a spawn does not follow the water change, repeat it daily for a few days. Spawning often happens in the morning or after the water change, and a group can spawn every week or two once they get going."}, {"heading": "Eggs and Fungus Prevention", "text": "Adults will eat eggs, so move the eggs or the adults after spawning. Eggs can be rolled off the glass gently with a finger or razor blade.\n\nEggs usually hatch in about 3 to 5 days around 75°F. Remove fungused eggs promptly and keep gentle aeration nearby. Some breeders use a small amount of methylene blue in a separate hatching container.\n\nEggs are about the size of a pinhead, clear at first and then darken. Unfertilized eggs turn white within a day or two. A small hatching container with an airstone, kept in the main tank to stay at the same temperature, works well."}, {"heading": "Raising the Fry", "text": "- Days 1 to 3: fry live on their yolk sacs\n- Days 3 to 10: microworms and crushed sinking foods\n- From about week 2: baby brine shrimp\n- Keep the bottom clean to prevent bacterial problems\n- Small water changes of 10 to 20 percent every few days\n\nCory fry are sensitive to dirty substrate. Siphon uneaten food daily and avoid deep gravel in the fry tank."}, {"heading": "Growing Out", "text": "Fry grow steadily on frequent small feedings. They reach about an inch by 2 to 3 months.\n\nA bare bottom tank makes it easier to keep clean during grow-out.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day with crushed pellets and baby brine shrimp. Raise them in a group, since corydoras are social.\n\nThe orange coloring often shows within the first few weeks and deepens as the fry grow. Juveniles can join a community tank once they are too large to be eaten, usually around an inch."}, {"heading": "Common Mistakes", "text": "- Leaving eggs with the adults\n- Not removing fungused eggs quickly\n- Dirty bottoms that harm the fry\n- Overfeeding\n- Skipping the cool water change trigger"}]$g$::jsonb, updated_at = now() where slug = $g$venezuelan-orange-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or fine sand, a sponge filter and some plants.\n\nThe library range is {{temp}}°F and pH {{ph}}. Peppered cories like cooler water than many tropicals, so do not overheat the tank.\n\nA sponge filter is best so eggs and fry are not pulled in. Fine leaved plants or a spawning mop give the female surfaces to choose from, though most eggs end up on the glass. Room temperature works in many homes, but avoid letting the water get above the mid 70s °F."}, {"heading": "Choosing and Conditioning a Group", "text": "Females are larger and rounder. Males are slimmer and often have a taller dorsal fin.\n\nCondition for 1 to 2 weeks with bloodworms, brine shrimp and sinking pellets.\n\nMature fish, usually around 2 inches, breed best. A well conditioned female looks noticeably broader across the body when viewed from above. Use a group with more males than females, such as 2 males to 1 female."}, {"heading": "Spawning: What You Will See", "text": "A large cool water change often triggers spawning. Males chase the female and use the T-position.\n\nShe sticks eggs to the glass and plants in batches. Spawns often total dozens to a few hundred eggs.\n\nUse water a few degrees cooler than the tank for the water change, and change a large amount, often 30 to 50 percent. Some breeders also increase aeration. If nothing happens, repeat daily for a few days. Peppered cories often spawn in the morning, and a group can spawn every week or two once they start."}, {"heading": "Eggs and Fungus Prevention", "text": "Move the eggs or the adults after spawning. Eggs usually hatch in about 4 to 6 days at around 72°F.\n\nRemove fungused eggs promptly and keep gentle aeration nearby.\n\nEggs are about the size of a pinhead, clear at first, then darken. Unfertilized eggs turn white within a day or two. A small hatching container with an airstone, kept in the main tank to hold temperature, works well. Some breeders add a small amount of methylene blue to the hatching container."}, {"heading": "Raising the Fry", "text": "- Days 1 to 3: fry live on their yolk sacs\n- Days 3 to 10: microworms and crushed sinking foods\n- From about week 2: baby brine shrimp\n- Keep the bottom clean\n- Small water changes every few days\n\nCory fry are sensitive to dirty substrate. Siphon uneaten food daily and avoid deep gravel. A bare bottom or thin sand layer makes cleaning easier. Feed small amounts 3 to 4 times a day.\n\nKeep the fry at the same cool temperature as the breeding tank, around 70 to 72°F, and avoid sudden temperature swings."}, {"heading": "Growing Out", "text": "Fry reach about an inch by 2 to 3 months. Keep the water cool and clean.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed with crushed pellets and baby brine shrimp. Raise them in a group, since corydoras are social. Fry develop their peppered spots as they grow.\n\nPeppered corydoras are also bred as albino and long-finned forms. These breed the same way, though long-finned fish need clean water to keep their fins healthy. Keep forms separate if you want true to type fry."}, {"heading": "Common Mistakes", "text": "- Keeping them too warm\n- Leaving eggs with adults\n- Not removing fungused eggs\n- Dirty bottoms\n- Overfeeding\n- Expecting warm tropical temperatures to trigger spawning, when cooler water works better for this species\n- Moving eggs into water much warmer than the tank they came from"}]$g$::jsonb, updated_at = now() where slug = $g$peppered-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use mesh, marbles or java moss on the bottom and add fine leaved plants or a spawning mop.\n\nThe library range is {{temp}}°F and pH {{ph}}. For spawning, aim for soft, slightly acidic water around pH 6.5 and about 77 to 79°F. Use a gentle sponge filter and dim lighting.\n\nBlack skirts are not fussy about water for everyday keeping, but soft water does improve egg hatching. If your tap water is hard, mixing in some RO or rain water for the spawning tank is a common approach.\n\nBlack skirts are strong swimmers and can be a little nippy. In the spawning tank they will focus on each other, but keep them alone, with no other fish, to protect the eggs."}, {"heading": "Choosing and Conditioning a Pair", "text": "Females are rounder and deeper bodied, especially when full of eggs. Males are slimmer and often have a broader anal fin.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Healthy, well fed fish give the best spawns.\n\nChoose fish that are at least an inch and a half long and healthy, with full fins. Mature fish around a year old spawn best. Condition males and females separately for a stronger spawn."}, {"heading": "Spawning: What You Will See", "text": "Introduce the pair or trio to the spawning tank in the evening. Spawning often happens the next morning.\n\nThe male chases the female through the plants, and eggs are scattered. Spawns can be large, often several hundred eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, try a partial water change with slightly softer water, or return the fish to conditioning and try again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 36 hours around 77°F. Keep the tank dim and remove fungused eggs.\n\nEggs are small and slightly sticky. Check the plants and mesh carefully. Unfertilized eggs turn white within a day and should be removed. Fertile eggs stay clear. Many breeders keep the tank dark until the eggs hatch, which also helps limit fungus."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake and feed small amounts often. Infusoria cultures should be started a week before spawning so they are ready when needed."}, {"heading": "Growing Out", "text": "Large spawns mean lots of fry. Spread them out as they grow so the water stays clean.\n\nFry reach about an inch by 2 to 3 months and adult size around 6 months.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Fry develop their black color as they grow.\n\nLong-finned and colored forms of black skirt tetras are common in the trade. If you breed one of these, keep it with the same form so the fry come out true to type. Avoid buying or breeding artificially dyed or tattooed fish."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No protection for the eggs\n- Bright light on the eggs\n- Not enough food for a large spawn\n- Overcrowding the grow-out tank\n- Using small, immature fish that are not ready to spawn\n- Hard water that reduces hatch rates"}]$g$::jsonb, updated_at = now() where slug = $g$black-skirt-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank works well. Use mesh or marbles on the bottom and add plants or a spawning mop.\n\nThe library range is {{temp}}°F and pH {{ph}}. Aim for around 72 to 77°F for spawning. Use a gentle sponge filter.\n\nBlind cave tetras are hardy and not fussy about water chemistry. A tight lid is useful, as spawning chases can be energetic. Lighting does not matter much to the adults, but dim light helps reduce fungus on the eggs."}, {"heading": "Choosing and Conditioning Fish", "text": "Females are rounder and deeper bodied, especially when full of eggs. Males are slimmer.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods.\n\nPick mature fish, at least 2 to 2.5 inches long. Healthy females should look visibly round after conditioning. Because they find food by smell and their lateral line, make sure food sinks where they can find it."}, {"heading": "Spawning: What You Will See", "text": "Introduce the fish to the spawning tank and do a slightly cooler water change. Spawning often happens at night or early morning.\n\nThe fish chase and scatter eggs. Spawns can be large, often several hundred eggs.\n\nSpawning often lasts a couple of hours. Breeders report spawning is frequently triggered by a drop in temperature of a few degrees from a water change. If nothing happens in 2 to 3 days, return the fish to conditioning and try again.\n\nA group with one female and two males often works well. Watch for the males closely following the female along the plants or bottom, which is the sign spawning is about to start."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 48 hours. Keep the tank dim and remove fungused eggs.\n\nEggs are small and slightly sticky and fall into the mesh or plants. Unfertilized eggs turn white within a day and should be removed. Fertile eggs stay clear. A small amount of methylene blue in a separate hatching container can help reduce fungus."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake and feed small amounts often. Start infusoria cultures a week before spawning."}, {"heading": "Growing Out", "text": "Fry grow steadily. They are born with eyes, which gradually regress and become covered by skin as they grow.\n\nThey reach about an inch by 2 to 3 months and adult size around 6 to 9 months.\n\nA 20 to 30 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group.\n\nBlind cave tetras are fun to watch as they grow. Fry hunt by scent and touch as well as sight early on, and adults rely on their lateral line to navigate. They are long lived and hardy, which makes them a good fish to share with other hobbyists.\n\nKeep the grow-out tank uncrowded. Blind cave tetras are active and can be pushy at feeding time, so spread food across the tank so smaller fish get their share."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No protection for eggs\n- Overfeeding and fouling the fry tank\n- Feeding baby brine shrimp too early\n- Not spreading out a large spawn\n- Using small, immature fish that are not ready to spawn"}]$g$::jsonb, updated_at = now() where slug = $g$blind-cave-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank is plenty for a pair or trio. Keep the water fairly shallow, around 6 to 8 inches, because bloodfins often spawn near the top and the eggs need to drop quickly out of reach.\n\nCover the bottom with a layer of marbles, plastic mesh or a sheet of egg crate topped with java moss or spawning mops. The goal is a floor the eggs can fall through but the adults cannot reach. Use a gentle sponge filter and a heater set to about 77 to 80°F. Bloodfins are not fussy about water: anything inside the library range of pH {{ph}} works, and many breeders use slightly softer, slightly acidic water around pH 6.5 to 7 for the spawning tank. Put the tank where it gets morning light, since spawning usually starts at first light."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing is easiest in mature fish of about 1.5 inches. Females are deeper and rounder through the belly, especially when full of eggs. Males are slimmer and often show stronger red in the fins. Males also carry tiny hooks on the anal fin that can snag in a net, which is a handy check.\n\nSeparate the sexes for 1 to 2 weeks and feed generously two or three times a day with frozen bloodworms, brine shrimp, daphnia and a good flake. Pick the plumpest female and one or two of the most colorful males. Move them into the breeding tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Most spawns happen the next morning. The male chases the female hard, then the pair swim side by side, often near the surface or over the plants, and release eggs and milt with a quiver. This repeats many times over a few hours. Eggs are small, clear and non-adhesive, and they drift down into the mesh or moss.\n\nIf nothing happens in 2 or 3 days, do a 20 to 30 percent water change with slightly cooler water. As soon as the female looks thin and the chasing stops, take both adults out. They will eat every egg they can find."}, {"heading": "Eggs and fungus", "text": "At 77 to 80°F the eggs hatch in about 24 to 36 hours. Unfertilized eggs turn white within a day and can grow fungus that spreads to good eggs. Keep the light dim for the first two days, keep a little water movement from the sponge filter, and siphon out white eggs with a pipette where you can. Some breeders add a few drops of methylene blue, but clean water and good aeration do most of the work.\n\nThe new hatchlings hang on the glass and plants, living off their yolk sacs. Leave them alone and do not feed yet."}, {"heading": "Raising the fry", "text": "About 3 to 5 days after hatching, the fry start swimming level and hunting. They are tiny, so the first foods must be tiny too.\n\n- Week 1: infusoria, green water or a fine powdered fry food, a few times a day in small amounts.\n- Week 2: add microworms and newly hatched brine shrimp once you see them taking the bigger food.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nChange 10 to 20 percent of the water every day or two from week two on, matching the temperature carefully. Keep the sponge filter running and siphon uneaten food. A few ramshorn snails help clean up."}, {"heading": "Growing out", "text": "With frequent feeding and clean water, fry reach half an inch in about 6 weeks and a sellable 1 inch in roughly 3 to 4 months. Move them to a bigger tank as they grow, since crowding slows growth. The red in the fins develops gradually as they grow. Spread out several meals a day and keep up with water changes: those two things decide how fast they grow."}, {"heading": "Common mistakes", "text": "- Leaving the parents in too long. The eggs disappear within hours.\n- Feeding brine shrimp too early. Most fry cannot swallow it for the first week.\n- Deep water with no mesh, so the adults catch eggs on the way down.\n- Big water changes on day one or two, which stress fragile hatchlings.\n- Overfeeding powdered food in a bare tank, which fouls the water fast."}]$g$::jsonb, updated_at = now() where slug = $g$bloodfin-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and a heater set around 75 to 79°F. These fish nibble live plants, so most breeders use synthetic spawning mops or a thick clump of java moss, which they leave alone.\n\nCover the bottom with marbles or a raised mesh so eggs drop out of reach. The library range of pH {{ph}} and GH {{gh}} suits them, and they spawn readily in ordinary tap water inside that range. A slightly softer fill, around pH 6.5 to 7, is a common choice for the spawning tank but is not required. Give the tank a tight lid: these are active, jumpy fish."}, {"heading": "Conditioning and choosing a pair", "text": "Adults are easy to sex once they reach about 2 inches. Males are slimmer, with brighter red in the fins. Females are larger, deeper bodied and noticeably round when full of eggs.\n\nSeparate males and females for 1 to 2 weeks. Feed two or three times daily with frozen bloodworms, brine shrimp, mysis, quality flake and some blanched spinach or a vegetable flake, since they are true omnivores. Pick the fullest female and an active, colorful male, and introduce them to the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts the next morning. The male drives the female into the mops or moss, the pair press together and scatter eggs, and this repeats for an hour or two. Eggs are slightly sticky and catch on the mops or fall through the mesh.\n\nOnce the female is slim and the chasing has stopped, remove both adults. If they have not spawned after 3 days, try a 25 percent change with slightly cooler water, or return them to conditioning for another week and try again."}, {"heading": "Eggs and fungus", "text": "At 75 to 79°F the eggs hatch in about 24 to 36 hours. Expect a share of infertile eggs, which turn white and fuzzy. Keep the tank dim, keep gentle aeration running, and pick out white eggs with a pipette if you can reach them. A few drops of methylene blue in the spawning tank is a common precaution, though clean water matters most.\n\nThe hatchlings hang on the mops and glass for a few days while they use up the yolk. Do not feed them yet."}, {"heading": "Raising the fry", "text": "The fry are free swimming about 3 to 5 days after hatching. With a large spawn, food and water quality become the main challenges.\n\n- Days 1 to 7 free swimming: infusoria, green water or powdered fry food, small amounts several times a day.\n- Week 2: add microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules, plus a little vegetable flake.\n\nFrom week two, change 10 to 20 percent of the water daily or every other day. If you have hundreds of fry, split them into more tanks early, since crowding causes losses and stunting."}, {"heading": "Growing out", "text": "Buenos Aires tetras grow fast. With heavy feeding they reach about 1 inch in roughly 3 months, and they can be sold at 1 to 1.5 inches. Their appetite for plants carries into the grow-out tank, so use hardy plants such as java fern or anubias, or none. Keep the young fish in a decent sized group: they get nippy when crowded or bored."}, {"heading": "Common mistakes", "text": "- Using soft live plants that get eaten before the spawn happens.\n- Leaving adults with the eggs for even a few hours.\n- Feeding brine shrimp before fry can swallow it.\n- Keeping hundreds of fry in one small tank.\n- Skipping water changes because the fry look fine. Losses usually come suddenly."}]$g$::jsonb, updated_at = now() where slug = $g$buenos-aires-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 15 gallon tank is enough. Serpaes spawn best in soft, slightly acidic water. The library range runs from pH {{ph}}, and for spawning most breeders aim for about pH 6 to 6.5 and low hardness, using RO or rain water mixed with tap water. Set the heater to 77 to 80°F.\n\nKeep the light dim: cover the sides with paper or use floating plants. Add fine leaved plants, java moss or spawning mops, and cover the bottom with mesh or marbles so eggs fall out of reach. A small sponge filter on low flow is all you need."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing serpaes takes a careful look. Males are slimmer and usually show deeper red color. Females are rounder and often a little paler, and a ripe female is clearly full through the belly. Comparing fish side by side in a group is the easiest way.\n\nSeparate the sexes for 1 to 2 weeks and feed well with frozen bloodworms, brine shrimp, daphnia and a good flake. Put the best pair, or two males with one female, into the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens the next morning. The male displays and drives the female into the plants, and the pair press together and scatter eggs in short bursts. The session can last a couple of hours.\n\nRemove the adults as soon as the female looks slim. If nothing happens after 2 or 3 days, a small change with soft, slightly cooler water often triggers them. If they still will not spawn, condition them for another week and check that the water is soft enough."}, {"heading": "Eggs and fungus", "text": "Eggs hatch in about 24 to 48 hours at 77 to 80°F. Serpae eggs are sensitive to light, so keep the tank dim for the first few days. Infertile eggs turn white and can grow fungus. Remove them with a pipette when you can, keep gentle aeration running, and avoid large water changes during this stage.\n\nAfter hatching the fry hang on the glass and plants for several days while they absorb the yolk."}, {"heading": "Raising the fry", "text": "The fry swim freely about 3 to 5 days after hatching and are very small.\n\n- Week 1: infusoria, green water or a fine liquid or powdered fry food several times a day.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and small granules.\n\nStart small water changes of 10 to 20 percent every day or two from the second week, using water matched in temperature and softness. Sudden jumps in hardness or pH are a common cause of losses. Keep the light gentle for the first couple of weeks."}, {"heading": "Growing out", "text": "Fry grow steadily with frequent meals. Expect about half an inch at 6 weeks and a sellable 1 inch at roughly 3 to 4 months. Red color develops gradually over the first couple of months. As they grow, you can slowly shift them toward your normal tap water. Keep them in a good sized group with plenty of space, which helps reduce the nipping serpaes are known for."}, {"heading": "Common mistakes", "text": "- Water that is too hard. Eggs may not develop well.\n- Bright light on the eggs and fry.\n- Leaving the adults in the tank after spawning.\n- Offering brine shrimp before the fry can eat it.\n- Changing large amounts of water with a different pH or hardness."}]$g$::jsonb, updated_at = now() where slug = $g$serpae-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank is enough for a pair. X-ray tetras tolerate a wide range, pH {{ph}} in the library, but they spawn most reliably in softer, slightly acidic water. Many breeders aim for about pH 6.5 to 7 with low hardness for the spawning tank. Keep the temperature at 77 to 80°F.\n\nAdd java moss, fine leaved plants or spawning mops and a bottom layer of marbles or mesh. Keep the light low and run a gentle sponge filter. The eggs are small and will be eaten quickly if they can be reached."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and rounder in the belly, and when full of eggs the difference is clear. Males are slimmer. Some keepers note that the male's body cavity looks more pointed at the rear, but comparing body shape in mature fish is the reliable test.\n\nSeparate the sexes for 1 to 2 weeks and feed two or three times a day with frozen and live foods such as bloodworms, daphnia and brine shrimp, plus a good flake. Move the best pair into the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts early the next morning. The male chases the female into the plants, they swim side by side and release eggs and milt, and this repeats for an hour or more. The eggs scatter into the moss and fall through the mesh.\n\nTake the adults out once the female is slim. If they have not spawned after 2 or 3 days, a small change with softer, slightly cooler water often helps."}, {"heading": "Eggs and fungus", "text": "At 77 to 80°F the eggs hatch in about 24 to 36 hours. Keep the tank dim, keep gentle aeration running, and remove any white, fuzzy eggs with a pipette so fungus does not spread. Avoid big water changes for the first few days.\n\nThe newly hatched fry cling to the glass and plants and are nearly invisible. Be patient: they live off their yolk for several days."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 4 to 5 days after hatching. They are among the smaller tetra fry, so start very small.\n\n- Week 1: infusoria, green water or a fine powdered fry food, small amounts several times daily.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nFrom the second week, change 10 to 20 percent of the water every day or two, matched in temperature. A bare bottom or a thin layer of sand makes it easier to siphon leftover food."}, {"heading": "Growing out", "text": "X-ray tetras grow at a steady pace. Expect half an inch at about 6 weeks and a sellable 1 inch at 3 to 4 months. The yellow, black and white fin pattern starts to show early. Keep feeding several small meals a day and give them more space as they grow. They can be moved gradually to harder tap water once they are a few weeks old.\n\nIf you want another spawn, put the parents back on conditioning foods right away. A rested, well fed pair can usually be spawned again in about 2 to 3 weeks, which lets you keep batches spaced out and tanks from getting crowded."}, {"heading": "Common mistakes", "text": "- Trying to spawn them in hard, alkaline water with poor results, then giving up.\n- Bright light on eggs and fry.\n- Leaving the adults with the eggs.\n- Starting with brine shrimp too early.\n- Overfeeding and not siphoning, which fouls a small fry tank quickly."}]$g$::jsonb, updated_at = now() where slug = $g$x-ray-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long is a good minimum for a pair. Use sand or fine gravel, a few plants, and one or two caves: half a clay flowerpot on its side or a coconut shell with an entrance just big enough for the female. Keep the temperature at 78 to 80°F, inside the library range of {{temp}}°F, and the pH between about 6.5 and 7.5.\n\nA small school of fast, peaceful dither fish helps the pair feel safe and spreads out their aggression, but they will be chased hard once fry arrive. Run a sponge filter or cover the filter intake with a sponge so fry are not sucked in."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing kribs is easy in adults. Females are smaller, rounder and develop a bright cherry red belly when ready. Males are larger, more elongated, and have longer, pointed dorsal and anal fins. Females usually have a rounded dorsal fin.\n\nThe best pairs form naturally. Raise five or six young fish together, or let a male and female settle in the breeding tank and watch for them shimmying and displaying to each other. Feed well for 1 to 2 weeks with frozen brine shrimp, bloodworms, daphnia and quality pellets. If the pair fights rather than displays, separate them and try another combination."}, {"heading": "Spawning: what you will see", "text": "The female does most of the courting. She bends her body into a U shape to show off her red belly and leads the male to the cave. The pair dig out the cave and the female lays her eggs on the inside wall or ceiling, often out of sight. The male fertilizes them and then guards the territory outside.\n\nThe first sign you get is usually that the female disappears into the cave and stays there, coming out only briefly to chase off intruders."}, {"heading": "Eggs and early care", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The female fans them and removes any bad eggs herself, so leave the cave alone. Do not lift the pot to check: disturbed pairs often eat their spawn.\n\nAfter hatching, the wrigglers stay in the cave for several more days. About 4 to 7 days after hatching they come out as a free-swimming cloud, and both parents herd and guard them around the tank."}, {"heading": "Raising the fry", "text": "Krib fry are large enough to take newly hatched brine shrimp and microworms from the first day they swim.\n\n- Weeks 1 to 2: newly hatched brine shrimp and microworms two to four times a day, plus a pinch of powdered fry food.\n- Weeks 3 to 4: add crushed flake and fine granules.\n- Weeks 5 to 8: small pellets and frozen foods.\n\nChange 15 to 25 percent of the water twice a week, siphoning gently around the fry. Keep the temperature steady. It is commonly reported that pH and temperature during development can skew krib sex ratios, so keep conditions moderate rather than extreme."}, {"heading": "Growing out", "text": "The parents usually guard the fry for several weeks. Once the fry are around 4 to 6 weeks old, or when the parents start preparing to spawn again and chase the youngsters, move the fry to a grow-out tank. With good feeding they reach a sellable 1 to 1.5 inches in about 2 to 3 months. You can usually start telling the sexes apart at around 3 months."}, {"heading": "Common mistakes", "text": "- Forcing two random fish together. A mismatched pair can fight badly.\n- Checking the cave every day. Stress leads to eaten eggs.\n- Leaving fry with the parents too long, so the next spawn is lost or the fry get hurt.\n- No sponge on the filter intake.\n- Keeping kribs with other bottom dwellers in a small tank, which leads to injuries during breeding."}]$g$::jsonb, updated_at = now() where slug = $g$kribensis$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 15 gallon tank works well. Fill a large part of it with java moss or other fine leaved plants, or use several spawning mops. Cherry barbs spread their spawning over several days, laying a few eggs at a time in the plants.\n\nKeep the temperature at 77 to 80°F, inside the library range of {{temp}}°F, and the pH around 6.5 to 7, which is within their 6 to 7.5 range. A sponge filter on low flow is ideal. Gentle light and some floating plants help the fish feel secure."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy once fish are mature and in color. Males turn a rich cherry red, especially when displaying. Females are tan to brown with a darker stripe along the side and a rounder belly. Young or stressed males can look washed out, so give them time to color up.\n\nCondition one male and two or three females on frozen bloodworms, brine shrimp, daphnia and a good flake for 1 to 2 weeks. Using more than one female spreads out the male's attention."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts in the morning. The male turns deep red, flares his fins and leads a female into the moss. They swim side by side and she releases a few eggs at a time, which stick to the plants. This repeats through the morning and over several days.\n\nAfter 3 to 5 days, either remove the adults or lift the moss with its eggs into a separate hatching tank with the same water. Then add fresh moss for the next round if you want to keep collecting."}, {"heading": "Eggs and fungus", "text": "Eggs are small and clear, and hatch in about 24 to 48 hours at 77 to 80°F. Infertile ones turn white within a day. Keep the hatching tank dim, with gentle aeration, and pick out white eggs where you can. Thick moss helps here too, since it hides good eggs from adults and keeps fungus from spreading as easily.\n\nAfter hatching, the fry hang in the moss for a few days while they finish their yolk."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 2 to 4 days after hatching.\n\n- Week 1: infusoria, green water or powdered fry food. Moss tanks grow their own microfauna, which helps.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nChange 10 to 20 percent of the water every two or three days from week two, matching temperature. Because eggs are laid over several days, expect mixed sizes. Make sure the smallest fry still get fine food."}, {"heading": "Growing out", "text": "Cherry barbs grow at a moderate pace. Expect about half an inch at 6 to 8 weeks and a sellable 1 inch at around 3 to 4 months. Males usually begin to show red as they mature, often from around 3 months. Keep the young fish in a planted tank with regular water changes and several small meals a day for the best color and growth.\n\nWhile the fry grow, the adults can go straight back to conditioning. Because cherry barbs spawn in small batches, many breeders simply rotate moss: lift a clump with eggs every few days into a hatching tank and replace it with fresh moss. This gives a steady supply of fry of similar age in each tank."}, {"heading": "Common mistakes", "text": "- Too little moss, so the adults find most of the eggs.\n- Leaving the adults in for weeks and getting few fry.\n- Starting with brine shrimp before fry can eat it.\n- Assuming a pale male is a female.\n- Big temperature swings during water changes."}]$g$::jsonb, updated_at = now() where slug = $g$cherry-barb$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and the heater set to 77 to 80°F, inside the library range of {{temp}}°F. Fill part of the tank with java moss, fine leaved plants or spawning mops, and cover the bottom with marbles or plastic mesh so eggs fall out of reach.\n\nTiger barbs spawn well in water inside their pH 6 to 7.5 range. Many breeders use somewhat softer water, around pH 6.5 to 7, for the spawning tank. Give the tank morning light if possible."}, {"heading": "Conditioning and choosing a pair", "text": "Mature males are slimmer and show a bright red snout, red edging on the fins and more intense color overall. Females are rounder, especially when full of eggs, and their colors are a little duller. These differences show clearly in fish over about 1.5 inches.\n\nSeparate the sexes for 1 to 2 weeks and feed heavily with frozen bloodworms, brine shrimp, daphnia and flake. Choose a plump female and an active male, or one male with two females. Move them in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts at first light. The male chases the female and drives her into the plants, the pair swim close together and scatter eggs, and this repeats for a couple of hours. The eggs are sticky and cling to plants or fall to the bottom.\n\nRemove both adults as soon as spawning ends. If they have not spawned in 2 or 3 days, do a 25 percent change with slightly cooler water. Watch the male: an overly hard chaser can injure a female that is not ready."}, {"heading": "Eggs and fungus", "text": "Eggs hatch in about 24 to 48 hours at 77 to 80°F. Expect some infertile eggs that turn white. Keep gentle aeration, dim the lights, and remove white eggs where practical. Some breeders add a small dose of methylene blue to the spawning tank to slow fungus.\n\nThe new fry hang on the glass and plants for a few days while their yolk sacs are used up."}, {"heading": "Raising the fry", "text": "Tiger barb fry become free swimming about 3 to 5 days after hatching.\n\n- Week 1: infusoria, green water or powdered fry food several times a day.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nStart 10 to 20 percent water changes every day or two from the second week. With a big spawn, split the fry into more than one tank by week three or four. Crowding is the most common reason growth stalls."}, {"heading": "Growing out", "text": "Tiger barbs grow fast with regular feeding. Fry reach about half an inch at 5 to 6 weeks and a sellable 1 inch at around 3 months. The black bands appear early and the red develops as they mature. Keep juveniles in a large group, which spreads out their natural nipping and chasing.\n\nMove the fry into a larger grow-out tank of 20 gallons or more by about 6 weeks. Feed three or four small meals a day of crushed flake, granules and frozen foods, and change 25 to 30 percent of the water weekly. Pick out any fry with bent spines or missing fins before you sell or trade, so only healthy fish leave your tanks."}, {"heading": "Common mistakes", "text": "- Leaving the adults in after spawning.\n- Too few plants or no mesh, so eggs are eaten as they fall.\n- Brine shrimp offered before fry can swallow it.\n- Keeping hundreds of fry in one small tank.\n- Pairing a pushy male with an unripe female, which leads to injury."}]$g$::jsonb, updated_at = now() where slug = $g$tiger-barb$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for a breeding group. The most important feature is a fine sand bottom at least 1 to 2 inches deep. Baby assassin snails spend their early life buried, and coarse gravel makes this much harder for them.\n\nKeep the water warm and hard, matching the library range of {{temp}}°F, pH {{ph}} and GH {{gh}}. Calcium is important for shell growth, so do not use soft RO water without remineralizing it. Add rocks, wood or glass surfaces for egg laying and use a sponge filter. Avoid fish that pick at snails, along with any loaches or puffers."}, {"heading": "Conditioning and choosing a group", "text": "Assassin snails are not hermaphrodites. Each snail is male or female, and there is no reliable way to tell them apart by looking. The simplest approach is to keep a group of five or more adults, which almost always includes both sexes.\n\nFeed them well. Their natural diet is other snails, so add a steady supply of small pond, bladder or ramshorn snails from a separate culture. They also take sinking protein foods such as bloodworms, shrimp pellets and fish food pellets. Well fed adults breed far more often than hungry ones."}, {"heading": "Mating and egg laying", "text": "Mating pairs lock together, one riding on the other's shell, and can stay that way for several hours. Do not separate them.\n\nAfter mating, females lay small, clear, roughly square capsules on hard surfaces such as glass, rocks, wood and filters. Each capsule holds a single egg, and you can see a small yellow dot inside. Expect only a few capsules at a time, spread out over weeks. This slow pace is why assassin snails never overrun a tank."}, {"heading": "Eggs and development", "text": "Development is slow and depends on temperature. Breeders commonly report hatching in about 3 to 6 weeks, quicker at the warmer end of the range. You can watch the dot inside each capsule grow and take shape.\n\nLeave the capsules where they are. They are tough and rarely bothered by other snails. Avoid scraping the glass where they sit, and keep water parameters steady."}, {"heading": "Raising the babies", "text": "Newly hatched snails are tiny and dig straight into the sand. You may not see them again for weeks or months. They feed on detritus, leftover protein food and very small snails.\n\n- Keep feeding the tank lightly with sinking protein foods even when no adults are hungry.\n- Keep small prey snails in the tank so their tiny babies are available as food.\n- Do not vacuum the sand deeply; skim only the surface.\n- Do small, regular water changes and keep calcium up.\n\nThe juveniles usually reappear when they are around a quarter inch long, often months after hatching."}, {"heading": "Growing out", "text": "Growth is slow compared to most snails. Juveniles are commonly reported to take several months to emerge and longer to reach adult size of nearly an inch. Their banded shells are visible once they surface. They are ready to rehome once they are actively hunting and around half an inch. Count your young carefully before selling, since many may still be buried."}, {"heading": "Common mistakes", "text": "- Gravel instead of fine sand, which makes it hard for babies to survive.\n- Soft water with little calcium, leading to weak shells.\n- Deep vacuuming that pulls out hidden babies.\n- Underfeeding, so adults stop laying.\n- Giving up too soon. Babies can stay out of sight for months.\n- Copper based medicines or plant products, which kill snails."}]$g$::jsonb, updated_at = now() where slug = $g$assassin-snail$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Give each adult at least 20 gallons. Use a sand or fine gravel bottom, plenty of caves, PVC pipes and rock piles, and a tight lid with every gap covered. These crayfish climb filter tubes and cords and escape easily.\n\nKeep water inside the library range of {{temp}}°F, pH {{ph}} and GH {{gh}}. Moderate hardness and enough calcium are vital for molting. A temperature around 70 to 75°F suits breeding well. Use a sponge filter or cover intakes so juveniles are not sucked in."}, {"heading": "Sexing and pairing", "text": "Flip a crayfish gently or look from below. Males have the first two pairs of swimmerets modified into hard, white, forward-pointing rods called gonopods. Males also tend to have larger claws. Females have soft swimmerets and a small round opening between the last pairs of walking legs.\n\nElectric blue crayfish are solitary and can be aggressive. Add the male to the female's tank only for mating, ideally a few days after she has molted and hardened. Watch closely and remove the male if fighting goes beyond brief sparring."}, {"heading": "Mating and egg laying", "text": "During mating, the male flips the female onto her back and holds her claws while he passes a sperm packet. This can last several minutes to more than an hour and looks rough. Remove the male afterward.\n\nOver the following days or weeks, the female hides, cleans her underside and lays her eggs, which she attaches to her swimmerets. She is now berried. You will see her fanning the eggs constantly to keep them oxygenated. Keep her alone and undisturbed."}, {"heading": "Eggs and incubation", "text": "The eggs are carried for about 3 to 5 weeks, faster in warmer water. They start dark and become clearer as the young develop, and you may see eyes near the end. A female that is stressed or handled roughly may drop her eggs, so keep the lights steady and avoid big water changes. Do small water changes of 10 to 15 percent once a week."}, {"heading": "Raising the juveniles", "text": "When the eggs hatch, the tiny crayfish stay attached under the mother's tail for 1 to 2 weeks and molt there. Then they begin walking off on their own. At this stage, move the mother back to her own tank, since she may eat the young.\n\n- Week 1 on their own: crushed sinking pellets, blanched vegetables, leaf litter and biofilm.\n- Weeks 2 to 6: small sinking pellets, frozen foods and vegetables.\n- Provide many tiny hides: moss, leaf litter and small pipes.\n\nJuveniles eat each other, especially when one is soft after molting. Plenty of hiding spots and steady feeding keep losses down."}, {"heading": "Growing out", "text": "Juveniles molt often and grow quickly. Expect around an inch in about 2 to 3 months in good conditions. Separate the larger ones as they grow, since size differences increase cannibalism. Rehome them before they reach adult size and begin territorial fights. Never release crayfish into ponds, streams or drains.\n\nGive the mother a few weeks of rest and good food before pairing her again. Females that breed back to back without recovering can struggle with their next molt."}, {"heading": "Common mistakes", "text": "- Leaving the male in after mating, risking injury to the female.\n- Too few hides for juveniles, leading to heavy losses.\n- Soft water with low calcium, causing failed molts.\n- Gaps in the lid, letting crayfish escape.\n- Handling the berried female, which can make her drop her eggs."}]$g$::jsonb, updated_at = now() where slug = $g$electric-blue-crayfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Keep a group of 5 to 10 ghost shrimp in a 5 to 10 gallon tank with a sponge filter, plants and hides. Water inside the library range works well: 72 to 78°F for breeding, pH {{ph}} and GH {{gh}}.\n\nSet up a second small tank, around 2 to 5 gallons, for the larvae. Use an air stone or a sponge filter on very low flow, no gravel, some java moss and the same water as the main tank. Let it age a couple of weeks to grow some biofilm."}, {"heading": "Sexing and conditioning", "text": "Females are larger, with a deeper underside where they carry eggs. Mature females often show a green saddle of developing eggs in the body. Males are smaller and slimmer.\n\nFeed a varied diet: sinking pellets, algae wafers, blanched spinach or zucchini and frozen foods. Well fed females in stable water breed regularly.\n\nBe aware that shrimp sold as ghost shrimp are sometimes mixed species. Some types need brackish water for larvae. If your larvae fail despite good care, that may be the cause."}, {"heading": "Spawning: what you will see", "text": "After mating, the female carries her eggs under her tail, attached to her swimmerets. They are small, green and easy to see through her clear body. She fans them often.\n\nThe eggs are carried for about 2 to 3 weeks. When you see tiny dark eyes in the eggs, move the female to the larvae tank. Use a cup, not a net, to reduce the chance she drops her eggs."}, {"heading": "Hatching and larvae", "text": "The eggs hatch into tiny swimming larvae that look nothing like adults. They drift and swim in the open water. Return the female to the main tank once the eggs are gone, since adults eat larvae.\n\nThe larvae go through several stages before taking adult form, which breeders commonly report takes about 1 to 3 weeks, depending on temperature. During this time, they cannot handle filter intakes and need very fine food."}, {"heading": "Raising the larvae", "text": "- Days 1 to 7: infusoria, green water and very fine powdered fry food several times a day in small amounts.\n- Week 2: continue fine foods; add crushed flake once they settle and look like small shrimp.\n- Weeks 3 to 6: crushed pellets, algae wafers and blanched vegetables.\n\nKeep the water clean with small changes of 5 to 10 percent a few times a week, dripped in slowly. Keep the temperature steady at 72 to 78°F. Once they look like tiny adults, they can live on the bottom and graze biofilm."}, {"heading": "Growing out", "text": "Young shrimp grow quickly once past the larval stage. Expect about an inch in 2 to 3 months. Keep them in the larvae tank until they are big enough not to be eaten by fish, then move them to a grow-out tank or back with the adults.\n\nSurvival from larvae is often low on the first attempts, so do not be discouraged if only a handful make it. Each batch teaches you how much fine food to give and how gentle the flow must be. A berried female usually comes along again within a few weeks, so you will get plenty of practice."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the main tank, where adults and fish eat them.\n- Strong filters that suck up larvae.\n- No fine food, so larvae starve.\n- Moving berried females with a net.\n- Not knowing your shrimp species, since some need brackish water for larvae.\n- Copper in medications or plant products, which kills shrimp and larvae."}]$g$::jsonb, updated_at = now() where slug = $g$ghost-shrimp$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank is enough for a pair or trio. Add plenty of hides: small pipes, rock piles, wood and thick java moss. A sponge filter keeps juveniles safe, and a tight lid stops escapes.\n\nKeep water inside the library range of {{temp}}°F, pH {{ph}} and GH {{gh}}. Room temperature in the low to mid 70s works well. Calcium matters for molting, so avoid very soft water."}, {"heading": "Sexing and conditioning", "text": "Look from below. Males have the first two pairs of swimmerets modified into hard, forward-pointing rods called gonopods. Males also usually have longer, slimmer claws. Females have soft swimmerets and a wider tail for carrying eggs.\n\nFeed sinking pellets, blanched vegetables like zucchini and spinach, frozen foods and leaf litter. Keep the water stable with regular small changes. Mexican dwarf crayfish live for only about 1.5 to 2 years, so start breeding young adults."}, {"heading": "Mating and egg laying", "text": "Mating usually happens soon after the female molts. The male flips her over and holds her briefly. Later, she hides and lays eggs under her tail, attaching them to her swimmerets. A berried female hides a lot and fans her eggs constantly.\n\nYou can leave her in a well planted tank with plenty of hides, or move her to a separate tank for best survival of the young. Use a cup, not a net, if you move her."}, {"heading": "Eggs and incubation", "text": "The eggs are carried for about 3 to 4 weeks at room temperature, faster when warmer. They start dark and become lighter as the babies develop. Keep the female undisturbed with steady water. Small weekly water changes of about 10 to 15 percent are best. Stressed females may drop their eggs.\n\nA berried female often eats less and spends most of her time in a cave. That is normal. Offer a small piece of food near her hide every day or two and remove anything left after a few hours."}, {"heading": "Raising the juveniles", "text": "After hatching, the tiny crayfish cling under the mother's tail for several days and molt there. Then they walk off. If you used a separate tank, move the mother back now.\n\n- Week 1 on their own: biofilm, crushed sinking pellets and blanched vegetables.\n- Weeks 2 to 6: small sinking pellets and frozen foods, plus leaf litter.\n- Lots of moss and small hides throughout.\n\nThey are tiny and grow with each molt. Juveniles may eat each other if hungry or crowded, so feed little and often."}, {"heading": "Growing out", "text": "Juveniles reach about half an inch in roughly 2 to 3 months and adult size of about 1.5 to 2 inches in roughly 4 to 6 months. Their orange color becomes more intense as they grow. Thin out the colony if it gets crowded, and never release extras into ponds or streams.\n\nIf you leave the young with the adults, a heavily planted 20 gallon tank with lots of moss and leaf litter lets a small colony build up on its own. For the best numbers, though, raise each batch in its own small tank with the mother removed once the babies walk off. Keep feeding light but often so leftover food does not foul the water."}, {"heading": "Common mistakes", "text": "- Too few hides, leading to injuries and eaten babies.\n- Soft water with low calcium, causing molting problems.\n- Missing escapes through lid gaps.\n- Handling berried females roughly.\n- Waiting too long to breed older adults with a short lifespan."}]$g$::jsonb, updated_at = now() where slug = $g$dwarf-mexican-crayfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for a male with two or three females. Use a bare bottom or a thin layer of sand, a sponge filter, a heater set to about 72 to 75°F and a spawning mop that hangs from the surface or sits on the bottom. Gardneri use both.\n\nThe library range of pH {{ph}} and GH {{gh}} suits breeding well. Use a tight lid: killifish are skilled jumpers. Keep the light moderate and add a few floating plants for cover."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy. Males are bright, with red dots on a blue or yellow body and colorful fin edges. Females are plain brown with small reddish dots and short, rounded fins.\n\nUse one male to two or three females so no single female gets too much attention. Condition for 1 to 2 weeks with frozen and live foods such as bloodworms, brine shrimp and daphnia. Males can be rough with each other, so keep only one per small tank."}, {"heading": "Spawning: what you will see", "text": "Gardneri spawn most days once settled. The male displays to a female and leads her into the mop, where they press together and she lays an egg or two at a time. Over the day, she may lay 10 to 30 eggs.\n\nCheck the mop every day or two. The eggs are small, clear and firm, and they can be picked off with your fingers without damage. Fertile eggs are clear; infertile ones turn white."}, {"heading": "Incubating the eggs", "text": "There are two common methods.\n\n- Water: place eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily. At 72 to 75°F, they hatch in about 14 to 21 days.\n- Peat: store eggs on damp peat in a sealed container for about 2 to 3 weeks, then add water when you see eyes. This is useful for shipping or timing hatches.\n\nIn water, they may hatch over several days, so check often and move fry to a growing tank."}, {"heading": "Raising the fry", "text": "Gardneri fry are free swimming as soon as they hatch and big enough for newly hatched brine shrimp or microworms right away.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms twice a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen bloodworms, brine shrimp and small pellets.\n\nChange 10 to 20 percent of the water twice a week, matching temperature. Sort fry by size, since bigger ones may eat smaller siblings."}, {"heading": "Growing out", "text": "Fry grow quickly with good feeding. Males start to show color at about 6 to 8 weeks, and they reach adult size at about 2 to 3 months. Separate males as they mature to avoid fights. Most fish are ready to sell or trade once colors are clear.\n\nGardneri are one of the most widely kept killifish, with many named populations from different collection sites. Most keepers keep the population name with every batch they raise and pass it on with fish they trade. A pair kept on good food will keep spawning for many months, so you can raise several batches without much extra work."}, {"heading": "Common mistakes", "text": "- No lid, so adults jump out.\n- Leaving eggs in the mop where adults eat them.\n- Mixing different populations, which ruins clean locality lines. Keep and label each one separately.\n- Feeding only dry foods during conditioning.\n- Not sorting fry by size."}]$g$::jsonb, updated_at = now() where slug = $g$gardneri-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for one male and two or three females. Use a sponge filter on gentle flow, a heater set to about 72 to 75°F and one or two spawning mops, either floating or weighted on the bottom. A bare bottom or a thin layer of sand makes it much easier to see and collect eggs.\n\nThe library range of pH {{ph}} and GH {{gh}} suits breeding. Many breeders use soft, slightly acidic water around pH 6 to 6.5, mixing RO or rain water with tap water, and some add a little peat or leaf litter to soften and tint it. Keep a tight lid on the tank, because lyretails are strong jumpers. Moderate light and a few floating plants help them settle and show color."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy. Males are colorful, usually orange to chocolate with red dots, and have the lyre-shaped tail with bright edges and extended tips that gives them their name. Females are plain brown with a few small dots and short, rounded fins.\n\nKeep one male with two or three females so no single female is chased too hard. Condition for 1 to 2 weeks on live and frozen foods such as bloodworms, brine shrimp, daphnia and white worms. They will take flake, but well fed fish on meaty foods lay more eggs, and the eggs hatch better. Keep only one male per small tank, since rival males fight."}, {"heading": "Spawning: what you will see", "text": "Once settled, lyretails spawn most days. The male spreads his fins and shimmies beside a female, then leads her into the mop. The pair press together side by side and she lays one or two eggs at a time, deep among the fibers. Over a day, a female commonly lays 10 to 20 eggs.\n\nCheck the mop every day or two. Eggs are small, clear and surprisingly firm, so you can pick them out with your fingers. Fertile eggs stay clear, while infertile eggs turn white within a day or two."}, {"heading": "Incubating the eggs", "text": "Killifish keepers use two methods with this species.\n\n- Water: place eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily so fungus does not spread. At 72 to 75°F, eggs hatch in about 14 to 21 days.\n- Peat: store eggs on damp, not wet, peat in a sealed container at room temperature for about 2 to 3 weeks, then add water once you can see eyes in the eggs.\n\nIn water, a batch may hatch over several days. Check every day and move new fry to a small growing tank so they are not left without food."}, {"heading": "Raising the fry", "text": "Lyretail fry are free swimming as soon as they hatch and are large enough to take newly hatched brine shrimp or microworms right away.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen bloodworms, brine shrimp and small pellets.\n\nChange 10 to 20 percent of the water twice a week, matching temperature and softness carefully. A shallow fry tank of a few inches of water makes it easier for fry to find food. Sort fry by size every couple of weeks, since bigger fry may eat smaller siblings."}, {"heading": "Growing out", "text": "With good feeding, males start showing color and tail extensions at about 6 to 8 weeks, and the young reach adult color at around 2 to 3 months. Separate young males if they begin to fight. Lyretails are not long lived, so keep a few pairs from each generation to continue your line. Keep each population labeled with its name or locality and never mix two different strains."}, {"heading": "Common mistakes", "text": "- Leaving eggs in the mop for days, where the adults eat them.\n- Hard, alkaline water that lowers fertility and hatch rates.\n- No lid, so adults jump out.\n- Not sorting fry by size.\n- Mixing populations or strains, which ruins clean lines that other keepers rely on."}]$g$::jsonb, updated_at = now() where slug = $g$lyretail-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank works well for one male and two or three females. Keep the water cool and soft: the library range is {{temp}}°F, pH {{ph}} and GH {{gh}}, and most breeders spawn them in the low 70s. In a cool room you may not need a heater at all, but keep the temperature steady.\n\nUse a sponge filter on gentle flow, a bare bottom or a thin layer of sand, and one or two spawning mops. A few floating plants and moderate light help them feel secure. A tight lid is essential, since striatum jump readily, especially when startled."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is straightforward in adults. Males have a blue-green body crossed by rows of bright red stripes, with red markings and edges on the fins. Females are plain brown with clear or lightly spotted fins and look much less striking.\n\nKeep one male with two or three females. Condition for 1 to 2 weeks with live and frozen foods such as bloodworms, brine shrimp, daphnia and white worms. Feed small amounts two or three times a day and keep up with water changes, since cool, soft water still fouls if food is left to rot."}, {"heading": "Spawning: what you will see", "text": "The male displays beside a female with spread fins and leads her into the mop. The pair press together and she lays one or a few eggs at a time, tucked into the fibers. Spawning goes on most days once the fish are settled, and a female commonly lays 10 to 20 eggs a day.\n\nCheck the mop every day or two and pick the eggs by hand. The eggs are small, clear and firm. White eggs are infertile and should be thrown away."}, {"heading": "Incubating the eggs", "text": "- Water: keep eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily. At 68 to 72°F, they hatch in about 2 to 3 weeks.\n- Peat: store eggs on damp, not wet, peat in a sealed container for about 2 to 3 weeks, then add water once eyes are visible in the eggs.\n\nWater-incubated eggs may hatch over several days, so check every day. Write the date on each container so you know which batch is due."}, {"heading": "Raising the fry", "text": "The fry are free swimming at hatching and can eat newly hatched brine shrimp or microworms from the start.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen foods and small pellets.\n\nChange 10 to 20 percent of the water twice a week, keeping it cool and soft. Shallow water helps young fry find food. Sort fry by size every couple of weeks to prevent the bigger ones eating the smaller."}, {"heading": "Growing out", "text": "Males start showing red stripes at about 6 to 8 weeks and reach adult color at around 2 to 3 months. Keep the water cool throughout: warm water speeds growth but is widely reported to shorten their lives. Like most Aphyosemion, striatum are fairly short lived, so keep a few young pairs from each batch to carry the line on, and label each population clearly."}, {"heading": "Common mistakes", "text": "- Water that is too warm or too hard for this cool water species.\n- Leaving eggs in the mop where the adults eat them.\n- No lid.\n- Not sorting fry by size.\n- Mixing populations, which ruins clean lines."}]$g$::jsonb, updated_at = now() where slug = $g$striatum-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank works well for one male and two females. These are larger killifish, up to about 4 inches, so they need more room than the small Aphyosemion. Use floating plants such as water sprite or hornwort, or a floating spawning mop, plus a sponge filter on gentle flow.\n\nKeep the water inside the library range of {{temp}}°F, pH {{ph}} and GH {{gh}}. Many breeders spawn them at about 75 to 78°F. Striped panchax are surface hunters and excellent jumpers, so a tight lid with no gaps is essential. Do not keep them with small fish they can swallow."}, {"heading": "Conditioning and choosing a group", "text": "Males are larger and more colorful, with longer, more pointed fins and more red or orange edging. In wild type fish, females show clear dark vertical bars on the rear half of the body, which is the easiest sign. In the golden form, the bars are faint or missing, so look for the male's larger size, brighter color and longer fins.\n\nCondition with live and frozen foods for 1 to 2 weeks: bloodworms, brine shrimp, crickets or other small insects, and chopped earthworms. These are predators and need meaty foods to produce good eggs."}, {"heading": "Spawning: what you will see", "text": "The male courts the female near the surface with spread fins and quick dashes. She lays a few eggs at a time among the plant roots or mop fibers, and spawning continues on most days once the fish are settled. A female commonly lays 10 to 30 eggs over a day or two.\n\nCheck the mop or plants every day or two and pick the eggs, or move the whole mop to a hatching tank and replace it with a fresh one."}, {"heading": "Incubating the eggs", "text": "Eggs are commonly reported to hatch in about 12 to 14 days at 75 to 78°F. Keep them in a small container of tank water with a drop or two of methylene blue, and remove any white eggs daily so fungus does not spread. A batch may hatch over a few days, so check each day and move fry to a growing tank as they appear.\n\nYou can also leave eggs in a mop moved to a separate hatching tank with a sponge filter. Fry then appear on their own at the surface over a couple of weeks, which saves picking eggs one by one."}, {"heading": "Raising the fry", "text": "The fry are fairly large and free swimming at hatching, and they eat well from day one.\n\n- Weeks 1 to 2: newly hatched brine shrimp and microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods such as bloodworms and brine shrimp.\n- Weeks 5 to 8: frozen bloodworms, small insects and small pellets.\n\nChange 10 to 20 percent of the water twice a week. Sort fry by size at least once a week. Striped panchax fry are strongly cannibalistic, and a fry that gets a head start will quickly eat its smaller siblings."}, {"heading": "Growing out", "text": "Fry grow fast on plenty of live and frozen food. Males start showing color at about 6 to 8 weeks, and adult color develops by around 3 months. Keep only fish of similar size together and give them more space as they grow. Keep a lid on every grow-out tank, since even young fish jump."}, {"heading": "Common mistakes", "text": "- No lid, or gaps around cords and filters.\n- Leaving eggs and fry with the adults.\n- Not sorting fry by size, which leads to heavy losses from cannibalism.\n- Feeding only flake during conditioning.\n- Overcrowding the grow-out tank."}]$g$::jsonb, updated_at = now() where slug = $g$golden-wonder-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank is ideal for a small breeding group. Keep the water inside the library range of {{temp}}°F, pH {{ph}} and GH {{gh}}. Hard, alkaline water is important for limia, and they do poorly in soft, acidic water.\n\nAdd plenty of dense plants and a layer of floating plants such as hornwort, water sprite or java moss. This gives newborn fry somewhere to hide straight away. Use a sponge filter, or cover the filter intake with a sponge, so fry are not sucked in. A gentle light and some algae on the rocks are welcome, since limia graze all day."}, {"heading": "Conditioning and choosing a group", "text": "Sexing adults is easy. Males have a gonopodium, the rod shaped anal fin used for mating, and are smaller and more strongly colored, with darker barring and fin markings. Females are larger and rounder, with a normal fan shaped anal fin and a dark gravid spot near the vent that grows as they fill with young.\n\nKeep one male with two or three females so the male's attention is spread out. Feed a varied diet with plenty of plant matter: vegetable or spirulina flake, algae wafers and blanched vegetables, plus frozen foods such as brine shrimp and daphnia a few times a week."}, {"heading": "Mating and gestation", "text": "Males display and chase females constantly, and mating is quick. Like other livebearers, females can store sperm and may produce several broods from one mating. Gestation is about 4 weeks, depending on temperature. A pregnant female grows deeper and boxier, and the gravid spot darkens. Close to birth she may hang near plants or away from the group. Keep notes of the date each female drops fry so you can predict her next brood about 4 weeks later."}, {"heading": "Birth and saving fry", "text": "Fry are born fully formed and free swimming, commonly about 10 to 30 per brood, with larger females producing more. Adults may eat newborn fry, so dense plants are your first line of defense. For the most fry, move a heavily pregnant female to a planted 5 to 10 gallon tank a few days before she is due, and return her once she has dropped. Small breeding boxes can stress females and cause early or failed births, so a planted tank is usually better."}, {"heading": "Raising the fry", "text": "Limia fry are large enough to eat crushed flake from their first day.\n\n- Weeks 1 to 2: crushed flake, newly hatched brine shrimp and powdered fry food three or four times a day.\n- Weeks 3 to 6: add crushed vegetable flake and small frozen foods.\n- Weeks 7 to 12: regular flake, small pellets and blanched vegetables.\n\nChange 15 to 25 percent of the water weekly with matched temperature and hardness. Keep algae growing on rocks and glass for grazing."}, {"heading": "Growing out", "text": "Fry reach near adult size in about 3 months with good feeding. Males develop their gonopodium and stronger color as they mature, so you can usually sex the young at around 6 to 10 weeks. Sell or trade them once they are well colored, and keep the best fish to continue your line."}, {"heading": "Common mistakes", "text": "- Soft or acidic water, which causes poor health and few fry.\n- No plants for fry cover, so most newborns are eaten.\n- Tiny breeding boxes that stress pregnant females.\n- Overcrowding the tank as broods add up.\n- Crossing limia with other livebearers. Keep the species pure."}]$g$::jsonb, updated_at = now() where slug = $g$humpbacked-limia$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is plenty for a starter colony. Fill it with fine leaved plants such as Java moss, hornwort and floating plants, since cover is what lets fry survive. Use an air driven sponge filter so the tiny fish are never pulled in, and keep a tight lid.\n\nMatch the site's care numbers: pH {{ph}}, GH {{gh}}, and 72 to 77°F for breeding. They tolerate cooler water down to the mid 60s, but births slow down.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning Your Group", "text": "Sexing is straightforward once fish are grown. Females reach about 1.2 inches and look deeper bodied. Males are noticeably smaller, slimmer, and carry a long, pointed gonopodium that is easy to see from the side.\n\nStart with 1 male to 2 or 3 females, ideally 6 or more fish. Condition for 1 to 2 weeks with live or frozen baby brine shrimp, microworms, daphnia and crushed flake two or three times a day. These are tiny mouths, so food must be small.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "How They Breed", "text": "Mating is quick and easy to miss. The male darts at a female and swings the gonopodium forward. Females store sperm, so a single male can keep several females producing.\n\nThe big difference from guppies is superfetation: a female carries several batches of embryos at different stages, so instead of dropping 30 fry in one day she releases a few at a time."}, {"heading": "Gestation and Birth", "text": "Each embryo is commonly reported to develop for about 4 weeks, but because batches overlap, births are spread out. Breeders commonly report 1 to 3 fry a day over a week or two. Total output per female is modest, so colony growth is gradual rather than explosive.\n\nThere is no need to move females or use breeding boxes. In a planted species tank the mothers simply give birth among the plants."}, {"heading": "Raising the Fry", "text": "Fry are tiny but swim and eat from birth.\n\n- Week 1: microworms, freshly hatched baby brine shrimp and powdered flake, three or four small feedings a day.\n- Weeks 2 to 4: add crushed flake and small frozen foods like cyclops.\n- Change 15 to 25 percent of the water weekly with a gentle siphon, checking for fry.\n- Keep 72 to 77°F for steady growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Young fish grow slowly by livebearer standards but are mature in about 2 to 3 months. Males show the gonopodium first. Because adults leave fry alone, you can grow the colony in one tank, though a second small tank helps once numbers pass 30 or so. Least killifish are native to the southeastern United States; never release them or any aquarium fish outdoors.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Adding tankmates, which quickly eat the fry.\n- Hang on back filters with open intakes.\n- Food that is too big for these tiny fish.\n- Expecting large broods; this species breeds in a slow trickle.\n- Too few plants, leaving fry with nowhere to hide."}]$g$::jsonb, updated_at = now() where slug = $g$least-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Mollies need room and hard, alkaline water. Use at least {{tank}} gallons for a small group, with pH {{ph}} and GH {{gh}}, matching the site's care numbers. Breeding goes best at 75 to 80°F.\n\nAdd dense cover such as hornwort, Java moss and floating plants so newborns can hide. A separate 10 gallon nursery tank with a sponge filter is the most reliable way to raise a full brood. Salt is not required for this species if your water is hard.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning a Breeding Group", "text": "Males have a gonopodium, the narrow, rod-shaped anal fin used to mate. Females have a normal fan-shaped anal fin and are larger and rounder. Keep 1 male to 2 or 3 females so no single female is chased all day.\n\nCondition for 2 to 3 weeks with a spirulina or algae flake as the main food, blanched spinach or zucchini, and frozen brine shrimp or bloodworms a few times a week. Mollies graze constantly, so several small feedings beat one big one.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "Males follow females and make quick thrusts with the gonopodium. Females store sperm, so a female can have several broods from one mating, even after the male is removed.\n\nA pregnant female grows boxy at the back of the belly. The dark gravid area near the vent is often hard to see on dark or black mollies, so body shape is the better guide."}, {"heading": "Gestation and Birth", "text": "Gestation is about 4 to 6 weeks at 75 to 80°F and can stretch in cooler water. Near the end the belly looks square from the front, and the female may hang near cover or stop eating.\n\nYou can move her to a heavily planted nursery tank a few days ahead. Small hang-on breeding boxes stress mollies and can cause early births, so use them only briefly. Broods are commonly 20 to 60, with big females occasionally dropping around 100."}, {"heading": "Raising the Fry", "text": "Molly fry are large and eat right away.\n\n- Week 1: crushed flake, baby brine shrimp and a pinch of spirulina powder, four or five times a day.\n- Weeks 2 to 4: add finely crushed algae wafers, blanched vegetables and frozen foods.\n- Change 25 to 30 percent of the water two or three times a week.\n- Keep 76 to 80°F for fast growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 2 to 3 months. Males show the gonopodium as they mature, often between 2 and 4 months. Separate young males early if you want to control which fish breed. Cull any with bent spines or poor shape and keep your best fish as the next breeders.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Soft or acidic water, which leads to clamped fins and poor health.\n- Too many males per female.\n- Leaving fry with the adults in a bare tank.\n- Skipping vegetables in the diet.\n- Mixing molly species and selling the crosses as pure fish.\n- Releasing unwanted fish outdoors. Mollies have become invasive in warm waters in many parts of the world."}]$g$::jsonb, updated_at = now() where slug = $g$molly$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Swordtails are active swimmers, so use at least 30 gallons for a breeding group. Match the site's care numbers: pH {{ph}}, GH {{gh}}, and 75 to 80°F for breeding. Good filtration is important, and swordtails are known jumpers.\n\nPlant one end heavily with floating plants, hornwort or Java moss for fry cover, or keep a 10 gallon nursery tank with a sponge filter ready for the births.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning a Breeding Group", "text": "Mature males are easy to sex: they have a gonopodium and the long sword on the bottom of the tail. Females are larger bodied with a fan-shaped anal fin and no sword. Young males can develop late, so a fish without a sword is not always a female until you check the anal fin.\n\nKeep 1 male to 2 or 3 females, because males chase hard and can fight each other. Condition for 2 to 3 weeks with flake, frozen bloodworms or brine shrimp and some vegetable flake.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "The male swims in front of the female with his sword showing, then darts in to mate with the gonopodium. Females store sperm, so they can produce several broods from a single mating.\n\nA pregnant female grows deep and boxy, and the dark gravid spot near the vent becomes larger and darker as birth gets close."}, {"heading": "Gestation and Birth", "text": "Gestation is about 4 to 6 weeks at 75 to 80°F. Broods are commonly 20 to 80, and big, mature females can drop well over 100.\n\nMove the female a few days ahead to a heavily planted nursery tank, or use plenty of floating plants in the main tank. Small breeding boxes stress swordtails, so keep any time in them short. Return the female once she has finished giving birth."}, {"heading": "Raising the Fry", "text": "The fry are large and start eating right away.\n\n- Week 1: crushed flake and baby brine shrimp, four or five times a day.\n- Weeks 2 to 4: add microworms, crushed frozen foods and vegetable flake.\n- Change 25 to 30 percent of the water two or three times a week.\n- Keep 76 to 80°F for steady growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 2 to 3 months. Some males show swords from around 3 months, but others take much longer, and these late developers often become the largest males. Separate males and females once you can sex them if you want control over pairings. Keep the best shaped fish with the strongest color as your next breeders.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Too many males in a small tank, leading to fighting.\n- Leaving fry with adults in a bare tank.\n- Culling swordless fish too early, when some are late males.\n- No lid on the tank.\n- Selling platy crosses as pure swordtails.\n- Releasing unwanted fish outdoors. Swordtails have become invasive in warm waters in several countries."}]$g$::jsonb, updated_at = now() where slug = $g$swordtail$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A pair does best in a 30 to 40 gallon tank of its own; the site lists {{tank}} gallons for keeping adults. Use a sand bottom, a couple of smooth flat stones or a slate, and a few hiding spots. A sponge filter is safest for the fry.\n\nKeep pH 6.5 to 7.5, GH 5 to 18 and 78 to 80°F for spawning, which sits inside the site's 72 to 82°F range.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing young acaras is tricky. Adult males are usually larger, with longer, more pointed dorsal and anal fins and sometimes a steeper forehead. Females are smaller and rounder. The surest check is the breeding tube at spawning time: the female's is short and blunt, the male's is thinner and pointed.\n\nThe best way to get a pair is to grow 6 young fish together and let two pair off. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, mysis and a good cichlid pellet.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A ready pair darkens, locks jaws and digs, then scrubs a flat stone clean. A 30 to 50 percent water change with slightly cooler water often sets them off. The female makes passes laying rows of eggs, and the male follows to fertilize them.\n\nClutches are commonly 150 to 400 eggs. Both parents fan the eggs and chase away anything that comes close."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents pick out white, fungused eggs. If you choose to hatch them yourself, move the stone to a tank or container with the same water, an airstone beside the eggs, and a small dose of methylene blue.\n\nAfter hatching, the parents often move the wrigglers into pits in the sand. They become free swimming about 3 to 5 days later."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp and microworms, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake and powdered pellets.\n- Week 4 onward: crushed pellets, frozen daphnia and cyclops.\n- Change 20 to 30 percent of the water twice a week, siphoning gently.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks with frequent feeding and clean water. Move them to a larger grow out tank once the parents start getting ready to spawn again, as they may chase older fry. Acaras grow steadily and are popular with local fish stores once they reach 1.5 to 2 inches.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Pulling the eggs after one lost clutch; young pairs often need a few tries.\n- Tankmates that keep the parents stressed and distracted.\n- Too little food for the fry in the first week.\n- Big temperature swings during water changes.\n- Crossing acaras with other cichlids."}]$g$::jsonb, updated_at = now() where slug = $g$electric-blue-acara$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 to 30 gallon tank works for one pair; the site lists {{tank}} gallons for keeping them. Use sand, a few flat stones or slate pieces, and plants or wood for cover. A sponge filter keeps the fry safe.\n\nKeep pH 6.5 to 7.0 and GH 4 to 10 for spawning, within the site's range of pH 6.0 to 7.8, and run 78 to 80°F. A few dither fish like a small tetra school help nervous pairs feel safe.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing Bolivian rams is not easy. Adult males are usually larger, with longer extensions on the tail and more pointed dorsal fin rays. Females tend to be rounder and may show a pinkish belly when ready. Even experienced keepers get it wrong with young fish.\n\nThe reliable route is to grow 6 juveniles together and let a pair form, then rehome the rest. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A ready pair stays close, cleans a flat stone and may dig shallow pits. The female lays rows of eggs and the male fertilizes them. Clutches are commonly 75 to 300 eggs.\n\nBoth parents take turns fanning the eggs and guarding the area. Keep the room quiet and avoid moving decor while they are busy."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F, and the parents often move the wrigglers into pits. Fry become free swimming roughly 4 to 6 days after hatching.\n\nThe parents normally remove infertile eggs. If you hatch eggs artificially, use water from the breeding tank, gentle aeration beside the stone and a little methylene blue to limit fungus."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus finely crushed flake.\n- Change 15 to 25 percent of the water two or three times a week, matching temperature.\n- Keep 78 to 80°F.\n\nThe parents lead the fry to food, so feed near the school.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Bolivian ram fry grow at a moderate pace, reaching about 1 inch in 8 to 10 weeks. Move them to a grow out tank when the parents start preparing for the next spawn. Feed several small meals a day and keep nitrates low for good finnage and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Buying two fish and assuming they are a pair.\n- Rough tankmates that bully the pair.\n- Giving up after one or two eaten clutches.\n- Letting nitrates build up while fry are being heavily fed.\n- Confusing them with German blue rams, which need much softer, warmer water."}]$g$::jsonb, updated_at = now() where slug = $g$bolivian-ram$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon long tank suits a male and two or three females, with more room better for a harem. Give each female her own cave, spaced apart, with plants, wood and leaf litter between them. Use sand and a sponge filter.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, aim for pH 6.0 to 7.0 and soft water. Temperature is known to affect the sex ratio of Apistogramma fry: breeders commonly report more males at the warm end and more females when cooler, so around 78°F gives a better mix.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning Your Fish", "text": "Males are easy to sex once grown. They are much larger, with long, crest-like front dorsal rays and a colorful tail that is often marked with red or orange in tank strains. Females stay small and plain, turning bright yellow with dark markings when breeding.\n\nCondition for 2 to 3 weeks with live or frozen baby brine shrimp, daphnia, bloodworms and mosquito larvae, plus a good small pellet.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "The male displays at the cave entrances. A ready female invites him in and lays her eggs on the cave ceiling, commonly 50 to 150. She then guards the cave and drives off the male and other fish.\n\nWith several females, spawns may be spread out, and you may have more than one yellow mother at once."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 78 to 82°F. The wrigglers stay in the cave for roughly another 4 to 6 days, and then the female brings out free swimming fry.\n\nThe mother handles fungus. Keep the tank calm, light lower than usual, and hold off on big water changes until the fry are out and feeding."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake or fine crumble.\n- Change 15 to 20 percent of the water twice a week, matched for temperature.\n- Keep 78 to 80°F.\n\nIn a busy tank, the male or other females may pick at fry. Moving the mother and her brood to a small tank of their own gives the best results.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 0.5 to 0.75 inch in 6 to 8 weeks. Males show their longer fins and the start of the crest from around 2 to 3 months. Grow them in a tank with gentle flow and plenty of small meals for the best fins and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Too few caves, leading to fighting between females.\n- Breeding only at very high temperatures and ending up with mostly males.\n- Leaving fry in a crowded community tank.\n- Hard, alkaline water that lowers hatch rates.\n- Disturbing the cave in the first few days."}]$g$::jsonb, updated_at = now() where slug = $g$cockatoo-dwarf-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank is enough for one pair, matching the site's minimum. Add sand, a few smooth stones and broad leaved plants such as Amazon swords, plus wood for cover. A sponge filter keeps the fry safe.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, soft water at pH 6.0 to 7.0 and 78 to 80°F works well. A small school of peaceful dither fish helps the pair feel secure.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing is honestly difficult. Males tend to be slightly larger, with longer and more pointed dorsal and anal fins, but the differences are small and inconsistent. The breeding tubes at spawning time are the surest check.\n\nBuy 6 young fish and let a pair form on its own. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, daphnia and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair stays together, darkens a little and cleans a flat stone or a broad leaf. The female lays rows of eggs, followed by the male. Clutches are commonly 100 to 200, sometimes more from large females.\n\nBoth parents tend the eggs. They are gentle with tankmates for a cichlid, but will still chase fish away from the nest."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents commonly move the wrigglers between small pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. If eggs keep turning white, check that the water is soft enough and that the pair is not disturbed."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 15 to 25 percent of the water twice a week, matching temperature.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Flag cichlid fry grow at a moderate pace, reaching around 0.5 to 0.75 inch in 8 weeks. Move them to a grow out tank once the parents begin preparing to spawn again. Clean water and several small meals a day bring out the best shape and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Assuming two store fish are a pair.\n- Hard, alkaline water that lowers hatch rates.\n- Busy, aggressive tankmates.\n- Giving up after one eaten clutch.\n- Big water changes during the egg stage."}]$g$::jsonb, updated_at = now() where slug = $g$dwarf-flag-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 30 gallon tank suits one pair, matching the site's minimum. Keyholes are shy, so give them plenty of cover: wood, plants, leaf litter and a few flat stones. Dim light and a small school of peaceful dither fish help them feel safe enough to spawn.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, soft water at pH 6.0 to 7.0 and 78 to 80°F works well. Use a sponge filter.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing keyholes is difficult. Males are often slightly larger, with longer, more pointed dorsal and anal fins, but the differences are subtle. The breeding tubes seen at spawning time are the surest sign.\n\nGrow a group of 6 juveniles and let a pair form. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, daphnia and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair stays close and cleans a flat stone or a loose leaf. The female lays rows of eggs and the male fertilizes them, commonly 100 to 300. Breeders often report that keyholes like a loose leaf because they can move it, eggs and all, if they feel threatened.\n\nKeep foot traffic and disturbance low for the first week."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The parents move the wrigglers into pits or onto leaves, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nIf a shy pair keeps eating eggs, more cover, a quieter spot and dither fish usually help more than artificial hatching."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 15 to 25 percent of the water twice a week, matching temperature.\n- Keep 78 to 80°F.\n\nThe parents guard the fry for several weeks and are rarely aggressive about it.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Keyhole fry are known as slow growers. Expect about 0.5 to 0.75 inch by 8 weeks with good feeding. Move them to a grow out tank once the parents prepare to spawn again, and keep them with gentle tankmates, since they are easily outcompeted for food.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- A bright, bare tank with no cover.\n- Boisterous tankmates that stress the pair.\n- Expecting fast growth from the fry.\n- Big water changes or rearranging decor while eggs are present.\n- Assuming two fish are a pair before they bond."}]$g$::jsonb, updated_at = now() where slug = $g$keyhole-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Texas cichlids grow large, and the site lists {{tank}} gallons as a minimum. A breeding pair is happier in more space. Use sand, a large flat stone and rockwork that gives the female places to retreat. Use heavy filtration with a guarded intake.\n\nKeep pH 7.0 to 8.0, GH 8 to 20 and 78 to 80°F for breeding, all within the site's ranges.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Adult males are usually larger and often develop a hump on the forehead. Females are smaller, and breeding females typically show a dark lower body. Sexing young fish is unreliable, and the breeding tubes at spawning time are the surest check.\n\nGrow 5 or 6 juveniles together and remove the rest once a pair forms. Condition for 2 to 3 weeks with quality pellets, vegetable foods and frozen krill or mysis.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair in breeding dress turns dark on the lower body with pale upper sides, digs pits and cleans a flat stone. The female lays rows of eggs and the male fertilizes them.\n\nClutches are commonly 500 to 1,000 eggs. Both parents guard aggressively. Watch the male closely: if he starts chasing the female hard, a divider or a rock barrier with a gap only she fits through can save her."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The parents move the wrigglers to pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. To hatch artificially, move the stone to matching water with an airstone beside it and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake.\n- Week 4 onward: crushed pellets, vegetable flake and frozen foods.\n- Change 30 to 40 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow fast and reach about 1 inch in 6 to 8 weeks. A big spawn quickly outgrows a small tank, so plan for several grow out tanks or cull to a number you can raise well. Texas cichlids are native to Texas and northern Mexico and have become invasive where released, such as around New Orleans; never release fish or fry outdoors.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Forcing two adults together, which can end badly.\n- A tank too small for a pair of large fish.\n- No plan for hundreds of fry.\n- Weak filtration for a heavily fed tank.\n- Crossing Texas cichlids with other cichlids."}]$g$::jsonb, updated_at = now() where slug = $g$texas-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 15 gallon tank suits a pair; the site lists {{tank}} gallons for keeping a group. Provide several small caves, such as narrow clay caves or short PVC pipe, plus plants and Java moss. Use a gentle sponge filter.\n\nKeep pH 6.5 to 7.5, GH 5 to 12 and 77 to 79°F for breeding, within the site's 72 to 79°F range. Start some infusoria or vinegar eel cultures before you expect eggs.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males are larger, more colorful and develop a hump on the forehead as they mature. Females are smaller and show a bright yellow belly when ready to spawn. Both sexes have the black eyespot at the base of the tail.\n\nKeep one pair or a small group with more caves than males. Condition for 2 to 3 weeks with live or frozen baby brine shrimp, daphnia, cyclops and bloodworms. They often ignore dry food.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "Unusually, the female often does the courting, swimming around the male with her yellow belly on show. She follows him into a cave and lays her eggs on the ceiling or walls, commonly a few dozen to around 150.\n\nThe male then stays inside or at the entrance, fanning and guarding the eggs, and may barely come out to eat."}, {"heading": "Eggs and Hatching", "text": "Breeders commonly report hatching in roughly 7 to 10 days at 77 to 79°F, longer than for many egg layers. Many breeders move the whole cave with the eggs to a small hatching tank or container with gentle aeration, so the fry are not eaten once they leave the cave.\n\nIf you leave the eggs with the male, check the cave daily from about day 6 and be ready to move the fry."}, {"heading": "Raising the Fry", "text": "The fry are small, and first foods are the hardest part.\n\n- Days 1 to 5: infusoria or vinegar eels, several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp once the fry can take them.\n- Weeks 3 to 4: baby brine shrimp and powdered flake.\n- Change 10 to 15 percent of the water every two days, carefully.\n- Keep 77 to 79°F.\n\nStart infusoria or vinegar eel cultures a week or two before you expect a hatch so they are thick and ready. Feed little and often and siphon leftovers gently, because tiny fry are very sensitive to fouled water. Rounded bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow steadily once they are on baby brine shrimp, reaching about half an inch in 8 to 10 weeks. Young fish start to show the tail eyespot early, while the male's forehead hump comes later. Keep them in a quiet tank with plenty of live and frozen food.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- No tiny live food ready when the eggs hatch.\n- Leaving free swimming fry with hungry adults.\n- Too few caves for the number of males.\n- Strong filter flow that sweeps away fry.\n- Disturbing the male so often that he abandons the eggs."}]$g$::jsonb, updated_at = now() where slug = $g$peacock-gudgeon$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank is enough for one pair. Add a few flat stones or slate pieces, some broad leaved plants, a sponge filter and a soft sand or fine gravel bottom where the parents can dig pits for the wrigglers. Dim lighting and a few floating plants help them feel secure.\n\nThe site's care range for this fish is {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, aim for the softer, warmer end: around 79 to 81°F, pH 6.5 to 7 and a GH under about 8."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing is genuinely difficult. Females are often a little smaller and plumper, and males may grow slightly longer fin extensions, but neither is reliable. The surest route is to buy 6 juveniles, grow them up together and watch for two fish that stake out a stone and chase others away. Move that pair to the breeding tank.\n\nFeed small meals of frozen bloodworms, brine shrimp, daphnia and a good flake two or three times a day for about 2 weeks. Do a 25 percent water change a few times that week; fresh, slightly softer water at the warm end of the range often sets them off."}, {"heading": "Spawning: what you will see", "text": "The pair will clean a flat stone or leaf for a day or two, nipping it spotless. The female then makes passes over it laying rows of small eggs, with the male following to fertilize them. A spawn of 100 to 500 eggs is commonly reported.\n\nBoth parents take turns fanning the eggs and chasing off anything that comes close."}, {"heading": "Eggs and fungus prevention", "text": "Eggs hatch in about 2 to 3 days at 79 to 81°F. The parents remove any white, fungused eggs themselves. Once the eggs hatch, the parents move the wriggling larvae into pits dug in the sand and may shift them between pits several times.\n\nIf the pair keeps eating eggs, you can move the stone to a separate tank with an air stone and a drop of methylene blue, but most breeders find that new pairs settle down after one or two tries."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 4 to 6 days after hatching, and they are tiny. Week 1: infusoria, green water or a liquid fry food several times a day, plus very fine powdered food. Week 2: add microworms and newly hatched brine shrimp. From week 3, crushed flake joins the menu.\n\nKeep the tank at 78 to 80°F and change 20 to 30 percent of the water every 2 to 3 days with matched soft water. The parents will herd the fry for several weeks; remove the fry if the parents start spawning again."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Spread them out in a larger tank, keep feeding brine shrimp and quality flake, and keep the water clean and soft. They start showing adult colors at around 1.5 inches.\n\nButterfly cichlids are peaceful enough that young ones can share a grow out tank with other small, gentle fish, but they grow faster and color up better without competition at feeding time. Keep a few of the best ones back to raise your next pair."}, {"heading": "Common mistakes", "text": "- Water that is too hard, which can lower hatch rates.\n- Giving up after a pair eats its first one or two spawns.\n- Feeding the free swimming fry baby brine shrimp only; many are too small for it the first few days.\n- Not separating the fry when the pair is ready to spawn again."}]$g$::jsonb, updated_at = now() where slug = $g$african-butterfly-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Auratus are small, about 4.5 inches, but very aggressive. A {{tank}} gallon tank is the minimum the site lists, and bigger is better. Stack rocks into many caves so females can break line of sight. Sand or fine gravel and strong filtration finish it.\n\nKeep the water at 76 to 82°F, pH 7.8 to 8.6 and GH 10 to 25, aiming for about 78 to 80°F for breeding. Change 30 to 50 percent of the water weekly.\n\nIf you can, use a dedicated species tank. A busy mixed mbuna tank adds stress, raises the odds of holding females being harassed and makes it easier for the male to cross with a similar looking female of another species."}, {"heading": "Choosing and conditioning a harem", "text": "Adult sexing is simple. Dominant males change from yellow to dark brown or black with yellow to gold stripes. Females and young fish stay yellow with black and white stripes. Note that a subordinate male may stay in female coloring, so do not assume every yellow fish is female.\n\nKeep only one male, with at least 4 females. Feed an omnivore flake or pellet with spirulina, plus occasional small portions of brine shrimp or mysis, twice daily for 2 to 3 weeks. Females that are well fed and not constantly chased fill out with eggs faster and hold more reliably.\n\nFemales can be ready to spawn at around 2 to 2.5 inches, so a group of young fish often starts breeding sooner than you expect."}, {"heading": "Spawning: what you will see", "text": "The male darkens even more, shakes and leads a female to a flat spot in his territory. She lays a few eggs at a time and picks them up in her mouth, then nips at his anal fin to fertilize them. Spawning can last an hour or more.\n\nAfterward the female will have a full throat, stop eating and hide in the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 weeks at 78 to 80°F. Auratus males often harass holding females, so most breeders move her after about a week to a 10 to 20 gallon tank with matched water and a cave. Net her gently and avoid chasing her around the tank, or she may spit the eggs.\n\nSome breeders strip well developed fry by hand. For beginners, letting her release naturally in her own tank is safer."}, {"heading": "Raising the fry", "text": "Fry are released free swimming at about 3/8 inch. Remove the female once she releases them and give her a week or so to recover before returning her to the harem.\n\nWeek 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Even young auratus squabble, so give them space and rockwork as they grow. Young males start turning dark at around 2 to 3 inches, which is also when they start fighting in earnest.\n\nFeed the fry three or four small meals a day if you can, and keep up the frequent water changes. Sort out obvious males as they color, since a single growing male will start bullying his tankmates. Groups of young fish are easiest to rehome or sell at about 1.5 to 2 inches, before males fully color and turn on each other."}, {"heading": "Common mistakes", "text": "- Keeping two males, or one male with only one or two females.\n- Leaving a holding female with a harassing male.\n- Mixing auratus with similar mbuna, which can lead to hybrids. Breed them in a species tank.\n- Assuming a yellow fish is a female; young males stay yellow for a while."}]$g$::jsonb, updated_at = now() where slug = $g$auratus-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for this species, and that suits a group of one male and three or four females, with or without other mbuna of different shapes and colors. Stack rocks into caves, give them a sand bottom, and leave some open water.\n\nKeep the water at 76 to 82°F, pH 7.6 to 8.6 and GH 10 to 20. For breeding, about 78 to 80°F and pH 8 to 8.4 works well. Change 30 to 50 percent of the water each week."}, {"heading": "Building a breeding group", "text": "Sexing electric blue johanni is not easy. Both sexes are the same blue with black horizontal stripes. Males often grow larger and may show slightly brighter color or more egg spots on the anal fin, but these signs are not reliable. Venting is the best way to be sure, or buy 6 to 8 juveniles and remove extra males as they become obvious by their behavior.\n\nDo not keep them with other blue and black striped mbuna such as johanni types or auratus, since mixed similar species may hybridize. Condition the group on a spirulina based flake or pellet with occasional small portions of mysis or brine shrimp for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The male intensifies his color, shakes and leads a female into his territory. As with other mbuna, she lays a few eggs at a time, takes them into her mouth and mouths at his anal fin to fertilize them. Broods are small, commonly 10 to 20 eggs.\n\nA holding female has a bulging throat, stops eating and keeps to the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Move her after about a week, gently, to a 10 to 20 gallon tank with the same water and a cave or two. Netting her in the first few days often causes her to spit.\n\nWhen she releases the fry, remove her and give her a week or two of good feeding before returning her to the group, so she can rebuild her condition."}, {"heading": "Raising the fry", "text": "The fry are released already free swimming and colored like the adults. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F, use a sponge filter and change 25 to 50 percent of the water two or three times a week."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months and around 2 inches by 5 to 6 months. They remain small as adults, around 3.5 inches. Grow them out in a tank with some rockwork so the weaker ones can escape. Young males start to show territorial behavior at about 2 inches, which is a good time to pick out the best ones to keep or sell.\n\nFeed young fish three or four small meals a day if you can, with spirulina flake as the base and baby brine shrimp or daphnia as extras. Frequent water changes do more for growth than any food. Sort the fry by size if a few start to outgrow the others, as large siblings can bully smaller ones away from food."}, {"heading": "Common mistakes", "text": "- Building a group without venting and ending up with too many males.\n- Keeping them with similar blue and black striped mbuna.\n- Moving the holding female too early.\n- Returning a female to the group before she has recovered her weight."}]$g$::jsonb, updated_at = now() where slug = $g$maingano-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank is a good size for one pair. Provide several flat stones or slate pieces for spawning, a cave or two and a fine sand or gravel bottom. Plants may get dug up, so use hardy ones attached to wood or rocks.\n\nThe site lists jewels at {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, keep the temperature around 78 to 80°F and the pH near neutral. A sponge filter is safest for fry, and weekly 30 percent water changes keep the pair in spawning shape."}, {"heading": "Choosing and pairing", "text": "Sexing jewels is unreliable by looks. Males are often slightly larger, and both sexes turn deep red with blue spangles when breeding. The safest way to get a pair is to raise 6 juveniles together and remove the others once two fish start guarding a spot together.\n\nJewels can kill a partner that is not ready to spawn. If you put an adult pair together, keep a tank divider handy and watch closely for the first few days. Torn fins or a hiding fish mean you should separate them.\n\nCondition the pair on frozen bloodworms, brine shrimp, mysis and a quality pellet twice a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "A ready pair colors up dramatically, with the red deepening and blue spots glowing. They clean a flat stone for a day or two, then the female lays rows of eggs while the male follows to fertilize. Clutches of 200 to 500 eggs are commonly reported, and large females can lay more.\n\nFrom this point, both parents attack anything that comes near."}, {"heading": "Eggs and fungus prevention", "text": "The eggs hatch in about 2 to 3 days at around 80°F. The parents fan the eggs and pick out any that turn white with fungus. Once hatched, they move the wrigglers to pits dug in the sand.\n\nIf a young pair eats the eggs, give them a few more chances. You can also move the stone to a separate tank with an air stone and a small dose of methylene blue, but you lose the parental care that makes jewels so fun to watch."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 5 days after hatching, and the parents herd them around the tank in a tight cloud. Week 1: baby brine shrimp and microworms two or three times a day. Week 2: add finely crushed flake. Week 3 onward: crushed pellets and small frozen foods.\n\nKeep the tank at 78 to 80°F and change 20 to 30 percent of the water every few days, siphoning carefully around the parents. When the pair starts cleaning a stone again, usually after 3 to 6 weeks, move the fry out."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months with good feeding. They grow fast but become territorial early, so spread them across a larger grow out tank with rocks and hiding spots. Sell or rehome them in groups before they pair off and start fighting.\n\nFeed growing jewels three small meals a day of crushed pellets, flake and frozen foods such as brine shrimp and bloodworms. They color up from about 1.5 inches, though the deepest reds come with maturity. Change 30 to 50 percent of the grow out water weekly; jewels are messy eaters and grow fastest in clean water."}, {"heading": "Common mistakes", "text": "- Forcing a random male and female together without a divider.\n- Keeping other fish in the breeding tank, which the parents may kill.\n- Leaving older fry in when the parents spawn again.\n- Assuming the brightest fish is the male; females color up strongly too."}]$g$::jsonb, updated_at = now() where slug = $g$jewel-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for kenyi, and that is the place to start. They grow to about 5 inches and males are very aggressive. Stack rocks into many caves and crevices along the full length of the tank so females can escape.\n\nKeep the water at 76 to 82°F, pH 7.6 to 8.6 and GH 10 to 20. Aim for 78 to 80°F for breeding, and change 30 to 50 percent of the water weekly. Strong filtration helps, as mbuna tanks get heavily stocked."}, {"heading": "Choosing and conditioning a harem", "text": "Kenyi sex by color, which is unusual among mbuna. Mature males turn yellow to orange, often with a few faint bars. Females and juveniles stay pale blue with dark vertical bars. Young males are blue at first and change color as they mature, usually at about 2 to 3 inches.\n\nKeep one male with three or four females. Kenyi are herbivores, so feed a spirulina based flake or pellet twice a day, with protein foods only as a small treat. Avoid keeping them with other blue barred Maylandia, as they can hybridize."}, {"heading": "Spawning: what you will see", "text": "The male brightens, shakes and leads a female to a spot near his cave. She lays a few eggs at a time, picks them up and mouths at the egg spots on his anal fin to fertilize them. A typical clutch is about 10 to 30 eggs.\n\nAfterward she hides with a bulging throat and refuses food."}, {"heading": "Holding time", "text": "Females hold for about 3 weeks, often 21 to 28 days at 78 to 80°F. Holding females eat very little, so a well conditioned female going in makes a big difference to how well she holds.\n\nKenyi males harass holding females, so most breeders move her after about a week to a 10 to 20 gallon tank with matched water and a cave. Move her gently and avoid chasing her.\n\nSome breeders strip the fry once they are well developed, but letting her release naturally is the safer choice for beginners."}, {"heading": "Raising the fry", "text": "Fry are released about 3/8 inch long and can eat right away. Week 1: baby brine shrimp and finely crushed spirulina flake twice a day. Weeks 2 to 4: add fry pellets. Keep the tank at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRemove the female after release and feed her well for a week or two before returning her to the male."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Give them space and rockwork as they grow, because even young kenyi squabble. At about 2 to 3 inches, young males start turning yellow, and you will need to split them up or move them on before they fight.\n\nFeed growing fry three or four small meals a day, with spirulina flake and pellets as the base. Kenyi are herbivores, so avoid rich protein foods beyond baby brine shrimp in the first weeks. Frequent water changes do more for growth than extra food. Sort out the largest fish if they start bullying their smaller siblings."}, {"heading": "Common mistakes", "text": "- Keeping kenyi in a tank that is too small, which leads to injured or dead females.\n- Keeping two males together.\n- Mixing them with similar blue barred mbuna and getting hybrids.\n- Leaving a holding female with the male.\n- Feeding high protein foods every day, which can cause bloat in these herbivores."}]$g$::jsonb, updated_at = now() where slug = $g$kenyi-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long tank is a good start, because multies use the bottom more than the height. Add at least 2 inches of fine sand, since they dig constantly and bury shells to make their homes. Then add 2 to 3 empty snail shells per fish, roughly 1.5 to 2 inches across. Shells sold for shell dwellers or cleaned escargot shells work well.\n\nThe site lists multies at {{temp}}°F, pH {{ph}} and GH {{gh}}. Aim for about 78 to 80°F and pH 8.2 to 8.6. A sponge filter is ideal, and a weekly 20 to 25 percent water change keeps things stable."}, {"heading": "Starting a colony", "text": "Males are noticeably larger than females, often close to 2 inches against about 1.25 inches for a female. That is the main way to tell them apart, which only works once fish are grown. The usual approach is to buy a group of 6 to 10 juveniles and let them sort out territories, or start with one male and two or three females.\n\nMulties are carnivores. Feed small amounts of baby or adult brine shrimp, daphnia, cyclops and a quality fine flake or micro pellet once or twice a day. Their mouths are small, so food size matters."}, {"heading": "Spawning: what you will see", "text": "You will rarely see the actual spawning. The female lays her eggs inside a shell and the male fertilizes them, all out of sight. The signs are a female who spends most of her time in or right at the mouth of one shell and fiercely chases other fish away from it.\n\nClutches are small, commonly a few eggs up to about 20 or 30. Each female will use her own shell, and a male often controls a territory containing several females."}, {"heading": "Eggs and the first week", "text": "The eggs hatch in roughly 2 to 3 days at 78 to 80°F, and the fry stay inside the shell while they absorb their yolk. About 7 to 10 days after spawning, you will see tiny fry hovering at the shell entrance and darting back inside when anything comes near.\n\nThere is nothing for you to do except keep the water clean and avoid disturbing the shells. Do not lift shells to check; you may spill or stress the fry."}, {"heading": "Raising the fry", "text": "Multie fry are best raised in the colony. Week 1: squirt baby brine shrimp or microworms near the shells with a pipette once or twice a day. Week 2 onward: add very finely powdered flake. Keep the temperature steady and do small water changes of 15 to 20 percent twice a week, siphoning gently above the sand.\n\nThe fry will start digging and claiming their own little spots as they grow. Adults generally tolerate their own young, which is why colonies grow so well."}, {"heading": "Growing out", "text": "Multies grow slowly. Expect fry to reach about 1/2 inch in 2 months, with full adult size taking many months. A colony can stay together for a long time, but once the tank gets crowded or fights over shells become constant, move some of the young to their own tank with plenty of shells.\n\nKeep adding shells as the colony grows. A good rule is to always have more shells than fish."}, {"heading": "Common mistakes", "text": "- Too few shells, which leads to fighting and lost fry.\n- Shallow sand, which stops them burying shells the way they like.\n- Feeding food that is too large for their small mouths.\n- Moving or rinsing shells while fry are inside.\n- Adding fish that compete for the bottom, such as other shell dwellers or bottom grazing cichlids."}]$g$::jsonb, updated_at = now() where slug = $g$multifasciatus-shell-dweller$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long tank is enough for a pair or a male with two females. Use at least 2 inches of fine sand, since ocellatus dig constantly and bury their shells until only the opening shows. Add at least 2 empty snail shells per fish, about 1.5 to 2 inches across.\n\nThe site lists ocellatus at {{temp}}°F, pH {{ph}} and GH {{gh}}. Breeding goes well at about 78°F and pH 8.2 to 8.6. A sponge filter and weekly 20 to 25 percent water changes keep the tank stable. Keep tankmates out, as these little fish will fight much larger ones over a shell."}, {"heading": "Choosing and conditioning a pair", "text": "Adult males are clearly larger than females, roughly 2 inches against about 1.5 inches. Both sexes have the dark spot on the gill cover that gives the fish its name. Some strains, such as gold ocellatus, have bright color in both sexes, so size is the best guide.\n\nA pair works well, and a male with two females also works if each female can claim her own shells. Feed small portions of brine shrimp, daphnia, cyclops and fine flake or micro pellets once or twice a day."}, {"heading": "Spawning: what you will see", "text": "The female picks a shell, buries it and starts guarding it. The male visits and courts her, and spawning happens inside the shell where you cannot see it. The female then spends most of her time in the shell or right at the opening and becomes very defensive.\n\nClutches are commonly around 20 to 50 eggs. The male is not much help with care, and he may move on to court other females."}, {"heading": "Eggs and the first week", "text": "The eggs hatch in roughly 2 to 3 days at about 78°F, and the fry stay inside the shell while they absorb their yolk. About 7 to 10 days after spawning, you will see tiny fry hovering around the shell entrance with mom keeping watch.\n\nLeave the shell alone. Lifting it to check will scatter the fry or stress the female."}, {"heading": "Raising the fry", "text": "Week 1 of free swimming: squirt baby brine shrimp or microworms near the shell once or twice a day. Week 2 onward: add very fine powdered flake. Keep the temperature steady and change 15 to 20 percent of the water twice a week, siphoning gently.\n\nAfter a few weeks, the female will usually want to spawn again and may start chasing the older fry away. That is the time to move them to their own grow out tank, along with a few shells."}, {"heading": "Growing out", "text": "Ocellatus grow slowly. Fry reach about 1/2 inch in 2 months, and full size can take most of a year. Grow them out in a tank with sand and plenty of small shells so each juvenile can find a spot. Feed small amounts several times a day and keep up water changes.\n\nAs they mature, young males start fighting over shells. Split them up or move them on before injuries happen.\n\nYoung ocellatus are easiest to sell or trade at around 1 inch, once they are big enough to eat small pellets and handle a move. Keep one or two of your best young females and an unrelated male if you want to start a fresh pair down the line. Label gold and regular forms separately so buyers know what they are getting."}, {"heading": "Common mistakes", "text": "- Too few shells, which leads to constant fighting.\n- Keeping them with other fish, which they will attack.\n- Lifting shells to look for eggs or fry.\n- Leaving older fry in with a female ready to spawn again.\n- Using coarse gravel, which stops them burying their shells."}]$g$::jsonb, updated_at = now() where slug = $g$ocellatus-shell-dweller$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for rusty cichlids, and that suits a breeding group of one male and three or four females. Stack rocks into caves and gaps, with a sand or fine gravel bottom and open swimming room in front.\n\nKeep the water at 76 to 82°F, pH 7.8 to 8.6 and GH 10 to 25, aiming for about 78 to 80°F and pH 8.0 to 8.4 for breeding. Change 30 to 50 percent of the water each week. Rusties are calmer than most mbuna, so avoid pairing them with very aggressive species that may stress the females."}, {"heading": "Building a breeding group", "text": "Rusties are hard to sex by eye. Males can be slightly larger and may show more egg spots on the anal fin, but females can show egg spots too. Venting is the most reliable method. Many breeders start with 6 to 8 juveniles and watch for the dominant male, then remove extra males.\n\nRusties are omnivores that graze on algae. Feed a spirulina based flake or pellet twice daily, with small portions of brine shrimp or mysis a couple of times a week for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The male darkens, shakes and leads a female to his chosen spot. She lays a few eggs, picks them up in her mouth and nips at his anal fin to fertilize them. Broods are small, commonly about 10 to 30 eggs.\n\nA holding female has a full throat, stops eating and hides near the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Since rusties are fairly peaceful, some breeders leave holding females in the main tank, but moving her after about a week to a 10 to 20 gallon tank with matched water gives the fry the best odds.\n\nNet her gently and avoid chasing her around the tank, which can make her spit. After release, give her a week or two of good feeding before putting her back."}, {"heading": "Raising the fry", "text": "The fry are released free swimming and ready to eat. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRusty fry are fairly peaceful with each other, which makes grow out easy. Do not overfeed: uneaten food in a small fry tank fouls the water quickly, so feed only what the fry clear in a minute or two and siphon the rest."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months, and around 2 inches by 5 to 6 months. They take on the rusty orange body and lavender sheen as they grow. Feed spirulina based foods as the base and keep the water changes going.\n\nBecause they are calm, young rusties can usually be raised in groups for longer than more aggressive mbuna. Move out obvious males when they start to dominate.\n\nThree or four small meals a day give the best growth, and frequent water changes help even more. Keep a few of your best young females and an unrelated male aside if you plan to start a new breeding group later, since breeding siblings over many generations can weaken a line."}, {"heading": "Common mistakes", "text": "- Keeping them with very aggressive mbuna, which stresses holding females.\n- Buying unvented adults and ending up with too many males.\n- Moving the holding female too early.\n- Feeding protein heavy foods every day."}]$g$::jsonb, updated_at = now() where slug = $g$rusty-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well for one pair. Use a sand bottom, plenty of plants, and a couple of caves such as coconut halves or small clay pots with an opening the female can use. Dim light and floating plants make them feel safe.\n\nThe site lists striped kribs at {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, aim for about 77 to 79°F, pH 6 to 6.5 and a GH under about 6. Soft water is the key difference from common kribs. A sponge filter and weekly 25 percent water changes with matched soft water keep them in shape."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing is easier than in many cichlids. Females are smaller and rounder, and when ready to spawn they show a bright, often purple or pink, belly. Males grow larger and have longer, pointed dorsal and anal fins. In many color forms, males also have spots or patterns on the tail.\n\nEach color form comes from a different location, such as Moliwe or Lokoundje. Keep forms separate and label them, so fry stay true to type. Condition the pair on frozen brine shrimp, bloodworms, daphnia and a good flake, fed twice a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The female shows her bright belly, bends her body and invites the male to a cave. She spends a lot of time inside cleaning it, and spawning happens on the cave ceiling or wall. Clutches of about 50 to 150 eggs are commonly reported.\n\nThe female then tends the eggs inside, while the male guards the area outside."}, {"heading": "Eggs and the first days", "text": "The eggs hatch in about 2 to 4 days at 77 to 79°F. The female moves the wrigglers around inside the cave while they absorb their yolk. Roughly 7 to 10 days after spawning, the fry swim out in a tight group with both parents guarding.\n\nFungus is not usually a problem, since the female fans and cleans the eggs. If a new pair eats the eggs, give them a few more chances."}, {"heading": "Raising the fry", "text": "Week 1 of free swimming: baby brine shrimp and microworms two or three times a day. Week 2: add finely crushed flake. Week 3 onward: crushed pellets and small frozen foods.\n\nKeep the temperature at 77 to 79°F and change 20 to 25 percent of the water every few days with matched soft water. The parents will guard the fry for several weeks. When they start getting ready to spawn again, move the fry to a grow out tank."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Young fish begin to show their color form at around 1.5 inches. Grow them out in a tank with caves and plants and keep up the water changes.\n\nBreeders report that water pH and temperature can affect the sex ratio of Pelvicachromis fry, so if you get very lopsided broods, try adjusting toward the middle of the range on the next spawn.\n\nFeed growing fry three or four small meals a day of baby brine shrimp, crushed flake and small frozen foods. Young striped kribs are generally peaceful with each other until they start pairing off at around 2 inches, which is a good time to sell or trade them in groups. Keep the color form name with every fish that leaves your tank."}, {"heading": "Common mistakes", "text": "- Using hard, alkaline water, which often leads to poor hatch rates.\n- Mixing color forms and losing the pure line.\n- Keeping them with boisterous tankmates that stress the pair.\n- Leaving older fry in when the parents spawn again."}]$g$::jsonb, updated_at = now() where slug = $g$striped-kribensis$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for yellow labs, and a group of one male and three or four females fits well in a 40 breeder or larger. Stack rocks into caves along the back, add sand or fine gravel and leave open water in front. Labs are calmer than most mbuna, but males still claim a territory.\n\nKeep the water at 75 to 82°F, pH 7.6 to 8.6 and GH 10 to 25. For breeding, aim for about 78 to 80°F and pH 8.0 to 8.4. Change 30 to 50 percent of the water every week."}, {"heading": "Choosing and conditioning a harem", "text": "Sexing yellow labs by looks is unreliable. Males usually grow larger and have more intense black on the dorsal, anal and pelvic fins, sometimes with a dusky throat. But many females also have black in their fins, so do not rely on it. Venting is the most reliable method. The other route is to grow out 6 to 8 juveniles and remove extra males once you see who is dominant.\n\nFeed a spirulina based flake or pellet twice a day with small portions of brine shrimp, mysis or daphnia a few times a week for about 2 weeks. Labs eat more protein than most mbuna, but rich foods every day can still cause bloat."}, {"heading": "Spawning: what you will see", "text": "The male brightens, shakes his body and leads a female toward a flat rock or cave. She lays a few eggs at a time, picks them up in her mouth and mouths at his anal fin to fertilize them. Spawning can last an hour or more.\n\nAfterward she hides with a puffy throat and stops eating. Broods are commonly about 10 to 25 eggs, with young females holding fewer."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Labs are mild enough that some breeders leave holding females in the main tank, but moving her after about a week to a 10 to 20 gallon tank with matched water gives the best fry survival.\n\nNet her gently without a long chase. Moving her in the first few days often makes her spit. Some breeders strip well developed fry, but natural release is easier on beginners and the female."}, {"heading": "Raising the fry", "text": "The fry come out free swimming, about 3/8 inch long and already yellow. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRemove the female after release and give her a week or two of good feeding before returning her to the group."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months and roughly 2 inches in 5 to 6 months. They are peaceful with each other, so grow out is straightforward. Feed three or four small meals a day if you can and keep up frequent water changes, which do more for growth than extra food.\n\nLook for good color: bright, even yellow and clean black fin edges. Keep your best fish for future breeding, and avoid breeding fish with faded or patchy color."}, {"heading": "Common mistakes", "text": "- Assuming black fins always mean male.\n- Keeping labs with similar yellow mbuna, which can lead to hybrids.\n- Moving the holding female too early.\n- Feeding heavy protein every day.\n- Overcrowding the grow out tank, which slows growth."}]$g$::jsonb, updated_at = now() where slug = $g$electric-yellow-lab$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for a group of Boeseman's rainbowfish. For a temporary breeding setup, a 30 gallon long or larger works for a male and two or three females. Add two or three spawning mops made of dark acrylic yarn, or dense fine leaved plants such as java moss. A sponge filter is ideal, because fry and eggs get pulled into stronger filters.\n\nThe site's care range is {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, aim for about 79 to 82°F and pH 7.2 to 7.8."}, {"heading": "Choosing and conditioning", "text": "Males are deeper bodied, with brighter blue fronts and orange to red rear halves, and longer dorsal and anal fins. Females are slimmer, with duller coloring. Males also show a bright color stripe on the forehead when displaying.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and spirulina, two or three times a day for about 2 weeks. A well fed group spawns more often and lays more eggs."}, {"heading": "Spawning: what you will see", "text": "Rainbowfish usually spawn in the morning, especially when the tank gets morning light. The male displays with his fins spread and a bright forehead stripe, then swims beside a female into the mop. She releases a few eggs at a time, each with a sticky thread that catches on the yarn or leaves.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick the eggs off, into a hatching tank or container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 12 days at 79 to 82°F. Because they are laid over several days, you will get a steady trickle of fry rather than one big hatch. Remove any eggs that turn white, since fungus can spread. A small dose of methylene blue in the hatching container helps, but remove it before the fry hatch."}, {"heading": "Raising the fry", "text": "Rainbowfish fry are tiny and stay near the surface. Week 1: infusoria, green water or liquid fry food, several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: add crushed flake.\n\nKeep the fry at 78 to 80°F with a gentle sponge filter, and change 10 to 20 percent of the water every few days with matched water. Keep the water clean but avoid big changes, which stress the fry. Many losses in the first two weeks come from starvation, so feed small amounts often."}, {"heading": "Growing out", "text": "Boeseman's rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. Young fish are silvery and plain, and the classic blue and orange colors can take a year or more to fully develop.\n\nFeed three or four times a day as they grow and keep up regular water changes. Separate fry by size if bigger siblings start bullying smaller ones.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch. More space and clean water are the two things that speed up rainbowfish growth the most. Keep your best colored fish back for future breeding."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults, who will eat them and the fry.\n- Feeding baby brine shrimp too early, before fry can eat it.\n- Mixing different Melanotaenia species in the breeding tank, which can cause hybrids.\n- Expecting full color in fry; it takes many months."}]$g$::jsonb, updated_at = now() where slug = $g$boesemani-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works for a breeding group of a male and two females, or a small group. Add one or two spawning mops of dark acrylic yarn or dense fine leaved plants like java moss. Use a sponge filter so eggs and fry are not sucked in.\n\nThe site lists dwarf neon rainbowfish at {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, aim for about 77 to 80°F and pH 7 to 7.5."}, {"heading": "Choosing and conditioning", "text": "Sexing is fairly easy. Males have bright red fins and a deeper body, and they show a brighter blue shimmer when displaying. Females have yellow to orange fins and are slimmer. Young fish are harder to sex until they mature at about 1.5 inches.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and some spirulina, two or three times a day for about 2 weeks before you add the mops."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male flashes his colors, spreads his fins and swims beside a female into the mop. She releases a few eggs at a time, each attached to the yarn or plants by sticky threads.\n\nThey spawn every day for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 10 days at 77 to 80°F. Because they are laid over several days, fry appear a few at a time. Remove any eggs that turn white with fungus. A small amount of methylene blue in the hatching container can help, but remove it before hatching.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry are tiny and stay at the surface. Week 1: infusoria, green water or liquid fry food several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: crushed flake.\n\nKeep the fry at 77 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water. Feed small amounts often, since starvation is the biggest cause of losses."}, {"heading": "Growing out", "text": "Dwarf neon rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. They show their blue color and red or yellow fins as they mature, usually by about 5 to 6 months.\n\nKeep feeding three or four times a day and keep up water changes. Sort them by size if bigger fish start pushing smaller ones off the food.\n\nMove the growing fry to a larger tank at around 1/2 inch, since space and clean water speed growth more than anything else. Dwarf neons are peaceful and do well in groups, so raise them together. Keep your best colored males and a few healthy females back to start the next generation."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Feeding baby brine shrimp too early.\n- Using strong filters in the fry tank.\n- Mixing different Melanotaenia species, which can hybridize."}]$g$::jsonb, updated_at = now() where slug = $g$neon-dwarf-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for forktail blue-eyes, and a 15 to 20 gallon tank is a good breeding setup. Add one or two spawning mops of dark acrylic yarn or plenty of fine leaved plants such as java moss. Use a sponge filter, since fry and eggs get pulled into stronger filters.\n\nKeep the water at {{temp}}°F, pH {{ph}} and GH {{gh}}, as the site lists. For breeding, aim for about 75 to 80°F and pH around 7."}, {"heading": "Choosing and conditioning", "text": "Males have larger, longer fins with bright yellow color and black edges, and they spar with each other constantly. Females are a little smaller and plainer with smaller fins. Sexing is easy in adults.\n\nFeed live or frozen foods such as baby brine shrimp, daphnia and cyclops, plus a fine flake, two or three times a day for about 2 weeks. These are small fish with small mouths, so choose small foods. Forktails spawn better when well fed and kept in a group with several females."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. Males display to females with fins spread, then swim beside a female into the mop or plants. She releases a few eggs at a time, each attached by a thread.\n\nForktails lay only a few eggs each day, but they spawn for many weeks, so egg numbers add up."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and pick off the eggs or move the mop to a hatching container with the same water. Breeders commonly report hatching after about 2 weeks, with a range of roughly 10 to 20 days depending on temperature.\n\nRemove any eggs that turn white with fungus. A small amount of methylene blue can help in the hatching container, but remove it before the fry hatch. Because eggs are collected over several days, fry hatch a few at a time.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry swim at the surface right after hatching. Week 1: infusoria, vinegar eels or very fine powdered food several times a day. Week 2: baby brine shrimp as soon as they can take it. Week 3 onward: crushed flake.\n\nKeep the fry at 75 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first week causes most losses."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 3 to 4 months. Males start to show their yellow fins at around 1 inch. Keep feeding three or four times a day and keep up water changes.\n\nForktail blue-eyes are short lived, often only about 2 to 3 years, so keep a few young fish back to breed next. Rotating new groups keeps the line healthy.\n\nMove the growing fry to a larger tank at around 1/2 inch if they are crowded. Forktails are peaceful and do well in groups, so raise them together, and keep a few of the best colored males and healthy females back for the next round of breeding."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Giving up on eggs too early; they can take 2 weeks or more to hatch.\n- Feeding food that is too large for the fry.\n- Using strong filters in the fry tank."}]$g$::jsonb, updated_at = now() where slug = $g$forktail-blue-eye$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for Lake Kutubu rainbowfish, so a 40 breeder or larger is a good breeding tank. Add two or three spawning mops of dark acrylic yarn or plenty of fine leaved plants like java moss. Use a sponge filter so eggs and fry are not sucked in.\n\nKeep the water at {{temp}}°F, pH {{ph}} and GH {{gh}}, as the site lists. For breeding, aim for about 78 to 80°F and pH 7.2 to 7.8."}, {"heading": "Choosing and conditioning", "text": "Males are deeper bodied, with brighter turquoise and blue color and longer dorsal and anal fins. Females are slimmer and paler. Males show a bright color stripe on the forehead when displaying.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and spirulina, two or three times a day for about 2 weeks before adding mops. Well fed fish spawn more often."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male displays with his fins spread and a glowing forehead stripe, then swims beside a female into the mop. She releases a few eggs at a time, each attached by a sticky thread.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 12 days at 78 to 80°F. Fry hatch a few at a time because eggs are laid over several days. Remove any eggs that turn white with fungus. A small amount of methylene blue can help, but remove it before hatching.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry are tiny and stay at the surface. Week 1: infusoria, green water or liquid fry food several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: crushed flake.\n\nKeep the fry at 78 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first weeks causes most losses."}, {"heading": "Growing out", "text": "Lake Kutubu rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. Young fish are silvery, and the full turquoise color can take a year or more to develop.\n\nFeed three or four times a day and keep up water changes. Separate fry by size if bigger siblings start bullying smaller ones.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch, since more space and clean water speed growth more than anything else. Keep your best colored fish back for future breeding, and avoid breeding fish with faded color or bent spines."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Feeding baby brine shrimp too early.\n- Mixing different Melanotaenia species, which can hybridize.\n- Expecting full color in fry; it takes many months.\n- Doing big water changes in the fry tank, which can shock the tiny fry."}]$g$::jsonb, updated_at = now() where slug = $g$turquoise-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a {{tank}} gallon minimum for Madagascar rainbowfish, so a {{tank}} gallon long or larger works for a breeding group. Add two or three spawning mops of dark acrylic yarn or plenty of fine leaved plants. A sponge filter keeps eggs and fry safe.\n\nThe site's care range is {{temp}}°F, pH {{ph}} and GH {{gh}}. These fish like cooler water than most rainbowfish, so aim for about 74 to 77°F for breeding with a pH near 7 to 7.5."}, {"heading": "Choosing and conditioning", "text": "Males have brighter fins, with red and black edging on the tail and dorsal fins, and are often slightly deeper bodied. Females are paler with less color in the fins. Sexing is easier in mature fish.\n\nFish sold as Madagascar rainbowfish are sometimes a closely related Bedotia species, since the names are often mixed up in the trade. Keep your group from one source and do not mix Bedotia types. Feed live or frozen foods such as brine shrimp, daphnia and bloodworms, plus a good flake, two or three times a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male displays with his fins spread and swims beside a female into the mop or plants. She releases a few eggs at a time, which stick to the yarn or leaves by fine threads.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and easy to spot.\n\nBreeders commonly report hatching in around a week, with cooler water taking longer. Fry hatch a few at a time because eggs are laid over several days. Remove any eggs that turn white with fungus. A small amount of methylene blue can help, but remove it before the fry hatch.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry swim at the surface after hatching. Week 1: infusoria, very fine powdered food or liquid fry food several times a day. Week 2: add vinegar eels and baby brine shrimp as soon as they can take it. Week 3 onward: crushed flake.\n\nKeep the fry at about 74 to 77°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first weeks causes most losses."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 3 to 4 months. They show their fin colors as they mature. Keep feeding three or four times a day and keep up water changes.\n\nBecause Madagascar rainbowfish are threatened in the wild, try to keep unrelated breeders and rotate new fish in over time to keep the line healthy.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch, since more space and clean water speed growth more than anything else. Keep your best colored, healthiest fish back for future breeding."}, {"heading": "Common mistakes", "text": "- Keeping them too warm, which shortens their lifespan and reduces spawning.\n- Leaving eggs in with the adults.\n- Feeding food that is too large for the fry.\n- Mixing different Bedotia species or populations."}]$g$::jsonb, updated_at = now() where slug = $g$madagascar-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank with a sponge filter is ideal. Fill much of the bottom with java moss, other fine-leaved moss or a spawning mop. Keep the water at 72 to 76°F, inside the care range of {{temp}}°F, with soft to moderately hard water around pH {{ph}}. Dim lighting or floating plants help these shy fish settle. A small hatching container with a gentle airstone is useful if you plan to collect eggs."}, {"heading": "Choosing and Conditioning the Group", "text": "Males have bright red orange fins with bold dark bars and a deeper blue body. Females are a little rounder and paler, with more orange than red in the fins. Males spar constantly but rarely cause harm.\n\nCondition the group with small live and frozen foods, such as daphnia, baby brine shrimp and cyclops, for 1 to 2 weeks. Well-fed females fill out noticeably."}, {"heading": "Spawning", "text": "Spawning happens near the bottom. A male displays to a female, leads her into the moss, and the pair release a few eggs at a time. Each session gives a small number, commonly around 10 to 30 eggs. In a mature group spawning can happen nearly every day.\n\nThere are two common methods. You can move a male and two or three females to the breeding tank for 3 to 5 days, then remove them. Or you can lift the moss every few days from the main tank into a separate container and let the eggs hatch there."}, {"heading": "Eggs and Hatching", "text": "The eggs are tiny and clear, and hard to see in moss. They commonly hatch in about 3 days at 72 to 76°F. Fry then hang on the glass and plants for a couple of days before swimming freely. Remove any eggs that turn white. A little methylene blue in a separate hatching container can help some breeders, but keep it out of a tank with moss and plants."}, {"heading": "Raising the Fry", "text": "CPD fry are very small and spend their first weeks near the bottom, hiding in moss.\n\n- Week 1: infusoria, vinegar eels and powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp and microworms\n- Week 4 on: crushed flake and small frozen foods\n\nFeed small amounts several times a day. Change about 10 to 20 percent of the water every couple of days with matched water. A clean bottom is important, so remove leftover food gently with a pipette. A small amount of moss in the fry tank gives them cover and a surface for biofilm to grow."}, {"heading": "Growing Out", "text": "Growth is slow at first and speeds up once the fry take baby brine shrimp. Juveniles start to show spots and fin color at around 6 to 8 weeks, and reach adult size and full color at about 2 to 3 months. Raising them in a planted tank with plenty of small foods gives the best color.\n\nMove the fry to a larger tank, 10 to 20 gallons, once they are taking baby brine shrimp well. Increase water changes to 20 to 30 percent a week. Sort out the largest fish if smaller ones fall behind. CPDs are peaceful as juveniles, but young males start sparring as their color appears, so give them plants and space. Keep a few of your best fish to start the next generation."}, {"heading": "Common Mistakes", "text": "- Leaving eggs in with the adults\n- Too little moss, so eggs are eaten as soon as they are laid\n- Missing the fry, which hide near the bottom for days\n- Large, sudden water changes\n- Expecting large spawns; this is a small batch fish"}]$g$::jsonb, updated_at = now() where slug = $g$celestial-pearl-danio$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is ideal. Use soft, acidic water: around pH 5.5 to 6.5 and GH {{gh}}, which sits inside the care range of pH {{ph}}. Keep the temperature at 77 to 80°F.\n\nFill a good part of the bottom with java moss or another fine moss, and add leaf litter and floating plants to dim the light. A sponge filter on a low setting keeps the water clean without sucking up fry. Mature tanks with established biofilm give much better results than new ones. If you can, let the tank run with moss and leaves for a month or more before adding the fish."}, {"heading": "Sexing and Conditioning", "text": "Males are slimmer and show more intense red color, especially when displaying. Females are rounder and paler. In practice, keeping a group of 6 to 10 gives you both sexes.\n\nCondition the group for 1 to 2 weeks with tiny live and frozen foods such as daphnia, cyclops and baby brine shrimp. Small, frequent meals work better than big ones for fish this size."}, {"heading": "Spawning", "text": "Chili rasboras spawn in moss and fine plants. A male shows his color and leads a female into the moss, where they release a few eggs. They tend to spawn often but in very small numbers, so you will not see a big event.\n\nTwo approaches work. One is to move a group into the breeding tank for about a week, then remove the adults. The other is to keep a heavily planted, species-only tank and let fry appear among the moss. This second method gives fewer fry but is less work."}, {"heading": "Eggs and Hatching", "text": "The eggs are tiny and very hard to find. They commonly hatch in about 1 to 2 days at 77 to 80°F, and the fry become free swimming a few days later. Keep the water stable and avoid disturbing the moss while you wait."}, {"heading": "Raising the Fry", "text": "Chili rasbora fry are some of the smallest fry in the hobby.\n\n- Weeks 1 to 2: infusoria, paramecium and the biofilm on moss and leaves\n- Weeks 2 to 3: vinegar eels and microworms\n- From about week 3: newly hatched baby brine shrimp\n\nFeed a little several times a day and keep a strong infusoria culture going so you never run short. Snails and a small amount of moss help clean up leftover food. Change about 10 percent of the water twice a week using soft water of the same temperature. Clean water matters, but large changes can do more harm than good."}, {"heading": "Growing Out", "text": "Growth is slow. Juveniles reach near adult size in about 3 months, and red color develops gradually. Keep them in soft water and feed small live foods to bring out the best color.\n\nOnce they are taking baby brine shrimp, move the young fish to a larger planted tank and increase water changes to about 20 percent a week, still using soft water. They can be sexed once color comes in. Chili rasboras are best kept and sold in groups, so wait until most of the batch is well colored before passing them on. Keep a group of your best fish to start the next generation."}, {"heading": "Common Mistakes", "text": "- Hard or alkaline water, which reduces spawning and egg survival\n- Leaving adults in with eggs and fry\n- A brand new tank without biofilm or infusoria\n- Big water changes with mismatched water\n- Giving up too soon; small spawns add up over weeks"}]$g$::jsonb, updated_at = now() where slug = $g$chili-rasbora$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or a thin layer of fine sand, a sponge filter and a spawning mop or some plants. Pandas like cooler water: keep the tank around 72 to 75°F, within the care range of {{temp}}°F. Soft to moderately hard water with a pH of 6 to 7.4 is ideal."}, {"heading": "Choosing and Conditioning the Group", "text": "Look down on your pandas from above. Females are larger and noticeably wider through the body, while males are smaller and slimmer. A group of at least 6, with about 2 males to each female, gives the best chance of spawning.\n\nCondition the group for 1 to 2 weeks with frequent meals of bloodworms, blackworms, brine shrimp and sinking pellets. Ripe females look rounded and full. Keep the tank clean during conditioning with regular water changes, since heavy feeding builds up waste quickly. Some breeders keep feeding heavily and doing cool water changes every few days until a spawn happens."}, {"heading": "Spawning", "text": "Do a large water change, 30 to 50 percent, with water a few degrees cooler than the tank. Spawning often follows within a day or two.\n\nYou will see males chasing a female, then the T-position, where the female clamps onto the male's side. She carries a small number of eggs between her pelvic fins and sticks them to the glass, plants or a mop. Panda spawns are usually small, commonly a few dozen eggs or fewer per session."}, {"heading": "Eggs and Fungus Prevention", "text": "Gently roll the eggs off the glass with a fingertip and move them to a hatching container with an airstone, or lift out the mop. Eggs commonly hatch in about 3 to 5 days at 72 to 75°F.\n\nFungus is the main risk. Remove any white, fuzzy eggs promptly. Some breeders add a little methylene blue or a few alder cones to the separate hatching container. Keep gentle water movement over the eggs."}, {"heading": "Raising the Fry", "text": "Panda fry live on their yolk sac for a day or two. Then feed small amounts several times a day.\n\n- Week 1: microworms and newly hatched baby brine shrimp\n- Weeks 2 to 4: add finely crushed sinking pellets\n- Week 4 on: small frozen foods and regular sinking food\n\nPanda fry are sensitive to poor water quality. Change 10 to 20 percent of the water every day or two and siphon out leftovers. A thin layer of fine sand in the fry tank often improves survival."}, {"heading": "Growing Out", "text": "Juveniles show the panda pattern early. They reach around three quarters of an inch in about 2 to 3 months. Keep them in a group in a tank with fine sand, keep the temperature on the cool side and continue weekly water changes of 25 to 30 percent.\n\nFeed several small meals a day of sinking pellets, baby brine shrimp and small frozen foods. Growth is steady but not fast, so be patient. Sort out runts and give them their own space if they are falling behind. A conditioned group will often spawn again every week or two, so keep a hatching container ready and plan room for several batches."}, {"heading": "Common Mistakes", "text": "- Keeping the breeding tank too warm for this cooler water species\n- Leaving eggs in with adults\n- Not removing fungused eggs quickly\n- Overfeeding fry and letting the water foul\n- Sharp gravel that damages barbels\n- Moving eggs into water with a different temperature"}]$g$::jsonb, updated_at = now() where slug = $g$panda-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is plenty for a breeding group of pygmy cories. Use a bare bottom or a thin layer of fine sand, a sponge filter on gentle flow and a good amount of fine-leaved plants or java moss. Pygmies often stick eggs on plant leaves and the glass rather than one spot.\n\nKeep the temperature at 72 to 77°F, within the care range of {{temp}}°F, with soft to moderately hard water around pH {{ph}}. A tight lid and a calm, species-only setup give the best results."}, {"heading": "Sexing and Conditioning the Group", "text": "Pygmy corydoras are about an inch long at most, so sexing takes a close look. Females are larger and rounder, especially from above, while males are smaller and slimmer. A group of 8 or more gives you a good mix and helps these social fish feel secure.\n\nCondition the group for 1 to 2 weeks with small, frequent meals of baby brine shrimp, daphnia, chopped bloodworms and fine sinking food. Females that fill out noticeably are ready."}, {"heading": "Spawning", "text": "Do a water change of about 30 percent with water a few degrees cooler than the tank. Spawning often follows within a day or two, though some groups need several tries.\n\nYou will see males chasing a female, then the classic T-position. The female carries one or a few eggs in her pelvic fins and sticks them on a leaf, moss or the glass. Eggs are spread around the tank rather than in one cluster. A session often adds up to a few dozen eggs, but small spawns are normal for this species."}, {"heading": "Eggs and Hatching", "text": "The eggs are small and clear and easy to miss. Check the glass, plant leaves and moss carefully with a flashlight. Roll eggs off the glass gently with a fingertip, or move the plants and moss with eggs into a hatching container with an airstone. You can also remove the adults instead.\n\nEggs commonly hatch in about 3 to 4 days at 72 to 77°F. Remove any eggs that turn white and fuzzy quickly so fungus does not spread. A few alder cones in a hatching container can help."}, {"heading": "Raising the Fry", "text": "Pygmy cory fry are very small and need fine foods. They live off their yolk for a day or two.\n\n- Week 1: microworms, vinegar eels and fine powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp\n- Week 4 on: crushed sinking food and small frozen foods\n\nFeed small amounts several times a day and siphon out leftovers. Change 10 to 20 percent of the water every day or two with water of the same temperature. A little moss and a thin layer of sand give the fry places to forage and help survival."}, {"heading": "Growing Out", "text": "Pygmies grow to near adult size, about an inch, in roughly 2 to 3 months. Keep the young in a group, since they are social from the start. Move them to a larger planted tank once they are eating baby brine shrimp well and continue weekly water changes of 20 to 30 percent. They will often begin swimming midwater in small schools like the adults."}, {"heading": "Common Mistakes", "text": "- Missing the eggs because they are scattered and small\n- Leaving eggs in a tank with other fish\n- Feeding food that is too large for the fry\n- Big swings in temperature during water changes\n- Keeping too few adults, which makes them shy and less likely to spawn"}]$g$::jsonb, updated_at = now() where slug = $g$pygmy-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is ideal. Use fine sand or a bare bottom, a gentle sponge filter, and fine-leaved plants or moss for the female to stick eggs on. Unlike pygmy corydoras, Corydoras habrosus stays near the bottom most of the time.\n\nKeep the water at 72 to 77°F, within the care range of {{temp}}°F, with a pH of {{ph}} and soft to moderately hard water. A calm, species-only tank works best. Larger or boisterous tankmates will eat eggs and stress these small catfish, and a peaceful tank also makes it easier to spot spawning when it happens."}, {"heading": "Sexing and Conditioning the Group", "text": "Sexing these tiny fish takes a close look from above. Females are larger and rounder through the body, and males are smaller and slimmer. In a group of 6 to 10 you will almost always have both.\n\nCondition with small, frequent meals for 1 to 2 weeks: baby brine shrimp, daphnia, chopped bloodworms and quality sinking food. Females should look noticeably full before you try to trigger a spawn."}, {"heading": "Spawning", "text": "A water change of about 30 percent with slightly cooler water is the usual trigger. Spawning often follows within a day or two, but some groups need a few rounds.\n\nYou will see males chasing a female and the T-position, after which she places one or a few eggs on a plant leaf, moss or the glass. Spawns are small, commonly a few dozen eggs or fewer, and eggs are spread around the tank."}, {"heading": "Eggs and Hatching", "text": "Search carefully, since the eggs are small and scattered. Roll eggs off the glass with a fingertip or move plants and moss into a hatching container with an airstone. Removing the adults is another option.\n\nEggs commonly hatch in about 3 to 4 days at 72 to 77°F. Remove any eggs that turn white and fuzzy. A few alder cones in a separate hatching container can help prevent fungus."}, {"heading": "Raising the Fry", "text": "The fry live on their yolk for a day or two, then begin foraging on the bottom.\n\n- Week 1: microworms, vinegar eels and fine powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp\n- Week 4 on: crushed sinking pellets and small frozen foods\n\nFeed small amounts several times a day and remove leftovers with a pipette or siphon. Change 10 to 20 percent of the water every day or two with temperature matched water. A thin layer of sand helps the fry forage naturally."}, {"heading": "Growing Out", "text": "Salt and pepper cories reach near adult size, about an inch, in roughly 2 to 3 months. Keep the young together in a group and move them to a larger tank with fine sand as they grow. Keep up weekly water changes of 20 to 30 percent and feed a mix of sinking pellets and live or frozen foods. The speckled pattern shows early, which makes them easy to tell from other small cories.\n\nA conditioned group will often spawn again every week or two, so keep a hatching container ready and plan space for several small batches. Because each spawn is small, many breeders collect eggs from a few sessions and raise them together. Keep the best grown fish to start your next breeding group."}, {"heading": "Common Mistakes", "text": "- Missing the scattered eggs\n- Leaving eggs with adults or tankmates\n- Feeding food too large for the fry\n- Coarse gravel that damages barbels\n- Confusing this species with pygmy cories, which swim midwater"}]$g$::jsonb, updated_at = now() where slug = $g$salt-and-pepper-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "Spotted hoplos reach about 6 inches, so a 40 gallon tank or larger is the minimum, in line with the care data. Keep the water at 77 to 80°F within the care range of {{temp}}°F. They tolerate a wide pH range of 6 to 8.\n\nFloat something for the male to build under. Breeders commonly use a plastic plate, a piece of foam, a lid or a large floating leaf. Use a sponge filter with gentle flow and keep a tight lid, as hoplos can jump. Some breeders lower the water level a few inches."}, {"heading": "Sexing and Conditioning", "text": "Hoplos are easiest to sex when mature. The male's first pectoral fin ray is a thick spine, longer and heavier than the female's, and in breeding condition it turns orange to reddish. Females have thinner spines and are often plumper.\n\nCondition the group for 1 to 2 weeks with plenty of bloodworms, earthworms, shrimp and sinking pellets. Keep up water changes while you feed heavily, as hoplos produce a lot of waste."}, {"heading": "Spawning", "text": "A large water change with cooler water is the usual trigger, and many breeders report better results during rainy or stormy weather. The male builds a large, foamy bubble nest under the floating object, often several inches across.\n\nThe pair spawn under the nest in a T-position similar to Corydoras. The female collects eggs in her pelvic fins and places them in the nest. Spawns commonly run to several hundred eggs. Once spawning ends, remove the female, as the male defends the nest aggressively."}, {"heading": "Eggs and the Male's Care", "text": "The male guards the nest and adds bubbles to keep the eggs covered. Do not put your hand near the nest; he may bite. Eggs commonly hatch in about 3 to 5 days at 77 to 80°F.\n\nMany breeders move the nest before hatching by sliding the plate or foam out with the eggs attached and placing it in a separate hatching tank with an airstone. Others leave the male in charge until hatching, then move the fry, as males may eat fry once they leave the nest."}, {"heading": "Raising the Fry", "text": "After hatching, fry drop to the bottom and live on their yolk for a day or two. Then they eat eagerly.\n\n- Week 1: newly hatched baby brine shrimp and microworms\n- Weeks 2 to 3: add finely crushed sinking pellets and wafers\n- Week 4 on: chopped frozen foods and small pellets\n\nFeed several times a day. Hoplo fry eat a lot and make a lot of waste, so change 20 to 30 percent of the water every day or two. Large spawns need room; split fry between tanks if they are crowded."}, {"heading": "Growing Out", "text": "Hoplo fry grow fast when fed well, reaching around an inch in about 2 months. Move them to larger tanks as they grow and keep up frequent water changes. Plan ahead for a large spawn: a few hundred juveniles take a lot of space and food, and adults need big tanks.\n\nSort the fry by size every couple of weeks, since faster growers can outcompete smaller siblings. Feed a mix of sinking pellets, chopped frozen foods and live foods several times a day. Juveniles are hardy and peaceful, and they do well in groups. Keep a few of your best grown fish if you want to start a second generation, choosing males that develop strong pectoral spines."}, {"heading": "Common Mistakes", "text": "- A tank too small for a 6 inch fish\n- No floating object for the nest\n- Leaving the female in with a guarding male\n- Reaching near the nest and getting bitten\n- Underestimating how much space a big spawn needs"}]$g$::jsonb, updated_at = now() where slug = $g$hoplo-catfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 15 to 20 gallon tank works well for a breeding group. Use a bare bottom or a thin layer of fine sand, a sponge filter and a spawning mop or a few plants. Sterbai cories like it warmer than many cories: keep the tank at about 77 to 80°F, inside the care range of {{temp}}°F. Soft to moderately hard water with a pH of 6 to 7.5 suits them."}, {"heading": "Sexing and Conditioning the Group", "text": "Look down on the fish from above. Females are larger and noticeably wider, while males are smaller and slimmer. Both sexes have the bright orange pectoral fin spines, so these do not help with sexing. A group of 6 or more with about 2 males per female works well.\n\nCondition for 1 to 2 weeks with frequent meals of bloodworms, blackworms, brine shrimp and quality sinking pellets. Ripe females look rounded through the belly. Keep up water changes during heavy feeding so waste does not build up in the tank."}, {"heading": "Spawning", "text": "The usual trigger is a large water change, 30 to 50 percent, with water a few degrees cooler than the tank. Spawning often follows within a day or two, and repeating the change every few days helps a reluctant group.\n\nDuring spawning, males chase the female until one forms a T-position with her. She carries a few eggs in her pelvic fins and sticks them on the glass, plants or a mop. Spawns are commonly a few dozen eggs, and sometimes more than 100 over a session."}, {"heading": "Eggs and Fungus Prevention", "text": "Roll the eggs gently off the glass with a fingertip and move them to a hatching container with an airstone, or lift out the mop. Eggs commonly hatch in about 3 to 5 days at 77 to 80°F.\n\nFungus is the main risk. Remove any white, fuzzy eggs right away. Many breeders add a little methylene blue or a few alder cones to the separate hatching container and keep a gentle flow of water over the eggs."}, {"heading": "Raising the Fry", "text": "Fry live on their yolk for a day or two, then begin feeding on the bottom.\n\n- Week 1: microworms and newly hatched baby brine shrimp\n- Weeks 2 to 4: add finely crushed sinking pellets and wafers\n- Week 4 on: small frozen foods and regular sinking food\n\nFeed small amounts several times a day and remove leftovers. Change 10 to 20 percent of the water every day or two with water at the same temperature. A thin layer of fine sand helps the fry forage and many breeders find it improves survival."}, {"heading": "Growing Out", "text": "Young sterbai show their spots early and their orange fins as they grow. They reach around an inch in about 2 to 3 months. Move them to a larger tank with fine sand as they grow, keep them in a group and continue weekly water changes of 25 to 30 percent. Conditioned adults often spawn again every week or two.\n\nFeed growing juveniles several small meals a day of sinking pellets, baby brine shrimp and small frozen foods. Sort out slower growers if they fall behind. Because spawns can repeat often, plan your tank space before you start, and keep a hatching container ready for the next batch. Keep the young fish warm, as they share the adults' preference for the warmer end of the range."}, {"heading": "Common Mistakes", "text": "- Keeping the breeding tank too cool for this warmer water species\n- Leaving eggs in with adults\n- Not removing fungused eggs quickly\n- Overfeeding fry and fouling the water\n- Sharp gravel that damages barbels"}]$g$::jsonb, updated_at = now() where slug = $g$sterbai-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is ideal. Cover the bottom with plastic mesh, marbles or a thick mat of java moss so eggs fall out of reach of the parents. Use a small sponge filter and keep the light low, or cover the sides with paper.\n\nThe site lists a range of pH {{ph}} and GH {{gh}} for keeping. For spawning, aim for the soft, acidic end: pH 6 to 6.5 and GH under 6, at 77 to 80°F. Rain water or RO water mixed with tap water and filtered over peat or leaves are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Females are rounder and deeper bodied, especially when full of eggs, while males are slimmer. Separate the sexes for one to two weeks if you can and feed generously with live or frozen brine shrimp, bloodworms and daphnia, plus a good flake.\n\nPick the roundest female and the most active, best colored male. Some breeders use two males with one female, which can improve fertility. Group spawning a few males and females together in a larger tank also works and needs less fuss over picking pairs, though egg eating is higher.\n\nStart preparing fry food now. Set up an infusoria culture and a vinegar eel or microworm culture a week or two ahead, because the fry will need them within days of hatching."}, {"heading": "Spawning: what you'll see", "text": "Move the pair into the breeding tank in the evening. Spawning commonly happens the next morning as light reaches the tank. The male chases the female through the moss, they quiver side by side, and a few eggs are released and fertilized each time. A full spawn is commonly 100 to 300 eggs over a couple of hours.\n\nIf nothing happens after two or three days, return the fish to conditioning and try again. A small, cooler water change of soft water can help start things."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning ends, as they will eat the eggs. Keep the tank dim, since the eggs and newly hatched fry are light sensitive. Eggs hatch in about 24 to 36 hours at 77 to 80°F.\n\nSome eggs will go white and fuzzy; these are infertile. Remove what you can with a pipette. A little methylene blue or a few dried leaves can help keep fungus down in soft water."}, {"heading": "Raising the fry", "text": "The fry hang on the glass and plants after hatching and become free swimming about 3 to 5 days later. At that point they need very small food.\n\n- Days 1 to 7 of free swimming: infusoria or paramecium, several times a day\n- Week 2: vinegar eels or microworms, adding newly hatched brine shrimp once they can take it\n- Weeks 3 to 6: brine shrimp and finely crushed flakes\n\nStart small water changes of about 10% every couple of days in the second week, using matched soft water. Keep the temperature steady around 77 to 79°F and gradually raise the light."}, {"heading": "Growing out", "text": "Black neons show their black and white stripes at a few weeks old and reach about three quarters of an inch in about 8 to 10 weeks. Move them into a larger tank with more frequent water changes as they grow, and keep feeding several small meals a day."}, {"heading": "Common mistakes", "text": "- Leaving adults in with the eggs\n- Bright light on the eggs and young fry\n- Hard, alkaline water, which lowers fertility\n- Offering baby brine shrimp before the fry can eat it\n- Big water changes that swing temperature or hardness"}]$g$::jsonb, updated_at = now() where slug = $g$black-neon-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Diamonds are a little larger than many tetras, so a 10 to 20 gallon tank works well. Use a sponge filter, a mat of java moss or a spawning mop, and mesh or marbles on the bottom. Keep the light dim.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}} for keeping. For spawning, aim for soft, acidic water: pH around 6 to 6.5 with low hardness, at 77 to 80°F."}, {"heading": "Conditioning and choosing a pair", "text": "Adult males develop long, trailing dorsal and anal fins and a stronger violet sparkle. Females are rounder with shorter fins. Note that the full sparkle takes many months to develop, so young fish can be hard to sex.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and a good flake. Separating the sexes during this time often improves results.\n\nChoose a female that looks clearly full of eggs and a male in his best color. Prepare an infusoria culture and a vinegar eel or microworm culture at least a week ahead, as you will need them within a few days of the eggs hatching. Having baby brine shrimp hatching on schedule for week two also saves a lot of stress."}, {"heading": "Spawning: what you'll see", "text": "Add the pair in the evening. Spawning commonly starts with the first light next morning. The male displays with spread fins and leads the female into the plants, where they quiver together and scatter eggs. A large, well fed female can lay a few hundred eggs over a couple of hours.\n\nIf they do not spawn within a few days, try a small water change with slightly cooler soft water. Some pairs need a second attempt after another week of conditioning, so do not give up after one try.\n\nA pair can be spawned again every couple of weeks if they are well fed between spawns, so a missed or poor first spawn is not a big loss."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning is over. Keep the tank dark or very dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nPull out white, fungused eggs where you can. A few dried leaves or a mild dose of methylene blue are common ways to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: brine shrimp and finely crushed flake\n\nFrom week two, change about 10% of the water every couple of days with matched water. Keep the temperature steady near 78°F."}, {"heading": "Growing out", "text": "Diamond tetra fry grow at a moderate pace, reaching about 1 inch in roughly 3 months. The famous sparkle develops slowly and can take most of a year to show fully. Give the growing fish more space and keep feeding varied foods.\n\nMove the young fish into a larger, planted tank once they are eating brine shrimp well. Weekly water changes of 20 to 30% and several small meals a day give the most even growth. Sort out any runts so they are not outcompeted at feeding time."}, {"heading": "Common mistakes", "text": "- Choosing young fish before they can be sexed reliably\n- Bright light on eggs\n- Hard, alkaline water\n- Leaving parents in the tank\n- Feeding food that is too large in the first week"}]$g$::jsonb, updated_at = now() where slug = $g$diamond-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is enough. The best results come from a mature tank that has been running for weeks with plenty of biofilm and microscopic life. Fill it with dense java moss or other fine leaved plants, use a gentle sponge filter, and keep the light low.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}} for embers. For breeding, stay soft and acidic: around pH 6 to 6.5 and GH under 5, at 77 to 80°F. A few dried leaves help soften and tint the water and grow infusoria at the same time."}, {"heading": "Conditioning and choosing a pair", "text": "Males are slimmer with a deeper orange red color, especially when displaying. Females are rounder through the belly and a little paler. Condition for one to two weeks with live or frozen baby brine shrimp, daphnia, cyclops and a fine flake.\n\nEmbers are tiny, so their foods should be tiny too. Pick one plump female with one or two of the brightest males, or move a small group of four to six fish into the breeding tank. Start an infusoria culture and a vinegar eel culture before you set them up."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the morning. The male flashes his colors and drives the female into the moss, where they quiver together and release a few eggs at a time. Embers lay far fewer eggs than larger tetras; a few dozen per spawn is typical, and the eggs are almost invisible.\n\nThere are two common methods. One is to leave the pair in for two or three days and then remove them. The other is a colony approach: keep a small group in a heavily mossed species tank and let a few fry survive among the moss without separating anything. The colony method gives fewer fry per spawn but needs little effort."}, {"heading": "Eggs and fungus", "text": "Once the adults are out, keep the tank dim. Eggs hatch in about 24 to 36 hours at 77 to 80°F. Because the eggs are so small and hidden in moss, you may not see them at all until fry appear.\n\nFungus is less of a problem in a mature, leafy tank, but keep the water clean and avoid overfeeding the adults while they are in the tank."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 4 days after hatching and are tiny, close to the size of a dust speck. This is the stage where most attempts fail.\n\n- Week 1: infusoria or paramecium several times a day, plus whatever grows on the moss\n- Week 2: vinegar eels added, along with very fine powdered fry food\n- Weeks 2 to 3 on: newly hatched brine shrimp once their bellies can take it\n\nDo not change much water in the first week; top up with matched soft water. From week two, small changes of about 10% every few days keep things clean. Keep the temperature steady at 77 to 79°F."}, {"heading": "Growing out", "text": "Ember fry grow slowly at first and then pick up speed once they eat baby brine shrimp. Expect around 2 to 3 months to reach about half an inch and start showing orange color. They can join the adults in a planted tank once they are too big to be eaten, usually at about a third of an inch."}, {"heading": "Common mistakes", "text": "- Starting in a brand new, sterile tank with no microscopic food\n- Offering baby brine shrimp too early; the fry are too small\n- Large water changes that shock tiny fry\n- Hard water, which cuts fertility\n- Expecting large spawns like bigger tetras"}]$g$::jsonb, updated_at = now() where slug = $g$ember-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 5 to 10 gallon tank with a sponge filter, mesh or marbles on the bottom, and a mat of java moss or a spawning mop. Keep the room dim and cover the sides.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}} for glowlights. For spawning, aim for soft, slightly acidic water around pH 6 to 6.5 and GH under 6, at 78 to 80°F. Filtering over peat or mixing RO water with tap water are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and noticeably rounder, especially from the side, while males are slimmer. Condition for one to two weeks on brine shrimp, bloodworms, daphnia and flake, ideally with the sexes kept apart.\n\nChoose a female that looks full of eggs and an active, well colored male. Start an infusoria culture and a microworm or vinegar eel culture before you spawn them.\n\nA female that has been well fed for two weeks is usually obvious: she looks swollen behind the pelvic fins when viewed from above. If she still looks slim, give it another week. Spawning an underconditioned female tends to give small spawns with many infertile eggs, which only invites fungus into the tank."}, {"heading": "Spawning: what you'll see", "text": "Move the pair in the evening. In the morning the male chases the female and the two often swim side by side and roll over together as they release eggs, a behavior many breeders describe as a barrel roll. Eggs drop into the moss a few at a time. A full spawn is commonly 100 to 200 eggs.\n\nIf nothing happens in two or three days, try a small water change with slightly cooler soft water. If that fails, return them to conditioning for another week."}, {"heading": "Eggs and fungus", "text": "Remove the adults right after spawning. Keep the tank dim, as tetra eggs are light sensitive. Eggs hatch in about 24 hours at 78 to 80°F.\n\nInfertile eggs turn white and grow fungus. Remove them where you can and consider a few dried leaves or a light dose of methylene blue to keep fungus down."}, {"heading": "Raising the fry", "text": "The fry hang on the glass and moss at first, then become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching temperature and hardness. Slowly increase light as the fry grow. Keep the temperature steady around 78°F, since swings stress tiny fry.\n\nA common trick is to add a few small snails or a little established moss from another tank before the fry hatch. They help keep uneaten food from fouling the water while the fry are too small to clean up after."}, {"heading": "Growing out", "text": "Glowlight fry grow at a steady pace and reach about three quarters of an inch in 2 to 3 months. The glowing stripe appears after a few weeks. Move them to a larger tank as they grow, feed several small meals a day and keep up weekly water changes of 20 to 30%."}, {"heading": "Common mistakes", "text": "- Bright light on the eggs and young fry\n- Leaving the parents in the tank\n- Water that is too hard\n- Feeding food that is too big in the first week\n- Overfeeding a bare breeding tank\n- Moving fry to new water without matching temperature"}]$g$::jsonb, updated_at = now() where slug = $g$glowlight-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty. Plant it heavily with fine leaved plants or moss, add a gentle sponge filter, and keep the light low. Floating plants help keep the surface dim.\n\nThe site lists a wide range of {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, aim for the soft, acidic end: around pH 6 to 6.5 and GH under 5, at 77 to 79°F."}, {"heading": "Conditioning and choosing a pair", "text": "Males are slimmer, show a stronger red in the fins and stripe, and usually have white or bluish tips on the pelvic fins. Females are rounder and paler. Like other pencilfish, both sexes switch to a pattern of dark blotches at night, which is normal.\n\nCondition for one to two weeks with small live and frozen foods such as daphnia, cyclops and baby brine shrimp. Pencilfish have small mouths, so keep foods fine. Start infusoria and vinegar eel cultures in advance."}, {"heading": "Spawning: what you'll see", "text": "Pencilfish do not spawn in a single burst. The male displays with spread fins, leads the female into the plants and the pair release a few eggs at a time. This continues on and off for days. The total from one pair is commonly a few dozen eggs over a spawning period.\n\nBecause the adults eat eggs, many breeders use one of two methods. One is to move the clumps of moss or plants into a separate hatching tank every day or two and replace them. The other is to leave a pair in a very heavily planted tank for about a week and then remove the adults."}, {"heading": "Eggs and fungus", "text": "The eggs are small, clear and hard to see. They hatch in roughly 1 to 3 days at 77 to 79°F, depending on temperature. Keep the hatching tank dim.\n\nFungus is usually limited in a planted, soft water setup, but remove any white eggs you can see and avoid overfeeding nearby."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 5 days after hatching. They are very small and need microscopic food.\n\n- Week 1: infusoria or paramecium several times a day\n- Week 2: vinegar eels and very fine powdered food\n- Week 3 on: newly hatched brine shrimp, then crushed flake\n\nKeep water changes small, about 10% every few days with matched soft water, and avoid temperature swings. If you move plants with eggs every few days, you will end up with fry of different ages, so keep batches in separate containers if you can, as larger fry outcompete smaller ones."}, {"heading": "Growing out", "text": "Pencilfish fry grow slowly at first. Expect roughly 3 months to reach about 1 inch, and a little longer for the full adult color. Feed several small meals a day and keep up regular water changes in a planted grow out tank.\n\nGolden pencilfish stay peaceful as they grow, so a planted community style grow out tank with only small, gentle tank mates works well once the young are about half an inch. Males start to show the red fins and white pelvic tips as they mature, which makes it easy to pick out future breeding pairs. Weekly water changes of 20 to 30% and fine, varied foods give the best color."}, {"heading": "Common mistakes", "text": "- Waiting for one big spawn, when pencilfish lay a few eggs a day\n- Leaving eggs with the adults for weeks\n- Offering food too large for the fry's tiny mouths\n- Hard or alkaline water\n- Mixing fry of very different sizes"}]$g$::jsonb, updated_at = now() where slug = $g$beckford-pencilfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank works well. Add a sponge filter, mesh or marbles on the bottom, and a mat of java moss or a spawning mop. Keep the light dim.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}} for keeping lemons. For spawning, aim for soft, slightly acidic water: around pH 6 to 6.5 and GH under 6, at 77 to 80°F."}, {"heading": "Conditioning and choosing a pair", "text": "Mature males show a broader black edge along the bright yellow anal fin, and the top of the eye turns a vivid red when they are in condition. Females are rounder and slightly paler.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and flake. Separating the sexes helps. Choose a plump female and the most colorful male, or put a small group of two males and two females into a larger breeding tank. Get infusoria and microworm or vinegar eel cultures going a week ahead of time."}, {"heading": "Spawning: what you'll see", "text": "Move the fish in the evening. Spawning usually starts the next morning. Males display with spread yellow fins, chase the female into the plants and the pair quiver side by side to release eggs. A full spawn is commonly 100 to 300 eggs.\n\nIf they do not spawn in a few days, try a small, slightly cooler soft water change, then go back to conditioning if needed.\n\nWatch the male's color. A ready male turns a much stronger yellow and the black on his fins becomes very sharp. A pale, shy male in the breeding tank usually means the fish are not yet settled. Give them a day or two before deciding the attempt has failed."}, {"heading": "Eggs and fungus", "text": "Remove the adults straight after spawning. Keep the tank dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nRemove white, fungused eggs where you can. A few dried leaves or a light dose of methylene blue can help limit fungus.\n\nThe eggs are small and slightly sticky, so most will be caught in the moss or under the mesh. Leave them where they fell rather than trying to move them."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching temperature and hardness. Gradually increase the light.\n\nA large spawn can produce more fry than one small tank can support. Once they are on baby brine shrimp, thin them out into a second tank rather than letting the water quality slide."}, {"heading": "Growing out", "text": "Lemon tetra fry reach around 1 inch in about 3 months. The yellow color builds slowly and the full adult color takes several more months. Grow them out in a larger tank with weekly 20 to 30% water changes and varied foods. Lemons that get a good mix of foods tend to color up better as adults.\n\nOnce the young fish are about half an inch they can move into a planted tank with other small, peaceful fish. Keep back a few of the best colored males and roundest females as your next breeding group. Avoid pairing siblings for generation after generation; bring in unrelated stock from time to time."}, {"heading": "Common mistakes", "text": "- Leaving the parents with the eggs\n- Bright light on the eggs\n- Hard water lowering fertility\n- Feeding food too large in the first week\n- Crowding a large spawn into a small tank\n- Expecting full adult color from young fish"}]$g$::jsonb, updated_at = now() where slug = $g$lemon-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 to 20 gallon tank with a sponge filter, mesh or marbles on the bottom, and a thick mat of java moss or a spawning mop. Keep the light low.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Penguins are not as fussy as some tetras, but softer, slightly acidic water around pH 6.5 and GH under 8, at 77 to 80°F, improves fertility and hatch rates."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and deeper through the belly, while males are slimmer. Condition for one to two weeks on bloodworms, brine shrimp, daphnia and quality flake.\n\nPick the roundest female and an active male, or try two males with one female. Because penguins can lay a lot of eggs, prepare plenty of infusoria and microworms or vinegar eels in advance, and think about where a big batch of fry will go."}, {"heading": "Spawning: what you'll see", "text": "Move the fish into the breeding tank in the evening. Spawning commonly happens the next morning. The male chases the female into the plants and they quiver side by side, releasing eggs a few at a time. Penguin tetras are often described as prolific; several hundred eggs from one spawn is commonly reported.\n\nIf they do not spawn in two or three days, try a small cooler water change, then return them to conditioning if needed.\n\nPenguins swim at a characteristic head up angle, and a ready male will display around the female with spread fins. Spawning usually lasts a couple of hours. Once the female looks noticeably slimmer and the chasing stops, the spawn is over."}, {"heading": "Eggs and fungus", "text": "Remove the adults right after spawning. Keep the tank dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nWith so many eggs, some will be infertile. Remove white, fungused eggs where you can, and consider a few dried leaves or a light dose of methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nA large batch of fry fouls water fast. Start 10 to 20% water changes every day or two from week two, matching temperature and hardness. Split the fry into more tanks as they grow rather than letting water quality drop. A few small snails in the fry tank help clean up uneaten food. Keep the temperature steady at 77 to 79°F."}, {"heading": "Growing out", "text": "Penguin fry grow at a good pace and show the black tail stripe early. Expect about 3 months to reach roughly 1 inch. Keep feeding several times a day, keep up weekly 20 to 30% water changes and give the growing fish room. Thinning out a large spawn early leads to bigger, healthier young fish.\n\nBy around half an inch the young fish can share a planted tank with other small, peaceful species. Penguins are a schooling fish, so keep the young in groups. When it is time to pass them on, a group of at least six is the friendliest way to rehome them."}, {"heading": "Common mistakes", "text": "- Leaving the parents in with the eggs\n- Not planning space for a big spawn\n- Letting fungus spread across a large batch of eggs\n- Feeding too large a food in the first week\n- Skipping water changes in a crowded fry tank\n- Bright light on eggs and newly hatched fry"}]$g$::jsonb, updated_at = now() where slug = $g$penguin-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank with a sponge filter, mesh or marbles on the bottom and a thick mat of java moss or a spawning mop is ideal. Keep the light dim and cover the sides.\n\nThe site lists a cooler, softer range for red phantoms: {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, keep the water soft and acidic, around pH 6 and GH under 4, at about 75 to 78°F. Peat filtration, dried leaves and RO water are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing is fairly easy in adults. Males have a taller, more pointed, mostly red dorsal fin and are slimmer. Females have a smaller dorsal fin marked with black and white, and a rounder belly.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and a quality flake. Wild caught or recently imported fish may need longer to settle and recover before they spawn well. Pick the roundest female and a male in strong color.\n\nSet up infusoria and microworm or vinegar eel cultures at least a week ahead. The fry need tiny food within days of hatching, and it is hard to start a culture fast enough once they are already swimming."}, {"heading": "Spawning: what you'll see", "text": "Move the pair into the breeding tank in the evening. Spawning commonly starts the next morning. The male displays with his red fins spread, leads the female into the moss, and the pair quiver side by side to release a few eggs at a time. A well conditioned female commonly lays 100 to 300 eggs.\n\nIf they do not spawn in a few days, a small water change with slightly cooler, very soft water may help. Some pairs need a second or third try.\n\nYou can also try a small group spawn with two males and one or two females in a slightly larger tank. Competition between males often triggers spawning in fish that ignore each other as a single pair. Expect more egg eating in a group spawn, so remove the adults promptly."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning ends. Keep the tank dark or very dim, as the eggs are light sensitive. Eggs hatch in about 1 to 2 days at 75 to 78°F.\n\nIn very soft water, fungus can spread quickly from dead eggs. Remove white eggs where you can and consider a few dried leaves or a light dose of methylene blue."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching the soft water closely. Keep the temperature steady and slowly increase the light."}, {"heading": "Growing out", "text": "Red phantom fry grow steadily and reach about three quarters of an inch in around 3 months. Red color builds gradually as they mature. Grow them on in a larger tank with weekly 20 to 30% water changes and varied foods. Slowly acclimate young fish to slightly harder water if they are going to buyers with different tap water.\n\nOnce the young fish are about half an inch they can share a planted tank with other small, peaceful fish. Keep a group of the best colored young as future breeders, and bring in unrelated fish now and then to avoid inbreeding over many generations."}, {"heading": "Common mistakes", "text": "- Water that is too hard or alkaline\n- Running the breeding tank too warm\n- Bright light on eggs\n- Leaving the adults in after spawning\n- Feeding food that is too large in the first week"}]$g$::jsonb, updated_at = now() where slug = $g$red-phantom-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and a tight fitting glass lid. Splash tetras are excellent jumpers, so the lid is essential. Lower the water level to leave a gap of about 2 to 4 inches between the surface and the lid.\n\nGive the pair a spawning surface above the water. Many breeders let them use the underside of the glass lid, or place a broad plant leaf or a sloping piece of slate that overhangs the surface. Floating plants help the fish feel secure.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. For spawning, soft and slightly acidic water around pH 6 to 6.5 at 77 to 80°F works well."}, {"heading": "Conditioning and choosing a pair", "text": "Males are larger and more colorful, with longer, flowing fins edged in red or orange. Females are smaller with shorter fins and less color.\n\nCondition for one to two weeks. Splash tetras feed heavily at the surface, so mosquito larvae, fruit flies, bloodworms and brine shrimp are ideal, along with flake. Pick a plump female and a male in full color.\n\nKeep the pair in the breeding tank for a few days before expecting a spawn. A settled male starts patrolling a spot just under the lid or leaf, which is usually where the eggs will be laid. If he picks a spot you cannot see well, that is fine; the splashing tells you where the eggs are."}, {"heading": "Spawning: what you'll see", "text": "The male courts the female near the surface and leads her to the spot he has picked. The pair then leap out of the water together, cling to the surface for a moment, and lay a few eggs before dropping back. This repeats many times, and the total commonly reaches several dozen to over 100 eggs.\n\nAfterward the male stays close to the egg site and regularly flicks water onto the eggs with his tail to keep them from drying out. Watching this is the best way to confirm a spawn."}, {"heading": "Eggs and hatching", "text": "Leave the male to do his job. The eggs hatch in about 2 to 3 days at 77 to 80°F, and the fry drop into the water below. Keep the room humid and the lid closed so the eggs do not dry out.\n\nOnce the eggs have hatched, remove both adults, as they may eat the fry. If the male is not tending the eggs, some breeders keep them moist with a gentle mist of tank water instead."}, {"heading": "Raising the fry", "text": "The fry become free swimming within a few days of hatching and stay near the surface.\n\n- First week: infusoria or vinegar eels several times a day\n- Week 2: newly hatched brine shrimp and very fine powdered food\n- Weeks 3 to 8: baby brine shrimp and crushed flake\n\nChange about 10% of the water every couple of days from week two, matching temperature and softness. Keep the lid on even for fry, as young splash tetras jump too.\n\nThe fry do best with a little floating plant cover and gentle filtration. Feed small amounts often, and siphon the bottom every day or two so leftover food does not foul the water."}, {"heading": "Growing out", "text": "Fry grow at a moderate pace, reaching about 1 inch in roughly 3 months. Males start to show longer fins as they mature. Grow them on in a covered tank with regular water changes and small surface foods."}, {"heading": "Common mistakes", "text": "- No lid, or a lid with gaps; splash tetras will jump out\n- Water level too high, leaving no space for egg laying\n- Removing the male before the eggs hatch\n- Leaving adults in with newly hatched fry\n- Letting the room dry out so eggs shrivel"}]$g$::jsonb, updated_at = now() where slug = $g$splash-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A pair needs a tall tank of of at least 30 gallons. Use a sponge filter or a well covered intake and a bare bottom for easy cleaning. Add a spawning site: a slanted slate, a length of PVC pipe, a broad plant leaf or a cone leaning against the glass.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Domestic angels spawn readily in that range. Most breeders keep spawning pairs at about 80 to 82°F with stable water and regular changes."}, {"heading": "Getting and conditioning a pair", "text": "Angelfish are hard to sex until they spawn. The most reliable way to get a pair is to raise about six young fish together and watch for two that claim a corner and chase the others away. Once they spawn, you can see the breeding tubes: the female's is broad and blunt, the male's is narrow and pointed.\n\nCondition for two to three weeks with bloodworms, brine shrimp, blackworms and quality pellets. Do frequent water changes during this time. Angels usually reach breeding age at around 8 to 12 months."}, {"heading": "Spawning: what you'll see", "text": "A pair ready to spawn will choose a site and clean it carefully with their mouths for a day or more. The breeding tubes then drop. The female makes passes along the surface laying rows of eggs, and the male follows to fertilize them. Spawns are commonly 200 to 1000 eggs, with older, larger females at the upper end.\n\nHealthy pairs often spawn every 1 to 2 weeks if they are well fed and their eggs are removed.\n\nIf you choose to let the parents raise the eggs, keep the tank quiet, avoid moving decor and keep other fish out. Parents that get through to free swimming fry can be great to watch, as they herd the cloud of babies around the tank."}, {"heading": "Eggs and fungus", "text": "You have two choices. Leave the eggs with the parents, who will fan and guard them, or remove the slate to a separate hatching tank. Many breeders remove the eggs, especially with young pairs that eat their first few spawns.\n\nIn a hatching container, place an air stone near the eggs so bubbles gently move water across them, and add a little methylene blue to help prevent fungus. Eggs hatch in about 2 to 3 days at 80 to 82°F. Infertile eggs turn white; remove them if you can."}, {"heading": "Raising the fry", "text": "After hatching, the fry are wigglers that hang from the slate or the bottom for about 4 to 5 days while they absorb their yolk. Once they swim freely, start feeding.\n\n- Weeks 1 to 2: newly hatched brine shrimp two or three times a day\n- Weeks 3 to 4: brine shrimp plus finely crushed flake or small pellets\n- Week 5 on: frozen foods and small pellets\n\nChange 10 to 20% of the water every day or two once they are eating, siphoning uneaten food. Keep the temperature around 80°F.\n\nA bare bottom makes it much easier to see and remove leftover brine shrimp. If you hatch eggs artificially, wait until the fry are swimming before you remove the methylene blue with water changes."}, {"heading": "Growing out", "text": "Angel fry grow quickly with good feeding. Fins and body shape develop within a few weeks, and they reach about quarter size in roughly 6 to 8 weeks. Most breeders sell them at quarter to half dollar body size, which takes around 2 to 3 months or more. Thin out the fry into more tanks as they grow; crowding stunts them."}, {"heading": "Common mistakes", "text": "- Buying two adults and assuming they are a pair\n- Giving up when a young pair eats its first spawns\n- No fungus control on artificially hatched eggs\n- Feeding fry before they are free swimming\n- Crowding fry in too small a tank"}]$g$::jsonb, updated_at = now() where slug = $g$angelfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Start with a 10 gallon or larger tank, an active buffering soil that holds pH low, and a sponge filter so babies cannot be sucked in. Let the tank cycle fully and mature for several weeks so biofilm forms on every surface.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Most breeders keep crystal reds at about 70 to 74°F. Use RO or rain water remineralized with a GH only shrimp mineral, so KH stays near zero. Total dissolved solids around 100 to 200 are commonly targeted. Stability matters more than any single number."}, {"heading": "Choosing and conditioning a colony", "text": "Females are larger with a deeper, broader abdomen that forms a pouch for eggs. Males are smaller and slimmer. A group of 10 or more shrimp almost always includes both sexes.\n\nFeed small amounts of varied foods: a quality shrimp pellet, powdered biofilm food, blanched vegetables and leaf litter such as dried oak or almond leaves. Remove uneaten food after a few hours. Do small, steady water changes with matched water rather than large ones."}, {"heading": "Mating and berried females", "text": "When a mature female molts, she releases a scent into the water. Males start swimming fast around the tank searching for her, which breeders call the mating dance. Mating happens within hours.\n\nShortly after, the female moves eggs under her tail, where she carries and fans them. A berried female commonly carries about 20 to 30 eggs. The eggs are carried for about 30 days at 70 to 74°F, and you will see them darken and develop eyes as they mature."}, {"heading": "Avoiding dropped eggs", "text": "Stressed females can drop their eggs. The common causes are large water changes, sudden parameter swings, catching or moving berried females, and high temperatures. Keep things calm and stable while females are carrying. Top up evaporation with RO water so TDS does not creep up.\n\nTemperature is a big factor. Crystal reds are sensitive to warm water, and summer heat is a common reason for berried females dropping eggs or colonies crashing. If the room gets warm, a small fan across the surface or a cooler room helps. Check your soil too: active buffering soils lose their effect over time, often after a year or two, and pH slowly rises. When that happens, breeding usually slows down long before shrimp start dying, so a sudden drop in berried females is a useful early warning."}, {"heading": "Raising the babies", "text": "Babies hatch as tiny copies of the adults, only a couple of millimeters long, and immediately start grazing.\n\n- Weeks 1 to 4: biofilm, powdered baby shrimp food, leaf litter\n- Month 2 on: shrimp pellets and the same foods as adults\n\nMature tanks with lots of moss and biofilm raise more babies. Keep the sponge filter clean but not sterile, and avoid strong flow. Do not keep fish in the breeding tank, as almost any fish will eat baby shrimp."}, {"heading": "Growing out", "text": "Crystal red babies grow slowly compared with cherry shrimp. Expect around 4 to 5 months before young females carry their first eggs. Grading out the best colored shrimp for breeding keeps the colony quality high.\n\nOnce the colony grows, move the best shrimp into a separate tank and sell or move on the rest. Keeping lower grade shrimp with your best breeders slowly dilutes color over generations."}, {"heading": "Common mistakes", "text": "- Using tap water with high KH that drives pH up\n- Large or sudden water changes\n- Overfeeding and polluting a small tank\n- Adding shrimp to a tank that has not matured\n- Keeping fish in the shrimp tank, as they eat babies\n- Medications or plant products containing copper"}]$g$::jsonb, updated_at = now() where slug = $g$crystal-red-shrimp$g$;
update public.breeding_guides set sections = $g$[{"heading": "How rabbit snails reproduce", "text": "Rabbit snails have separate sexes, so you need both a male and a female. After mating, the female carries a developing egg inside her body and later releases a single large white egg capsule. A fully formed baby snail emerges from it. Some females release more than one capsule at a time, but one is typical.\n\nBreeders commonly report a new capsule every few weeks from a healthy female. Output is slow compared with most snails, so a colony grows gradually rather than exploding."}, {"heading": "Setting up the breeding tank", "text": "A 20 gallon or larger tank gives a group room to roam. Use a soft sand bottom, plenty of hiding spots, and some leaf litter. A sponge filter or a well covered intake protects babies.\n\nRabbit snails come from warm lakes and rivers on Sulawesi. The site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Most breeders keep them at about 78 to 82°F in hard, alkaline water. Low pH and soft water can damage the shell over time."}, {"heading": "Choosing and conditioning a group", "text": "Telling males from females by looking at the shell is very difficult, and the shell is not a reliable guide. The simple answer is to keep a group of at least five snails, which almost always includes both sexes.\n\nFeed well and steadily. Rabbit snails eat blanched vegetables like zucchini and spinach, sinking pellets and wafers, algae and decaying leaves. A well fed group in warm, stable, hard water is the best trigger for breeding."}, {"heading": "Egg capsules and babies", "text": "Look for a white, round egg capsule on rocks, glass or decor. It is often found near the bottom. A baby snail emerges from it as a tiny, fully formed rabbit snail, a few millimeters long.\n\nThere is nothing you need to do at this stage. Leave the capsule where it is and keep the water stable.\n\nCapsules are easy to overlook in a tank with gravel or lots of decor, which is one reason a sand bottom and a fairly simple layout help. Check the tank regularly with a flashlight. If you find a capsule, note the date so you can time your Society stages. Avoid moving it unless it is somewhere fish could reach it."}, {"heading": "Raising the babies", "text": "Babies graze on biofilm right away. Add a little extra food for them:\n\n- First weeks: biofilm, algae, crushed sinking pellets, blanched vegetables\n- Following months: the same foods as the adults\n\nKeep up regular water changes with matched hard water. Make sure the babies can reach food without competing with large adults; scatter food around the tank."}, {"heading": "Growing out", "text": "Growth is slow. Babies can take many months to reach adult size, and it is common for a colony to take a year or more to build up. Good feeding and warm, stable water give the best growth. Small snails are easy to miss, so check around rocks and in the sand before deciding none survived.\n\nBecause breeding is slow, plan on keeping your colony for the long term rather than expecting quick numbers. Rabbit snails live for several years, and a healthy group will keep adding babies year round in warm water. Avoid moving young snails until they are large enough to handle easily and to be counted in photos."}, {"heading": "Common mistakes", "text": "- Soft, acidic water that erodes shells\n- Water too cool for steady breeding\n- Keeping only one or two snails and hoping for a pair\n- Fish tank mates that eat small snails\n- Copper based medicines or plant products"}]$g$::jsonb, updated_at = now() where slug = $g$rabbit-snail$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Blue gularis grow to about 4.5 inches, so use a 20 to 30 gallon tank with a tight lid, since killifish jump. Add a sponge filter, plenty of plants or floating cover for the females to hide in, and a spawning medium on the bottom. Most breeders use a layer of boiled, rinsed peat, either across the bottom or in a container the fish can dive into. A bottom spawning mop also works.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Many breeders keep them around 72 to 76°F. Slightly soft water helps, but they are not extremely fussy."}, {"heading": "Conditioning and choosing a group", "text": "Males are unmistakable: large, with bright blue, red and yellow colors and long, extended fins. Females are smaller, brownish, with rounded fins and only faint markings.\n\nMales can be rough on females, so use one male with two or three females, and give the females places to hide. Condition for two to three weeks on meaty foods such as bloodworms, blackworms, brine shrimp and chopped earthworms. Many gularis will refuse dry food, so plan on frozen or live food."}, {"heading": "Spawning: what you'll see", "text": "The male displays with fully spread fins and leads a female down to the peat or mop. The pair press together and dive into the substrate, laying and fertilizing eggs inside it. A female lays a few eggs at a time, and spawning goes on daily for as long as she is in condition. Over a couple of weeks you can collect dozens of eggs.\n\nThe eggs are fairly large and clear when fresh. You may see them if you gently sift the peat over a white dish."}, {"heading": "Incubating the eggs", "text": "Collect the peat every one to two weeks. Squeeze out most of the water until it is damp, not dripping, and store it in a labeled, dated bag or container at about 72 to 77°F. Incubation is commonly reported at about 4 to 8 weeks, depending on temperature and method. Some breeders incubate eggs in shallow water instead, which can be faster.\n\nCheck the eggs every couple of weeks. When they are ready you will see the dark eyes of the developing fry inside. Wet the peat with tank water in a small container, and the fry should hatch within a day or so. If only a few hatch, dry the peat again and rewet it a few weeks later."}, {"heading": "Raising the fry", "text": "Blue gularis fry are large for killifish and can eat newly hatched brine shrimp right away.\n\n- Weeks 1 to 2: baby brine shrimp two or three times a day\n- Weeks 3 to 4: baby brine shrimp and chopped blackworms or grindal worms\n- Month 2 on: frozen bloodworms and other meaty foods\n\nKeep fry in a shallow tank at first and change about 20% of the water every two or three days. Siphon uneaten food. Grade fry by size, as bigger siblings will bully or eat smaller ones."}, {"heading": "Growing out", "text": "Fry grow quickly with plenty of food. Males start showing color after a couple of months, and adult size and full fins take several months. Keep grow out tanks covered and separate growing males if they start fighting."}, {"heading": "Common mistakes", "text": "- One male with one female, which can lead to the female being harassed\n- Peat left too wet or allowed to dry out completely\n- Giving up on eggs before they have had enough time\n- No lid; these fish jump\n- Mixing fry of different sizes"}]$g$::jsonb, updated_at = now() where slug = $g$blue-gularis$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank with a tight lid is ideal, because clown killies jump. Add plenty of floating plants with trailing roots, a spawning mop near the surface, and a gentle sponge filter. These fish live at the surface and prefer very little flow.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. For breeding, soft, slightly acidic water around pH 6 to 6.5 at 75 to 77°F works well."}, {"heading": "Conditioning and choosing a group", "text": "Males are easy to spot by their bright tail fin, streaked with red and blue in a rocket shape, and colorful dorsal and anal fins. Females have the same dark vertical bands but plain, clear fins.\n\nCondition for one to two weeks with small live and frozen foods: baby brine shrimp, daphnia, microworms and wingless fruit flies. Use one male with two or three females, or a small colony in a heavily planted tank.\n\nA colony tank is the low effort option: a small group in a mature, heavily planted 10 gallon with lots of floating plants will usually produce a trickle of fry that hide at the surface among the roots. Separating eggs gives far more fry, but needs more containers and more food cultures. Either way, start infusoria and vinegar eel cultures before you expect the first hatch."}, {"heading": "Spawning: what you'll see", "text": "The male displays with spread fins next to a female near the surface. The pair settle together into floating plant roots or the mop, and she lays a single egg or a few eggs at a time. This goes on daily rather than in one burst.\n\nEggs are tiny and clear. You can find them by gently checking the mop or plant roots with a flashlight. Each female adds only a few eggs per day, so numbers build up slowly.\n\nIf you pick eggs, a simple routine works well: check the mop every two or three days, move eggs into a small labeled container with the date, and keep each batch separate. That way you know roughly when each batch should hatch and can match the fry to the right food."}, {"heading": "Incubating the eggs", "text": "You can leave eggs in the tank and let some fry survive among the plants, or pick eggs from the mop every few days and move them to a small container with tank water. Commonly reported hatch time is about 8 to 14 days at 75 to 77°F, so be patient.\n\nA small dose of methylene blue or a few dried leaves can limit fungus. Remove white or fuzzy eggs."}, {"heading": "Raising the fry", "text": "Clown killifish fry are very small and stay at the surface. They swim right away and need tiny foods.\n\n- Week 1: infusoria or paramecium several times a day\n- Week 2: vinegar eels and finely powdered food\n- Week 3 on: microworms, then newly hatched brine shrimp\n\nKeep fry in shallow water with floating plants. Change about 10% of the water every couple of days, matching temperature and softness. Because eggs hatch over many days, fry will be different sizes, so separate bigger ones from smaller ones."}, {"heading": "Growing out", "text": "Growth is slow. Expect about 3 months for fry to reach adult size, around 1.25 inches. Males start showing tail color a few weeks before then. Keep grow out tanks covered and well planted.\n\nYoung clown killies are peaceful and do well together in groups. Once they are about half grown they can rejoin the adults in a planted tank. Keep feeding several small meals a day of live or frozen foods, as well fed fry reach breeding size sooner and color up better."}, {"heading": "Common mistakes", "text": "- Strong filter flow that pushes these surface fish around\n- No lid\n- Feeding baby brine shrimp too soon\n- Expecting one large spawn\n- Discarding eggs too early when they can take up to two weeks to hatch"}]$g$::jsonb, updated_at = now() where slug = $g$clown-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank with a tight lid is enough for a male and two or three females. Add a sponge filter and a layer of peat or a container of boiled, rinsed peat for spawning. Use plants or floating cover to give females places to rest from the male.\n\nThe site lists {{temp}}°F, pH {{ph}} and GH {{gh}}. Many breeders keep rachovii around 72 to 76°F. Avoid very soft, acidic water, which can increase the risk of velvet."}, {"heading": "Conditioning and choosing a group", "text": "Males are a brilliant mix of blue and red with dark edges on the tail. Females are plain brown and smaller. They mature fast and live only about a year in most aquariums, so breed them while they are young and healthy.\n\nCondition with live and frozen bloodworms, blackworms and brine shrimp. Annual killies rarely accept dry food. Keep one male with two or three females to spread his attention."}, {"heading": "Spawning: what you'll see", "text": "The male displays to a female with spread fins and leads her to the peat. They press together and dive into it side by side, laying and fertilizing an egg or a few at a time. This repeats daily. Over a few weeks you can collect dozens of eggs.\n\nAfter a spawning period, give the females a rest by moving them to a separate tank for a week or two with heavy feeding. This keeps them in good condition and protects them from a persistent male. You can then put them back for another round of spawning."}, {"heading": "Storing the eggs", "text": "Every one to two weeks, remove the peat and squeeze out most of the water until it is damp but not wet. Place it in a labeled, dated bag or container and store it at room temperature, about 70 to 77°F.\n\nIncubation is long. Breeders commonly report about 3 to 6 months for rachovii, depending on temperature and the eggs themselves. Check the eggs every few weeks. When they are ready, you can see the developing fry's dark eyes, often with a gold ring around them. If the peat starts to dry out, mist it lightly."}, {"heading": "Hatching and raising the fry", "text": "To hatch, place the peat in a small container and add an inch or two of cool, soft water, a bit cooler than the tank. Fry usually hatch within hours.\n\n- Days 1 to 3: newly hatched brine shrimp, with microworms or vinegar eels for fry that are too small\n- Weeks 1 to 4: baby brine shrimp several times a day, adding chopped worms\n- Month 2 on: bloodworms, blackworms and other meaty foods\n\nMove the fry out of the peat after a day or so. Keep water shallow at first and change 20% every few days. Re-dry the peat; often more eggs hatch on a second wetting a few weeks later."}, {"heading": "Growing out", "text": "Rachovii grow very fast with heavy feeding. Males often start showing color within a few weeks, and fish can be mature in about 6 to 10 weeks. Because they are short lived, plan new batches of eggs on a regular schedule to keep your line going.\n\nKeep males apart if they fight as they mature, and give females cover. Heavy feeding with small meals several times a day and frequent water changes gives the best growth. A good habit is to always have at least two or three bags of peat incubating at different stages, so a single bad batch never ends your line."}, {"heading": "Common mistakes", "text": "- Storing peat too wet, which rots eggs\n- Letting peat dry out completely\n- Wetting eggs before they are developed\n- Only keeping one generation and losing the line when adults age\n- Starving fry, which slows growth"}]$g$::jsonb, updated_at = now() where slug = $g$rachovii-killifish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank is a sensible minimum for one pair, and larger is better if you want fry to stay with the parents. Use a sand bottom and build tall stacks of rock with plenty of narrow gaps and caves, so the pair can claim one and the fry have places to hide.\n\nKeep water hard and alkaline, in line with the care numbers for this fish: pH {{ph}}, GH {{gh}}, and {{temp}}°F. Around 78 to 80°F suits spawning. A sponge filter or a gently flowing canister with a sponge pre-filter keeps fry safe from the intake."}, {"heading": "Getting a compatible pair", "text": "Julies are hard to sex by looks. Females are usually the larger fish, but size alone is not reliable, and venting (checking the genital papilla) takes practice. The easiest route is to raise 6 juveniles together and let a pair form on its own.\n\nOnce two fish start sharing one cave and chasing others away, move the rest out. Pairs can turn on each other, so watch for one fish being driven into a corner. If that happens, separate them with a divider for a while before trying again.\n\nCondition with good pellets plus frozen mysis and brine shrimp for 2 to 3 weeks."}, {"heading": "Spawning: what you'll see", "text": "You often won't see the spawn itself. The pair spend more time in one cave, dig sand out of it, and become more defensive. The female lays her eggs on the roof or wall of the cave, and the male fertilizes them.\n\nBreeders commonly report 20 to 100 eggs, with large, mature females sometimes laying more. The pair take turns guarding the entrance. Avoid moving rocks or shining a flashlight into the cave, which can stress them into eating the spawn.\n\nIf the pair spawn again while older fry are still in the tank, you may see two or three sizes of fry around the same rock pile. That is normal for Julies and a good sign the pair is settled."}, {"heading": "Eggs and early fry", "text": "At 78 to 80°F the eggs commonly hatch in about 3 days. The wrigglers stay stuck to the cave or on the floor of it while they use up their yolk.\n\nRoughly a week after hatching, about 10 days after the spawn, the fry start swimming. They do not roam the tank like many fish; they hover close to the rockwork near their cave. Parents handle egg care and fungus control themselves, so leave them alone."}, {"heading": "Raising the fry", "text": "- Week 1 of swimming: baby brine shrimp once or twice a day, plus finely powdered flake.\n- Weeks 2 to 4: keep up baby brine shrimp and add crushed flake and small pellets.\n- Water changes: 15 to 20% weekly with matched temperature and hardness.\n- Temperature: hold steady at 78 to 80°F.\n\nFry can stay with the parents, which is the natural way for this species. If you want to raise every fry, move some to a grow-out tank once they reach about half an inch."}, {"heading": "Growing out", "text": "Julies grow slowly. Expect fry to reach roughly an inch at 2 to 3 months and close to adult size in about a year. Feed small meals several times a day and keep the water clean, since stunting is common in crowded grow-out tanks. Rockwork in the grow-out tank cuts down on squabbles.\n\nOnce fry are around an inch, they can be moved to a separate tank or sold on as juveniles. Leaving a large group of older fry with the pair works for a while, but parents may start to chase them once a new spawn arrives."}, {"heading": "Common mistakes", "text": "- Buying two adults and assuming they will pair. Raise a group instead.\n- Too few caves, which leads to fighting.\n- Soft or acidic water; keep it hard and alkaline.\n- Shifting rocks to peek at the eggs.\n- Tankmates that steal fry. A species tank gives the best results."}]$g$::jsonb, updated_at = now() where slug = $g$regani-julie$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use at least {{tank}} gallons, in line with the care numbers for this fish. Peacocks spawn over sand or on flat stones, so give them an open sandy area plus some rockwork for females to hide in. Hard, alkaline water suits them: pH 7.8 to 8.6, GH 6 to 15, and 76 to 82°F, with about 78 to 80°F ideal for breeding.\n\nStrong filtration and weekly water changes of 25 to 30% keep nitrate low, which helps females hold full term. Have a separate 10 to 20 gallon tank ready for holding females.\n\nAvoid housing them with aggressive mbuna, which stress holding females. Peaceful peacocks or haps of a similar size are fine in a display tank, but a species tank gives you the clearest results and no risk of crosses."}, {"heading": "Choosing a harem", "text": "Keep one male with 3 or 4 females so his attention is spread out. Males are easy to spot: they turn bright blue with yellow or orange depending on the strain. Females stay brown or grey with darker bars.\n\nKeep only one Aulonocara species in the tank. Female peacocks look very similar across species and cross easily, and hybrids should never be sold or passed on. Condition with good pellets and frozen mysis or brine shrimp for 2 to 3 weeks."}, {"heading": "Spawning: what you'll see", "text": "The male darkens, digs a shallow pit or picks a flat stone, and shimmies to lead a female over. She lays a few eggs, picks them up in her mouth, and the male fertilizes them as she mouths at his anal fin. This repeats until she has her clutch.\n\nAfterwards she has a swollen throat and a square chin, eats little or nothing, and hides. That's a holding female.\n\nYoung females often hold poorly on their first few spawns and may eat or spit the eggs early. That usually improves with age and size, so don't give up on a female after one failed hold."}, {"heading": "Holding time", "text": "Females commonly hold for about 3 to 4 weeks at 78 to 80°F. Broods of 15 to 40 are commonly reported, and young females often hold fewer.\n\nMove a holding female after 3 to 7 days, gently, in a net or container with water, so she is less likely to spit. Let her release in the holding tank, then return her to the group once she has eaten for a few days. Some breeders strip fry at about 2 weeks and finish them in a tumbler, but letting her hold to term is simpler and easier on her.\n\nFeed the holding tank lightly while the female is in it, since she usually won't eat until she releases. Keep the water clean and the tank quiet, with a few rocks or a flowerpot she can hide behind."}, {"heading": "Raising the fry", "text": "- First week: baby brine shrimp and crushed flake two or three times a day.\n- Weeks 2 to 4: add crushed small pellets and frozen cyclops.\n- Water changes: 20 to 30% twice a week in small tanks.\n- Temperature: 78 to 80°F.\n\nFry are released fully formed, so there is no wriggler stage to manage."}, {"heading": "Growing out", "text": "Expect about an inch at 2 months. Males usually start showing color from around 6 months, though it varies by strain. Grow them in a tank with plenty of room and frequent feeding. Crowded, underfed fry grow slowly and fight more.\n\nFry from different broods grow at different speeds, so sort them by size every few weeks. Feeding three or four small meals a day gives better growth than one big feed, and frequent water changes keep growth steady."}, {"heading": "Common mistakes", "text": "- Mixing peacock species, which leads to hybrids.\n- Too few females, so one gets harassed.\n- Moving a female too early, causing her to spit.\n- Leaving fry in the main tank, where adults will eat them.\n- High nitrate, which can cause females to swallow or spit early."}]$g$::jsonb, updated_at = now() where slug = $g$sunshine-peacock$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Venustus reach about {{size}} inches, so start with at least {{tank}} gallons, in line with the care numbers for this fish. Use sand, some rockwork, and plenty of open swimming room. Keep water hard and alkaline: pH 7.8 to 8.6, GH 10 to 25, and 76 to 82°F, with 78 to 80°F good for spawning.\n\nThese are heavy eaters, so use strong filtration and change 30% or more weekly. Set up a separate 20 to 40 gallon tank for holding females and fry."}, {"heading": "Choosing a group", "text": "Keep one male with at least 3 females. A single female will get pestered hard. Mature males develop a bright blue head and a yellowish body, while females keep the giraffe-like brown blotches. Young fish all look like females, so buy a group of juveniles if you can.\n\nKeep one Nimbochromis species per tank to avoid hybrids. Feed a carnivore diet: quality pellets plus frozen krill and mysis for 2 to 3 weeks before you expect spawning.\n\nFemales usually start breeding at around 4 to 5 inches. Males take longer to show full color and may not spawn well until they are the dominant fish in the tank. Remove any second male that starts coloring up and harassing the group."}, {"heading": "Spawning: what you'll see", "text": "The male colors up, clears a spot in the sand or on a flat rock, and displays to females. When one is ready, the pair circle, she lays eggs, picks them up in her mouth, and the male fertilizes them.\n\nAfterwards the female has a stretched, bulging throat, stops eating, and hides. Large females can hold big broods; 30 to 100 is commonly reported, and big females may carry more."}, {"heading": "Holding time", "text": "Holding females commonly carry the brood for about 3 weeks at 78 to 80°F. Move her after a few days, gently and with a container rather than a long chase, to reduce the chance she spits.\n\nOnce she releases, give her a week or two to eat and recover before returning her to the group. Some breeders strip fry at about 2 weeks and finish them in a tumbler. That works, but holding to term is easier on beginners.\n\nKeep the holding tank quiet and covered, with a few rocks or a flowerpot she can hide behind. She won't eat much while holding, so feed lightly and keep the water clean until she releases."}, {"heading": "Raising the fry", "text": "- First week: baby brine shrimp and crushed pellets two or three times a day.\n- Weeks 2 to 4: move up to small pellets and frozen foods.\n- Water changes: 25 to 30% twice a week.\n- Temperature: 78 to 80°F.\n\nFry are released fully formed and eat from day one. They grow quickly and get bossy with each other as they grow.\n\nVenustus fry are bold eaters. Feed small amounts several times a day rather than one large feed, and siphon leftovers from the bottom. Sort out larger fry if they start bullying smaller ones."}, {"heading": "Growing out", "text": "Expect 1 to 1.5 inches by 2 months with good feeding. You will need more tank space fast, as a brood of 60 venustus outgrows a 20 gallon tank quickly. Plan homes for the fry before you start; large broods of a 10 inch predator are hard to rehome.\n\nJuveniles look like small females at first, and males usually take many months to show the blue head. Keep the grow-out tank lightly stocked and well filtered, since these fish produce a lot of waste as they grow."}, {"heading": "Common mistakes", "text": "- A tank that's too small, which leads to injured females.\n- Only one female for the male.\n- Mixing Nimbochromis species, which risks hybrids.\n- Leaving fry with the adults, who will eat them.\n- No plan for where dozens of fry will go."}]$g$::jsonb, updated_at = now() where slug = $g$venustus-cichlid$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well. Use a sponge filter, no gravel or a thin layer, and add two or three yarn spawning mops or bunches of fine leaved plants like java moss.\n\nKeep water hard and slightly alkaline, in line with the care numbers for this fish: pH {{ph}}, GH {{gh}}, and {{temp}}°F. About 76 to 80°F is good for spawning. Bright light and some morning sun or a light on a timer help, since they spawn mainly in the morning.\n\nMany breeders keep adults in the breeding tank and simply rotate mops every few days, moving full mops to a hatching container. This lets the fish spawn steadily without the stress of moving them back and forth."}, {"heading": "Conditioning and choosing fish", "text": "Males are easy to pick out once mature: they have long, trailing rays on the dorsal and anal fins and more yellow color. Females are plainer with shorter fins.\n\nUse 1 male to 2 or 3 females, or spawn a small school. Feed daphnia, brine shrimp and other live or frozen foods for about 2 weeks, along with quality flake.\n\nCelebes rainbowfish are active swimmers, so a longer tank helps. Males display more and spawn better when they have a couple of rival males to show off to, so a school of 6 to 8 with more females than males also works well."}, {"heading": "Spawning: what you'll see", "text": "Males display to females with fins spread, then the pair swim into the mop and release a few eggs, which stick to the strands with fine threads. They spawn a little each day rather than all at once.\n\nCheck the mops every day or two and pick off eggs, or swap the mop for a fresh one. Expect a few to a few dozen eggs a day."}, {"heading": "Eggs and fungus", "text": "Hatch eggs in a small container or tank with water from the breeding tank and a gentle air stone. At 76 to 80°F, hatching commonly takes about 7 to 12 days.\n\nRemove white, fungused eggs daily so fungus doesn't spread. Because eggs are collected over several days, you'll have fry hatching at different times. Keep batches separate by date if you can so bigger fry don't bully smaller ones."}, {"heading": "Raising the fry", "text": "- Days 1 to 7: infusoria, green water or a fine liquid fry food several times a day.\n- Week 2: add baby brine shrimp and microworms.\n- Weeks 3 to 6: baby brine shrimp plus crushed flake.\n- Water changes: small, 10 to 20% every few days, matched in temperature.\n- Temperature: 76 to 80°F.\n\nFry stay near the surface, so a low water level for the first week helps them find food.\n\nStart an infusoria culture or green water a week before you expect hatching, so food is ready on day one. Fry that miss their first feeds in the first few days rarely recover."}, {"heading": "Growing out", "text": "Fry reach about an inch by 2 to 3 months. Males start showing longer fins and yellow color at a few months old. A larger grow-out tank with frequent small meals gives the best growth.\n\nAs fry grow, move them to a bigger tank and add small frozen foods such as daphnia and cyclops. Keep hardness steady at the level they were hatched in, then match it to the adults' tank once they are about an inch long."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults.\n- Feeding baby brine shrimp too early, before fry can eat it.\n- Big water changes that shock tiny fry.\n- Soft, acidic water; this fish prefers hard and alkaline."}]$g$::jsonb, updated_at = now() where slug = $g$celebes-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank is plenty, in line with the care numbers for this fish. Use a gentle sponge filter, a dark bottom and a big clump of java moss or two yarn mops. Floating plants help the fish feel secure.\n\nKeep water soft to medium hard: pH 6 to 7.5, GH 3 to 12, and 72 to 82°F, with 75 to 80°F a good spawning range.\n\nSome breeders keep a breeding colony in a well planted tank and let a few fry survive naturally in the moss. That gives fewer fry than pulling eggs, but it's a low effort way to keep a line going. For a breeding log, collecting eggs gives you more control."}, {"heading": "Conditioning and choosing fish", "text": "Males have bigger dorsal and anal fins with bolder dark spots and more yellow color. Females are paler, with smaller and less heavily marked fins. Use 1 male to 2 or 3 females to spread out the male's attention.\n\nFeed small live and frozen foods such as baby brine shrimp, daphnia and cyclops for 1 to 2 weeks, plus fine flake. Spotted blue-eyes are short lived, often only about 2 to 3 years, so breed them while they're young and healthy."}, {"heading": "Spawning: what you'll see", "text": "Males flare their fins and dance around a female. The pair dive into the moss or mop together and release a few eggs, which stick by fine threads. This repeats most mornings.\n\nYou won't get a big clutch. Most females lay a few eggs a day, sometimes up to 10 to 20 over a good day, so collect over a week or two for a usable batch.\n\nFemales that have spawned recently may look a little thin. Keep feeding them well, and give them breaks by adding more females or rotating them out if the male chases one too hard."}, {"heading": "Eggs and fungus", "text": "Pick eggs off the mop with your fingers or a soft brush and put them in a small container with tank water. A drop of methylene blue or a few almond leaves helps prevent fungus, though many breeders skip it. Remove any eggs that turn white.\n\nHatch time is long for such a small fish: commonly about 10 to 20 days at 75 to 80°F. Warmer water hatches them faster."}, {"heading": "Raising the fry", "text": "- Days 1 to 3: infusoria, vinegar eels or a fine fry powder several times a day.\n- Day 4 to week 3: newly hatched baby brine shrimp and microworms.\n- Week 4 on: add crushed flake.\n- Water changes: 10 to 20% every few days, matched carefully.\n- Temperature: 75 to 80°F.\n\nFry live near the surface, so keep the water level low at first and feed in small amounts often.\n\nKeep each week's batch of fry in its own container if you can. A clean, small container or a 2 to 5 gallon tank with a sponge filter is enough for the first few weeks."}, {"heading": "Growing out", "text": "Fry reach about half an inch at 1 to 2 months and can spawn by 3 to 4 months. Keep batches separated by age so larger fry don't outcompete smaller ones for food.\n\nGrow-out tanks should be well planted and stable. Feed small meals of baby brine shrimp and fine flake several times a day. Males usually show their fin spots and color by about 3 months."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults.\n- Giving up because eggs haven't hatched after a week; they often take longer.\n- Feeding too much at once and fouling the fry tank.\n- Waiting too long to breed short lived adults."}]$g$::jsonb, updated_at = now() where slug = $g$gertrudes-blue-eye$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank works well, in line with the care numbers for this fish. Use a gentle sponge filter, little or no current, and plenty of fine leaved plants, java moss or yarn mops.\n\nKeep water soft to medium: pH 6 to 7.5, GH 3 to 12, and 75 to 82°F, with about 78 to 82°F good for spawning. Threadfins are shy, so avoid boisterous tankmates.\n\nMany breeders leave the adults in a planted species tank and simply pull mops or moss every few days. This reduces stress on the adults, who can be skittish and don't move well between tanks."}, {"heading": "Conditioning and choosing fish", "text": "Males are easy to tell: they grow long, trailing dorsal and anal fins. Females are plain silver with short fins. Use 1 male to 2 or 3 females, or keep a small school with more females than males.\n\nThreadfins have tiny mouths. Feed baby brine shrimp, daphnia, cyclops and crushed flake for about 2 weeks.\n\nFeed small meals two or three times a day rather than one larger feed. Threadfins are slow, gentle eaters, and faster tankmates will take most of the food if you don't watch."}, {"heading": "Spawning: what you'll see", "text": "Males flare their fins and display in front of females, often in a jerky dance. The pair dart into the mop or moss together and leave a few eggs that stick with fine threads.\n\nThey spawn a little each day, so check the mops every day or two and move eggs to a hatching container, or swap the mop out.\n\nSpawning is spread over many days, so plan to collect eggs over a week or two. A typical daily haul is small, from a few to a dozen or so eggs, which adds up over time."}, {"heading": "Eggs and fungus", "text": "Hatch the eggs in a small tank or container with water from the breeding tank and gentle aeration. At 78 to 82°F, hatching commonly takes about 7 to 12 days.\n\nRemove white, fungused eggs daily. A few almond leaves or a drop of methylene blue can help with fungus.\n\nSince eggs are collected over several days, label each container with the date. Fry that hatch a week apart are very different in size, and keeping batches apart stops the bigger fry taking all the food."}, {"heading": "Raising the fry", "text": "- Weeks 1 to 2: infusoria or paramecium cultures several times a day. Many fry are too small for baby brine shrimp at first.\n- Weeks 2 to 3: add microworms and newly hatched baby brine shrimp as soon as fry can take them.\n- Weeks 4 on: baby brine shrimp plus finely crushed flake.\n- Water changes: 10% every few days, matched carefully.\n- Temperature: 78 to 82°F.\n\nStart your infusoria cultures before the eggs hatch, since you'll need a steady supply."}, {"heading": "Growing out", "text": "Threadfins grow slowly. Expect about half an inch at 2 months and adult size in several months. Males start to show their trailing fins as they mature. Avoid fin nippers in the grow-out tank.\n\nOnce fry are taking baby brine shrimp well, survival improves a lot. Grow them in a tank with gentle flow and plenty of fine plants. Keep feeding small meals often, as their small mouths limit how much they can take at once."}, {"heading": "Common mistakes", "text": "- No infusoria ready when fry hatch.\n- Feeding only baby brine shrimp from day one, which many fry can't eat yet.\n- Strong filter flow that pushes weak fry around.\n- Leaving eggs with the adults.\n\nMost failures with threadfins happen in the first two weeks after hatching. If you can get a batch past that point on infusoria and microworms, the rest of the grow-out is usually smooth."}]$g$::jsonb, updated_at = now() where slug = $g$threadfin-rainbowfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank works well. Use a gentle sponge filter and add several broad leaved plants such as Cryptocoryne or Anubias. Keep light dim.\n\nThe care numbers for this fish list pH {{ph}}, GH {{gh}}, and {{temp}}°F, which is fine for keeping them. For spawning, use soft, acidic water: drop pH to about 5.5 to 6.5 and keep GH low, around 2 to 4. Many breeders run the spawning tank slightly warmer, about 78 to 82°F.\n\nSet the breeding tank up a week or two early so the plants settle and the water is stable. A layer of peat or a few almond leaves helps lower pH and gives the water a light tint, which many breeders find helps."}, {"heading": "Choosing and conditioning a pair", "text": "Males are slimmer and their black triangle patch is sharper and extends further down the body. Females are rounder and their patch has a straighter edge. Sexing is easiest when the fish are mature and well fed.\n\nCondition the group with daphnia, bloodworms and brine shrimp for about 2 weeks. Then move a pair, or 2 males and 1 female, into the breeding tank in the evening.\n\nHarlequins are slow to mature. Use fish that are at least 9 months old and full sized. If spawning doesn't happen within a few days, return the pair to the main tank, keep conditioning, and try again in a couple of weeks."}, {"heading": "Spawning: what you'll see", "text": "The male displays around the female and leads her to a broad leaf. She turns upside down under the leaf and presses eggs onto its underside while the male wraps around her to fertilize them. They repeat this over several hours.\n\nA spawn commonly yields from a few dozen to around 100 or more eggs. Remove the adults once they're done, since they will eat eggs.\n\nSome breeders prefer to spawn harlequins in a group in a planted tank and remove the leaves with eggs as they're laid. This works well if you check the plants daily."}, {"heading": "Eggs and fungus", "text": "At 78 to 82°F, the eggs commonly hatch in about 1 to 2 days. The fry hang from the leaves or the glass for the next few days while they use up their yolk.\n\nKeep the tank dark during this time. A few almond leaves or a little methylene blue helps prevent fungus, though many breeders use neither. Remove any fungused eggs carefully with a pipette."}, {"heading": "Raising the fry", "text": "- Days 1 to 7 after free swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days with soft water matched in temperature.\n- Temperature: 78 to 82°F.\n\nFry are tiny and grow slowly at first, so steady feeding matters."}, {"heading": "Growing out", "text": "Expect about half an inch by 2 months. The black patch starts to appear as fry grow, and they look like small harlequins after a few months. Move them to a larger tank and slowly raise hardness to normal keeping levels.\n\nExpect harlequins to take 6 months or more to reach adult size. Keep water clean and feed small meals several times a day. Larger fry can quickly outcompete smaller ones, so sort them if needed."}, {"heading": "Common mistakes", "text": "- Hard, alkaline water; spawning usually fails without soft, acidic water.\n- No broad leaved plants for egg laying.\n- Leaving the parents with the eggs.\n- Feeding baby brine shrimp too early.\n- Bright light in the breeding tank."}]$g$::jsonb, updated_at = now() where slug = $g$harlequin-rasbora$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank works, in line with the care numbers for this fish. Use a gentle sponge filter, dim light and broad leaved plants like Cryptocoryne or Anubias.\n\nThe care numbers list pH {{ph}}, GH {{gh}}, and {{temp}}°F. For spawning, go softer and more acidic: about pH 5.5 to 6.5 and GH around 2 to 4, at 78 to 82°F.\n\nSet the tank up a week or two before you plan to spawn, so the plants settle in. Peat or almond leaves help soften and acidify the water and give a light tint."}, {"heading": "Choosing and conditioning a pair", "text": "Males are slimmer, with brighter orange color and a bolder, more defined black lambchop patch. Females are rounder, especially when full of eggs, and paler. Sexing is easiest in mature, well fed fish.\n\nCondition with daphnia, baby brine shrimp and fine frozen foods for about 2 weeks. Move a pair or 2 males and 1 female into the breeding tank in the evening.\n\nLambchops are small, so be patient. Use full sized adults at least 6 to 9 months old. If they don't spawn within a few days, return them to the main tank, keep conditioning, and try again."}, {"heading": "Spawning: what you'll see", "text": "Males display to the female, then the pair swim under a broad leaf. The female turns upside down and sticks her eggs to the underside of the leaf while the male fertilizes them. They repeat this over several hours, usually in the morning.\n\nSpawns are commonly reported in the dozens of eggs. Remove the adults once spawning has finished.\n\nSome breeders prefer to keep a group in a planted tank and remove leaves with eggs as they're laid. This works well as long as you check the plants daily."}, {"heading": "Eggs and fungus", "text": "At 78 to 82°F, the eggs commonly hatch in about 1 to 2 days. The fry then hang from leaves and glass for a few days while they use up their yolk.\n\nKeep the tank dark. A few almond leaves or a little methylene blue can help with fungus. Remove any fungused eggs carefully with a pipette."}, {"heading": "Raising the fry", "text": "- Days 1 to 7 after free swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days with soft water matched in temperature.\n- Temperature: 78 to 82°F.\n\nFry are even smaller than harlequin fry, so be ready with infusoria cultures before the spawn.\n\nUse a small container or a 2 to 5 gallon tank with a sponge filter for the first few weeks. Feed small amounts often and remove leftovers with a pipette to keep the water clean."}, {"heading": "Growing out", "text": "Expect about a third to half an inch by 2 months. Orange color and the black patch develop over a few months. Move them to a larger tank and slowly raise hardness to normal keeping levels.\n\nLambchops reach adult size in about 6 months. Keep them in clean, soft water during grow-out and feed small meals several times a day.\n\nSort fry by size if larger ones start taking most of the food."}, {"heading": "Common mistakes", "text": "- Hard, alkaline water.\n- No broad leaved plants for egg laying.\n- Leaving the adults with the eggs.\n- Feeding baby brine shrimp too early.\n- Bright light in the breeding tank.\n\nIf spawns keep failing, check your water hardness first. Most failed lambchop spawns come down to water that isn't soft enough, rather than the fish themselves."}]$g$::jsonb, updated_at = now() where slug = $g$lambchop-rasbora$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank works well, in line with the care numbers for this fish. Use a sponge filter, a sand or bare bottom, and a few plants or spawning mops for the eggs.\n\nKeep water soft and acidic: pH 5.5 to 7, GH 1 to 10, and 73 to 79°F. Many breeders use pH around 6 and low hardness for spawning.\n\nLeaf litter, such as dried oak or almond leaves, adds cover and lowers pH slightly. Keep the tank in a quiet spot. Corydoras feel safer with some cover and spawn more readily in a calm tank."}, {"heading": "Choosing and conditioning a group", "text": "Females are larger and broader when seen from above, especially when full of eggs. Males are slimmer. Use 2 males to 1 female, or keep a group of 6 or more.\n\nCondition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks. Keep water clean; Adolfo's corydoras can be sensitive to poor water quality.\n\nIf you're unsure of sexes, keep a group of 6 or more and let them sort themselves out. Groups also spawn more readily than single pairs, because the chasing seems to stimulate them."}, {"heading": "Spawning: what you'll see", "text": "A large water change with slightly cooler water often triggers spawning, the way the rainy season does in the wild. Males chase the female, then a male and female form the classic T position. The female holds a few eggs in her pelvic fins and then sticks them on glass, plants or decor.\n\nAdolfo's corydoras usually lay modest numbers, commonly reported from a few to a few dozen eggs, often spread over a day or two.\n\nIf a water change doesn't trigger spawning, try repeating it every few days, or lowering the temperature by a couple of degrees with the change. Barometric pressure changes before storms also seem to trigger corydoras spawns."}, {"heading": "Eggs and fungus", "text": "Move eggs gently with a finger or credit card edge to a hatching container with tank water and an air stone. At 73 to 77°F, the eggs commonly hatch in about 3 to 5 days.\n\nCory eggs are prone to fungus. Remove white eggs daily, and many breeders add a few almond leaves or a little methylene blue to the hatching container."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 10 to 20% every 2 to 3 days with soft water.\n- Temperature: 73 to 77°F.\n\nA thin layer of sand in the fry container helps, but keep it clean of leftover food."}, {"heading": "Growing out", "text": "Fry reach about half an inch to 3/4 inch by 2 months. Their black and orange markings develop as they grow. Keep water clean and feed small meals often, as losses usually come from dirty water rather than lack of food.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep feeding a mix of baby brine shrimp, microworms and crushed sinking foods."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water.\n- Leaving eggs in the main tank.\n- Overfeeding fry, which fouls the water.\n- No cool water change to trigger spawning.\n- Too few males in the group.\n\nAdolfo's corydoras are often wild caught. Give new fish several weeks to settle and feed well before expecting spawns. Captive-bred fish often settle and spawn more readily."}]$g$::jsonb, updated_at = now() where slug = $g$adolfos-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank works well, in line with the care numbers for this fish. Use a sponge filter, a sand bottom and a few plants or spawning mops.\n\nKeep water cool: 64 to 75°F, with pH 6 to 7.5 and GH 2 to 12. Many breeders keep the tank around 68 to 72°F for spawning. A room that stays cool helps, since heat in summer can stop breeding.\n\nBearded corydoras like more flow and oxygen than many corydoras. An extra air stone or a small powerhead helps. Keep a lid on the tank, since corydoras sometimes jump when spawning."}, {"heading": "Choosing and conditioning a group", "text": "Unusually for corydoras, males of this species are larger than females. Mature males grow bristles on their cheeks, which gives the bearded name, and show stronger color. Females are plainer without bristles.\n\nUse 2 males to 1 female, or keep a group of 6 or more. Condition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks.\n\nKeep a group of 6 or more if you can. Males may squabble over females, but it rarely leads to injury. A group also helps you confirm sexes as the fish mature."}, {"heading": "Spawning: what you'll see", "text": "A large, cooler water change often triggers spawning. Males chase the female, then a pair form the classic T position. The female holds eggs in her pelvic fins and then sticks them on glass, plants or decor.\n\nBreeders commonly report spawns from a few dozen to over 100 eggs. Spawning can be spread over a day or two.\n\nIf spawning doesn't start after one water change, repeat it every few days. A slightly cooler change, a few degrees below tank temperature, is a common trigger."}, {"heading": "Eggs and fungus", "text": "Move eggs gently to a hatching container with tank water and an air stone. At 68 to 72°F, the eggs commonly hatch in about 4 to 6 days.\n\nRemove white, fungused eggs daily. Many breeders add a few almond leaves or a little methylene blue to the hatching container.\n\nCooler water slows development, so eggs kept toward the lower end of the range may take a day or so longer to hatch. That's normal; just keep removing any fungused eggs and keep the water moving."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 10 to 20% every 2 to 3 days.\n- Temperature: 68 to 72°F; keep fry cool too.\n\nA thin layer of sand in the fry container helps, but keep it clean of leftover food.\n\nFry are fairly robust once they start feeding, but they still need clean water. A few small snails or shrimp in the fry container help clean up leftover food."}, {"heading": "Growing out", "text": "Fry reach about an inch by 2 months with steady feeding. Males start showing cheek bristles as they mature. Keep grow-out tanks cool and well filtered.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep the tank cool and feed a mix of baby brine shrimp, microworms and crushed sinking foods."}, {"heading": "Common mistakes", "text": "- Keeping them too warm, which stops breeding and shortens their lives.\n- Leaving eggs in the main tank.\n- Overfeeding fry, which fouls the water.\n- Assuming the larger fish are females, as with most corydoras.\n\nSummer heat is the most common reason bearded corydoras stop spawning. If your room gets warm, plan your breeding attempts for the cooler months of the year."}]$g$::jsonb, updated_at = now() where slug = $g$bearded-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank works for a pair, in line with the care numbers for this fish. Panaqolus graze on wood, so include plenty of driftwood. Add a few narrow caves, about 1 to 1.5 inches wide, made of clay or slate. Use good water flow from a sponge filter or powerhead.\n\nThe care numbers list {{temp}}°F, pH {{ph}} and GH {{gh}}. Many breeders spawn them at about 78 to 82°F with clean, well oxygenated water.\n\nKeep the tank in a quiet spot. Clown plecos are shy and nocturnal, so a tank with dim light and little traffic gives them the best chance to settle and breed."}, {"heading": "Choosing and conditioning a pair", "text": "Males have heavy bristles, called odontodes, on the rear half of the body and on the pectoral fin spines. Females are rounder with fewer bristles. Sexing is easiest in adults.\n\nUse one pair or 1 male to 2 females. Condition with driftwood plus zucchini, cucumber and quality sinking foods for 2 to 3 weeks. Clean water matters as much as food.\n\nPairs often take months to settle before they spawn. Keep feeding well, keep water clean and stable, and give them time. Many breeders report their first spawn coming long after the pair was set up."}, {"heading": "Spawning: what you'll see", "text": "The male claims a cave and cleans it. When the female is ready, she joins him inside, and you may see her tail sticking out. She lays the eggs inside the cave and leaves. The male stays and fans the eggs.\n\nClutches are commonly reported around 10 to 40 eggs. A water change with slightly cooler water sometimes triggers spawning.\n\nYou may notice the female looks thinner or the male stops coming out to feed. Those are often the first signs of a spawn inside the cave."}, {"heading": "Eggs and guarding", "text": "At 78 to 82°F, the eggs commonly hatch in about 4 to 7 days. The male stays in the cave the whole time and fans the eggs.\n\nDon't disturb the cave. If the male abandons or ejects the eggs, they can be hatched in a tumbler or a container with gentle water flow, though survival is often lower.\n\nFirst-time males sometimes eat or abandon their first clutch. That often improves with experience, so give the pair another chance before you give up on them."}, {"heading": "Raising the fry", "text": "- First week after hatching: fry stay in the cave and live on their yolk.\n- Week 2: fry leave the cave and graze; give wood, algae wafers and blanched zucchini.\n- Weeks 3 to 8: add gel foods and quality sinking foods.\n- Water changes: 20 to 30% weekly with clean, well oxygenated water.\n- Temperature: 78 to 82°F.\n\nRemove uneaten vegetables daily to keep water clean.\n\nFry often stay near the cave for a few days after leaving it. Place food close by so they find it easily."}, {"heading": "Growing out", "text": "Clown pleco fry grow slowly. Expect about half to 3/4 of an inch by 2 months. Keep wood in the tank at all times, since it's part of their diet.\n\nFeed small amounts several times a day and keep plenty of wood in the tank. Fry do best in a tank with good flow and stable water."}, {"heading": "Common mistakes", "text": "- Caves that are too wide or too large.\n- No driftwood for grazing.\n- Weak water flow and low oxygen.\n- Checking the cave too often.\n- Leaving rotting vegetables in the tank.\n\nPatience is the biggest factor with L104. Pairs that seem uninterested for months often start spawning once they feel settled, so keep the tank stable and keep feeding well."}]$g$::jsonb, updated_at = now() where slug = $g$clown-pleco$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank or larger is a good start, in line with the care numbers for this fish. Use a sponge filter, a sand bottom and plenty of plants, including some floating plants, since this species often lays eggs on leaves.\n\nThe care numbers list {{temp}}°F, pH {{ph}} and GH {{gh}}. Many breeders spawn them at about 75 to 79°F with soft to medium water.\n\nEmerald corydoras are larger than most corydoras, so give them open sand to forage and plenty of room. A lid is a good idea, since corydoras sometimes jump during spawning."}, {"heading": "Choosing and conditioning a group", "text": "Sexing is hard. Females are larger and broader when seen from above, especially when full of eggs. Males are slimmer. Buy a group of 6 or more and let them sort themselves out.\n\nCondition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks. Keep water clean with weekly water changes.\n\nHome spawns of this species are less common than with smaller corydoras, so be patient. Some groups take months to settle before they spawn. Keep conditioning and keep water clean and stable."}, {"heading": "Spawning: what you'll see", "text": "A large water change with slightly cooler water can trigger spawning. Males chase the female, then a pair form a T position like other corydoras. The female sticks eggs to plants, glass or the underside of floating plant leaves.\n\nBreeders report large clutches, sometimes a few hundred eggs, spread over several hours or days. Remove eggs as they're laid, since adults may eat them.\n\nIf a water change doesn't trigger spawning, try repeating it every few days, or lowering the temperature by a couple of degrees with the change."}, {"heading": "Eggs and fungus", "text": "Move eggs gently to a hatching container with tank water and an air stone. At 75 to 79°F, the eggs commonly hatch in about 3 to 5 days.\n\nRemove white, fungused eggs daily. Large clutches mean more fungus risk, so spread eggs over two containers if needed. Almond leaves or a little methylene blue help.\n\nInfertile eggs turn white within a day or so. Remove them quickly, as fungus can spread from them to healthy eggs."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 20% every 2 to 3 days.\n- Temperature: 75 to 79°F.\n\nWith big clutches, split the fry over several tanks to keep water clean.\n\nA few small snails in the fry container help clean up leftover food without harming the fry."}, {"heading": "Growing out", "text": "Fry reach about 3/4 inch to an inch by 2 months. Their green shine develops as they grow. Keep the grow-out tank clean and well fed, and plan for space: this species reaches about 3 inches.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep feeding a mix of baby brine shrimp, microworms and crushed sinking foods.\n\nGrow fry with a few other peaceful fish or on their own, and keep water changes regular so their barbels stay healthy on the sand."}, {"heading": "Common mistakes", "text": "- A tank that's too small for a breeding group.\n- Leaving eggs in the main tank.\n- Overcrowding fry from a large clutch.\n- Overfeeding, which fouls the water.\n\nWild-caught fish may take a long time to settle. Captive-bred fish are often easier to spawn, so they're a good place to start."}]$g$::jsonb, updated_at = now() where slug = $g$emerald-cory$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A {{tank}} gallon tank is a good size, in line with the care numbers for this fish. Use a sponge filter and cover the bottom with a spawning mesh, marbles or a thick layer of fine leaved plants so eggs fall out of reach of the adults.\n\nThe care numbers list pH {{ph}}, GH {{gh}}, and {{temp}}°F. For spawning, use softer, slightly acidic water: about pH 6 to 6.5 and low hardness, at 75 to 79°F. Many breeders filter through peat.\n\nSet up the tank a week or two before spawning so it's stable. Morning sunlight or a light on a timer helps, since Congo tetras often spawn as the light comes up."}, {"heading": "Choosing and conditioning fish", "text": "Males are larger with longer fins, white edges, a ragged extension in the middle of the tail, and stronger colors. Females are smaller and plainer.\n\nCondition males and females separately for 2 to 3 weeks with live or frozen foods like bloodworms, brine shrimp and daphnia. Then add 1 male and 2 females to the breeding tank in the evening.\n\nCongo tetras mature at around a year old. Choose full sized, healthy adults. If they don't spawn within a few days, return them to the main tank, keep conditioning, and try again."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the morning, often helped by sunlight. The male chases the female, then the pair swim side by side and release eggs that fall to the bottom.\n\nCommonly reported spawns are up to about 300 eggs. Remove the adults once spawning has finished, since they will eat the eggs.\n\nSome breeders prefer to spawn a small group, which can give larger spawns. Either way, make sure the bottom is well covered, so eggs fall out of reach."}, {"heading": "Eggs and fungus", "text": "Congo tetra eggs are large and take longer to hatch than most tetra eggs. At 75 to 79°F, they commonly hatch in about 5 to 7 days.\n\nRemove fungused eggs daily with a pipette. Keep the tank dim and add a little methylene blue or almond leaves to help prevent fungus.\n\nCongo eggs are not sticky, so they fall to the bottom and stay there. A mesh or marbles on the bottom keeps them safe from the adults while they develop."}, {"heading": "Raising the fry", "text": "- First few days of swimming: infusoria or a fine fry powder.\n- Week 1 to 3: newly hatched baby brine shrimp and microworms.\n- Weeks 3 to 6: add crushed flake.\n- Water changes: 10 to 20% every few days.\n- Temperature: 75 to 79°F.\n\nCongo fry are bigger than most tetra fry, so they move onto baby brine shrimp fairly quickly.\n\nKeep the fry tank lightly lit. Too much light can encourage algae and stress young fish."}, {"heading": "Growing out", "text": "Expect about an inch by 2 months. Fry grow quickly with good feeding and clean water. Males start showing longer fins and color as they mature over several months.\n\nMove fry to a larger tank as they grow, and keep water clean with frequent changes. Feed small meals several times a day.\n\nJuveniles are peaceful but active, so a longer tank gives them room to swim."}, {"heading": "Common mistakes", "text": "- Leaving the adults with the eggs.\n- Giving up before the eggs hatch; they take about a week.\n- Hard, alkaline water.\n- Fungus spreading from dead eggs.\n\nIf spawns keep failing, check that both fish are mature and well conditioned. Young Congo tetras often fail to spawn even in good conditions."}]$g$::jsonb, updated_at = now() where slug = $g$congo-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A small 5 to 10 gallon tank works. Use a gentle sponge filter, a dark bottom, fine plants or spawning mops, and cover the sides to keep it dim.\n\nThe care numbers list pH {{ph}}, GH {{gh}} and {{temp}}°F. For spawning, use very soft, acidic water: about pH 5.5 to 6 and GH around 1 to 2, at about 75 to 77°F. RO or rain water is commonly used to get it soft enough.\n\nSet up the breeding tank a week or two early, so it's stable. Peat or almond leaves help lower pH and tint the water. Clean everything well, since soft water has little buffering and bacteria and fungus can grow quickly."}, {"heading": "Choosing and conditioning a pair", "text": "Females are rounder, which makes their blue stripe look bent. Males are slimmer with a straight stripe. Choose adult fish that are at least 6 months old.\n\nCondition with live or frozen foods like daphnia and brine shrimp for about 2 weeks. Move a pair or 2 males and 1 female into the breeding tank in the evening.\n\nIf a pair doesn't spawn within a few days, return them to the main tank, keep conditioning, and try again in a couple of weeks."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the early morning. The male chases the female into the plants and the pair release eggs that stick lightly to the plants or fall to the bottom.\n\nCommonly reported spawns are about 60 to 130 eggs. Remove the adults once they've finished, since they eat eggs.\n\nSome breeders cover the tank with dark paper or a cloth, leaving only a little light. This keeps eggs and fry from light and helps the adults feel secure."}, {"heading": "Eggs and fungus", "text": "Keep the tank dark. Neon eggs and fry are sensitive to light. At 75 to 77°F, the eggs commonly hatch in about a day.\n\nRemove white, fungused eggs with a pipette. Keep the water still and clean, and avoid big changes.\n\nSoft, acidic water helps keep fungus down, but it also has little buffering, so keep an eye on pH. Avoid adding anything that could cause sudden changes."}, {"heading": "Raising the fry", "text": "- Days 1 to 5: fry hang on plants and glass and use up their yolk.\n- Week 1 of swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days, matched carefully.\n- Temperature: 75 to 77°F.\n\nKeep the light low for the first week or two, then slowly increase it.\n\nUse an infusoria culture started a week before spawning, so you have food ready when the fry need it."}, {"heading": "Growing out", "text": "Expect about half an inch by 2 months. The blue and red stripes develop as fry grow. Slowly raise hardness to normal keeping levels over a few weeks.\n\nGrow fry in a tank with gentle flow and some cover. Keep feeding small meals several times a day. Neon tetras grow slowly, reaching adult size in about 6 months."}, {"heading": "Common mistakes", "text": "- Hard water; neons rarely spawn without very soft water.\n- Bright light on eggs and fry.\n- Leaving the adults with the eggs.\n- Feeding baby brine shrimp too early.\n\nPatience matters with neons. Many breeders need several attempts before their first successful spawn, and getting water soft enough is usually the key."}]$g$::jsonb, updated_at = now() where slug = $g$neon-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Silver dollars need a big tank. The care numbers for this fish list {{tank}} gallons as a minimum, and breeding groups do better in larger tanks. Use a sponge or canister filter, dim light and fine leaved plants or floating plants for cover.\n\nThe care numbers list pH {{ph}}, GH {{gh}} and {{temp}}°F. Many breeders use soft, slightly acidic water for spawning, about pH 6 to 6.5, at around 79 to 82°F.\n\nPlastic or hardy plants are a good choice, since silver dollars eat most soft plants. Floating plants also help the fish feel secure. Keep a tight lid on, since they can jump when startled."}, {"heading": "Choosing and conditioning a group", "text": "Males have a longer, lobed anal fin with a red edge. Females have a plain, straight anal fin. Keep a school of 6 or more so pairs can form.\n\nCondition with vegetables, plant-based foods and some frozen foods like bloodworms for 2 to 3 weeks. Silver dollars eat plants, so live plants in the breeding tank may be eaten.\n\nSilver dollars mature at around a year old and several inches long. Keep a mixed group and be patient; pairs form on their own once the fish are settled and mature."}, {"heading": "Spawning: what you'll see", "text": "Males chase females and the pair swim side by side, releasing eggs that drop among plants and to the bottom. Spawning often happens in the morning.\n\nSpawns are commonly reported in the hundreds, sometimes up to about 2000 eggs. Adults usually don't eat many eggs, but moving the eggs or adults gives better results.\n\nIf you want to raise a lot of fry, siphon eggs from the bottom into a separate tank or move the adults after spawning. Leaving eggs in a busy tank with other fish usually means few survive."}, {"heading": "Eggs and fungus", "text": "At 79 to 82°F, the eggs commonly hatch in about 3 days. Fry then rest on the bottom while they use up their yolk.\n\nRemove white, fungused eggs. A little methylene blue or almond leaves can help prevent fungus spreading.\n\nSilver dollar eggs are not sticky, so they fall to the bottom. If you siphon them into a separate tank, use water from the breeding tank to avoid any shock."}, {"heading": "Raising the fry", "text": "- First few days of swimming: infusoria or a fine fry powder.\n- Weeks 1 to 3: newly hatched baby brine shrimp several times a day.\n- Weeks 3 to 6: crushed flake and blanched vegetables.\n- Water changes: 20% every few days.\n- Temperature: 79 to 82°F.\n\nFry usually start swimming roughly a week after hatching, once the yolk is used up.\n\nFry grow fast and eat a lot. Keep the water clean with regular changes, and remove uneaten food every day."}, {"heading": "Growing out", "text": "Expect about an inch by 2 months. Fry grow quickly with good feeding and clean water. Plan ahead: silver dollars reach about 6 inches, and a big spawn needs a lot of space.\n\nFeed small amounts several times a day and keep water clean. Move fry to larger tanks as they grow, since crowded fry grow slowly.\n\nSilver dollars grow fast in their first year, so check that grow-out tanks have enough filtration and space. Splitting large batches over several tanks keeps water quality up and growth even."}, {"heading": "Common mistakes", "text": "- A tank that's too small for a breeding group.\n- Hard, alkaline water.\n- Not planning for hundreds of fry.\n- Leaving fungused eggs to spread.\n\nMost failed attempts come from tanks that are too small or crowded. Silver dollars need space and calm to breed well."}]$g$::jsonb, updated_at = now() where slug = $g$silver-dollar$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Most breeders use a 30 to 40 gallon bare bottom tank for a pair, which makes cleaning easy. Add a spawning cone, a length of PVC pipe or a piece of slate leaned against the glass. Use one or two air driven sponge filters and a heater sized to hold 84 to 86°F steadily, inside the site's {{temp}}°F care range.\n\nFor breeding, use soft water with pH around 6 to 6.5 and low hardness, within the library range of pH {{ph}}. Very soft water helps eggs develop, so many breeders blend RO water with tap water. Keep the tank in a quiet spot with few people walking past."}, {"heading": "Choosing and conditioning a pair", "text": "Discus are very hard to sex by appearance. Males are sometimes larger with a thicker lip and bigger forehead, but none of this is reliable. The best way is to grow up a group of 6 or more young discus and watch for two fish that pair off, clean a surface together and chase others away. When they spawn, the female's breeding tube is blunt and thick, and the male's is smaller and pointed.\n\nCondition with several small meals a day: beef heart based mixes, frozen bloodworms, brine shrimp and a high quality discus pellet. Daily water changes of 25 to 50 percent are normal for discus breeders."}, {"heading": "Spawning: what you will see", "text": "The pair clean the cone thoroughly, then start trembling and bowing at each other. The female makes passes up the cone laying lines of eggs, and the male follows to fertilize them. Clutches are commonly 100 to 300 eggs. Both parents then fan the eggs and remove any that go bad."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F the eggs hatch in about 2 to 3 days. The parents often move the wrigglers to a different spot on the cone. Roughly 2 to 4 days after hatching, the fry become free swimming and head straight for the parents.\n\nYoung pairs commonly eat their first few clutches. Patience usually pays off, and many pairs get it right after a few tries. Some breeders place a mesh cone guard around the eggs so the parents can fan but not eat them, then remove it once the fry swim."}, {"heading": "Raising the fry", "text": "For the first days of free swimming the fry eat only the slime on their parents' skin. From about day 5 to 7, start offering newly hatched brine shrimp several times a day while they stay with the parents. Keep the temperature steady and do daily water changes, siphoning carefully around the fry.\n\nThe parents' skin can become worn as the fry grow. Most breeders separate the fry at about 3 to 4 weeks, once they are eating brine shrimp well."}, {"heading": "Growing out", "text": "After separation, feed baby brine shrimp, then crushed flake and fine discus pellets, and later beef heart mixes, five or six times a day. Large daily water changes are what drive good growth. Even with good care, expect several months for juveniles to reach around 2 inches and show strain color, and stunting is common if water quality slips.\n\nRaise fry in a bare bottom tank so you can siphon every scrap of food, and spread them out as they grow. Overcrowded fry tanks are the most common cause of stunted discus with large eyes and small bodies. Stick to one strain per pair so the young breed true to their parents."}, {"heading": "Common mistakes", "text": "- Assuming two fish are a pair before they spawn together\n- Hard water, which leads to eggs that never hatch\n- Too few water changes, causing stunted growth\n- Separating fry before they eat brine shrimp well\n- Moving a pair or the cone mid spawn"}]$g$::jsonb, updated_at = now() where slug = $g$discus-domestic-strains$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank, the minimum for this species, works well for a small group or pair. Use a dark substrate, plenty of leaf litter, driftwood and floating plants to keep the light dim. Filtration should be very gentle, ideally an air driven sponge filter.\n\nChocolate gouramis come from peat swamp waters. The library range is pH {{ph}} and GH {{gh}}, at {{temp}}°F. For breeding, aim for the soft, acidic end: pH around 5.5 to 6, very low hardness and conductivity, and 80 to 84°F. This usually means RO or rain water with leaf litter for tannins. Change water carefully, in small amounts, with water matched for temperature and chemistry."}, {"heading": "Sexing and choosing fish", "text": "Sexing is subtle. Males often have a more pointed dorsal fin and yellowish or gold edges on the dorsal and anal fins, while females tend to be plainer. These differences are easier to see in mature, well conditioned fish. Many breeders keep a group of 4 to 6 and let pairs form, then move a pair to a species tank. Avoid tankmates; chocolate gouramis are shy and easily outcompeted.\n\nBuy from a source that keeps them in soft water if you can, since fish moved suddenly from hard water often struggle. Quarantine new fish carefully in the same soft water before adding them, because chocolate gouramis are prone to skin and gill infections when stressed."}, {"heading": "Conditioning", "text": "Feed small live and frozen foods: daphnia, brine shrimp, small bloodworms and mosquito larvae. Many specimens refuse dry food at first. Feed small portions two or three times a day and remove leftovers, as decaying food quickly harms these sensitive fish. Watch for any signs of disease, which spreads quickly in this species, and keep the tank stable rather than chasing perfect numbers."}, {"heading": "Spawning and holding", "text": "Spawning usually happens near the bottom. The male courts the female with fins spread, and after the eggs are released and fertilized, the female collects them in her mouth. Breeders commonly report broods of a few dozen eggs or fewer.\n\nThe female commonly holds for about 14 days at 80 to 84°F. During this time she eats little or nothing and may hide. Disturbance can make her swallow or spit the brood, so keep the tank quiet and avoid moving her if you can.\n\nWrite down the date you first notice the female holding so you know when release is due. If you must move her, do it near the end of the hold, gently, in a container of tank water rather than a net, into a small tank with identical water."}, {"heading": "Raising the fry", "text": "When the fry are released, they are free swimming and fairly well developed. Feed newly hatched brine shrimp and microworms several times a day, with infusoria as a backup for the smallest fry. Keep water quality excellent with small, careful water changes every couple of days, matched for temperature and chemistry.\n\nMany breeders move the female to her own tank before release so the fry are safe, or move the fry out after release. Fry are sensitive to changes, so treat their tank just as carefully as the adults' tank."}, {"heading": "Growing out", "text": "Fry grow slowly. Continue with brine shrimp and add crushed frozen foods over time. Expect several months to reach about 1 inch. Keep the water soft and acidic, and avoid overcrowding. Losses are common even for skilled breeders, so expect to try several times.\n\nA small, mature grow out tank with leaf litter, floating plants and an established sponge filter is better than a bare new tank. Feed several small meals a day and keep the population modest so water quality stays high."}, {"heading": "Common mistakes", "text": "- Hard or neutral water\n- Big, sudden water changes\n- Busy tanks with active tankmates\n- Moving a holding female too early\n- Feeding only dry foods"}]$g$::jsonb, updated_at = now() where slug = $g$chocolate-gourami$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank, the minimum for this species, is enough for a pair. Use a dark substrate or bare bottom, leaf litter, small caves such as tiny clay pots or film canisters, and floating plants to keep the light dim. Use a gentle sponge filter.\n\nLicorice gouramis come from blackwater peat swamps. The library range is pH {{ph}} and GH {{gh}}, at {{temp}}°F. For breeding, aim for the soft, acidic end: pH around 5.5, very low hardness and conductivity, and 77 to 80°F. This usually means RO or rain water with leaf litter. Change water carefully, in small amounts, with matched water.\n\nPlace two or three caves around the tank so the male can choose. Many breeders lay the caves on their side with the opening facing the front so they can glance in without disturbing the fish. Keep the tank in a quiet room with no vibration or sudden light changes."}, {"heading": "Choosing and conditioning a pair", "text": "Males have brighter fins with colored edges, which look more striking when they display. Females are plainer, with darker horizontal stripes. Keep one pair in a species tank so the male can claim a cave without competition.\n\nMany fish sold as licorice gouramis are other Parosphromenus species, which look very similar. Keep fish from one source together and avoid mixing species or populations.\n\nFeed small live foods such as daphnia, cyclops, microworms and baby brine shrimp two or three times a day. Many licorice gouramis refuse dry food. Feed small portions and remove leftovers, since decaying food harms these sensitive fish quickly."}, {"heading": "Spawning: what you will see", "text": "The male claims a small cave and builds a small bubble nest on the ceiling. He displays to the female with fins spread, and the pair spawn upside down in the cave. Eggs stick to the ceiling and the male guards them. Clutches are small; breeders commonly report a few dozen eggs or fewer.\n\nYou may not see spawning at all, since it happens inside the cave. A male hanging near the cave entrance and chasing the female away is a good sign."}, {"heading": "Eggs and fry", "text": "At 77 to 80°F eggs commonly hatch in about 1 to 2 days. The fry hang in the cave for a few more days, becoming free swimming about 4 to 7 days after hatching. The male usually guards the brood until then. Avoid checking the cave often, as disturbance can make the male eat the eggs.\n\nOnce the fry are free swimming, many breeders move the adults out so the fry are safe."}, {"heading": "Raising the fry", "text": "The fry are very small. Offer infusoria or paramecium several times a day for the first week, then add microworms and newly hatched brine shrimp. Keep water quality excellent with small, careful water changes every couple of days, matched for temperature and chemistry. A lightly planted tank with leaf litter grows microorganisms between feedings.\n\nKeep the fry tank covered to hold warmth and humidity, as many labyrinth fry are sensitive to cold air while their labyrinth organ develops. Start brine shrimp only once the fry can clearly take it, usually after the first week."}, {"heading": "Growing out", "text": "Fry grow slowly. Continue with brine shrimp and microworms, adding crushed frozen foods such as cyclops over time. Expect several months to reach about half an inch, and longer before males show their adult colors. Keep the water soft and acidic, and avoid overcrowding."}, {"heading": "Common mistakes", "text": "- Hard or neutral water\n- Bright light and no cover\n- Checking the cave constantly\n- Mixing similar looking Parosphromenus species\n- No live foods ready for tiny fry"}]$g$::jsonb, updated_at = now() where slug = $g$licorice-gourami$g$;
update public.breeding_guides set sections = $g$[{"heading": "What is known", "text": "Chaetostoma formosae comes from fast, cool streams in Colombia. Captive spawns have been reported by a small number of hobbyists, but there is little detailed, repeatable information. What follows is based on those reports and on how related Chaetostoma breed. Where numbers are given, treat them as a guide rather than a promise.\n\nThe good news is that these fish are hardy, long lived and easy to keep healthy in the right conditions, so you can keep a group for years while you work toward a spawn. Patience and steady conditions matter far more than any special trick."}, {"heading": "Setting up the breeding tank", "text": "Use 30 gallons or more with lots of current: a canister or strong filter plus one or two powerheads. Oxygen is critical, so add air stones too. Keep the temperature on the cool side of our care range, about 68 to 74°F, with pH {{ph}}.\n\nProvide smooth river stones, flat slates propped up to make crevices, and clay or slate caves facing the current. A lid helps keep temperatures stable and fish in. In warm rooms you may need a fan or a chiller, since these fish struggle when the water climbs into the high 70s °F for long periods. Mature algae covered rocks give both adults and future fry something to graze."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is unreliable. Mature males are often described as having broader heads, while females look fuller through the belly when ripe. Keeping 4 to 6 adults gives the best chance of a pair. Provide more caves than fish to reduce squabbles.\n\nThese are grazers. Let algae grow on rocks, and feed vegetable wafers, blanched zucchini and spinach, with small meaty foods like bloodworms a few times a week. Condition for at least 6 to 8 weeks with large weekly water changes."}, {"heading": "Spawning and eggs", "text": "In reports, eggs are laid in a cave or under a flat stone, and the male stays with them, fanning and guarding. You may first notice a male refusing to leave his spot.\n\nBreeders report hatching in roughly a week, faster in warmer water. If eggs are abandoned, move them to a tumbler or a mesh basket in strong flow with an air stone, and remove white, fungused eggs daily."}, {"heading": "Raising the fry", "text": "Fry live on their yolk sac first and should not be fed until it is nearly gone. After that they graze constantly.\n\n- Weeks 1 to 2: biofilm, algae covered stones from the main tank, finely crushed algae wafers.\n- Weeks 3 to 6: blanched vegetables, algae wafers and a little crushed sinking pellet.\n- Change 20 to 30 percent every few days and keep the water cool, clean and well oxygenated.\n\nWarm, low oxygen water is the biggest danger for both fry and adults."}, {"heading": "Growing out", "text": "Growth is slow. Expect several months for fry to reach 1 to 2 inches. Keep stones with algae rotating through the grow out tank, feed several times a day and keep up strong flow. Keep good notes, since detailed reports for this species are scarce and useful to other breeders. Record temperature, flow, foods and dates, plus how many fry survive at each stage. Growing youngsters do best in their own tank with no larger grazers competing for the same food."}, {"heading": "Common mistakes", "text": "- Warm, still tropical tank conditions. These are cool stream fish.\n- Too few caves, which leads to fighting.\n- Feeding fry before the yolk is gone.\n- Assuming species: several Chaetostoma look alike in the trade, so record what you have carefully.\n- Skipping oxygen. An air stone or two is cheap insurance in warm weather.\n- Giving up too soon. Groups may take a long time to settle before they spawn."}]$g$::jsonb, updated_at = now() where slug = $g$rubber-lip-pleco$g$;
update public.breeding_guides set sections = $g$[{"heading": "What is known", "text": "Green neons come from blackwater habitats in South America. Spawns in home tanks are uncommon, and detailed reports are few. Breeders who have succeeded generally used methods similar to cardinal tetra breeding. The guidance here follows that approach, and any numbers should be seen as a starting point."}, {"heading": "Setting up the breeding tank", "text": "Use a small tank of around 5 gallons with dark sides, a dark bottom, and clumps of java moss or spawning mops. A gentle sponge filter or air stone is enough.\n\nUse soft water from reverse osmosis or rain, with GH near zero and pH about 5.5 to 6.0, within the 5.5 to 6.5 range in our care data. Leaf litter or peat helps. Keep the temperature around 78 to 82°F, inside our care range of {{temp}}°F."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is difficult in these tiny fish. Ripe females look fuller and rounder from the side, while males stay slim. Condition a group for 1 to 2 weeks on tiny live or frozen foods such as daphnia, cyclops and baby brine shrimp, and keep them in stable soft water.\n\nMove the best looking fish into the breeding tank in the evening, either as a pair or as a small group.\n\nChoose fish that are active, fully colored and eating well. Wild caught green neons can arrive thin, so quarantine new fish and give them a few weeks to settle in soft water before conditioning. A group of 8 or more, as our care data suggests, keeps them calm and confident."}, {"heading": "Spawning and eggs", "text": "Spawning is reported to happen in dim light or early in the morning, with eggs scattered in fine plants or moss. Remove adults as soon as possible.\n\nKeep the tank dark, since eggs and fry are light sensitive. Breeders report hatching in about a day at 78 to 82°F. Remove white, fungused eggs if you can do it without disturbing the rest. Very soft, acidic water helps prevent fungus.\n\nIf you can't see eggs, leave the tank dark and untouched for a few days and then look closely for tiny fry clinging to the glass or moss. Many spawns of small tetras are only noticed this way. Keep the hatching tank at the same temperature and chemistry as the spawning tank."}, {"heading": "Raising the fry", "text": "Fry are extremely small and need microscopic foods first.\n\n- First week of free swimming: infusoria or paramecium, several times a day.\n- Week 2: vinegar eels or microworms.\n- Week 3 on: newly hatched baby brine shrimp.\n\nDo small, careful water changes of 10 percent every few days with the same soft water. Raise the light slowly as fry grow. A few small snails can help clean up leftover food."}, {"heading": "Growing out", "text": "Fry grow slowly and take several months to reach adult size, usually under an inch. Feed baby brine shrimp and fine crushed foods several times a day. As they color up, you can move them into a larger tank with gentle flow and the same soft, acidic water. Keep detailed notes on water values and dates, as reports for this species are scarce and useful to others."}, {"heading": "Common mistakes", "text": "- Hard or neutral water.\n- Bright light on eggs and fry.\n- Food that is too large for the fry.\n- Leaving adults in with the eggs.\n- Big water changes that swing the pH.\n- Using tap water softened only partly. Measure GH and pH rather than guessing."}]$g$::jsonb, updated_at = now() where slug = $g$green-neon-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 gallon tank with dark sides and a sponge filter. Add spawning mops or clumps of fine leaved plants like java moss, and a mesh above the bottom if you like.\n\nUse very soft water with GH under 4 and pH around 5.5 to 6.5, inside the 5.5 to 7.0 range in our care data. Reverse osmosis or rain water with peat or leaf litter works. Keep the temperature at 80 to 84°F, within our care range of {{temp}}°F.\n\nA dim room or a towel over the tank helps, as eggs and fry are light sensitive. Let the water settle for a few days before adding fish so pH and temperature are stable. Remove snails and other tankmates that might eat eggs."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is hard. Females are rounder and deeper bodied when ripe, while males are slimmer. Buy a group so you can pick a well rounded female and an active male.\n\nCondition with live and frozen foods such as daphnia, brine shrimp and bloodworms, plus quality flakes, for 1 to 2 weeks. Separating sexes during conditioning can help. Make sure the fish are healthy, with bright red noses, before trying.\n\nHealthy rummynose have bright red heads, so a pale nose is a sign of stress or poor water. Fix that first. Fish at least a year old and close to full size are the best breeders."}, {"heading": "What spawning looks like", "text": "Spawning usually happens early in the morning. The pair swims side by side into the plants, scattering eggs that stick to leaves or fall to the bottom. Spawns are often modest, commonly reported from dozens to the low hundreds of eggs.\n\nRemove the adults as soon as spawning ends, since they eat eggs.\n\nIf nothing happens after two or three days, return the fish to the conditioning tank, feed them well for another week and try again. A slight rise in temperature or a soft water change sometimes helps."}, {"heading": "Eggs and fungus prevention", "text": "Eggs are commonly reported to hatch in about 24 to 36 hours at 80 to 84°F. Keep the tank dark during this time, since eggs and fry are light sensitive.\n\nRemove white, fungused eggs with a pipette. Very soft, acidic water helps keep fungus down, and gentle aeration helps the good eggs."}, {"heading": "Raising the fry", "text": "Fry are very small and need the tiniest foods.\n\n- First week: infusoria or paramecium several times a day.\n- Week 2: microworms or vinegar eels.\n- Week 3 on: baby brine shrimp.\n\nStart 10 percent water changes after the first week, using the same soft water, every couple of days. Keep the temperature steady and lighting low.\n\nCheck the fry daily with a flashlight from the side. Round, full bellies mean they are eating. If bellies stay thin, offer smaller foods more often. Siphon uneaten food from the bottom so the water stays clean."}, {"heading": "Growing out", "text": "Rummynose fry grow slowly and take about 3 months to reach an inch. Feed baby brine shrimp and fine crushed flakes several times a day, and keep the water clean and soft. The red nose develops as they mature. Once they are around an inch, move them into a larger tank with gentle flow.\n\nKeep fry in soft water through grow out, and if you need to move them to harder water later, do it slowly over several weeks."}, {"heading": "Common mistakes", "text": "- Hard water, which often stops eggs from hatching.\n- Leaving the parents with the eggs.\n- Bright light on eggs and fry.\n- Giving up after one try. Pairs often take a few attempts."}]$g$::jsonb, updated_at = now() where slug = $g$brilliant-rummynose-tetra$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Most breeders use a 30 to 40 gallon tall, bare bottomed tank for a single pair, even though our care data lists 75 gallons for keeping a group. A bare tank is easy to keep spotless. Use one or two sponge filters, a heater and a ceramic spawning cone, slate or a section of pipe stood upright.\n\nKeep the temperature at {{temp}}°F, within our care range of {{temp}}°F. Water should be soft and acidic. Many breeders lower the pH to about 6.0 to 6.5 for spawning, inside our care range of 6.0 to 7.0, with very low hardness. Very hard water often stops eggs from hatching."}, {"heading": "Choosing a pair", "text": "Sexing discus by looks is unreliable. Males are sometimes larger with thicker lips and a steeper forehead, but that's not consistent. The surest way is the breeding tube that appears just before spawning: the female's is short and blunt, the male's thinner and pointed.\n\nThe easiest route is to grow 5 or more young discus together and let a pair form. A pair stays near each other, cleans surfaces together and chases other fish away. Move them to their own tank once they are clearly bonded."}, {"heading": "Conditioning and spawning", "text": "Feed several times a day with beefheart mix, frozen bloodworms, quality pellets and flakes. Do 30 to 50 percent water changes daily or every other day with matched soft water.\n\nBefore spawning, the pair cleans the cone, shivers, and shows their breeding tubes. The female lays rows of eggs up the cone, and the male follows to fertilize them. Spawns are commonly reported around 100 to 300 eggs, sometimes more."}, {"heading": "Eggs and wrigglers", "text": "Both parents fan the eggs and remove bad ones. At 84 to 86°F, eggs hatch in about 2 to 3 days. The hatched wrigglers stay attached to the cone and are moved around by the parents.\n\nAbout 5 to 6 days after spawning, fry become free swimming and swarm onto the parents' sides. Keep the light low and avoid disturbing the pair during this time. Young pairs may eat the eggs a few times before they get it right. Be patient."}, {"heading": "Raising the fry", "text": "For the first week, fry feed on mucus the parents produce on their skin. This is normal and important.\n\n- Days 5 to 7 of free swimming: start offering newly hatched baby brine shrimp a few times a day.\n- Weeks 2 to 3: baby brine shrimp several times a day, plus finely crushed flake.\n- Week 3 to 4: remove the parents or the fry, as the parents' mucus runs low and fry can nip at them.\n\nKeep doing water changes of 30 to 50 percent daily with matched water, and siphon leftovers carefully."}, {"heading": "Growing out", "text": "Discus fry grow fast with lots of food and clean water. Expect roughly 2 to 3 months of heavy feeding for them to reach 1 to 2 inches. Feed several times a day, change water daily, and sort fry by size so smaller ones aren't left behind. A bare tank with sponge filters keeps cleaning simple. Keep water warm, around 82 to 86°F, through grow out.\n\nHealthy fry are round, active and dark eyed. If some stay thin or hang near the surface, they are often not getting enough food, so offer more frequent, smaller meals and move the biggest fish to a separate tank."}, {"heading": "Common mistakes", "text": "- Water that is too hard, which stops eggs from hatching.\n- Moving a pair too often, which stresses them.\n- Removing eggs from young pairs too quickly. Let them learn.\n- Infrequent water changes. Discus are very sensitive to poor water.\n- Raising fry without the parents. It is possible but very difficult; leave fry with parents if you can."}]$g$::jsonb, updated_at = now() where slug = $g$discus$g$;
update public.breeding_guides set sections = $g$[{"heading": "Setting up the breeding tank", "text": "Use 20 gallons or more, as our care data suggests, with soft sand so they can dig. Plant densely and add floating plants with long roots, plus caves and leaf litter. Keep the lights dim.\n\nFor spawning, use soft, acidic water with pH around 5.5 to 6.5 and temperatures of 78 to 80°F, within our care range of {{temp}}°F. Use a sponge filter or covered intake to keep fry safe.\n\nA species only tank gives the best chance, since many tankmates will eat eggs and tiny fry. Leaf litter and moss add hiding places and grow microorganisms that young kuhlis can graze on. Keep the lid tight, as kuhlis can squeeze through small gaps."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is possible with a close look. Males have larger, more paddle shaped pectoral fins with a thicker first ray. Ripe females look fuller, and their green eggs may show through the skin.\n\nKeep a group of 6 or more. Feed frozen bloodworms, blackworms, brine shrimp, daphnia and quality sinking pellets for several weeks. Feeding at night, when they are most active, helps them get enough.\n\nMost kuhlis sold are a mix of similar Pangio species, so try to buy your group from one batch that all look the same. Quarantine new fish and give them time to settle before you expect spawning. Healthy kuhlis are active at night and eat eagerly."}, {"heading": "Spawning", "text": "Spawning is rarely seen, as it often happens at night. Reports describe groups gathering near the surface and laying eggs among floating plant roots. Triggers often mentioned include a cooler water change, raising the water level, or soft rainwater style changes.\n\nIf you find green eggs, gently move the roots or plants into a hatching container with tank water and an air stone.\n\nSpawning is often noticed after a large, soft, slightly cooler water change, which imitates the rainy season. Check floating plant roots in the morning with a flashlight for green eggs. If you never find eggs, look for tiny fry in moss and leaf litter instead."}, {"heading": "Eggs and fungus prevention", "text": "The eggs are bright green and easy to recognize. Breeders report hatching in about 1 to 2 days at 78 to 80°F. Remove white, fungused eggs daily. Keep the hatching container dim, and use very gentle aeration.\n\nIf you leave eggs in the main tank, dense plants and moss give some fry a chance to survive."}, {"heading": "Raising the fry", "text": "Fry are tiny and hide all the time.\n\n- First week: infusoria several times a day.\n- Week 2: microworms.\n- Week 3 on: baby brine shrimp.\n\nDo small water changes of 10 to 20 percent every few days, and siphon carefully. Moss and leaf litter grow microorganisms that fry can graze on.\n\nKeep the fry tank dark and quiet, and add a small piece of moss or a few leaves so they have cover. Fry that hide constantly still need food nearby, so spread food across the bottom rather than in one spot."}, {"heading": "Growing out", "text": "Kuhli fry grow slowly, taking several months to reach 1 to 2 inches. Feed baby brine shrimp, microworms and crushed sinking pellets several times a day. Give them soft sand and lots of cover. Keep the water clean and soft through grow out.\n\nOnce the young are about an inch long, they can move into a larger tank with sand and plenty of cover. Keep feeding at night, when they are most active."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water.\n- No floating plants for spawning.\n- Bright light, which keeps kuhlis hidden and stressed.\n- Strong filters that suck up fry.\n- Mixing Pangio species, as many look alike in the trade."}]$g$::jsonb, updated_at = now() where slug = $g$kuhli-loach$g$;
update public.breeding_guides set sections = $g$[{"heading": "Breeding tank and water", "text": "The site's care guide lists {{temp}}°F and pH {{ph}}. For breeding wild fish, most breeders go softer and more acidic: pH about 5.5 to 6, lowered slowly, general hardness close to zero, and low conductivity. Wild discus eggs in harder water often fail to develop, so a reverse osmosis unit is close to essential.\n\nUse a 30 to 40 gallon tank per pair with a bare bottom, a sponge filter, a heater set to 84 to 86°F and a spawning cone or upright slate. Keep the tank in a quiet spot, and change 30 to 50% of the water several times a week with matched temperature and chemistry."}, {"heading": "Finding a pair", "text": "You cannot reliably sex discus by shape or color. The usual method is to raise a group of five or more together and watch for two fish that stay together and start cleaning a surface. Once they are paired, move them to their own tank.\n\nCondition with several small meals a day: a beef heart based mix, frozen bloodworms and quality discus granules. Wild fish can be shy feeders at first, so be patient.\n\nKeep the pair tank calm: no busy tank mates, steady lighting and a cover on the front glass if people walk past often. Wild fish that feel exposed tend to eat their eggs. Give a new pair several weeks to settle in before you expect a spawn, and keep water changes regular so the chemistry does not swing."}, {"heading": "Spawning", "text": "A pair about to spawn will clean the cone repeatedly, shake and bow to each other, and show their breeding tubes. The female's tube is broad and blunt, the male's thinner and more pointed. She lays lines of eggs and he follows to fertilize. Breeders commonly report about 100 to 300 eggs."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F eggs hatch in roughly 2 to 3 days. The parents move the wrigglers, which hang on the cone for another 2 to 3 days. Eggs that turn white are infertile or fungused; a few are normal, but a whole clutch going white usually points to water that is too hard, or an inexperienced male.\n\nEgg eating is common with new pairs. Give them several chances before trying anything else. A mesh guard around the cone helps some pairs."}, {"heading": "Raising the fry", "text": "Discus fry feed on the slime coat on their parents' sides. This is the most important stage, and wild pairs sometimes fail at it at first.\n\n- Days 1 to 5 free swimming: fry graze the parents, no extra food needed\n- From about day 5: add newly hatched brine shrimp several times a day\n- Weeks 2 to 3: remove the parents gently once fry are eating well on their own\n- Throughout: small, frequent water changes, keeping the temperature steady"}, {"heading": "Growing out", "text": "Young discus need lots of food and lots of clean water. Feed five or more small meals a day of baby brine, then a beef heart mix and fine granules as they grow. Change water daily if you can. With good care they can reach around 1.5 to 2 inches in 2 to 3 months, but stunting is common if water quality slips."}, {"heading": "Common mistakes", "text": "- Using tap water that is too hard for wild fish eggs\n- Disturbing the pair during the first spawns\n- Pulling the parents too early, before fry eat brine well\n- Skipping water changes in the grow-out tank\n- Mixing wild and tank-bred strains when your goal is wild-type stock"}]$g$::jsonb, updated_at = now() where slug = $g$wild-discus$g$;
update public.breeding_guides set sections = $g$[{"heading": "The breeding tank", "text": "Butterflyfish live at the surface, so surface area matters more than depth. A 30 gallon or larger tank, long and shallow, works well. Cover part of the surface with floating plants, keep flow gentle and fit a tight lid, because these fish jump.\n\nThe site's care guide lists {{temp}}°F and pH {{ph}}. For breeding, breeders report better results at about 77 to 82°F with soft, slightly acidic water, around pH 6.5."}, {"heading": "Sexing and conditioning", "text": "Sexing is possible with a close look at the anal fin. In males the rear edge is curved and the central rays form a tube-like structure; in females the edge is straight. This difference is well described, but it can be hard to see on young fish.\n\nCondition with a varied insect diet: crickets, fruit flies, mosquito larvae and small floating foods, offered daily for several weeks. Butterflyfish rarely take food from the bottom, so offer it at the surface.\n\nA well-conditioned female looks fuller through the belly. Keep only one male per tank if you can, since males may squabble at the surface. Avoid fast or fin-nipping tank mates during breeding attempts; quiet, bottom-dwelling companions or a species-only tank work best."}, {"heading": "Spawning", "text": "Pairs embrace near the surface, and eggs are released over several days rather than all at once. Fertilization is thought to happen inside the female. The eggs float, which makes them easy to spot as small round beads among the plants. Numbers vary a lot between reports, so don't worry about matching a figure."}, {"heading": "Eggs", "text": "Collect floating eggs each day with a spoon or small cup and move them to a shallow container with water from the breeding tank, plus gentle aeration or a small airline nearby. Breeders commonly report hatching in about 2 to 3 days at 77 to 82°F. Remove any eggs that turn white or fuzzy to stop fungus spreading. Leaving eggs with the adults usually means losing many of them.\n\nKeep the egg container in dim light at the same temperature as the breeding tank, and change a little of its water daily with water from the main tank. Clean, matched water matters more than anything you add to it."}, {"heading": "Raising the fry", "text": "This is the hard part. Fry stay right at the surface and, like the adults, will not chase food that sinks. Breeders report the best results with tiny floating live foods.\n\n- First feeding: springtails and other very small floating live foods\n- As they grow: fruit flies, small floating insects and mosquito larvae at the surface\n- Keep the water shallow, a few inches, so food stays near them\n- Small, gentle water changes every few days at the same temperature\n\nNewly hatched brine shrimp sink and are often ignored, which is why many attempts fail at this stage."}, {"heading": "Growing out", "text": "Grow-out is slow and not well documented. Keep fry in shallow, covered containers, sort them by size because larger fry may eat smaller ones, and step up food size as they grow. Expect several months before they look like small adults."}, {"heading": "Common mistakes", "text": "- Offering sinking foods to fry that only eat at the surface\n- Leaving eggs with the adults\n- Deep containers where fry can't find food\n- No lid, so adults jump during spawning\n- Expecting a full clutch to survive; even a few grown fry is a success\n- Mixing fry of very different sizes, which invites cannibalism"}]$g$::jsonb, updated_at = now() where slug = $g$african-butterfly-fish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Why nerite eggs don't hatch into snails", "text": "Neritina natalensis lives in rivers and estuaries in Africa. Adults live in fresh or slightly brackish water, but their larvae are swept downstream and develop in brackish or sea water before young snails travel back up. In a freshwater aquarium the capsules may hatch, but the larvae can't develop, so you never see baby snails.\n\nThis also means nerites won't overrun a tank, which is part of their appeal. Captive raising is rarely reported, and published hobby methods are thin. Treat this guide as an outline of what is known."}, {"heading": "Keeping the adults", "text": "The site's care guide lists {{temp}}°F, pH {{ph}} and moderate to hard water. Hard, alkaline water keeps their shells strong. Feed algae wafers, blanched zucchini and spinach, and leave some algae growing on the glass and rocks.\n\nNerites have separate sexes, but there is no reliable way to tell them apart by eye. Keep a group of five or more to improve the odds of having both. Capsules can appear even from a single snail kept alone, so capsules alone don't prove you have both sexes.\n\nWell-fed adults lay more capsules, so keep algae and vegetables on the menu and supplement calcium if your water is soft. Healthy nerites are active, keep their trapdoor (operculum) closed tightly when disturbed and have smooth, unpitted shells. Pitting or white erosion on the shell usually means the water is too soft or acidic."}, {"heading": "The egg capsules", "text": "Females lay small, white, sesame-seed capsules on hard surfaces: glass, wood, rocks and even other snails. Each capsule holds many tiny eggs. Breeders who have raised nerites usually move capsule-covered rocks or wood into salt water rather than scraping the capsules off, because scraped capsules are easily damaged.\n\nHatch time varies with temperature and is not well documented for this species, so check the larval container daily.\n\nSet up the larval container before you move any capsules: a small tank or jar with an air line, a heater, a light and pre-mixed salt water at the starting salinity. Have a phytoplankton culture running too, since there is no time to start one once larvae appear."}, {"heading": "The larval stage", "text": "Larvae hatch as microscopic swimming veligers. Successful breeders report raising salinity from brackish toward full sea water, and feeding live phytoplankton so the larvae always have food. They need gentle aeration to stay in suspension and stable temperature.\n\n- Keep the larval container in light, with no filter that could catch larvae\n- Add live microalgae daily to keep the water lightly green\n- Do small, careful water changes with matched salinity\n- Watch with a magnifying glass for settled snails on the walls\n\nThe larval stage can last several weeks or longer. Losses are high."}, {"heading": "Raising the baby snails", "text": "Once larvae settle, they become tiny crawling snails grazing on algae films. Breeders report slowly lowering salinity over weeks before moving them back toward fresh water. Give them glass or rocks coated with soft algae, and never let the water quality swing. Growth is slow, and it takes months before they look like small adults.\n\nKeep a dated record as you go: salinity, temperature and what you fed. With so few reports out there, your notes are valuable to other members."}, {"heading": "Common mistakes", "text": "- Expecting capsules in freshwater to produce snails\n- Scraping capsules off glass and damaging them\n- Using a filter in the larval container\n- Changing salinity too fast in either direction\n- Not having live phytoplankton ready before the larvae hatch\n- Copper based medicines or plant products, which kill snails"}]$g$::jsonb, updated_at = now() where slug = $g$nerite-snail$g$;
update public.breeding_guides set sections = $g$[{"heading": "The honest picture", "text": "Clown loaches come from rivers in Sumatra and Borneo, where they are thought to spawn during the rainy season. The fish sold in shops are wild caught or produced on farms that use hormone injections. Hormone use is not something we suggest; this guide is about natural spawning only.\n\nNatural spawns in home aquariums have been reported, but only a handful, and details are thin. That is why clown loaches are a class F species."}, {"heading": "What you need", "text": "Clown loaches grow to 12 inches and live a long time. The site's care guide calls for at least {{tank}} gallons and a group of five or more, and breeding attempts need mature adults, which can mean fish several years old.\n\n- A large tank with strong, oxygen-rich flow\n- Fine gravel or sand, wood and plenty of hiding places\n- Temperature 75 to 85°F, pH 6 to 7.5\n- Excellent water quality with large regular water changes"}, {"heading": "Sexing and conditioning", "text": "Sexing clown loaches is difficult. Some keepers report that males have more inward-curving tail tips and that ripe females are plumper, but these signs are debated and unreliable. A large group is the best way to make sure you have both sexes.\n\nCondition with a varied diet: snails, bloodworms, blackworms, shrimp and quality sinking pellets, several times a week.\n\nKeep the group as stable as you can. Clown loaches are social and do best in larger numbers, with plenty of caves and wood to squeeze into. Healthy fish are active during the day, click when feeding and show bright orange and black color. Thin or pale fish should be brought back to full condition first."}, {"heading": "Spawning attempts", "text": "Since spawning is thought to follow seasonal rains, some keepers simulate a rainy season. This usually means a period of stable warm conditions followed by large, slightly cooler water changes, higher flow and heavier feeding. There's no proven recipe. Watch for unusual chasing, fish swimming together near plants or the substrate, and plumper females.\n\nReported home spawns have often been in very large tanks with mature groups, sometimes after years with no sign of breeding. Some spawns have been noticed only when fry appeared. Fine-leaved plants or spawning mops near the bottom give scattered eggs somewhere to land, and a heavily planted area may let a few fry survive unnoticed."}, {"heading": "If you find eggs", "text": "Clown loaches are egg scatterers with no parental care. If you see eggs, remove them or the adults as soon as you can, because adults are likely to eat them. Move eggs to a bare container with water from the main tank and gentle aeration, and remove any that turn white or fuzzy. Hatch time and egg counts for home spawns are not well documented, so keep notes."}, {"heading": "Raising the fry", "text": "With so few reports, fry care is based on general practice for small egg-scattering fish.\n\n- First days: infusoria or rotifers once the fry start to swim\n- After a few days: newly hatched brine shrimp and microworms\n- Small, frequent water changes with matched temperature\n- Fine sponge filtration so fry are not sucked up\n\nAny breeder who raises clown loaches should record everything, from water to foods to dates."}, {"heading": "Common mistakes", "text": "- Trying with a few young fish in a small tank\n- Using hormones, which we don't recommend\n- Leaving eggs with the adults\n- Expecting quick results; this can take years\n- Small, infrequent water changes, which leave the water stale for big, messy fish\n- Overlooking fry in a planted tank; check carefully with a flashlight"}]$g$::jsonb, updated_at = now() where slug = $g$clown-loach$g$;
update public.breeding_guides set sections = $g$[{"heading": "Tank and water", "text": "Altums are taller than common angelfish and need a tall tank, ideally 24 inches deep or more. The site's care guide lists at least {{tank}} gallons, {{temp}}°F, pH {{ph}} and very soft water.\n\nFor breeding, breeders report the best results at the soft, acidic end: pH around 5.5 to 6.0 and hardness close to zero, lowered slowly over a couple of weeks. Reverse osmosis water is close to essential. Provide upright slate, wood or broad leaves as spawning sites, and keep the tank calm with dim lighting. Use a sponge filter or a gently flowing canister, and change water often with matched temperature and chemistry. Peat or leaf litter helps keep the water soft and slightly stained."}, {"heading": "Forming a pair", "text": "Sexing altums by eye is unreliable. The best approach is to raise a group of five or more and wait for two fish to start claiming a spawning site together. Once a pair forms, move them to their own tank or move the others.\n\nCondition with frozen bloodworms, brine shrimp and quality flake or granules. Wild-caught altums can be shy feeders at first, so be patient.\n\nAltums are sensitive to stress, so keep the group in a quiet room with steady lighting and few tank mates. Peaceful dither fish such as small tetras can help them feel secure. Pairs can take a long time to form, sometimes years, so don't rush the process or split a group too early."}, {"heading": "Spawning", "text": "Before spawning, the pair cleans a vertical surface. The breeding tubes show: the female's is broad and blunt, the male's thinner and pointed. The female lays rows of eggs and the male follows to fertilize them. Clutches are commonly reported in the low hundreds.\n\nSpawning usually takes an hour or two. Both parents then fan and guard the eggs. With a young pair, it is common for the first few clutches to be eaten or to fail, which is why many breeders choose to hatch the eggs separately."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F eggs hatch in about 2 to 3 days. Wrigglers become free swimming about 4 to 6 days after hatching. Eggs that turn white are infertile or fungused; a whole clutch going white usually points to water that is too hard.\n\nMany breeders remove the egg slate to a separate container with water from the breeding tank, gentle aeration and a few drops of methylene blue to prevent fungus."}, {"heading": "Raising the fry", "text": "- Once free swimming: newly hatched brine shrimp and microworms, several times a day\n- Weeks 2 to 4: add crushed flake and frozen foods\n- Small, frequent water changes with matched temperature and chemistry\n- Sponge filtration so fry are not sucked up"}, {"heading": "Growing out", "text": "Altum fry grow slowly and need clean, soft water. Feed several small meals a day and keep water quality high. It takes several months before they look like small altums, and longer before they reach full height. Keep the grow-out tank tall as they get bigger, since cramped altums often develop bent fins. Share young fish with other altum keepers so this rarely bred species becomes more available."}, {"heading": "Common mistakes", "text": "- Water that is too hard for altum eggs\n- A tank that is too short for their tall bodies\n- Disturbing the pair during spawning\n- Skipping water changes in the grow-out tank\n- Expecting quick results; pairs can take years to form\n- Moving a pair to a new tank just as they settle, which often sets them back months"}]$g$::jsonb, updated_at = now() where slug = $g$altum-angelfish$g$;
update public.breeding_guides set sections = $g$[{"heading": "Tank and water", "text": "Senegal bichirs grow to around 12 inches. The site's care guide lists at least {{tank}} gallons, {{temp}}°F and pH {{ph}}. For breeding, provide dense plants or spawning mops where eggs can land, and a tight lid since bichirs can escape through small gaps.\n\nBichirs are hardy, and they tolerate a wide range of water. For breeding, some keepers lower the hardness and pH slightly, while keeping within the site's range. Give the group plenty of space and hiding places such as wood and caves, since males can squabble when they are in breeding condition."}, {"heading": "Sexing and conditioning", "text": "Males have a thicker, broader anal fin, which they use to cup the eggs during spawning. Females are often plumper. A group of mature adults gives the best chance of a pair.\n\nCondition with meaty foods: worms, shrimp and pieces of fish, several times a week. Well-fed females look noticeably fuller. Mature fish are needed, and bichirs can take a few years to reach breeding size. Young fish under several inches are unlikely to spawn."}, {"heading": "Triggering a spawn", "text": "Breeders report spawns after large, slightly cooler and softer water changes that copy the rainy season. Keep this up for a few weeks and watch for chasing and the male following the female closely.\n\nSome breeders also drop the temperature slightly for a period, then raise it again with fresh, softer water. There is no proven recipe, and many keepers try for months before seeing anything. Keep notes on what you change and when."}, {"heading": "Spawning", "text": "During spawning, the male cups his anal fin to collect the eggs and fertilizes them, then scatters them among plants. Clutches are commonly reported as a few hundred eggs or fewer. Remove the eggs or the adults right away, since adults readily eat them.\n\nSpawning tends to happen at night or early morning, so check the plants and mops each morning. The eggs are small and sticky, and easy to miss among dense plants. A spawning mop that you can lift out makes collecting them much easier."}, {"heading": "Eggs and larvae", "text": "Eggs commonly hatch in roughly 3 to 4 days at 77 to 82°F. The larvae have feathery external gills, which they lose as they grow. They look more like tiny salamanders than fish at first. They stay near the bottom and use their yolk for several days before feeding.\n\nKeep the eggs in a separate container with water from the main tank, gentle aeration and dim light. Remove any eggs that turn white or fuzzy to stop fungus spreading. Larvae should be kept in shallow water, a few inches deep, so they can reach the surface easily, since bichirs gulp air as they grow."}, {"heading": "Raising the fry", "text": "- Once feeding: newly hatched brine shrimp and microworms, several times a day\n- Weeks 2 to 4: add chopped bloodworms and blackworms\n- Small, frequent water changes with matched temperature\n- Sort by size, since larger fry eat smaller ones\n\nGrowth is slow, and it takes several months to reach a juvenile size."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults\n- No lid, so bichirs escape\n- Mixing fry of very different sizes\n- Expecting quick results; spawns are rare and unpredictable\n- Overfeeding larvae, which fouls the shallow water quickly\n- Deep water for larvae, which makes it harder for them to reach the surface\n- Forgetting that adult tank mates will hunt any fry that escape into the main tank"}]$g$::jsonb, updated_at = now() where slug = $g$senegal-bichir$g$;
update public.glossary_terms set sections = $g$[{"text": "- Ceramic disc diffusers: a fine porous disc in a glass or plastic holder. They make a mist of tiny bubbles and need a fair amount of pressure to push gas through.\n- Inline diffusers: fit on the canister filter outflow hose, keeping equipment out of sight.\n- Reactors: chambers where water and CO2 mix fully. Very efficient, good for large tanks.\n- Bubble ladders: simple, cheap and visible, but less efficient.", "heading": "Types of diffusers"}, {"text": "Put an in-tank diffuser low in the tank under or near the filter outflow, so current carries the bubbles around before they reach the surface. The longer bubbles stay in the water, the more CO2 dissolves. Use a CO2-rated check valve on the line and confirm levels with a drop checker.", "heading": "Placement"}, {"text": "Most planted tanks aim for about {{fact.co2}} ppm CO2, which turns a standard drop checker green. Start with a low bubble rate and raise it slowly over a week or two. Many keepers turn CO2 on 1 to 2 hours before the lights and off about an hour before lights out. Fish gasping at the surface means too much: turn it down and add aeration right away.", "heading": "Getting the dose right"}, {"text": "Ceramic discs clog with algae and biofilm, which makes bubbles bigger. Soak the disc in a dilute bleach or hydrogen peroxide solution, rinse thoroughly, and soak it in dechlorinated water before reuse.", "heading": "Cleaning"}]$g$::jsonb where slug = $g$co2-diffuser$g$;
update public.glossary_terms set body = $g$Most tropical fish need water around {{fact.tropical_temp}} F, and sudden temperature swings weaken their immune systems and invite diseases like ich. A reliable, correctly sized heater keeps conditions steady day and night, and a heater that fails stuck on is one of the fastest ways to lose a tank.$g$, sections = $g$[{"text": "A common rule is {{fact.heater_watts}} watts per gallon, using the higher end if the room is cool or the tank is uncovered. A 20 gallon tank usually needs a 75 to 100 watt heater. For tanks over about {{fact.two_heaters}} gallons, two smaller heaters at each end spread heat evenly and give you a backup if one fails.", "heading": "Choosing the right size"}, {"text": "- Place the heater near the filter outflow or another spot with good flow.\n- Mount it at an angle if fully submersible, and let it sit in the water about 15 to 30 minutes before plugging in so the glass adjusts.\n- Use a separate thermometer. The dial on many heaters is off by a few degrees.\n- Add a heater guard for large or curious fish that might get burned.", "heading": "Setup tips"}, {"text": "Heaters can fail stuck on, cooking a tank in hours, or stuck off. An external temperature controller that cuts power if water gets too hot is cheap insurance on any valuable setup. Always unplug the heater before a water change and wait several minutes before lifting it out of the water, since a hot heater in air can crack.", "heading": "Safety and backups"}, {"text": "Tropical fish almost always do. Some fish, like goldfish, white cloud minnows and many hillstream loaches, prefer cooler water and often do fine at room temperature if the room stays stable.", "heading": "Do you need one?"}]$g$::jsonb, faq = $g$[{"a": "About {{fact.heater_watts}} watts per gallon. Use the higher end in a cold room or for a tank without a lid.", "q": "What size heater do I need for my aquarium?"}, {"a": "Most tropical community fish do well at 76 to 78 F, but check the needs of each species.", "q": "What temperature should my aquarium be?"}, {"a": "No. Leaving it on keeps the temperature steady, which is what the heater is for.", "q": "Should I turn off my aquarium heater at night?"}]$g$::jsonb where slug = $g$heater$g$;
update public.glossary_terms set sections = $g$[{"text": "- Usually adapted to a wider range of pH and hardness than wild fish\n- Already eats flakes, pellets and frozen foods\n- Fewer wild parasites, though quarantine is still smart\n- No collection pressure on wild habitats\n- Often easier to find in bright color strains and long-finned forms", "heading": "Why many keepers prefer it"}, {"text": "Captive-bred does not automatically mean healthy. Some mass-produced strains suffer from inbreeding, weaker immune systems, deformities or shorter lifespans. Fancy guppies, bettas and some angelfish lines are known for this. Fish raised on farms in very different water may still need careful acclimation, and some farm fish are given hormones or dyes to boost color, a practice many hobbyists avoid supporting.", "heading": "The downsides"}, {"text": "These labels are used loosely. Captive-bred usually means spawned in captivity. Farmed or pond-raised fish are bred in large outdoor ponds, mostly in Florida and Southeast Asia. Some sellers call a fish tank-raised when it was collected wild as a juvenile and grown out in captivity, which is not the same thing, so ask if it matters to you.", "heading": "Captive-bred vs tank-raised vs farmed"}, {"text": "Look for active fish with full color, clean fins and rounded bellies. Local breeders and hobbyist clubs often sell healthier, less inbred fish than mass farms, and can tell you the water they were raised in. Quarantine still applies: give any new fish {{fact.quarantine_weeks}} weeks in a separate tank before it joins your display.", "heading": "Choosing good stock"}]$g$::jsonb, faq = $g$[{"a": "For most beginners, yes. They tend to be hardier in tap water and eat prepared food, though wild-caught fish can show stronger natural color.", "q": "Are captive-bred fish better than wild-caught?"}, {"a": "Ask the seller. Common store species like guppies, platies, mollies and most bettas are almost always captive-bred, while some tetras and many rare species are still collected wild.", "q": "How can I tell if a fish is captive-bred?"}, {"a": "Yes. They can still carry ich, bacteria and internal parasites from the farm or store, so quarantine for {{fact.quarantine_weeks}} weeks is a good habit.", "q": "Do captive-bred fish still need quarantine?"}]$g$::jsonb where slug = $g$captive-bred$g$;
update public.glossary_terms set sections = $g$[{"text": "- Forked: deep notch, built for speed, as in danios, tetras and barbs\n- Rounded: broad and fan-like for quick bursts and maneuvering, common in many cichlids and killifish\n- Lyre-shaped: long upper and lower points, seen in lyretail mollies and some killifish\n- Bred forms: veiltail, delta, halfmoon and crowntail bettas, or the long flowing tails of fancy guppies and goldfish\n\nLong, heavy tails are bred for looks and make fish slower and weaker swimmers, so those fish do best in gentle flow.", "heading": "Common tail shapes"}, {"text": "Watch for ragged or receding edges, white or red margins, fraying, holes, blood streaks and clamped tails held tightly together. Ragged edges with a white or dark rim that keeps advancing point to fin rot. Clean crescent-shaped bites or missing chunks point to fin nipping. Tail biting, especially in bettas, shows as sudden loss without rot.", "heading": "Signs of trouble"}, {"text": "Caudal fins usually grow back if the base of the fin is intact. New growth looks clear and thin at first, often as a fine white or transparent edge, which is normal and not a fungus. Expect weeks to a few months for full regrowth. Clean water with nitrate below about {{fact.nitrate_ok}} ppm, steady temperature and good food speed it up.\n\nIf the edges keep receding, look red or grow fuzzy white tufts after a week of clean water, treat for fin rot or fungus in a hospital tank rather than waiting.", "heading": "Regrowth"}]$g$::jsonb where slug = $g$caudal-fin$g$;
update public.glossary_terms set faq = $g$[{"a": "Zebra danios, white cloud minnows, platies and bristlenose plecos are among the hardiest common choices for a properly cycled tank.", "q": "What is the hardiest aquarium fish?"}, {"a": "They survive longer than sensitive fish, but ammonia and nitrite still damage their gills and can kill them. Cycle the tank first.", "q": "Can hardy fish live in an uncycled tank?"}, {"a": "Bettas tolerate low oxygen thanks to their labyrinth organ, but they still need a heated, filtered tank of at least {{betta.tank}} gallons to stay healthy.", "q": "Are bettas hardy fish?"}]$g$::jsonb where slug = $g$hardy$g$;
update public.glossary_terms set sections = $g$[{"text": "- Natural color patterns and behaviors that captive strains may have lost\n- Fresh bloodlines for breeding programs\n- Species that are rarely or never bred in captivity, such as many wild bettas, some catfish and dwarf cichlids\n- Many cardinal tetras are still wild collected, and some sustainable collection projects support local communities and help protect river habitats", "heading": "Why keepers choose them"}, {"text": "Wild fish go through capture, holding and long shipping, so they arrive stressed and sometimes thin. They commonly carry internal parasites, worms and gill flukes. Many come from very soft, acidic blackwater and struggle in hard tap water at first. Some will not recognize flakes or pellets as food right away.", "heading": "Challenges"}, {"text": "- Quarantine for at least {{fact.quarantine_min}} weeks, and many keepers treat for internal parasites during that time\n- Match their native water as closely as you can, often softer water with a pH around 6.0 to 7.0, then shift gradually if needed\n- Keep lights dim and give plenty of cover\n- Offer live or frozen foods like bloodworms and brine shrimp, then mix in prepared foods\n- Acclimate slowly, especially if your water differs a lot from the seller's", "heading": "Helping them settle in"}, {"text": "Ask sellers where fish came from and how long they have been in store. Fish that have been in store for a week or two and are eating are usually a safer buy than ones fresh off the plane.", "heading": "Buying responsibly"}]$g$::jsonb where slug = $g$wild-caught$g$;
update public.glossary_terms set sections = $g$[{"text": "This works for most hardy fish when your water is similar to the store's.\n\n- Turn off the tank light to lower stress.\n- Float the sealed bag in the tank for about 15 minutes so the temperature evens out.\n- Open the bag and add about half a cup of tank water every 5 minutes for 20 to 30 minutes.\n- Net the fish into the tank and throw the bag water away instead of pouring it in.", "heading": "The float method"}, {"text": "Use this for shrimp, sensitive fish, wild-caught fish or when your water is very different from the seller's. After floating, pour the fish and their water into a clean bucket. Run airline tubing from the tank to the bucket, tie a loose knot or use a valve so it drips about 2 to 4 drops per second, and let the water volume double, then double again. That usually takes 45 to 90 minutes for fish and 1 to 2 hours for shrimp.", "heading": "The drip method"}, {"text": "Fish that spent many hours in a bag build up ammonia, but the bag water's pH drops from their breath, which keeps that ammonia in a less toxic form. Once you open the bag, the pH rises and the ammonia becomes more harmful. For fish shipped overnight, many keepers float to match temperature, then move them fairly quickly into tank water rather than doing a long acclimation in old bag water.", "heading": "The ammonia trap with shipped fish"}, {"text": "Keep the lights off for a few hours and skip feeding until the next day. Watch for hiding, clamped fins or rapid breathing. Ideally, every new fish goes into a quarantine tank for {{fact.quarantine_weeks}} weeks first, and you acclimate them into that tank the same way.", "heading": "After release"}]$g$::jsonb where slug = $g$acclimation$g$;
update public.glossary_terms set sections = $g$[{"text": "- Red or reddish brown threads hanging from the vent, often only when the fish is resting or after lights out\n- Thin body or sunken belly even though the fish eats well\n- Swollen or red vent area\n- Lethargy, hanging near the bottom and slow deaths over weeks\n\nCheck fish with a flashlight about an hour after lights out. The worms extend out of the vent more when the fish is still, so you can spot light infections you would miss during the day.", "heading": "Signs to watch for"}, {"text": "Camallanus usually arrives with new fish, especially cheap livebearers from crowded farms. Some species pass directly from fish to fish when tankmates eat worm larvae released into the water, and copepods and other small crustaceans can carry them too. That means one infected fish can seed the entire tank within a few weeks.", "heading": "How fish catch them"}, {"text": "The standard treatments are levamisole, fenbendazole and flubendazole. Levamisole works by paralyzing the worms so the fish passes them, and it is usually gentler on tanks with invertebrates. Fenbendazole and flubendazole kill snails and can harm shrimp, so move invertebrates out first or treat in a hospital tank. Praziquantel, a common dewormer, does not work against camallanus.\n\nDose the whole tank, not just the fish showing worms. Do a large water change and vacuum the gravel 24 to 48 hours after dosing to remove expelled worms and eggs. Repeat the full treatment about 2 to 3 weeks later, since the first round does not kill larvae that are still developing.", "heading": "How to treat camallanus"}, {"text": "Quarantine every new fish for at least {{fact.quarantine_min}} weeks and watch for worms at night. Many breeders deworm all new livebearers in quarantine as a routine step. Avoid moving nets, plants or decor between tanks while you are treating, and rinse anything you share in hot water.", "heading": "Preventing a repeat"}]$g$::jsonb where slug = $g$camallanus-worms$g$;
update public.glossary_terms set sections = $g$[{"text": "- White, green or reddish threads about a quarter to half an inch long sticking out of the skin, often near fins\n- A red, swollen sore at the base of each thread\n- Twin egg sacs at the end of mature females, giving a forked look\n- Fish rubbing against decor, clamped fins, lethargy or loss of appetite", "heading": "Signs to watch for"}, {"text": "Anchor worms, from the genus Lernaea, are copepods. They come in on new fish, with water from bags, live foods from ponds or plants from outdoor setups. Only adult females attach permanently. The young larvae swim free in the water for days to weeks before finding a host, which is why the whole tank needs treating, not just the visible parasites. Warm water above about 77°F speeds up their life cycle.", "heading": "How fish get them"}, {"text": "- Remove visible worms with tweezers, gripping close to the skin and pulling slowly so the head comes out. Swab the wound with an antiseptic. Get help the first time if you can, since it is stressful for the fish.\n- Treat the whole tank with an antiparasitic that targets crustaceans, such as one containing diflubenzuron, repeating as the label directs to catch new larvae.\n- These medications kill shrimp, crayfish and other crustaceans, so move invertebrates out first. Snails are generally safer but check the label.\n- Watch the wounds for infection, and use an antibacterial treatment if they turn white or fuzzy.", "heading": "Treatment"}, {"text": "Quarantine all new fish for at least {{fact.quarantine_min}} weeks and inspect them closely. Avoid adding pond water or wild-collected live food to indoor tanks.", "heading": "Prevention"}]$g$::jsonb where slug = $g$anchor-worms$g$;
update public.glossary_terms set sections = $g$[{"text": "A healthy fish spreads its dorsal and tail fins as it swims. A fish with clamped fins keeps the dorsal fin flat and the tail folded like a closed fan. It often hovers in one place, rocks side to side or hides. One clamped fish may have a personal problem, but several clamped fish usually point to the water.", "heading": "What it looks like"}, {"text": "- Ammonia or nitrite above 0 ppm, or nitrate creeping above {{fact.nitrate_watch}} ppm\n- A temperature drop or swing, such as a failed heater\n- pH crashes or a sudden change in hardness\n- Bullying or fin nipping from tankmates\n- Parasites such as ich, velvet or skin flukes\n- Bacterial infections like fin rot or columnaris\n- New arrivals still adjusting after shipping", "heading": "Common causes"}, {"text": "Test ammonia, nitrite, nitrate, pH and temperature. If anything is off, do a 25 to 50 percent water change with dechlorinated water matched to the tank temperature, and repeat daily until readings are safe. Check that the heater and filter are running.\n\nThen watch closely for a day or two. Look for white spots, a gold dusty sheen, frayed fins, rapid gill movement or scratching against decor. If you see a clear sign of disease, treat for that specific problem. Avoid dosing general medications on a guess, since that adds stress without fixing the cause.", "heading": "What to do first"}, {"text": "Keep up regular weekly water changes, use a reliable heater sized for your tank, and research tankmates so peaceful fish are not housed with nippers. Quarantining new fish keeps parasites from reaching your display.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$clamped-fins$g$;
update public.glossary_terms set sections = $g$[{"text": "- White or grayish patches, often a band across the back called saddleback\n- Fuzzy or cottony growth around the mouth, sometimes called cotton wool or mouth fungus\n- Frayed, eroded fins with a white edge\n- Pale or brown, damaged gills and rapid breathing\n- Lethargy and loss of appetite\n\nThe fast-moving form can kill in under 24 hours with few visible signs, while a slower form develops over several days.", "heading": "Signs to watch for"}, {"text": "True fungus looks like long, fluffy cotton strands and usually grows on an existing wound or dead tissue. Columnaris patches are flatter, more matted, and spread across healthy skin quickly. If a fuzzy patch shows up on a fish with no injury and spreads fast, assume columnaris. Antifungal medications will not stop it.", "heading": "Columnaris vs fungus"}, {"text": "- Move sick fish to a hospital tank if you can.\n- Lower the temperature to around 74 to 76°F if the species allows; the bacteria thrive at 80°F and above.\n- Use an antibacterial that targets gram-negative bacteria, such as kanamycin or nitrofurazone, alone or combined, and follow the label.\n- Add strong aeration, since gill damage makes breathing hard.\n- Aquarium salt can help in some cases, but avoid it with scaleless fish, sensitive plants and invertebrates.\n- Remove carbon from the filter during treatment.", "heading": "How to treat columnaris"}, {"text": "The bacteria live in most aquariums and only cause trouble when fish are stressed by poor water, crowding, shipping or injuries. Livebearers like mollies and guppies are common victims. Keep water clean, avoid overcrowding, and quarantine new fish for at least {{fact.quarantine_min}} weeks so outbreaks start away from your display.", "heading": "Causes and prevention"}]$g$::jsonb where slug = $g$columnaris$g$;
update public.glossary_terms set sections = $g$[{"text": "- Small pits or pinholes on the head, often near the eyes and nostrils\n- Pits that enlarge and join into open sores\n- Erosion along the lateral line on the sides of the body\n- White, stringy feces or weight loss in some cases\n- Pale or faded color", "heading": "Signs to watch for"}, {"text": "There is no single proven cause, and the hobby still debates it. The most common suspects are:\n\n- High nitrate and infrequent water changes\n- A diet low in vitamins and variety, especially vitamin C\n- Internal parasites such as Hexamita\n- Activated carbon, which some studies have linked to lateral line erosion in marine fish\n- Chronic stress from small tanks or aggressive tankmates", "heading": "What causes it"}, {"text": "- Increase water changes to 30 to 50 percent weekly or more and keep nitrate under {{fact.nitrate_ok}} ppm.\n- Remove activated carbon from the filter.\n- Improve the diet with a quality pellet, vegetable matter and a vitamin supplement.\n- If the fish has white feces or weight loss, treat for Hexamita with metronidazole, ideally in medicated food.\n- Treat any sores that look infected with an antibacterial.\n\nMild pits often fill in within a few weeks to months. Deep, advanced lesions may leave permanent scarring even after healing.", "heading": "How to treat it"}, {"text": "Give big cichlids enough room, typically {{oscar.tank}} gallons or more for an adult oscar, with strong filtration and frequent water changes. Feed a varied, fresh diet and avoid relying on one cheap staple. Watch your fish's head closely during regular feeding so you catch pits early.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$hole-in-the-head$g$;
update public.glossary_terms set sections = $g$[{"text": "- Weight loss or a sunken belly despite a good appetite\n- White, stringy or clear feces\n- Red threads from the vent, a sign of camallanus worms\n- Bloating in some cases\n- Lethargy, darkened color and hiding\n- Loss of appetite in advanced cases", "heading": "Signs to watch for"}, {"text": "- Roundworms (nematodes) such as camallanus and capillaria: treated with levamisole, fenbendazole or flubendazole\n- Tapeworms and flukes: treated with praziquantel\n- Protozoa such as Hexamita: treated with metronidazole\n\nIf you are not sure which one you have, a combination of praziquantel plus a nematode treatment covers most worms. A vet or experienced keeper with a microscope can examine a fecal sample for a firm answer.", "heading": "Common types and treatments"}, {"text": "Medicated food is the most effective option because the drug goes straight to the gut. Use it while fish are still eating, feeding for the length the label suggests. For fish that stopped eating, dose the water in a hospital tank.\n\nMost dewormers need a second round 2 to 3 weeks later to kill parasites that hatch after the first dose. Vacuum the gravel and do a water change after each round. Fenbendazole and flubendazole kill snails and can harm shrimp, so treat fish separately if you keep invertebrates.", "heading": "How to treat"}, {"text": "Quarantine new fish for {{fact.quarantine_weeks}} weeks and watch their feces and body shape. Many keepers deworm wild-caught fish and livebearers routinely during quarantine. Be careful with live foods from ponds or streams, which can carry parasite larvae.", "heading": "Preventing them"}]$g$::jsonb where slug = $g$internal-parasite$g$;
update public.glossary_terms set sections = $g$[{"text": "- A 10 to 20 gallon tank, sized for the fish you buy\n- A seeded sponge filter kept running in your main tank so it is ready\n- A heater, thermometer and lid\n- A bare bottom and a few hiding places like PVC pipe or a pot\n- Separate nets, siphon and buckets that never touch the display tank\n\nThe same tank works as a hospital tank when a fish gets sick.", "heading": "Setting up a quarantine tank"}, {"text": "Most keepers quarantine for {{fact.quarantine_weeks}} weeks. Two weeks catches fast problems like ich and columnaris, but internal parasites and slow infections can take longer to show. Watch fish daily for spots, clamped fins, odd feces, weight loss and scratching. If you treat a problem, restart the clock after the last symptoms clear.", "heading": "How long to quarantine"}, {"text": "Keepers disagree on preventive treatment. Some treat every new fish with a dewormer and a parasite medication during quarantine, which catches problems that do not show obvious signs. Others prefer to observe and treat only when needed, to avoid stressing fish with drugs they may not need. Either way, quarantine works best when you know your fish's source and watch closely. Deworming is common for livebearers and wild-caught fish.", "heading": "To medicate or just watch"}, {"text": "Plants can carry snails, algae, pest eggs and even fish parasites. Rinse them, remove pots and wool, and hold them in a separate container of water for a couple of weeks if you want to be sure. Shrimp and snails can also carry parasites and should be quarantined in their own tank, since many fish medications are toxic to them.", "heading": "Quarantining plants and invertebrates"}]$g$::jsonb where slug = $g$quarantine$g$;
update public.glossary_terms set sections = $g$[{"text": "- Faded or darkened color\n- Hiding more than usual or pacing the glass\n- Clamped fins\n- Loss of appetite\n- Rapid breathing or hanging at the surface\n- Scratching against decor\n- Stress stripes or blotches in species like bettas and cichlids", "heading": "Signs of a stressed fish"}, {"text": "- Ammonia, nitrite or high nitrate\n- Temperature or pH swings, including from large untreated water changes\n- Aggressive or fin-nipping tankmates\n- A tank that is too small, overcrowded or bare, with nowhere to hide\n- Keeping schooling fish alone or in groups under 6\n- Shipping, netting and moving between tanks\n- Loud vibration, constant tapping, or lights left on around the clock\n\nShort-term stress from a move usually passes within days. Ongoing stress from a poor setup is the bigger danger, because it wears fish down slowly.", "heading": "Common causes"}, {"text": "Start by testing your water and fixing anything off. Keep the temperature steady with a properly sized heater, and do regular water changes of {{fact.water_change}} percent with dechlorinated, temperature-matched water. Research every species before you buy: right tank size, compatible tankmates, preferred water and group size. Add plants, rocks or wood so fish can break line of sight. Give a regular light schedule of about {{fact.light_hours}} hours with darkness at night.", "heading": "How to reduce it"}, {"text": "Dim the lights for the first day, acclimate slowly, and feed lightly. Some fish hide for a few days after arrival, which is normal. Rearranging decor slightly when adding fish to a tank with territorial species can reduce aggression toward newcomers.", "heading": "Helping new fish settle"}]$g$::jsonb where slug = $g$stress$g$;
update public.glossary_terms set sections = $g$[{"text": "Measure the inside length, width and height in inches, multiply them together and divide by 231. For example, a tank 30 by 12 by 16 inches holds 5,760 cubic inches, or about 25 gallons.\n\nThe real water volume is lower than the rated size. Substrate, rock, wood and the gap below the rim usually take up 10 to 20 percent. Use the actual water volume when dosing medications, and the rated size when choosing equipment.", "heading": "Calculating tank volume"}, {"text": "- 5 to 10 gallons: nano tanks for a betta, shrimp or a few tiny fish\n- 20 gallons: long or high, a popular starter size\n- 29 and 40 gallons: room for a real community\n- 55 and 75 gallons: 4 foot tanks for larger schools and cichlids", "heading": "Common tank sizes"}, {"text": "The old one inch of fish per gallon rule is a rough guess at best. It ignores body mass, activity and waste, and fails for big fish. Think instead about the adult size of the fish, swimming space and filtration. For heaters, about {{fact.heater_watts}} watts per gallon is a common starting point. Filters are often sized to turn over the tank volume 4 to 6 times an hour.", "heading": "Rules of thumb"}, {"text": "A UK (imperial) gallon is about 4.5 liters, larger than a US gallon. If a guide or medication label is from outside the US, double-check which one it uses.", "heading": "Metric and imperial gallons"}]$g$::jsonb where slug = $g$gallon$g$;
update public.glossary_terms set faq = $g$[{"a": "Local fish store, usually an independent aquarium shop.", "q": "What does LFS stand for in fishkeeping?"}, {"a": "A good LFS usually has healthier stock and better advice, but quality varies at both. Judge the specific store by its tanks.", "q": "Is it better to buy fish from an LFS or a chain store?"}, {"a": "Yes. Quarantine any new fish for {{fact.quarantine_weeks}} weeks if you can, no matter where you bought it.", "q": "Should I quarantine fish from a local fish store?"}]$g$::jsonb where slug = $g$lfs$g$;
update public.glossary_terms set sections = $g$[{"text": "- Ammonia or nitrite readings in a tank that has been cycled\n- Nitrate climbing past {{fact.nitrate_watch}} ppm within a week\n- Fish gasping at the surface, especially in the morning\n- Constant aggression, torn fins or fish hiding all the time\n- Frequent disease outbreaks and cloudy water\n- Algae that won't stay under control", "heading": "Signs a tank is overstocked"}, {"text": "Most overstocking comes from buying fish at juvenile size without checking adult size, adding schooling fish in big groups to small tanks, or slowly accumulating extra fish one at a time. Some species, like common plecos, goldfish and oscars, grow far larger and messier than people expect. Space and territory also count: a tank can have clean water and still be overcrowded for territorial fish.", "heading": "Why it happens"}, {"text": "Rehome some fish through a local fish store, club or hobbyist. Until then, increase water changes, for example 30 to 50 percent twice a week, and test often. Add filtration rated well above your tank size, increase surface agitation for oxygen, and feed lightly. Upgrading to a larger tank is the most lasting fix if you want to keep everyone.", "heading": "How to fix it"}, {"text": "Check each species' adult size, minimum tank size, swimming level and temperament before buying. Use the inch-per-gallon rule only as a loose sanity check for small, slim fish; it fails badly for large or bulky species. Leave room for growth.", "heading": "Planning to avoid it"}]$g$::jsonb where slug = $g$overstocking$g$;
update public.glossary_terms set sections = $g$[{"text": "- Dechlorinated tap water works for most community tanks\n- In soft-water or shrimp tanks, pure RO or distilled water avoids slowly building hardness, since minerals did not evaporate\n- Never add salt in a brackish or salted tank during a top-off; salt stays behind, so adding more raises salinity\n- Match the temperature roughly when adding more than a few percent of the tank volume", "heading": "Choosing the right water"}, {"text": "Mark the normal water line with a small piece of tape. Pour new water slowly into a cup or onto a decoration so you don't disturb substrate. Treat tap water with dechlorinator before or as you add it. Top off every few days in fast-evaporating tanks so the level never drops much.", "heading": "How to do it"}, {"text": "An auto top-off uses a float or optical sensor and a small pump to refill evaporated water from a reservoir. It keeps levels and parameters very stable, especially on open-top tanks and sumps. Use one with a backup sensor or limited reservoir so a stuck switch can't flood the tank. Check it regularly.", "heading": "Auto top-off systems"}, {"text": "Topping off only replaces water; it removes nothing. Nitrate, dissolved waste and minerals keep building unless you also do partial water changes, typically {{fact.water_change}} percent weekly. Skipping changes and only topping off is a common path to old-tank syndrome. Test nitrate before a change to see how fast it builds.", "heading": "Top-off is not a water change"}]$g$::jsonb where slug = $g$top-off$g$;
update public.glossary_terms set sections = $g$[{"text": "- Green spot: hard green dots on glass and slow leaves. Usually long light periods or low phosphate.\n- Green hair and thread: long strands. Excess light with unbalanced nutrients.\n- Black beard: dark tufts on wood and leaf edges. Linked to unstable CO2 and poor flow.\n- Green water: free-floating algae that turns the tank pea green.\n- Brown diatoms: dusty brown film, common in new tanks.\n- Blue-green slime: actually cyanobacteria, not true algae.", "heading": "Common types"}, {"text": "Too much light is the most common cause, either a light left on more than 8 hours a day or direct sunlight. Excess nutrients from overfeeding and skipped water changes come next. In planted tanks, giving strong light without enough fertilizer or CO2 lets algae outcompete plants.", "heading": "What causes outbreaks"}, {"text": "Set the light on a timer for {{fact.light_hours}} hours. Feed less and change 25 to 50 percent of the water weekly. Add more fast-growing plants or floating plants to compete for nutrients.\n\nRemove what you can by hand, then let algae eaters help: nerite snails, otocinclus, amano shrimp and bristlenose plecos each target different types. Chemical algaecides are a last resort, and many harm plants and invertebrates.", "heading": "How to control it"}, {"text": "Changing many things at once makes it hard to tell what worked. Adding algae eaters without fixing the cause rarely solves anything. Give changes 2 to 3 weeks to show results.", "heading": "Mistakes to avoid"}]$g$::jsonb where slug = $g$algae$g$;
update public.glossary_terms set sections = $g$[{"text": "Green spot algae looks like tiny, flat, bright green circles about the size of a pinhead that gradually merge into patches. It feels hard and crusty and won't wipe off with a soft sponge. It favors the front glass, where light is strongest, and old leaves on slow plants such as Anubias, Java fern and Bucephalandra.", "heading": "How to recognize it"}, {"text": "- Low phosphate, often below about 0.5 ppm, in tanks with good light\n- A long photoperiod or very strong light for the plants you keep\n- Unstable or low CO2 in a high-tech tank\n- Slow plants with old leaves that stay in place for months\n\nThe phosphate link is widely reported but not universal, so treat it as a strong lead rather than a guarantee.", "heading": "What causes it"}, {"text": "Scrape glass with a razor blade or plastic card scraper; use plastic on acrylic so you don't scratch it. On leaves, it is usually easier to trim the worst ones. Nerite snails eat it slowly and are one of the few grazers that make a dent. Most algae-eating fish and shrimp ignore it.", "heading": "How to remove it"}, {"text": "Test phosphate and, if it is very low, dose a bit more with your fertilizer routine or a phosphate supplement to reach roughly 1 to 2 ppm in a planted tank. Cut lighting to {{fact.light_hours}} hours or lower its intensity, and keep CO2 steady if you inject it. Light regrowth on the glass every week or two is normal in a bright tank and just part of maintenance.", "heading": "Stopping it coming back"}]$g$::jsonb where slug = $g$green-spot-algae$g$;
update public.glossary_terms set sections = $g$[{"text": "- Pressurized CO2 with a regulator, solenoid, bubble counter and diffuser or reactor\n- A drop checker to confirm CO2 levels, usually aiming for lime green, roughly {{fact.co2}} ppm\n- A strong planted-tank light on a timer\n- A nutrient-rich active substrate or root tabs\n- A dosing routine for macro and micro nutrients\n- Good flow so CO2 and nutrients reach every plant", "heading": "What you need"}, {"text": "Turn CO2 on 1 to 2 hours before the lights and off about an hour before they go off. Keep a 6 to 8 hour photoperiod, and dose fertilizer several times a week or daily. Change 30 to 50 percent of the water weekly to reset nutrient levels. Expect to trim stems every week or two, since fast growth is the point.", "heading": "Running it day to day"}, {"text": "Too much CO2 suffocates fish. Signs include fish gasping at the surface or hanging near the outflow in the morning. Raise CO2 slowly over several days, watch your fish after each change, and keep good surface movement so oxygen stays high. A solenoid on a timer prevents CO2 running all night when plants aren't using it.", "heading": "Fish and CO2 safety"}, {"text": "The biggest mistake is turning the light up before CO2 and fertilizer are dialed in. Others include fluctuating CO2, too little flow, and letting dead leaves rot in place. When algae shows up, fix the balance first, lowering light if needed, rather than reaching for chemicals.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$high-tech-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "- Java fern, Anubias and Bucephalandra tied to wood or rock\n- Cryptocoryne and Amazon swords in the substrate, with root tabs\n- Java moss and other mosses\n- Vallisneria and dwarf sagittaria for backgrounds\n- Floating plants like salvinia and frogbit\n- Easy stems like hornwort, water wisteria and Ludwigia repens", "heading": "Good plants for low tech"}, {"text": "Use plain gravel or sand with root tabs, or an aquarium soil for a nutrient boost. Choose low to medium light and run it for {{fact.light_hours}} hours on a timer. Plant heavily from the start, since a full tank uses nutrients that would otherwise feed algae. Gentle surface movement keeps CO2 from the air available to plants.", "heading": "Setting one up"}, {"text": "Change {{fact.water_change}} percent of the water every week or two, trim dead leaves, and dose a light all-in-one fertilizer once a week if plants look pale. Many keepers add liquid carbon as a mild boost, but it can melt Vallisneria and some mosses. Growth is slow, so expect months rather than weeks for a tank to fill in. Pull out any dying leaves before they rot, and thin floating plants so they don't shade everything below.", "heading": "Maintenance"}, {"text": "The biggest mistake is a light that's too strong, which grows algae faster than the plants can compete. Others include choosing high-light carpet plants that won't survive without CO2, and burying rhizomes of Anubias and Java fern. Start simple and add plants as you learn what thrives.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$low-tech-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "Every day, fish waste becomes nitrate and the nitrogen cycle produces acids. KH buffers those acids, but if water changes are skipped, the buffer slowly runs out and pH falls, sometimes into the 5s. Evaporation and top-offs concentrate dissolved solids, and debris builds up in the gravel and filter.\n\nBecause it happens over months, the existing fish adjust. The water still looks clear, so owners assume all is well.", "heading": "How it develops"}, {"text": "- New fish die within days while old fish seem fine\n- Nitrate readings of {{fact.nitrate_high}} ppm or more\n- pH well below your tap water, and KH near zero\n- Thick mulm in the substrate, slow plant growth and stubborn algae\n- Fish that are sluggish, faded or breed rarely", "heading": "Signs to watch for"}, {"text": "The goal is to bring the tank back toward your tap water slowly. Start with 10 to 15 percent water changes every two or three days, vacuuming a small section of gravel each time. Test pH before and after; avoid moving it more than about 0.3 to 0.5 in a day.\n\nOver two to four weeks, increase to 25 percent changes as nitrate drops and pH rises. Clean the filter in old tank water, not all at once. Only add new fish after parameters match your tap water and stay stable.", "heading": "How to fix it safely"}, {"text": "Weekly water changes of {{fact.water_change}} percent prevent old tank syndrome almost entirely. Testing nitrate, pH and KH once a month will catch slow drift long before it becomes a problem.", "heading": "Prevention"}]$g$::jsonb where slug = $g$old-tank-syndrome$g$;
update public.glossary_terms set sections = $g$[{"text": "- Ammonia and nitrite: should always read 0 ppm in a cycled tank\n- Nitrate: under {{fact.nitrate_ok}} ppm, and change water before it reaches {{fact.nitrate_watch}} ppm\n- pH: most community fish handle 6.5 to 7.8\n- Temperature: most tropical fish {{fact.tropical_temp}} F\n- GH: about 4 to 12 dGH for most community fish\n- KH: 3 dKH or more helps keep pH steady\n\nThese are general guides. Check the needs of each species you keep.", "heading": "The core parameters"}, {"text": "Fish adapt to a wide range, especially captive-bred ones, but they handle sudden changes poorly. A steady pH of 7.6 is better than chasing 6.8 with chemicals and causing daily swings. Make changes slowly, keep water changes regular and consistent, and match temperature and conditioner every time.\n\nWhen you do need to change a parameter, move it a little at a time over days or weeks, and retest after each step.", "heading": "Stability beats perfection"}, {"text": "Start by testing your tap water. If it's hard and alkaline, livebearers, rainbowfish and many cichlids will be easy. If it's soft and acidic, tetras, rasboras and many catfish suit it. Choosing fish that fit your water is far easier than reshaping your water to fit the fish.", "heading": "Choosing compatible fish"}, {"text": "Write down test results with dates, along with water changes, feeding and new additions. A log shows trends like slowly rising nitrate or falling KH before fish suffer, and it makes it much easier to get useful help when something does go wrong.", "heading": "Keeping a log"}]$g$::jsonb, faq = $g$[{"a": "For most community tanks: 0 ammonia, 0 nitrite, nitrate under {{fact.nitrate_ok}} ppm (never above 40), pH 6.5 to 7.8 and temperature 74 to 80 F.", "q": "What are the ideal water parameters for a freshwater aquarium?"}, {"a": "Usually not. Most fish adapt to a stable pH, and chemical adjustments often cause dangerous swings.", "q": "Should I adjust my pH to match my fish?"}, {"a": "Do regular water changes, avoid overfeeding and overstocking, and keep KH high enough to buffer pH.", "q": "How do I keep water parameters stable?"}]$g$::jsonb where slug = $g$water-parameters$g$;
update public.glossary_terms set sections = $g$[{"text": "- Fancy goldfish: about 65 to 72 F, but they grow large and need roughly 30 gallons or more for a pair\n- Common and comet goldfish: better suited to ponds than most tanks\n- White cloud mountain minnows: {{white-cloud-mountain-minnow.temp}} F, great for 10 to 20 gallon tanks\n- Hillstream loaches: cool, fast, well-oxygenated water\n- Some danios, rice fish and dojo loaches tolerate cooler rooms\n\nPeppered corydoras and cherry shrimp also handle the low 70s.", "heading": "Fish that suit cool water"}, {"text": "Cycle the tank before adding fish, just like a tropical tank. Use a filter rated for more than the tank's volume, since goldfish produce lots of waste. Cooler water holds more oxygen, but surface movement still matters. Choose a spot away from windows and heating vents.\n\nGoldfish dig and uproot plants, so hardy choices like anubias, java fern and hornwort hold up best. Plan on weekly water changes of 25 to 50 percent for goldfish tanks, since their waste output is high even at cool temperatures.", "heading": "Setting one up"}, {"text": "If your room stays steady, no. But if the house drops below about 60 F in winter or swings a lot between day and night, a small heater set to the low end of your fish's range keeps things stable. Big temperature swings stress fish more than a slightly low steady temperature.", "heading": "Do you really not need a heater?"}, {"text": "- Keeping goldfish in bowls or small tanks\n- Mixing goldfish with tropical fish that need 78 F\n- Skipping filtration because the tank is unheated\n- Assuming cool water means less maintenance", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$cold-water-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "Freshwater fish are generally hardier, cheaper and easier to find than marine fish. Equipment is simpler, with no need for salt mixing, protein skimmers or salinity checks. Mistakes are more forgiving, and dechlorinated tap water works for most species.", "heading": "Why start with freshwater"}, {"text": "- A tank of 20 gallons or more if possible, since bigger tanks are more stable\n- A filter rated for your tank size\n- A heater for tropical fish, set around {{fact.heater_set}} F\n- A thermometer, light and lid\n- Substrate, decor or plants\n- Water conditioner and a liquid test kit\n- A gravel vacuum and bucket used only for the aquarium", "heading": "Basic equipment"}, {"text": "Community tanks with peaceful mixed species are the most popular. Other options include planted tanks, species-only tanks, cold water goldfish tanks, shrimp tanks, African cichlid tanks with hard alkaline water, and blackwater tanks with soft, tea-colored water. Each has different water and stocking needs.", "heading": "Types of freshwater setups"}, {"text": "Set up the tank, add conditioned water and run the filter. Cycle it for about {{fact.cycle_weeks}} weeks so beneficial bacteria can handle waste, testing ammonia and nitrite along the way. Then add a few hardy fish, feed lightly and do weekly water changes of {{fact.water_change}} percent.\n\nResist the urge to fill the tank all at once. Add a few fish every couple of weeks, test the water after each addition, and only add more once ammonia and nitrite stay at zero.", "heading": "First steps"}]$g$::jsonb where slug = $g$freshwater$g$;
update public.glossary_terms set sections = $g$[{"text": "- A single betta in {{betta.tank}} gallons or more\n- Neocaridina shrimp colonies, starting in about 5 gallons\n- Small schooling fish like chili rasboras, ember tetras or celestial pearl danios in {{celestial-pearl-danio.tank}} gallons\n- Nerite or ramshorn snails\n- Pygmy corydoras in 10 gallons or more\n\nAvoid goldfish, bettas in tiny bowls, fast swimmers like zebra danios, and fish that grow over about 2 inches.", "heading": "What can live in a nano"}, {"text": "Small volumes heat and cool quickly, so use an adjustable heater sized for the tank and keep it away from windows. Ammonia from one dead snail or overfeeding can spike in hours. Feed sparingly, remove leftovers, and do small weekly water changes of 15 to 25 percent. Top off evaporation often, since it concentrates minerals faster in small tanks.\n\nA small battery-powered air pump and a spare heater are cheap insurance, since a nano can overheat or chill within hours if equipment fails. Test ammonia and nitrite whenever something seems off rather than waiting for a weekly check.", "heading": "Keeping it stable"}, {"text": "Choose a gentle filter like a sponge filter or small hang-on-back with adjustable flow, especially for shrimp and bettas. Cover the intake with a sponge so shrimp aren't sucked in. Live plants help a lot, using waste and adding stability.", "heading": "Equipment tips"}, {"text": "- Overstocking because fish are small in the store\n- Skipping the cycle\n- Big water changes with water that doesn't match temperature\n- Using a heater that's too strong for the volume", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$nano-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "Low-tech tanks use modest lighting, no added CO2, and hardy plants. They grow slowly, need little trimming and are very forgiving.\n\nHigh-tech tanks use strong lighting, pressurized CO2 and regular fertilizer dosing. They grow fast and allow demanding carpets and red stem plants, but light, CO2 and nutrients must stay balanced or algae takes over.", "heading": "Low-tech vs high-tech"}, {"text": "- Java fern and anubias: attach to wood or rock, don't bury the rhizome\n- Cryptocorynes: rooted plants that like root tabs\n- Java moss and other mosses\n- Amazon sword and vallisneria\n- Hornwort and floating plants like frogbit, which soak up nitrate fast", "heading": "Easy plants to start with"}, {"text": "Root feeders grow best in nutrient-rich aquasoil or plain gravel with root tabs. Rhizome plants and floaters feed from the water and need liquid fertilizer instead. Run lights about {{fact.light_hours}} hours a day on a timer; longer periods mostly feed algae. Dose a comprehensive liquid fertilizer if plants show yellowing or holes. Many fertilizers are shrimp-safe, but check copper content first.\n\nStart with a lighter stocking of fish while plants settle in, and add fast-growing stem or floating plants early. They take up nutrients quickly and help keep algae down while slower plants establish.", "heading": "Substrate, light and fertilizer"}, {"text": "- Melting: new plants, especially crypts, often shed leaves while adjusting; trim and wait\n- Algae: usually too much light for the CO2 and nutrients available\n- Yellow leaves: often nitrogen, potassium or iron deficiency\n- Rotting rhizomes from burying java fern or anubias", "heading": "Common problems"}]$g$::jsonb where slug = $g$planted-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "- Glass stick-in: floats or sticks to the glass inside the tank. Cheap and fairly accurate, but can break.\n- Stick-on strip: a liquid crystal strip on the outside of the glass. Easy to read, but it is affected by room temperature and can be off by a few degrees.\n- Digital with probe: a probe sits in the water and the display mounts outside. Usually the most accurate and easiest to read.\n- Controllers and smart monitors: digital units that can cut power to a heater or send alerts if the temperature drifts.", "heading": "Types of thermometers"}, {"text": "Place it on the opposite side of the tank from the heater, about midway down, so you read the overall water temperature rather than the warm spot next to the heater. In tanks over about 75 gallons, two thermometers at each end show whether heat is spreading evenly.", "heading": "Where to put it"}, {"text": "Compare it with a second thermometer, or test it in a glass of ice water, which should read 32°F. If two thermometers disagree by more than a degree or two, trust the digital probe and replace the odd one out.", "heading": "Checking accuracy"}, {"text": "Most tropical community fish do well at {{fact.tropical_temp}}°F. Goldfish and many coldwater species prefer the mid 60s to low 70s. Discus and some wild-type fish like {{discus.temp}}°F. What matters most is stability; swings of more than 2 to 3°F in a day stress fish.", "heading": "What the numbers mean"}]$g$::jsonb, faq = $g$[{"a": "Yes. Heaters fail and their dials are often inaccurate, so a thermometer is the only way to know the real temperature.", "q": "Do I really need an aquarium thermometer?"}, {"a": "They are fine for a rough reading but can be off by a few degrees because room air affects the glass. A digital probe or glass thermometer inside the water is more reliable.", "q": "Are stick-on aquarium thermometers accurate?"}, {"a": "For most tropical fish, {{fact.tropical_temp}}°F. Check the needs of your specific species, since goldfish, discus and hillstream fish all differ.", "q": "What temperature should my aquarium be?"}]$g$::jsonb where slug = $g$thermometer$g$;
update public.glossary_terms set sections = $g$[{"text": "- Most plecos and many other suckermouth catfish\n- Kuhli loaches and many other loaches\n- Pictus catfish and upside-down catfish\n- Black ghost knifefish and other knifefish\n- Many shrimp, snails and crayfish become more active after dark\n\nSome species, like corydoras, are crepuscular, most active at dawn and dusk.", "heading": "Common nocturnal fish"}, {"text": "Day-active tankmates eat most food before nocturnal fish come out. Drop sinking pellets, wafers or frozen food in shortly after lights go out, or 15 to 30 minutes before. Target caves and hiding spots, and check that bellies look rounded rather than sunken. Remove uneaten food the next morning if it is still there.", "heading": "Feeding them"}, {"text": "Give each nocturnal fish a cave, driftwood hollow or tube to rest in during the day. A tank with plenty of cover, dim areas under floating plants and fewer hyperactive tankmates helps them venture out sooner. Many become more visible over time as they settle in.", "heading": "Helping them feel secure"}, {"text": "A dim blue or red light lets you watch without fully disrupting their night, since many fish see red light poorly. Keep it low and avoid running bright lights around the clock. Most tanks do well with {{fact.light_hours}} hours of light and a real dark period, which both day and night species need. Avoid tapping the glass or switching bright room lights on suddenly at night, since startled nocturnal fish can crash into decor.", "heading": "Watching them at night"}]$g$::jsonb, faq = $g$[{"a": "Yes. Fish need a regular dark period for rest and normal behavior. Most tanks do well with lights on about {{fact.light_hours}} hours a day, so they get a long, regular dark period.", "q": "Do fish need darkness at night?"}, {"a": "Most plecos are nocturnal and hide in caves or under wood during the day. Look for them after lights out.", "q": "Why do I never see my pleco?"}, {"a": "A very dim light for an hour or two is fine for viewing, but leaving it on all night can disturb sleep patterns. Most keepers put it on a timer.", "q": "Is a moonlight on all night OK for fish?"}]$g$::jsonb where slug = $g$nocturnal$g$;
update public.glossary_terms set sections = $g$[{"text": "- Flat, round, greenish or clear bumps about 1/8 to 3/8 inch across that can move around the body\n- Two dark eye spots visible on the parasite up close\n- Red, inflamed spots where they have fed\n- Flashing, rubbing against surfaces and jumping\n- Clamped fins, rapid breathing and lethargy", "heading": "Signs to watch for"}, {"text": "Argulus arrives on new fish, especially goldfish and koi from outdoor ponds, and sometimes on plants or in water from wild sources. Adults can leave a fish and swim freely for several days, longer in cool water. Females lay rows of eggs on hard surfaces like glass, rocks and decor, and those eggs hatch over several weeks, which is why infestations come back if you only remove the visible adults.", "heading": "How they get in"}, {"text": "- Remove visible lice with blunt tweezers. Hold the fish gently in a wet net and pull straight off; dab the spot with a disinfectant safe for fish wounds.\n- Treat the whole tank or pond with an antiparasitic product labeled for crustacean parasites like anchor worms and fish lice.\n- Repeat according to the label, often several doses spread over 3 to 4 weeks or more, to catch lice that hatch later.\n- Scrub glass and decor to remove egg clusters.\n- Watch for bacterial infections in bite wounds and treat if they appear.\n\nMedications that kill fish lice also kill other crustaceans, so they are deadly to shrimp, crayfish and some other invertebrates. Move those animals out before treating.", "heading": "How to get rid of fish lice"}, {"text": "Quarantine new pond and coldwater fish for at least {{fact.quarantine_min}} weeks and inspect them closely in good light. Avoid adding wild-caught plants or water to your tank. Rinse new plants and inspect them for egg clusters.", "heading": "Preventing them"}]$g$::jsonb where slug = $g$fish-lice$g$;
update public.glossary_terms set faq = $g$[{"a": "Yes. If one fish has it, the parasite is in the tank. Treat the whole aquarium.", "q": "Is ich contagious?"}, {"a": "Sometimes healthy fish fight off a light case, but it often explodes. Treating early is much safer.", "q": "Can ich go away on its own?"}, {"a": "Quarantine new fish for at least {{fact.quarantine_min}} weeks, ideally 4 to 6, avoid sudden temperature swings and keep water quality high.", "q": "How do I prevent ich?"}]$g$::jsonb where slug = $g$ich$g$;
update public.glossary_terms set faq = $g$[{"a": "Until the tank finishes cycling, usually {{fact.cycle_weeks}} weeks.", "q": "How long does new tank syndrome last?"}, {"a": "Cloudy white water in a new tank is usually a harmless bacterial bloom, but it can mean the tank isn't fully cycled yet. Test for ammonia and nitrite.", "q": "Does cloudy water mean new tank syndrome?"}, {"a": "It's the most common cause of new tank syndrome. Cycle first, or use fully seeded media and add only a few hardy fish.", "q": "Can I add fish the same day I set up a tank?"}]$g$::jsonb where slug = $g$new-tank-syndrome$g$;
update public.glossary_terms set sections = $g$[{"text": "- Platies, mollies and swordtails: colorful livebearers that eat anything; mollies do best in harder water\n- Zebra and leopard danios: very tough, active, best in groups of 6 or more\n- White Cloud Mountain minnows: unheated tanks around {{white-cloud-mountain-minnow.temp}}°F\n- Corydoras catfish: peaceful bottom dwellers, kept in groups\n- Harlequin rasboras and many tetras: once the tank is fully cycled\n- A single betta: in {{betta.tank}} gallons or more with a heater", "heading": "Good choices for a first tank"}, {"text": "Common plecos grow to over 12 inches. Goldfish are hardy but get large and very messy, needing much more space than a small bowl. Oscars and other big cichlids outgrow most starter tanks quickly. Bala sharks and iridescent sharks are schooling fish that reach a foot or more. Always check adult size before buying.\n\nAlso be wary of fish that need very specific water. Discus, wild bettas, many Caridina shrimp and most saltwater species are best left until you have experience.", "heading": "Fish that are often sold to beginners but shouldn't be"}, {"text": "Cycle the tank before adding fish, or use a fish-in cycle with a few hardy fish and daily testing. Add fish a few at a time over several weeks so the beneficial bacteria can keep up. A 20 to 30 gallon tank is actually easier than a tiny one, because water quality stays more stable.", "heading": "Setting yourself up to succeed"}, {"text": "Once you have kept a tank stable for a few months, you can try more sensitive fish like cardinal tetras, apistogrammas or shrimp.", "heading": "Next steps"}]$g$::jsonb where slug = $g$beginner-fish$g$;
update public.glossary_terms set sections = $g$[{"text": "- 10 to 20 gallons: a betta or a honey or dwarf gourami\n- 20 to 40 gallons: a pair of German blue rams, a pair of apistogrammas, a pair of kribensis or, toward the upper end, a pearl gourami\n- 40 to 75 gallons: a group of rainbowfish or a bristlenose pleco with character, and from about 55 gallons a pair or small group of angelfish\n- {{discus.tank}} gallons and up: a group of discus, a severum, or a larger peaceful cichlid", "heading": "Popular choices by tank size"}, {"text": "Check the adult size, not the size in the store. Make sure the fish fits your water: discus and rams want warm, soft water, roughly 80 to 86°F, while many rainbowfish are fine in harder water. Consider personality too. Gouramis and cichlids interact with their keepers, which is part of the appeal.", "heading": "How to choose"}, {"text": "Build the community around the centerpiece. Avoid fin nippers like tiger barbs with long-finned fish such as angelfish and bettas. Remember that angelfish will eat small fish like neon tetras as they grow. Pick dither fish, such as a school of medium tetras or rasboras, that are too big to be eaten and calm enough not to stress the main fish.\n\nAdd the centerpiece last when possible, after the dither fish have settled, so it isn't the only fish in the tank while you finish stocking.", "heading": "Planning tankmates"}, {"text": "Some centerpiece species, like many gouramis, fight with their own kind in small tanks. Others, like angelfish or discus, do better in groups. Research before deciding whether to buy one or several.", "heading": "One or several?"}]$g$::jsonb where slug = $g$centerpiece-fish$g$;
update public.glossary_terms set sections = $g$[{"text": "- Shrimp: dwarf shrimp like cherry and crystal shrimp, plus larger amano and ghost shrimp\n- Snails: nerite, mystery, ramshorn, Malaysian trumpet and rabbit snails\n- Crayfish and dwarf crayfish, which are messy and often eat plants and slow fish\n- Freshwater crabs, many of which need land areas and escape-proof lids\n- Clams and mussels, which filter feed and are hard to keep alive long term", "heading": "Common freshwater inverts"}, {"text": "Most inverts want stable temperature and parameters more than any exact number. Shrimp and snails need some hardness to build shells and molt, so a GH of 6 to 10 degrees and KH of 2 to 8 suits many common species, while crystal shrimp prefer softer water. Ammonia and nitrite must be at zero, and nitrate ideally under {{fact.nitrate_ok}} ppm.\n\nThey graze biofilm and algae, but most also need supplemental foods like blanched vegetables or sinking invert foods with calcium.", "heading": "Water and diet needs"}, {"text": "Many fish see small shrimp as food, so pair them with tiny, peaceful species or give them dense plants and moss. Never use copper-based medications around inverts, and check fertilizers and treatments for warnings. Acclimate slowly, often by drip over an hour, since sudden changes can cause failed molts.", "heading": "Tankmates and safety"}, {"text": "Adding shrimp to an uncycled tank, keeping them with larger fish, and making big sudden water changes with very different water are the main causes of losses. Moderate, regular changes with matched temperature work best.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$invertebrate$g$;
update public.glossary_terms set sections = $g$[{"text": "Mystery snails grow to about {{mystery-snail.size}} inches. One or two do well in a 10 gallon or larger tank. Keep the water at about 68 to 82 F, pH 7 to 8, and GH of 8 or more so the shell stays strong. They breathe air through a siphon tube, so leave an inch or two of space between the water and the lid, and keep the lid tight because they explore.", "heading": "Basic care"}, {"text": "They eat leftover flakes and pellets, but in a clean tank they need their own food. Offer sinking pellets, algae wafers and blanched vegetables like zucchini, spinach or cucumber a few times a week. Calcium sources such as cuttlebone or calcium-rich foods help shell growth. A starving mystery snail may start nibbling soft plants.", "heading": "Feeding"}, {"text": "Mystery snails have separate sexes. Females lay a pink, firm clutch of eggs above the waterline, often on the lid. Each clutch can hold 100 or more eggs that hatch in about 2 to 4 weeks. To prevent babies, remove the clutch and freeze it before throwing it away. To hatch them, leave the clutch in a humid spot above the water.", "heading": "Eggs and breeding"}, {"text": "- A snail floating for a day can be normal; check with a sniff test, since a dead snail smells strongly\n- Pitted or cracked shells point to soft water or low calcium\n- Avoid fin-nipping fish and puffers that pick at their tentacles\n- Never dose copper medications with snails in the tank\n\nThey live about 1 to 2 years.", "heading": "Health signs and mistakes"}]$g$::jsonb where slug = $g$mystery-snail$g$;
update public.glossary_terms set sections = $g$[{"text": "Fish waste, uneaten food, decaying plants and dead animals all break down into ammonia. Big-bodied and messy fish like goldfish, plecos, oscars and cichlids produce far more waste than the same length of slim tetras. Feeding is the part you control most directly, since every bit of food that goes in eventually becomes waste.", "heading": "What adds to bioload"}, {"text": "- Beneficial bacteria in the filter and substrate convert ammonia to nitrite and then nitrate\n- Live plants absorb ammonia and nitrate as nutrients\n- Water changes physically remove nitrate and dissolved waste\n- Water volume dilutes waste, so bigger tanks are more forgiving\n\nA tank is in balance when ammonia and nitrite stay at 0 ppm and nitrate rises slowly enough that your normal water changes keep it under about {{fact.nitrate_ok}} ppm.", "heading": "What handles bioload"}, {"text": "Ammonia or nitrite readings above zero in a cycled tank, nitrate that climbs past {{fact.nitrate_watch}} ppm within a week, cloudy water, algae blooms and fish gasping at the surface are common signals. Low oxygen often comes with high bioload because waste breakdown uses oxygen too.", "heading": "Signs the bioload is too high"}, {"text": "Add new fish slowly, a few at a time, so bacteria can catch up. Feed sparingly. Upgrade filtration or increase water changes for heavy-waste species. Research adult size and waste output before buying, not just the size at the store. When unsure, stock lighter than you think you can.", "heading": "How to manage it"}]$g$::jsonb where slug = $g$bioload$g$;
update public.glossary_terms set sections = $g$[{"text": "Cycling takes about {{fact.cycle_weeks}} weeks, but a tank is fully mature only after several months. By then bacteria colonize every surface, biofilm coats glass and decor, plants are rooted and the tank handles daily waste with ammonia and nitrite always at 0 ppm. Numbers stay steady between water changes and pH no longer drifts much.", "heading": "What maturity looks like"}, {"text": "- Resists ammonia spikes when you add fish or overfeed slightly\n- Biofilm and microfauna provide constant grazing for shrimp, otocinclus and fry\n- Less algae trouble once plants and nutrients settle\n- Better survival for sensitive species like crystal shrimp, discus and many wild-caught fish\n\nThat is why stores and breeders often say an animal needs a mature tank.", "heading": "Why it matters"}, {"text": "Moving a used filter sponge, some media or a handful of substrate from a healthy mature tank into a new one carries a big dose of beneficial bacteria. A new tank can often be cycled in a few days to a week or two this way. Only seed from tanks without disease outbreaks, and still test water closely for the first few weeks.", "heading": "Seeding new tanks from a mature one"}, {"text": "Don't replace all filter media at once or rinse it in chlorinated tap water. Avoid deep cleaning everything on the same day. Keep up steady water changes so old-tank syndrome, where nitrate builds and pH slowly falls, does not creep in over the years. Replace only part of the media at a time when it truly wears out.", "heading": "Keeping a tank mature"}]$g$::jsonb, faq = $g$[{"a": "Cycling takes about {{fact.cycle_weeks}} weeks, but most keepers consider a tank mature after 6 months or more of stable operation.", "q": "How long does it take for a tank to mature?"}, {"a": "Seeding with media from an established tank helps the bacteria side quickly, though biofilm and plant balance still take time.", "q": "Can I speed up tank maturity?"}, {"a": "Mature tanks have stable chemistry and lots of biofilm, which young shrimp graze on constantly.", "q": "Why do shrimp do better in mature tanks?"}]$g$::jsonb where slug = $g$mature-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "- Adult size, not store size\n- Minimum tank length for active swimmers\n- Water needs: temperature, pH and hardness that all species share\n- Temperament: peaceful, semi-aggressive, fin-nippers or territorial\n- Swimming level: top, middle or bottom, to use the whole tank\n- Group size: schooling fish usually need 6 or more\n- Waste output: goldfish and large cichlids need far more filtration", "heading": "What to consider"}, {"text": "The old one inch of fish per gallon rule is a rough guide at best. It treats one {{oscar.size}} inch adult oscar the same as eight 1.5 inch neon tetras, which is badly wrong. Body mass, activity level and territory matter more than length. Use it only as a sanity check for small, slim community fish.", "heading": "Why simple rules fall short"}, {"text": "Add fish in small groups over weeks, giving bacteria time to catch up. Start with hardy species, often a school of peaceful midwater fish, then add bottom dwellers, and add centerpiece or more territorial fish last so they don't claim the whole tank early. Test ammonia and nitrite a few days after each addition.", "heading": "Stocking in order"}, {"text": "Mixing fish that need very different temperatures, buying single schooling fish, choosing fish based only on color, and putting fin-nippers like tiger barbs with long-finned fish like bettas are the classic errors. Ask about each fish's adult needs before buying. Then buy from a store or breeder that quarantines its stock, and quarantine new fish yourself for {{fact.quarantine_weeks}} weeks when you can.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$stocking$g$;
update public.glossary_terms set sections = $g$[{"text": "Most tanks do well with a partial water change of {{fact.water_change}} percent once a week. Heavily stocked tanks or messy fish may need 40 to 50 percent weekly, or two changes a week. Lightly stocked planted tanks can sometimes stretch to every two weeks. Let your nitrate readings guide you: aim to keep nitrate under about {{fact.nitrate_ok}} ppm, and never let it pass {{fact.nitrate_watch}} ppm.", "heading": "How much and how often"}, {"text": "- Unplug heaters and filters if the water level will drop below them\n- Siphon water out with a gravel vacuum, cleaning a section of substrate as you go\n- Wipe glass and rinse filter sponges in the removed tank water if needed\n- Prepare new water at about the same temperature, within 2 F\n- If you fill straight from the tap, add dechlorinator for the full tank volume, not just the new water\n- Refill slowly, then plug equipment back in", "heading": "Step by step"}, {"text": "Changing all the water at once swings temperature, pH and hardness, which shocks fish and can trigger failed molts in shrimp. A partial change keeps those swings small. Fish in tanks that have gone months without changes are adjusted to poor water, so restore them with several smaller changes, about 10 to 15 percent every two or three days, rather than one huge one.", "heading": "Why partial and not all"}, {"text": "Forgetting dechlorinator, refilling with water much colder or warmer than the tank, rinsing filter media under tap water, and replacing filter cartridges at the same time as a big change all cause problems. Keep a dedicated bucket that never touches soap.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$water-change$g$;
update public.glossary_terms set sections = $g$[{"text": "First, an ammonia source starts the process, either bottled ammonia, fish food or the fish themselves. Bacteria that eat ammonia grow and turn it into nitrite, so ammonia falls and nitrite climbs. A second group of bacteria then turns nitrite into nitrate.\n\nThe tank is cycled when it handles a full day's ammonia with 0 ppm ammonia and 0 ppm nitrite showing on a test, and nitrate rising.", "heading": "What happens during a cycle"}, {"text": "- Set up the tank with filter and heater running and dechlorinated water.\n- Choose a method: fishless cycling with an ammonia source is safest, fish-in cycling is possible with daily care.\n- Test ammonia, nitrite and nitrate every couple of days with a liquid test kit.\n- Optionally add bottled bacteria or seeded media to speed things up.\n- When readings hit 0, 0 and some nitrate, do a large water change and add fish slowly.", "heading": "How to cycle a tank"}, {"text": "Expect {{fact.cycle_weeks}} weeks for a fishless cycle from scratch. A warm tank around {{fact.cycling_temp}} F with pH above 7 cycles faster. Seeding from an established tank can cut it to a few days or a week or two.", "heading": "How long it takes"}, {"text": "Do not deep clean the filter mid-cycle, and in a fishless cycle keep adding ammonia after the tank is cycled until fish go in, or the bacteria starve. Very high nitrite can stall the second stage, so a water change helps if nitrite stays off the chart for a week or more. Adding a full stock of fish at once can overwhelm even a cycled tank.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$cycling$g$;
update public.glossary_terms set sections = $g$[{"text": "- Keep the stock light: a few hardy fish, not a full tank.\n- Feed small amounts once a day or every other day.\n- Test ammonia and nitrite daily with a liquid kit.\n- Change 25 to 50 percent of the water whenever ammonia plus nitrite goes above 0.25 ppm.\n- Use a dechlorinator that also binds ammonia and nitrite temporarily.\n- Keep the temperature steady and toward the warmer end of what your fish are comfortable with, since the bacteria grow faster in warmth.", "heading": "How to do it safely"}, {"text": "Bottled bacteria products can shorten the process. A handful of filter media or a squeezed sponge from a healthy tank works even better. Live plants help too, since they take up ammonia directly.\n\nExpect the cycle to take {{fact.cycle_weeks}} weeks. It may feel slower than fishless cycling because frequent water changes keep ammonia low, which is the point. Avoid adding shrimp or snails until the cycle is finished, since invertebrates are very sensitive to ammonia and nitrite.", "heading": "Speeding it up"}, {"text": "Gasping at the surface, red or inflamed gills, lethargy, clamped fins and refusing food all suggest ammonia or nitrite stress. Test right away and do a water change if readings are up.", "heading": "Signs your fish are struggling"}, {"text": "The tank is cycled when ammonia and nitrite stay at 0 ppm for about a week without water changes and nitrate is rising. Add new fish a few at a time over the next weeks so the bacteria can keep up. Keep testing weekly after that, since a newly cycled tank can still slip if you overfeed or add too many fish at once.", "heading": "When it is done"}]$g$::jsonb where slug = $g$fish-in-cycling$g$;
update public.glossary_terms set sections = $g$[{"text": "- Ammonia: released by fish gills, waste, uneaten food and decay. Harmful even at low readings over time, and more toxic at higher pH and temperature.\n- Nitrite: produced when the first group of bacteria eats ammonia. Also toxic, it blocks fish blood from carrying oxygen.\n- Nitrate: produced when a second group eats nitrite. Much safer, but it builds up and should be kept under about 20 ppm and never allowed past 40 ppm.", "heading": "The three stages"}, {"text": "The bacteria live on surfaces, mostly inside the filter, but also on gravel, decor and plants. They need oxygen and steady flow, which is why the filter should run all the time.\n\nIn a new tank these bacteria do not exist yet. Growing them is called cycling and takes about {{fact.cycle_weeks}} weeks. Fishless cycling with a bottled ammonia source is the safest way to grow them before fish arrive.", "heading": "Where it happens"}, {"text": "The cycle stops at nitrate in most aquariums. You remove it with regular water changes, usually {{fact.water_change}} percent a week and more for heavily stocked tanks. Live plants and algae also use some, and a small amount is turned into nitrogen gas in low-oxygen spots.", "heading": "How nitrate leaves the tank"}, {"text": "Feed only what fish eat in a minute or two, add fish gradually, and clean filter media in removed tank water. Test ammonia, nitrite and nitrate regularly. In an established tank, ammonia and nitrite should always read 0 ppm. A liquid test kit is more accurate than paper strips for these readings. If ammonia or nitrite ever shows up, do a water change and look for the cause, such as overfeeding, a dead fish or a recently cleaned filter.", "heading": "Keeping the cycle healthy"}]$g$::jsonb, faq = $g$[{"a": "Ammonia and nitrite should be 0 ppm. Nitrate is best kept under about {{fact.nitrate_ok}} ppm, with a water change before it reaches {{fact.nitrate_watch}} ppm.", "q": "What are safe levels of ammonia, nitrite and nitrate?"}, {"a": "Usually 4 to 8 weeks to establish, faster if you seed with media from a mature tank.", "q": "How long does the nitrogen cycle take in a new tank?"}, {"a": "No. The bacteria live on surfaces, not in the water, so dechlorinated water changes do not harm them.", "q": "Do water changes reset the nitrogen cycle?"}]$g$::jsonb where slug = $g$nitrogen-cycle$g$;
update public.glossary_terms set sections = $g$[{"text": "Pest cladophora grows as stiff, branched dark green threads that feel rough, almost like wet steel wool, unlike slimy hair algae. It often tangles into moss and around stem plants and rarely floats free.\n\nMarimo moss balls are round, dense, velvety green spheres that grow only a few millimeters a year. They are now classified as Aegagropila linnaei but are still widely sold under the old Cladophora name.", "heading": "How to identify it"}, {"text": "Pest cladophora almost always hitchhikes on new plants or moss. Inspect and rinse new plants, and quarantine them for a week or two in a separate container if possible.", "heading": "How it gets in"}, {"text": "- Pull out as much as possible by hand, winding it around a toothbrush.\n- Remove badly infested moss or plant portions entirely.\n- Spot treat remaining patches with liquid carbon or hydrogen peroxide using a syringe with the filter off for a few minutes. Overdosing can harm shrimp, snails and delicate plants like Vallisneria.\n- Keep nutrients balanced and lights at {{fact.light_hours}} hours to slow regrowth.\n\nFew animals eat it, though some keepers report amano shrimp and certain fish picking at it.", "heading": "How to control it"}, {"text": "Keep them in cool water under 78°F with low light, rotate them now and then, and squeeze them out in tank water every few weeks. White or pale patches usually mean too much light; brown patches often point to too little light, trapped debris or water that is too warm. Buy from trusted sources; in 2021 some shipments carried invasive zebra mussels.", "heading": "Caring for moss balls"}]$g$::jsonb where slug = $g$cladophora$g$;
update public.glossary_terms set sections = $g$[{"text": "- A pressurized cylinder stores the gas.\n- A regulator lowers the pressure, and a needle valve sets the bubble rate.\n- A solenoid valve on a timer turns gas on and off.\n- A bubble counter shows the flow rate.\n- A diffuser or reactor dissolves the gas into the water.\n- A drop checker shows the level by color.\n\nDIY yeast or citric acid kits exist for small tanks, but they are harder to control.", "heading": "How a system works"}, {"text": "Most planted tanks aim for about {{fact.co2}} ppm CO2. A drop checker filled with 4 dKH reference solution turns lime green at roughly that level, blue when too low and yellow when too high.\n\nStart with a low bubble rate and raise it slowly over a week or two while watching fish. A pH drop of about 1.0 from fully degassed water to the peak of the CO2 period is a common target.", "heading": "Safe levels and dialing it in"}, {"text": "Turn CO2 on 1 to 2 hours before the lights so levels are up when plants start working, and off about an hour before lights out. Plants do not use CO2 in the dark, and running it overnight is a common cause of fish losses in CO2 tanks.", "heading": "Timing"}, {"text": "Fish gasping at the surface, breathing hard or lying still mean too much CO2. Turn it off, increase surface agitation and do a water change. Never adjust the needle valve and walk away; check fish for the next few hours. Shrimp are especially sensitive.", "heading": "Warning signs and mistakes"}]$g$::jsonb where slug = $g$co2-injection$g$;
update public.glossary_terms set sections = $g$[{"text": "- Slimy sheets that peel off in one piece, unlike stringy or fuzzy algae.\n- Blue-green, dark green, or sometimes red to purple color.\n- A strong earthy, musty smell when disturbed.\n- Often starts on the substrate against the front glass, where light hits and flow is weak.\n- Bubbles trapped under the film in the afternoon.", "heading": "How to identify it"}, {"text": "Low flow and dead spots are the most common factor. Excess organic waste from overfeeding and infrequent cleaning help it along. In planted tanks, very low nitrate with plenty of phosphate can favor it, which is why it sometimes shows up in tanks that seem clean. Direct sunlight on the tank also feeds it.", "heading": "What causes it"}, {"text": "- Siphon out as much as you can and do a 30 to 50 percent water change.\n- Improve circulation, especially along the bottom.\n- Do a blackout: cover the tank fully for 3 to 4 days with no light, keeping filter and aeration running, then do another water change.\n- In planted tanks, check that nitrate is not near zero.\n\nSome keepers use the antibiotic erythromycin as a last resort. It works well on cyanobacteria but should be used carefully and only as directed, and it is not allowed for sale in every area. Antibiotics can also set back the filter bacteria, so test ammonia and nitrite during and after treatment. Spot treating with hydrogen peroxide is another option, but it can harm shrimp, snails and fish at high doses.", "heading": "How to get rid of it"}, {"text": "Keep up weekly water changes, feed less, vacuum the substrate surface, and keep flow strong enough that nothing is stagnant. Return light to {{fact.light_hours}} hours after a blackout.", "heading": "Preventing a comeback"}]$g$::jsonb where slug = $g$cyanobacteria$g$;
update public.glossary_terms set sections = $g$[{"text": "- Anubias: tough dark leaves, very low light needs.\n- Java fern: long leaves, often grows little plantlets on its leaves.\n- Bucephalandra: small, colorful leaves, slow growing.\n- Mosses like Java moss and Christmas moss: cover wood and rock.\n- Bolbitis: a fern that likes good flow.", "heading": "Common epiphytes"}, {"text": "Tie the rhizome or moss to wood or rock with cotton thread, which dissolves in a few weeks, or fishing line. Gel superglue also works well and is safe once cured; a small dab on the hardscape holds the plant in place underwater.\n\nYou can also wedge plants into gaps between rocks or wood. Within a few weeks roots grip the surface on their own.", "heading": "How to attach them"}, {"text": "Keep the rhizome above the substrate at all times; burying it causes rot. Feed with a light liquid fertilizer since these plants feed from the water. Moderate flow helps bring nutrients and keeps debris off their leaves.\n\nPropagate by cutting the rhizome into pieces with several leaves each, or by collecting the baby plants Java fern grows on its leaves. Many epiphytes also grow well out of water in a humid tank, which is handy for a dry start or a paludarium.", "heading": "Care tips"}, {"text": "Slow leaves can collect algae, so keep light moderate and the light period around {{fact.light_hours}} hours. Java fern can develop black or brown patches from low nutrients, often potassium. Raised brown dots in neat rows on the underside of leaves are spores, which are normal. Moss can trap debris and needs a gentle rinse during maintenance.", "heading": "Common problems"}]$g$::jsonb where slug = $g$epiphyte$g$;
update public.glossary_terms set sections = $g$[{"text": "Green water is caused by microscopic suspended algae, often Chlorella or Euglena types, multiplying in the water itself. Blooms usually follow a combination of excess light and excess nutrients: a tank near a sunny window, lights left on 10 or more hours, overfeeding, or an ammonia spike from a new tank or a big disturbance like a deep substrate clean.", "heading": "Why it happens"}, {"text": "- UV sterilizer: the most reliable fix, often clearing water in 3 to 7 days\n- Blackout: turn off the lights and cover the tank completely for 3 to 4 days, then do a large water change\n- Diatom or very fine micron filtration catches the cells\n- Cut feeding and photoperiod while you treat\n\nWater changes alone rarely work because the algae regrows from what remains within a day or two.", "heading": "How to clear it"}, {"text": "Fish and most plants handle a few dark days well. Add an air stone, since algae and plants consume oxygen in the dark and a dense bloom dying off can drop oxygen quickly. Feed lightly, keep the tank covered, and keep peeking to a minimum, since light lets the bloom recover. Expect some leaf loss on demanding plants.", "heading": "Care during a blackout"}, {"text": "Keep the tank out of direct sunlight, run lights {{fact.light_hours}} hours on a timer, and feed only what fish finish in a minute or two. Fast-growing stem and floating plants starve suspended algae of nutrients. Avoid algaecides: they kill the bloom all at once, which can crash oxygen and harm shrimp and snails.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$green-water$g$;
update public.glossary_terms set sections = $g$[{"text": "- Macronutrients: nitrogen (as nitrate), phosphorus (as phosphate) and potassium\n- Secondary nutrients such as magnesium, calcium and sulfur\n- Micronutrients: iron, manganese, boron, zinc and other trace elements\n- All-in-one products contain both, while some keepers dose them separately or mix their own dry salts\n\nPotassium deficiency shows as pinholes in older leaves; iron deficiency shows as pale or yellow new growth.", "heading": "What's in it"}, {"text": "Start with half the label dose in a low-tech tank and adjust from there. High-tech tanks with CO2 usually need the full dose, sometimes daily. Dose after your weekly water change and then on a set schedule, since a steady supply works better than occasional big doses. Many keepers aim for roughly 10 to {{fact.nitrate_ok}} ppm nitrate and 1 to 2 ppm phosphate in planted tanks.", "heading": "How to dose"}, {"text": "Fertilizers made for aquariums are safe at the recommended dose. Overdosing can harm shrimp and snails, and some products contain copper as a trace element. It is usually a tiny amount, but shrimp keepers should dose carefully and choose products labeled shrimp safe or very low in copper. Never use houseplant or garden fertilizer, which can contain ammonia-based nitrogen at levels that harm fish.", "heading": "Safety with fish and shrimp"}, {"text": "Dosing heavily under weak light, which feeds algae instead of plants, is the most common one. Others are using only liquid fertilizer for heavy root feeders like swords and crypts, which also need root tabs, and changing several things at once so you can't tell what helped.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$liquid-fertilizer$g$;
update public.glossary_terms set faq = $g$[{"a": "Most tanks do well with 6 to 8 hours a day. Fish-only tanks can go a bit longer if algae isn't a problem.", "q": "How many hours should aquarium lights be on?"}, {"a": "Yes. Fish need darkness to rest, and long photoperiods fuel algae. Use a timer to give a consistent day and night.", "q": "Is it bad to leave aquarium lights on all night?"}, {"a": "No. Planted tanks grow well on {{fact.light_hours}} hours of good light, and longer periods usually help algae more than plants.", "q": "Do aquarium plants need 12 hours of light?"}]$g$::jsonb where slug = $g$photoperiod$g$;
update public.glossary_terms set sections = $g$[{"text": "Aim to keep nitrate under {{fact.nitrate_ok}} ppm and do a water change before it reaches {{fact.nitrate_watch}} ppm. Keep it as low as you can for sensitive fish, shrimp and fry. Levels above 80 ppm are a clear sign of overdue maintenance and can cause lethargy, faded color and long-term health problems.\n\nTest your tap water too. Some tap water contains 10 to {{fact.nitrate_watch}} ppm of nitrate already, which changes how low you can realistically go.", "heading": "Safe levels"}, {"text": "- Regular water changes, usually {{fact.water_change}} percent weekly, more for heavily stocked tanks, are the main tool.\n- Vacuum the gravel and clean filters to remove decaying waste.\n- Feed less, and only what fish eat in a minute or two.\n- Add plants, especially fast growers and floating plants, which use nitrate as fertilizer.\n- If tap water is high in nitrate, mix in RO water.", "heading": "How to lower nitrate"}, {"text": "In planted tanks, nitrate is a nutrient, not just a waste product. Many planted tank keepers target 10 to 20 ppm and dose nitrogen fertilizer if it drops to zero, since nitrogen-starved plants yellow from the older leaves first. Zero nitrate in a heavily planted tank isn't a goal by itself.", "heading": "Planted tanks"}, {"text": "Liquid nitrate kits are much more reliable than strips, but one common kit needs its second bottle shaken hard for 30 seconds or more, or it reads falsely low. Read the color in good light against a white background. A sudden jump usually means something died or the tank was overfed.", "heading": "Testing tips"}]$g$::jsonb where slug = $g$nitrate$g$;
update public.glossary_terms set sections = $g$[{"text": "The nitrogen cycle and decaying organics constantly produce acid. Carbonates, measured as KH, neutralize that acid and hold pH steady. When KH is low to begin with, or water changes are skipped, the buffer runs out and pH falls fast.\n\nTanks with soft tap water, lots of driftwood or peat, heavy stocking, or CO2 injection with very low KH are most at risk. Once pH drops below about 6, nitrifying bacteria slow down sharply, which can cause ammonia to build up later.", "heading": "Why it happens"}, {"text": "- KH test reading 1 to 2 dKH or lower\n- pH noticeably lower than a week ago\n- Fish suddenly lethargic, hiding, gasping or with clamped fins\n- Cloudy water or rising ammonia after a stretch of low pH", "heading": "Warning signs"}, {"text": "Do a {{fact.water_change}} percent water change with dechlorinated tap water, assuming your tap water has reasonable KH. Repeat over a few days rather than all at once so pH rises gradually. Raise KH long term with a small bag of crushed coral or aragonite in the filter, or a measured dose of baking soda: about 1 teaspoon per 50 gallons raises KH by roughly 1 dKH. Add baking soda slowly and retest before adding more. If ammonia has built up during the low pH, lower it with water changes first, because ammonia becomes more toxic as pH rises.\n\nAvoid pH-down or pH-up chemicals without fixing KH; they cause swings, not stability.", "heading": "How to fix it"}, {"text": "Keep KH at 3 dKH or higher for most community tanks, test KH every week or two, keep up with water changes, and don't overstock.", "heading": "Prevention"}]$g$::jsonb where slug = $g$ph-crash$g$;
update public.glossary_terms set sections = $g$[{"text": "Match three things: temperament, size and water needs. Avoid fish big enough to swallow tankmates, and avoid pairing fin nippers like tiger barbs with long-finned fish like bettas or angelfish. Then check that temperature, pH and hardness ranges overlap.\n\nThink in layers: a schooling group in the middle, bottom dwellers like corydoras, and maybe one centerpiece fish.", "heading": "Choosing compatible fish"}, {"text": "- 20 gallons: a school of 8 small tetras such as neons, 6 small corydoras such as pandas, and a nerite snail or two\n- 29 gallons: harlequin rasboras, platies, a group of kuhli loaches and a honey gourami\n- 40 gallons or more: a larger tetra school, a single dwarf gourami or a pearl gourami, and a group of corydoras\n\nSchooling fish should be kept in groups of 6 or more.", "heading": "Beginner-friendly combinations"}, {"text": "Cycle the tank first. Add fish in small groups over weeks, starting with the hardiest, so the bacteria keep up. Quarantine new fish for {{fact.quarantine_weeks}} weeks if you can, since one sick newcomer can infect the whole tank.\n\nWatch new arrivals closely for the first few days for chasing, hiding or torn fins, and be ready to rehome a fish that doesn't fit in. Plenty of plants and decor help break lines of sight and reduce squabbles.", "heading": "Adding fish the right way"}, {"text": "- Buying fish on impulse without checking adult size\n- Keeping schooling fish in groups of two or three\n- Overstocking, which raises waste and aggression\n- Adding a single aggressive fish to a peaceful group", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$community-tank$g$;
update public.course_sections set content = $c$Fish are cold-blooded. Their bodies match the water around them, so water temperature controls how they eat, grow, and fight off disease.

**Typical ranges:**

- **Tropical fish:** about {{fact.tropical_temp}}°F
- **Goldfish and other coldwater fish:** about 65 to 72°F

**Keep it steady.** Try to keep your tank within about 1 to 2 degrees of where you set it. Big swings stress fish and can lead to disease like ich.

**Your gear:**

- **A heater** for tropical tanks. A common guideline is about {{fact.heater_watts}} watts per gallon.
- **A thermometer** you can read easily. Don't just trust the heater's dial.

**Warm water holds less oxygen.** On a hot day, or if your heater gets stuck on, fish may gasp at the surface. More surface movement from your filter helps.

**During water changes,** make the new water about the same temperature as the tank. A thermometer makes this easy.$c$ where id = $v$6e9634f8-c8a7-4d2e-ae31-0e981a38a1ba$v$::uuid;
update public.course_sections set content = $c$A brand new tank has almost none of the bacteria from Lesson 1. Fresh gravel, a new filter, and dechlorinated tap water are basically sterile. That's why the most common way to lose fish is buying a tank and stocking it the same weekend.

**What happens, step by step:**

1. Fish go in and start producing ammonia on day one.
2. With no bacteria to eat it, ammonia climbs for a week or two.
3. Ammonia-eating bacteria finally grow, ammonia drops, and nitrite spikes instead.
4. Nitrite-eating bacteria lag behind, so nitrite stays high for another week or more.
5. Eventually both groups catch up and the tank settles. Many fish don't make it that far.

Hobbyists call this **new tank syndrome**. The fish store didn't sell you bad fish, and the tank isn't broken. It just wasn't ready.

**Signs your fish are in trouble:** gasping at the surface, sitting on the bottom, clamped fins, red or inflamed gills, cloudy eyes, refusing food. If you see these in a tank under 6 weeks old, test ammonia and nitrite right away.

**The fix is patience.** Cycling a tank before fish go in (Lesson 3) takes about {{fact.cycle_weeks}} weeks. If fish are already in, Lesson 4 shows you how to get them through it.

**Cloudy water is not the cycle.** A milky haze in a new tank is usually a harmless bacterial bloom. It clears on its own in a few days. Don't take it as a sign the tank is cycled, and don't chase it with chemicals. Test the water instead.$c$ where id = $v$19b26dbb-339b-4025-b3df-381a21c32f1f$v$::uuid;
update public.course_sections set content = $c$Most fish in a store are babies. They look small and cute in the tank, but many of them keep growing for years. Picking fish by how big they are in the store is one of the most common beginner mistakes.

**Some popular fish that outgrow home tanks:**

- **Common pleco:** often 15 to 18 inches or more
- **Bala shark:** about 12 to 14 inches, and it swims in groups
- **Oscar:** about {{oscar.size}} inches and very heavy-bodied
- **Iridescent shark:** can pass 3 feet long

None of these belong in a 20 or 30 gallon tank, even if they fit today.

**The fix is easy:** before you buy any fish, look up its **adult size** and **minimum tank size**. Every fish in our Species Library lists both. If the adult fish won't fit your tank, pick a different fish.

**A good habit:** take a photo of the fish's name at the store, then look it up before you pay. A few minutes of research saves a fish from a cramped life.$c$ where id = $v$d411877a-c351-410e-8870-d1eeb594d4b1$v$::uuid;
update public.course_sections set content = $c$Every fish has a range of water it likes. Fish in the same tank need ranges that overlap, because they all share the same water.

**Tropical vs. coldwater fish:**

- **Tropical fish** like tetras, bettas, and gouramis want warm water, about {{fact.tropical_temp}}°F. They need a heater.
- **Goldfish** are coldwater fish. They do best around 65 to 72°F and do not need a heater.

Don't keep goldfish with tropical fish. One group will always be too hot or too cold. Goldfish also make a lot of waste and grow much bigger than most people expect.

**pH and hardness:** most fish sold today were raised on fish farms and handle a wide range of water. What matters most is keeping your water **steady**. A few fish, like African cichlids, need hard water with a high pH. Check before you buy.

**Use the Species Library** to compare temperature and pH ranges. Pick fish whose ranges overlap with each other and with your tap water.$c$ where id = $v$8ad547c4-441e-468e-b080-f5d6515a05f4$v$::uuid;
update public.course_sections set content = $c$Plants use light to make food. Too little light and they slowly fade. Too much light and you grow algae.

**How long to leave the light on:**

- Most planted tanks do well with about **{{fact.light_hours}} hours** of light a day.
- Use a **timer** so it's the same every day. Plants and fish both like a steady schedule.

**Low-light vs. high-light tanks:**

- **Low-light tanks** use a normal aquarium light. Java fern, anubias, crypts, java moss, and floating plants all grow well here.
- **High-light tanks** use stronger lights. They grow plants faster but usually need added CO2 and more fertilizer to keep algae away. Save this for later.

**The balance rule:** more light means plants need more food. If you add a lot of light without more nutrients, algae takes over.

**Watch for these signs:**

- **Plants getting tall, thin, and pale:** probably not enough light.
- **Algae growing quickly:** probably too much light, or the light is on too long. Try cutting back an hour or two.

**Keep the tank out of direct sunlight.** Sunlight is hard to control and often causes algae blooms.$c$ where id = $v$8d425cfc-7552-47c9-a186-5330af1c16d3$v$::uuid;
update public.course_sections set content = $c$Every tank has a little algae. That's normal and even healthy. Problems start when there's more light and food than your plants can use.

**Common types of algae:**

- **Brown algae (diatoms):** brown dust on glass and decor. Very common in new tanks. It usually fades on its own after the first month or two.
- **Green spot algae:** small, hard green dots on glass and slow-growing leaves. Often linked to too much light, or too little of a plant nutrient called phosphate.
- **Hair algae:** long green threads. Usually too much light or extra nutrients.
- **Black beard algae:** dark, fuzzy tufts on edges of leaves and decor. Often tied to unsteady CO2 and older tanks.

**How to keep algae down:**

1. Keep the light on {{fact.light_hours}} hours with a timer.
2. Don't overfeed fish or overdose fertilizer.
3. Keep up with water changes.
4. Add more fast-growing plants, like floating plants, to use up extra nutrients.
5. Scrub glass and remove algae by hand when you see it.

**A cleanup crew helps:**

- **Nerite snails** eat many algae types, including green spot. They lay small white eggs that won't hatch in fresh water.
- **Amano shrimp** are great at eating hair algae.
- **Otocinclus** (small catfish) eat brown diatoms. Keep them in groups, and add them only after your tank has been running for a few months.

**Don't overreact.** Change one thing at a time and give it a week or two before changing something else.$c$ where id = $v$bef3c643-e48f-44a4-8550-ac9ac719deb8$v$::uuid;
update public.course_sections set content = $c$The most counterintuitive beginner fact: **bigger tanks are easier, not harder.** More water dilutes mistakes, so temperature and water chemistry stay stable. A tiny 3 to 5 gallon “desktop” tank swings wildly and punishes small errors. If you can, start with **at least 20 gallons**. It's far more forgiving than the cute little cubes marketed to beginners.

The essential gear: a **filter** rated for your tank size (it's where the helpful bacteria will live), a **heater** (most tropical fish want a stable {{fact.tropical_temp}}°F), a **light**, **substrate** (gravel or sand), **water conditioner (dechlorinator)**, a **liquid water test kit** (more accurate than paper strips, and you genuinely need one), and a **siphon and a dedicated bucket** that has never touched soap.

Placement matters: use a stand that can truly hold the weight (water is about **8.3 pounds per gallon**), keep the tank out of **direct sunlight** (it fuels algae), away from drafts and vents, and near an outlet. Rinse the substrate (never use soap), add it, fill the tank, install and start the filter and heater, and then leave it running **without fish.** You're about to find out why.$c$ where id = $v$c5d2f608-4ed0-40ca-a4ae-bc41b7da1ca1$v$::uuid;
update public.course_sections set content = $c$Tap water almost always contains **chlorine or chloramine** to make it safe for people, but those chemicals harm fish and kill the beneficial bacteria you just worked to grow. So **every time** you add tap water, treat it first with a **water conditioner (dechlorinator).** It works instantly. Roughly match the new water's temperature to the tank so you don't shock the fish.

Use your test kit to watch four things: **ammonia: 0**, **nitrite: 0**, **nitrate:** kept low (under about {{fact.nitrate_ok}} ppm, and never above {{fact.nitrate_watch}} ppm; this is what water changes remove), and **pH**, where stability matters more than a specific number.

The routine is simple: about a **25% water change once a week**, using your gravel siphon to vacuum debris from the substrate as you drain. Two things to never do: don't replace all the water at once (it wipes out stability), and **never rinse filter media under the tap**, since the chlorine kills your bacteria. When the filter needs cleaning, gently rinse the media in a bucket of old tank water instead.$c$ where id = $v$e6fd6637-2e05-4fb5-ba2b-6dea693dae4a$v$::uuid;
update public.course_sections set content = $c$You can't see ammonia or nitrite. A test kit is the only way to know where your tank stands. Log every result in Water Check so you can spot trends instead of guessing.

**Liquid kits beat strips.** Liquid kits (drops in a test tube) are more accurate and cheaper per test. Strips are handy for quick checks but can read high or low, especially once the tub has been open a while.

**What the numbers mean in a cycled tank:**

- **Ammonia:** healthy is 0 ppm. Act on any reading above 0.
- **Nitrite:** healthy is 0 ppm. Act on any reading above 0.
- **Nitrate:** healthy is under {{fact.nitrate_ok}} ppm. Once it passes 20 ppm, plan a water change, and don't let it go over 40 ppm.
- **pH:** healthy is steady (most fish do well between 6.5 and 7.8). Watch for sudden swings.

**Reading the stage of a cycle:**

- Ammonia high, nitrite 0: bacteria haven't started. Early cycle.
- Ammonia falling, nitrite rising: the first bacteria are working. Mid cycle.
- Ammonia 0, nitrite falling, nitrate rising: the second bacteria are arriving. Nearly there.
- Ammonia 0, nitrite 0, nitrate rising slowly: cycled.

**pH and temperature change how toxic ammonia is.** In higher pH and warmer water, more of it is in the toxic form. The same 0.5 ppm reading is more dangerous at pH 8.2 than at pH 6.8. In hard, alkaline water, treat any ammonia as urgent.

**Testing tips:**

- Follow the kit's shake and wait times exactly. Nitrate bottles need hard shaking.
- Read colors in daylight against a white background.
- Test your tap water once too. Some tap water already has ammonia (from chloramine) or nitrate in it.
- Check expiry dates. Old reagents give false readings.$c$ where id = $v$2cc6d5e5-d038-4954-a98d-68cdc3bddb7a$v$::uuid;

commit;
